window.GNN_LESSONS=window.GNN_LESSONS||{};window.GNN_LESSONS["L3"]={"deck":"L3","slides":[{"p":1,"title":"표지: GNN의 표현력","terms":["Expressive power","Message passing"],"pass1":[{"kind":"say","lines":["3주차 주제는 GNN의 **표현력(Expressive power)**이에요.","표현력은 GNN이 서로 다른 그래프 모양을 보고 '둘이 다르다'고 알아보는 힘이에요.","지난주에 배운 **메시지 패싱(Message passing)**, 즉 이웃에게 정보를 받아 모으는 방식이","어디까지 알아볼 수 있는지 이번 주에 차근차근 따져 봐요."]}],"pass2":[{"kind":"look","head":"표지에서 볼 곳","boxes":[{"x":0.08,"y":0.16,"w":0.5,"h":0.17,"say":"제목 Expressivity of GNNs 에서 Expressivity 가 **표현력(Expressive power)**이에요."},{"x":0.15,"y":0.47,"w":0.3,"h":0.27,"say":"이오준 교수님, 가톨릭대학교 인공지능학과, 이메일 주소예요."},{"x":0.66,"y":0.0,"w":0.34,"h":1.0,"say":"오른쪽 파란 배경은 점(노드)과 선(엣지)으로 그린 그래프 무늬예요."}]},{"kind":"prof","when":"3주차 화요일 수업","lines":["이번 주 주제는 GNN 의 **표현력(Expressive power)** 이라고 소개했어요.","'모델이 커지면 표현력이 커진다'보다 한 걸음 더 들어간대요.","수업 중에 '조금 난해하더라도 잘 들어 달라'고 했어요. 반복해서 봐요."]}],"pass3":[],"pass4":[]},{"p":2,"title":"목차: 오늘의 여섯 덩어리","terms":["Expressive power","Separation power","Approximation","Computational graph","Rooted subtree","Injective","Aggregation","GIN","1-WL test","Color refinement"],"pass1":[{"kind":"say","lines":["오늘 강의는 여섯 덩어리로 되어 있어요.","지금은 '이런 순서로 가는구나' 하고 가볍게 훑어보기만 하면 돼요."]},{"kind":"figure","head":"오늘 강의의 여섯 덩어리","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\">\n<rect class=\"box2 b1\" x=\"8\" y=\"30\" width=\"148\" height=\"78\" rx=\"10\"/>\n<rect class=\"box2 b1\" x=\"166\" y=\"30\" width=\"148\" height=\"78\" rx=\"10\"/>\n<rect class=\"box b1\" x=\"324\" y=\"30\" width=\"148\" height=\"78\" rx=\"10\"/>\n<text class=\"tb b1\" x=\"82\" y=\"62\" font-size=\"16\" text-anchor=\"middle\">1 표현력의 뜻<\/text>\n<text class=\"t b1\" x=\"82\" y=\"88\" font-size=\"14\" text-anchor=\"middle\">구별하는 힘이란?<\/text>\n<text class=\"tb b1\" x=\"240\" y=\"62\" font-size=\"16\" text-anchor=\"middle\">2 계산 그래프<\/text>\n<text class=\"t b1\" x=\"240\" y=\"88\" font-size=\"14\" text-anchor=\"middle\">노드가 보는 나무<\/text>\n<text class=\"tb b1\" x=\"398\" y=\"62\" font-size=\"16\" text-anchor=\"middle\">3 모으는 방법<\/text>\n<text class=\"t b1\" x=\"398\" y=\"88\" font-size=\"14\" text-anchor=\"middle\">합, 평균, 최댓값<\/text>\n<rect class=\"box b2\" x=\"8\" y=\"140\" width=\"148\" height=\"78\" rx=\"10\"/>\n<rect class=\"box b2\" x=\"166\" y=\"140\" width=\"148\" height=\"78\" rx=\"10\"/>\n<rect class=\"box b2\" x=\"324\" y=\"140\" width=\"148\" height=\"78\" rx=\"10\"/>\n<text class=\"tb b2\" x=\"82\" y=\"172\" font-size=\"16\" text-anchor=\"middle\">4 가장 강한 모델<\/text>\n<text class=\"t b2\" x=\"82\" y=\"198\" font-size=\"14\" text-anchor=\"middle\">이름은 GIN<\/text>\n<text class=\"tb b2\" x=\"240\" y=\"172\" font-size=\"16\" text-anchor=\"middle\">5 색칠 시험<\/text>\n<text class=\"t b2\" x=\"240\" y=\"198\" font-size=\"14\" text-anchor=\"middle\">이름은 1-WL 테스트<\/text>\n<text class=\"tb b2\" x=\"398\" y=\"172\" font-size=\"16\" text-anchor=\"middle\">6 한계 넘기<\/text>\n<text class=\"t b2\" x=\"398\" y=\"198\" font-size=\"14\" text-anchor=\"middle\">색칠 시험이 틀리는 곳<\/text>\n<text class=\"tb b3\" x=\"240\" y=\"252\" font-size=\"16\" text-anchor=\"middle\">이번 레슨은 1번 전체와 2번 입구까지<\/text>\n<\/svg>","caption":"이번 레슨(1쪽부터 16쪽까지)은 1번 덩어리 전체와 2번 덩어리의 입구까지 다뤄요.","builds":3}],"pass2":[{"kind":"look","head":"목차 한 줄씩","boxes":[{"x":0.26,"y":0.263,"w":0.42,"h":0.062,"say":"**분리 능력(Separation power)**은 다른 두 그래프를 가르는 힘, **근사(Approximation)**는 계산을 흉내 내는 힘."},{"x":0.26,"y":0.337,"w":0.42,"h":0.062,"say":"**계산 그래프(Computational graph)**: 노드가 보는 정보가 나무로 펼쳐져요. **뿌리 있는 부분 트리(Rooted subtree)**예요."},{"x":0.26,"y":0.414,"w":0.42,"h":0.062,"say":"**단사(Injective)** 이웃 **집계(Aggregation)**: 합이 평균보다, 평균이 최댓값보다 잘 구별해요."},{"x":0.26,"y":0.49,"w":0.42,"h":0.062,"say":"**그래프 동형 네트워크(GIN)**: 가장 강한 모으기 방법으로 만든 모델이에요."},{"x":0.26,"y":0.565,"w":0.42,"h":0.062,"say":"**1-WL 테스트(1-WL test)**와 **색 정제(Color refinement)**: GNN 실력의 한계를 재는 자예요."},{"x":0.26,"y":0.642,"w":0.42,"h":0.062,"say":"그 자로도 못 가르는 그래프가 있고, 그 천장을 넘는 방법들을 봐요."}]},{"kind":"points","head":"기호와 범위","items":["기호 ≻ 는 '왼쪽이 오른쪽보다 더 많이 구별한다'는 뜻이에요.","'vs.(대)'는 둘을 비교한다는 뜻이에요.","p.1~16 은 1번 덩어리 전체와 2번 덩어리 첫 장까지예요."]},{"kind":"prof","when":"3주차 화요일 수업","lines":["순서는 셋이라고 했어요. 표현력이란 무엇인가,","GNN 에서 표현력은 무엇을 말하나, 그리고 개선 방안이에요."]}],"pass3":[{"kind":"check","q":"**표현력(Expressive power)**의 뜻으로 가장 알맞은 것은?","choices":["계산이 빠른 정도","서로 다른 그래프 구조를 구별하는 능력","학습 정확도","모델의 파라미터 수"],"a":1,"why":"표현력은 '다른 것을 다르다고 알아보는 눈'이에요. 속도나 정확도가 아니에요."}],"pass4":[]},{"p":3,"title":"GNN 이론: 얼마나 구별하나","terms":["Expressive power","GCN","GraphSAGE","Design space","Message passing","Graphlet"],"pass1":[{"kind":"say","lines":["이번 주 질문은 하나예요. GNN은 서로 다른 그래프 모양을 얼마나 잘 구별할까요?","이 구별하는 힘을 **표현력(Expressive power)**이라고 불러요. 계산이 빠른 것과는 상관없어요.","그리고 구별을 가장 잘하는 GNN은 어떻게 만드는지도 알아봐요."]},{"kind":"look","head":"슬라이드에서 이 두 줄만 보면 돼요","boxes":[{"x":0.07,"y":0.28,"w":0.72,"h":0.06,"say":"괄호 속 문장이 표현력의 뜻이에요. '서로 다른 그래프 구조를 구별하는 능력'이라고 적혀 있어요."},{"x":0.07,"y":0.39,"w":0.43,"h":0.06,"say":"'표현력이 가장 큰 GNN을 어떻게 설계할까?'라는 질문이에요. 답은 이 강의 뒷부분에 나와요."}]},{"kind":"analogy","head":"흐린 안경으로 틀린 그림 찾기","scene":"민수가 틀린 그림 찾기를 해요. 두 그림은 분명 세 군데가 다른데, 민수 안경이 뿌옇게 흐려서 '똑같은 그림이네' 하고 말해 버려요. 안경이 선명할수록 차이를 더 많이 찾아내겠죠. GNN도 똑같아서, 표현력이 클수록 서로 다른 그래프를 더 잘 가려내요.","map":[["안경","GNN 모델"],["안경이 얼마나 선명한가","**표현력(Expressive power)**"],["세 군데가 다른 두 그림","모양이 서로 다른 두 그래프"]]}],"pass2":[{"kind":"look","head":"슬라이드 글자 하나씩","boxes":[{"x":0.03,"y":0.14,"w":0.26,"h":0.06,"say":"'GNN은 얼마나 강력한가?' 강력함은 속도가 아니라 구별하는 눈이에요."},{"x":0.07,"y":0.21,"w":0.6,"h":0.06,"say":"**그래프 합성곱 신경망(GCN)**, GAT, **그래프세이지(GraphSAGE)**, **설계 공간(Design space)**: 여러 GNN이에요."},{"x":0.07,"y":0.28,"w":0.72,"h":0.06,"say":"괄호 속이 **표현력(Expressive power)**의 정의: 서로 다른 그래프 구조를 구별하는 능력."},{"x":0.07,"y":0.39,"w":0.43,"h":0.06,"say":"'표현력이 최대인' GNN: 메시지 패싱 안의 천장에 딱 닿는 모델. 답은 뒤의 GIN."},{"x":0.02,"y":0.94,"w":0.49,"h":0.04,"say":"스탠퍼드 CS224W 강의 자료를 바탕으로 했다는 표시예요."}]},{"kind":"points","head":"슬라이드 속 이름들","items":["**그래프 합성곱 신경망(GCN)**: 이웃을 평균 비슷하게 모아요.","GAT: 이웃마다 얼마나 중요하게 들을지 따로 정해요.","**그래프세이지(GraphSAGE)**: 모으는 방법을 여러 가지로 골라요.","**설계 공간(Design space)**: 층 수, 모으는 법 같은 선택지로 만들 수 있는 GNN 전부.","그래프 구조: 노드 이름표가 아니라 누가 누구와 이어졌는지, 그 모양 자체예요."]},{"kind":"figure","head":"육각형 고리 대 삼각형 두 개","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\">\n<line class=\"e\" x1=\"120\" y1=\"50\" x2=\"185\" y2=\"88\"/>\n<line class=\"e\" x1=\"185\" y1=\"88\" x2=\"185\" y2=\"162\"/>\n<line class=\"e\" x1=\"185\" y1=\"162\" x2=\"120\" y2=\"200\"/>\n<line class=\"e\" x1=\"120\" y1=\"200\" x2=\"55\" y2=\"162\"/>\n<line class=\"e\" x1=\"55\" y1=\"162\" x2=\"55\" y2=\"88\"/>\n<line class=\"e\" x1=\"55\" y1=\"88\" x2=\"120\" y2=\"50\"/>\n<line class=\"e\" x1=\"290\" y1=\"70\" x2=\"250\" y2=\"150\"/>\n<line class=\"e\" x1=\"250\" y1=\"150\" x2=\"330\" y2=\"150\"/>\n<line class=\"e\" x1=\"330\" y1=\"150\" x2=\"290\" y2=\"70\"/>\n<line class=\"e\" x1=\"410\" y1=\"70\" x2=\"370\" y2=\"150\"/>\n<line class=\"e\" x1=\"370\" y1=\"150\" x2=\"450\" y2=\"150\"/>\n<line class=\"e\" x1=\"450\" y1=\"150\" x2=\"410\" y2=\"70\"/>\n<circle class=\"n\" cx=\"120\" cy=\"50\" r=\"16\"/><circle class=\"n\" cx=\"185\" cy=\"88\" r=\"16\"/>\n<circle class=\"n\" cx=\"185\" cy=\"162\" r=\"16\"/><circle class=\"n\" cx=\"120\" cy=\"200\" r=\"16\"/>\n<circle class=\"n\" cx=\"55\" cy=\"162\" r=\"16\"/><circle class=\"n\" cx=\"55\" cy=\"88\" r=\"16\"/>\n<circle class=\"n3\" cx=\"290\" cy=\"70\" r=\"16\"/><circle class=\"n3\" cx=\"250\" cy=\"150\" r=\"16\"/>\n<circle class=\"n3\" cx=\"330\" cy=\"150\" r=\"16\"/><circle class=\"n3\" cx=\"410\" cy=\"70\" r=\"16\"/>\n<circle class=\"n3\" cx=\"370\" cy=\"150\" r=\"16\"/><circle class=\"n3\" cx=\"450\" cy=\"150\" r=\"16\"/>\n<text class=\"tl\" x=\"120\" y=\"55\" font-size=\"14\" text-anchor=\"middle\">2<\/text>\n<text class=\"tl\" x=\"185\" y=\"93\" font-size=\"14\" text-anchor=\"middle\">2<\/text>\n<text class=\"tl\" x=\"185\" y=\"167\" font-size=\"14\" text-anchor=\"middle\">2<\/text>\n<text class=\"tl\" x=\"120\" y=\"205\" font-size=\"14\" text-anchor=\"middle\">2<\/text>\n<text class=\"tl\" x=\"55\" y=\"167\" font-size=\"14\" text-anchor=\"middle\">2<\/text>\n<text class=\"tl\" x=\"55\" y=\"93\" font-size=\"14\" text-anchor=\"middle\">2<\/text>\n<text class=\"tl\" x=\"290\" y=\"75\" font-size=\"14\" text-anchor=\"middle\">2<\/text>\n<text class=\"tl\" x=\"250\" y=\"155\" font-size=\"14\" text-anchor=\"middle\">2<\/text>\n<text class=\"tl\" x=\"330\" y=\"155\" font-size=\"14\" text-anchor=\"middle\">2<\/text>\n<text class=\"tl\" x=\"410\" y=\"75\" font-size=\"14\" text-anchor=\"middle\">2<\/text>\n<text class=\"tl\" x=\"370\" y=\"155\" font-size=\"14\" text-anchor=\"middle\">2<\/text>\n<text class=\"tl\" x=\"450\" y=\"155\" font-size=\"14\" text-anchor=\"middle\">2<\/text>\n<text class=\"tb b1\" x=\"120\" y=\"238\" font-size=\"16\" text-anchor=\"middle\">C6: 한 덩어리<\/text>\n<text class=\"tb b1\" x=\"350\" y=\"198\" font-size=\"16\" text-anchor=\"middle\">2 x C3: 두 덩어리<\/text>\n<text class=\"tm b2\" x=\"240\" y=\"262\" font-size=\"14\" text-anchor=\"middle\">노드 안 숫자 = 차수. 모두 2라서 GNN 결과가 같아요<\/text>\n<\/svg>","caption":"$C_6$(점 6개가 한 바퀴로 이어진 육각형 고리)과 $2 \\times C_3$(삼각형 두 개). 노드 6, 엣지 6, 모든 차수 2. 모양은 다른데 GNN 눈엔 같아요.","builds":2},{"kind":"steps","head":"숫자로: 이웃 값을 더하는 GNN","steps":["0층: $C_6$ 도 $2 \\times C_3$ 도 모든 노드 1","1층: 이웃 2명 합 1 + 1 = 2. 양쪽 모두 2","2층: 2 + 2 = 4. 양쪽 모두 4","3층: 4 + 4 = 8. 양쪽 모두 8","그래프 전체 합: 6 × 8 = 48. 양쪽 모두 48"],"answer":"하나는 한 덩어리, 하나는 두 덩어리인데 숫자가 끝까지 같아요. 평균, 최댓값도 마찬가지예요.","given":"모든 노드 특징 1. 층마다 이웃 값을 전부 더해요."},{"kind":"prof","when":"3주차 화요일 수업","lines":["다른 분야에서는 파라미터를 늘리거나 층을 더 쌓아 표현력을 키우기도 해요.","그런데 GNN 은 층을 쌓는다고 표현력이 강해지지 않는다고 했어요.","층을 쌓으면 생기는 문제가 훨씬 많고, 그건 학기 뒤에서 따로 배운대요.","그래서 이번 주는 GNN 표현력을 '다른 방식'으로 키우는 법을 봐요."]},{"kind":"mining","src":"마이닝 9강 Graph Kernels","lines":["**그래플릿(Graphlet)**은 노드 3개, 4개짜리 미리 정한 작은 부분 그래프예요.","삼각형을 세면 $C_6$ 은 0개, $2 \\times C_3$ 은 2개라 바로 갈라져요.","대신 크기 $k$ 그래플릿을 전부 세려면 대략 $O(n^k)$, 즉 노드 수 $n$ 을 $k$ 번 곱한 만큼 걸려서 느려요."]}],"pass3":[{"kind":"exam","src":"그래프 마이닝 2026 봄 기말 1번 (b) (5점)","q":"How does graphlet size k dictate the trade-off between the expressive power of the Graphlet Kernel and its computational complexity?","qko":"그래플릿 크기 $k$ 가 그래플릿 커널의 표현력과 계산량 사이 트레이드오프를 어떻게 정하나?","solve":["$k$ 가 커지면 더 큰 구조, 더 풍부한 패턴을 담아요.","그래서 비슷하지만 동형이 아닌 그래프를 더 잘 구별해요. **표현력(Expressive power)** 상승.","대신 크기 $k$ 부분 그래프를 모두 세는 시간은 최악 $O(n^k)$ 로 늘어요.","가능한 **그래플릿(Graphlet)** 종류도 $k$ 에 따라 폭발해서 특징 차원이 커져요."],"answer":"k 가 크면 표현력은 올라가지만 계산량이 급격히 늘어요. 작은 k 는 빠르지만 구별력이 약해요."},{"kind":"english","head":"표현력 정의 한 문장","en":"Expressive power is the ability to distinguish different graph structures.","ko":"표현력은 서로 다른 그래프 구조를 구별하는 능력이다.","tip":"distinguish(구별하다)와 graph structures 두 말을 꼭 넣어요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["**표현력(Expressive power)**은 정확도가 아니에요. 구별할 수 있는 능력이 있느냐예요.","학습에서 그 능력을 다 끌어내는지, 과적합 없이 일반화하는지는 또 다른 문제예요."]}],"pass4":[{"kind":"say","lines":["4회독은 3주차 실습 노트북 Sample_Code_3.ipynb 를 슬라이드와 맞춰 봐요.","셀 번호는 원본 노트북 맨 위 셀을 1로 센 번호예요.","이 노트북은 파이토치 없이 networkx(그래프 도구)만 써요."]},{"kind":"pyterm","name":"import (도구 상자 불러오기)","say":["`import` 는 남이 만들어 둔 도구 상자(라이브러리)를 가져오는 명령이에요.","`import networkx as nx` 는 그래프 도구 상자를 `nx` 라는 짧은 이름으로 불러요.","그다음엔 `nx.cycle_graph(6)` 처럼 점 뒤에 도구 이름을 써서 꺼내 써요."],"example":"import numpy as np\nimport networkx as nx"},{"kind":"code","head":"두 그래프 만들기","file":"Sample_Code_3.ipynb 셀 8 (2. The Failure)","code":"C6    = nx.cycle_graph(6)\nTwoC3 = nx.disjoint_union(nx.cycle_graph(3), nx.cycle_graph(3))\n\nfor name, G in [('C6', C6), ('2 x C3', TwoC3)]:\n    print(f'{name:7s} | nodes {G.number_of_nodes()} | edges {G.number_of_edges()} '\n          f'| components {nx.number_connected_components(G)} '\n          f'| degrees {sorted(d for _, d in G.degree())} '\n          f'| triangles {sum(nx.triangles(G).values()) // 3}')\nprint(f'Isomorphic? {nx.is_isomorphic(C6, TwoC3)}')\n\n# Fixed layouts reused by later figures: a hexagon, and two triangles side by side\nPOS_C6  = nx.circular_layout(C6)\nPOS_2C3 = {}\nfor nodes, cx, start in [([0, 1, 2], -1.0, np.pi), ([3, 4, 5], 1.0, 0.0)]:\n    for i, n in enumerate(nodes):\n        a = start + 2 * np.pi * i / 3\n        POS_2C3[n] = np.array([cx + 0.55 * np.cos(a), 0.55 * np.sin(a)])\n\nfig, axes = plt.subplots(1, 2, figsize=(10, 3.8))\ndraw_graph(C6, POS_C6, axes[0], title='$C_6$  (one 6-cycle)')\ndraw_graph(TwoC3, POS_2C3, axes[1], title='$2 \\\\times C_3$  (two triangles)')\nfig.suptitle('Two non-isomorphic graphs - every node has degree 2', fontsize=13, fontweight='bold')\nplt.tight_layout(); plt.show()","lines":[{"from":1,"to":1,"say":"`=` 는 오른쪽 결과를 왼쪽 이름표(변수)에 담아요. `nx.cycle_graph(6)` 은 노드 6개 고리, $C_6$ 이에요."},{"from":2,"to":2,"say":"삼각형 `nx.cycle_graph(3)` 두 개를 `nx.disjoint_union` 으로 떨어진 채 붙여요. 이게 $2 \\times C_3$."},{"from":3,"to":9,"say":"두 그래프마다 노드 수, 엣지 수, 덩어리 수, 차수 목록, 삼각형 수를 한 줄씩 출력하고, 마지막 줄에서 동형인지 물어요."},{"from":10,"to":17,"say":"뒤 그림에서 계속 쓸 좌표를 정해요. 육각형은 원 모양으로, 삼각형 두 개는 왼쪽과 오른쪽에 나란히 놓아요."},{"from":18,"to":23,"say":"그림판 두 칸을 만들어 두 그래프를 나란히 그리고 화면에 보여 줘요."}],"link":"슬라이드의 '서로 다른 그래프 구조' 한 쌍을 코드로 만든 거예요."}]},{"p":4,"title":"정의: 분리와 근사","terms":["Separation power","Approximation","Universality","Permutation-invariant","Graph isomorphism","Injective"],"pass1":[{"kind":"say","lines":["표현력을 재는 방법은 두 가지가 있어요.","슬라이드의 왼쪽 상자와 오른쪽 상자가 그 두 방법이에요."]},{"kind":"look","head":"두 상자와 아래 결론","boxes":[{"x":0.045,"y":0.225,"w":0.44,"h":0.17,"say":"왼쪽 상자는 서로 다른 두 그래프에 서로 다른 답을 내는지 봐요. 이걸 **분리 능력(Separation power)**이라고 해요."},{"x":0.515,"y":0.225,"w":0.44,"h":0.37,"say":"오른쪽 상자는 우리가 원하는 계산을 거의 똑같이 흉내 내는지 봐요. 이걸 **근사(Approximation)**, 또는 **보편성(Universality)**이라고 해요."},{"x":0.045,"y":0.62,"w":0.91,"h":0.17,"say":"아래 상자는 수학자들이 증명한 사실(정리)이에요. 조건만 맞으면 두 방법이 결국 같은 이야기라는 내용이에요."}]},{"kind":"say","lines":["두 방법이 같은 이야기라면 더 쉬운 쪽만 보면 되겠죠?","그래서 이 강의에서 표현력은 '서로 다른 그래프에 다른 답을 내는 힘', 곧 분리 능력을 뜻해요."]}],"pass2":[{"kind":"look","head":"슬라이드 상자 차례로","boxes":[{"x":0.03,"y":0.145,"w":0.26,"h":0.055,"say":"'표현력을 말하는 두 방법'. 왼쪽 상자와 오른쪽 상자가 그 둘이에요."},{"x":0.045,"y":0.225,"w":0.44,"h":0.17,"say":"왼쪽: **분리 능력(Separation power)**. 모델 $f$ 가 $f(G) \\neq f(H)$ 이면 두 그래프를 가른 거예요."},{"x":0.11,"y":0.4,"w":0.32,"h":0.09,"say":"$Sep(F)$ 는 가족 $F$ 가 가를 수 있는 동형 아닌 쌍 목록, $F \\le G$ 는 목록 포함 관계."},{"x":0.515,"y":0.225,"w":0.44,"h":0.37,"say":"오른쪽: **근사(Approximation)**, 즉 **보편성(Universality)**. 어떤 정답 함수든 흉내 내나?"},{"x":0.045,"y":0.62,"w":0.91,"h":0.17,"say":"정리: **순열 불변(Permutation-invariant)** 가족에서 보편적이다 ⟺ 동형 아닌 쌍을 모두 분리한다."},{"x":0.04,"y":0.815,"w":0.91,"h":0.07,"say":"그래서 쉬운 조합론 질문(무엇을 가르나)만 풀면 돼요. 이 강의에서 표현력 = 분리 능력."}]},{"kind":"formula","head":"분리 목록 Sep(F)","tex":"Sep(F) = \\{(G,H) : G \\ncong H,\\ \\exists f \\in F,\\ f(G) \\neq f(H)\\}","parts":[{"sym":"F","say":"모델 하나가 아니라 모델 가족. 예: 가중치를 뭘로 하든 GCN 전부"},{"sym":"G \\ncong H","say":"G 와 H 가 동형이 아님. 진짜로 다른 그래프"},{"sym":"\\exists f \\in F","say":"가족 안에 그런 모델이 적어도 하나 있다"},{"sym":"f(G) \\neq f(H)","say":"두 그래프에 서로 다른 답을 낸다"}],"whole":"진짜 다른 그래프 쌍 중, 가족 안 누군가가 가를 수 있는 쌍을 모두 모은 목록이에요."},{"kind":"formula","head":"표현력 비교","tex":"F \\le G \\iff Sep(F) \\subseteq Sep(G)","parts":[{"sym":"F \\le G","say":"가족 G 의 표현력이 F 이상. 여기 G 는 그래프가 아니라 다른 모델 가족"},{"sym":"\\iff","say":"양쪽이 같은 말(필요충분)"},{"sym":"\\subseteq","say":"왼쪽 목록이 오른쪽 목록 안에 전부 들어감"}],"whole":"F 가 가르는 쌍을 G 도 모두 가르면, G 가 F 보다 강하거나 같아요."},{"kind":"formula","head":"근사(보편성) 식","tex":"\\forall \\varepsilon > 0,\\ \\forall g \\in C_{inv}(K),\\ \\exists f \\in F : \\sup_{G \\in K} |f(G) - g(G)| < \\varepsilon","parts":[{"sym":"\\varepsilon","say":"허용 오차. 아주 작은 양수"},{"sym":"g \\in C_{inv}(K)","say":"흉내 낼 정답 함수. 연속이고 노드 번호를 섞어도 안 변함"},{"sym":"\\exists f \\in F","say":"가족 안에서 모델 f 를 찾을 수 있다"},{"sym":"\\sup_{G \\in K} |f(G) - g(G)|","say":"범위 안 모든 그래프 중 가장 크게 틀린 정도"}],"whole":"오차를 아무리 작게 잡아도 그보다 덜 틀리는 모델이 있으면 **보편성(Universality)**이 있어요."},{"kind":"steps","head":"작은 예: Sep 직접 만들기","steps":["노드 수: P3 3, K3 3, S 4, P4 4. 엣지 수: P3 2, K3 3, S 3, P4 3","(P3, K3): 노드 수 같고 엣지 수 2 대 3. F1 은 못 가르고 F2 는 가름","(P3, S), (P3, P4), (K3, S), (K3, P4): 노드 수가 달라 둘 다 가름","(S, P4): 노드 4, 엣지 3 으로 같아서 둘 다 못 가름","$Sep(F1)$ 4쌍은 $Sep(F2)$ 5쌍 안에 들어가요. 그래서 $F1 \\le F2$"],"answer":"F2 가 F1 이상이에요. (S, P4) 는 둘 다 못 가르니 '가장 큰 차수(3 대 2)' 같은 함수도 근사 못 해요.","given":"P3 일렬 3개, K3 삼각형, S 별(가운데 1 + 3), P4 일렬 4개. F1 = {노드 수}, F2 = {노드 수, 엣지 수}"},{"kind":"figure","head":"분리 목록끼리의 포함 관계","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\">\n<rect class=\"box\" x=\"10\" y=\"10\" width=\"460\" height=\"250\" rx=\"14\"/>\n<text class=\"tm\" x=\"22\" y=\"34\" font-size=\"14\">동형 아닌 그래프 쌍 전체<\/text>\n<rect class=\"box b1\" x=\"28\" y=\"48\" width=\"340\" height=\"190\" rx=\"12\"/>\n<text class=\"tb b1\" x=\"298\" y=\"74\" font-size=\"16\" text-anchor=\"middle\">Sep(F2): 5쌍<\/text>\n<text class=\"t b1\" x=\"310\" y=\"150\" font-size=\"14\" text-anchor=\"middle\">(P3,K3)<\/text>\n<rect class=\"box2 b2\" x=\"44\" y=\"90\" width=\"212\" height=\"132\" rx=\"10\"/>\n<text class=\"tb b2\" x=\"150\" y=\"116\" font-size=\"16\" text-anchor=\"middle\">Sep(F1): 4쌍<\/text>\n<text class=\"t b2\" x=\"150\" y=\"154\" font-size=\"14\" text-anchor=\"middle\">(P3,S) (P3,P4)<\/text>\n<text class=\"t b2\" x=\"150\" y=\"184\" font-size=\"14\" text-anchor=\"middle\">(K3,S) (K3,P4)<\/text>\n<text class=\"t b3\" x=\"420\" y=\"140\" font-size=\"14\" text-anchor=\"middle\">(S,P4)<\/text>\n<text class=\"tm b3\" x=\"420\" y=\"164\" font-size=\"14\" text-anchor=\"middle\">둘 다 못 가름<\/text>\n<text class=\"tb b3\" x=\"240\" y=\"254\" font-size=\"14\" text-anchor=\"middle\">안쪽이 바깥쪽에 포함: F1 ≤ F2<\/text>\n<\/svg>","caption":"안쪽 목록을 가진 가족(F1)이 더 약해요.","builds":3},{"kind":"prof","when":"3주차 화요일 수업","lines":["표현력은 두 측면이래요. 다른 입력에 다른 벡터 표현을 줄 수 있나,","그리고 입력의 특징을 벡터 표현에 충분히 다 담을 수 있나.","둘은 조금 상충해요. 구별만 극단으로 높이면 '비슷하다'고 말하기 어려워요.","이번 주는 그중 '다른 것을 다르다고 말하기'에 초점을 둔대요."]},{"kind":"mining","src":"마이닝 9강 Graph Kernels","lines":["특징 함수가 **단사(Injective)**면 '완전한 그래프 커널'이라 불렀어요.","완전한 커널 계산은 **그래프 동형(Graph isomorphism)** 판정만큼 어렵다고 했죠.","모든 다른 그래프를 다르게 보는 건 원래 어려운 목표예요. 오늘의 분리 능력과 같은 이야기."]}],"pass3":[{"kind":"english","head":"예상 서술형 (올해 새 내용, 기출 없음)","en":"Expressive power means separation or approximation; for permutation-invariant classes the two are equivalent.","ko":"표현력은 분리나 근사를 뜻하고, 순열 불변 클래스에서는 둘이 동치다. 그래서 분리만 본다.","tip":"separation, approximation, permutation-invariant, equivalent 네 단어가 뼈대예요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["$F \\le G$ 의 $G$ 는 그래프가 아니라 다른 모델 가족이에요. 같은 글자를 두 뜻으로 썼어요.","$\\le$ 는 '성능이 좋다'가 아니라 분리 목록의 포함 관계예요.","영어판 참고문헌 'Lei, C.' 는 'Chen, L.' 이 맞아요. 한국어판은 고쳐져 있어요."]},{"kind":"check","q":"**분리 능력(Separation power)**의 뜻으로 맞는 것은?","choices":["원하는 함수를 오차 없이 흉내 내는 힘","동형이 아닌 두 그래프에 서로 다른 답을 내는 힘","학습이 빨리 끝나는 성질","노드 번호를 섞어도 결과가 같은 성질"],"a":1,"why":"분리 = 다른 쌍에 다른 답. 1번은 **근사(Approximation)**, 4번은 **순열 불변(Permutation-invariant)**이에요."}],"pass4":[]},{"p":5,"title":"그래프 동형 문제","terms":["Graph isomorphism","Invariant","Polynomial time","NP-complete","Node degree","Graphlet"],"pass1":[{"kind":"say","lines":["두 그래프가 겉보기엔 달라 보여도 사실은 같은 모양일 수 있어요.","점에 붙은 이름표만 바꿔 붙이면 연결 모양이 똑같아지는 관계, 이걸 **그래프 동형(Graph isomorphism)**이라고 해요.","두 분자가 같은 구조인지 알아볼 때처럼, 모양이 같은 그래프인지 묻는 일은 여러 곳에서 중요해요.","그런데 이 질문은 빠르게 푸는 방법(**다항 시간(Polynomial time)** 풀이)이 아직 없는 어려운 문제예요."]},{"kind":"analogy","head":"이름만 다른 두 반의 친구 관계도","scene":"1반과 2반의 친구 관계도가 한 장씩 있어요. 1반 그림엔 철수, 영희 같은 이름이, 2반 그림엔 다른 이름이 적혀 있어요. 그런데 이름을 가리고 보면 누가 몇 명과 친한지, 누구끼리 이어졌는지가 완전히 똑같아요. 이럴 때 두 관계도는 같은 모양이고, 그래프에서는 이걸 동형이라고 불러요.","map":[["학생 이름표","노드 번호"],["친구 사이를 잇는 선","엣지"],["이름만 다른 같은 관계도","**그래프 동형(Graph isomorphism)**"]]},{"kind":"look","head":"슬라이드의 두 그래프","boxes":[{"x":0.2,"y":0.27,"w":0.19,"h":0.23,"say":"왼쪽 그래프는 점 5개가 선 5개로 이어져 있어요."},{"x":0.52,"y":0.27,"w":0.19,"h":0.23,"say":"오른쪽 그래프도 점 5개인데, 선이 하나 더 있어요."},{"x":0.61,"y":0.31,"w":0.025,"h":0.14,"say":"바로 이 세로선 하나가 차이예요. 그래서 두 그래프는 같은 모양이 아니에요."}]}],"pass2":[{"kind":"look","head":"슬라이드 글자와 그림","boxes":[{"x":0.03,"y":0.14,"w":0.37,"h":0.06,"say":"고전적인 표현력 시험은 **그래프 동형(Graph isomorphism)**. 같은지 다른지 맞히게 해 봐요."},{"x":0.07,"y":0.21,"w":0.45,"h":0.05,"say":"두 그래프가 주어질 때 동형인지 판별할 수 있을까?"},{"x":0.2,"y":0.27,"w":0.19,"h":0.23,"say":"왼쪽: 선 1-2, 1-5, 2-5, 5-4, 4-3. 선 5개예요."},{"x":0.52,"y":0.27,"w":0.19,"h":0.23,"say":"오른쪽: 같은 모양에 선이 하나 더 있어 선 6개예요."},{"x":0.61,"y":0.31,"w":0.025,"h":0.14,"say":"차이는 이 세로선 2-4 하나예요."},{"x":0.07,"y":0.61,"w":0.73,"h":0.06,"say":"**다항 시간(Polynomial time)** 풀이는 아직 모르고, **NP-완전(NP-complete)**임도 증명 안 됐어요."}]},{"kind":"formula","head":"동형의 정확한 정의","tex":"G \\cong H \\iff \\exists\\, \\pi : V(G) \\to V(H),\\ (u,v) \\in E(G) \\iff (\\pi(u), \\pi(v)) \\in E(H)","parts":[{"sym":"G \\cong H","say":"G 와 H 가 동형이다"},{"sym":"V(G),\\ E(G)","say":"G 의 노드 목록, 엣지 목록"},{"sym":"\\pi : V(G) \\to V(H)","say":"노드끼리 빠짐도 겹침도 없이 1대1로 짝짓는 규칙"},{"sym":"(u,v) \\in E(G) \\iff (\\pi(u), \\pi(v)) \\in E(H)","say":"이어진 쌍은 짝꿍도 이어지고, 안 이어진 쌍은 짝꿍도 안 이어짐"}],"whole":"선을 전부 그대로 옮기는 1대1 짝짓기가 하나라도 있으면 동형이에요."},{"kind":"compare","head":"슬라이드 두 그래프의 **불변량(Invariant)**","cols":["확인할 것","왼쪽","오른쪽"],"rows":[["노드 수","5","5"],["엣지 수","5","6"],["차수 (1, 2, 3, 4, 5번)","2, 2, 1, 2, 3","2, 3, 1, 3, 3"],["차수 합","10 = 2 × 5","12 = 2 × 6"]]},{"kind":"steps","head":"동형인 예, 그리고 어려운 이유","steps":["가운데 노드끼리 짝: b 를 x 로","나머지 짝: a 를 y 로, c 를 z 로","(a, b) 는 (y, x) 로, (b, c) 는 (x, z) 로. 둘 다 Q 에 있어요","안 이어진 (a, c) 는 (y, z) 로. Q 에서도 안 이어져요","짝짓기 경우의 수는 $n!$($1 \\times 2 \\times \\cdots \\times n$): 5개면 120, 10개면 3,628,800, 20개면 약 $2.4 \\times 10^{18}$"],"answer":"P 와 Q 는 동형이에요. 하지만 큰 그래프는 전부 해 보는 방법이 금방 불가능해져요.","given":"그래프 P: a-b, b-c (b 가 가운데). 그래프 Q: x-y, x-z (x 가 가운데)"},{"kind":"prof","when":"3주차 화요일 수업","lines":["작은 그래프는 눈으로 봐도 다르다는 걸 알지만,","그래프가 커지면 계산 복잡도가 굉장히 높아지는 문제라고 했어요.","중심 질문: 구조가 다르면 GNN 이 '다른 그래프'라고 확실히 말할 수 있나?"]},{"kind":"mining","src":"마이닝 9강 Graph Kernels, 7강 Subgraph Mining","lines":["동형이면 노드 수, 엣지 수, 차수 같은 **불변량(Invariant)**이 같아야 해요.","하나라도 다르면 동형 아님. 전부 같다고 동형이라는 보장은 없어요.","'작은 그래프가 큰 그래프 안에 있나'를 묻는 부분 그래프 동형은 NP-완전이었어요."]}],"pass3":[{"kind":"english","head":"서술형 한 문장","en":"Graph isomorphism asks whether a bijection between node sets preserves all edges; no polynomial-time algorithm is known.","ko":"그래프 동형은 모든 엣지를 보존하는 노드 일대일 대응이 있는지 묻는 문제이고, 다항 시간 알고리즘은 알려져 있지 않다.","tip":"'is not known' 을 쓰세요. 'does not exist' 는 틀린 표현이에요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["영어 원문 'does not exist' 는 틀려요. **다항 시간(Polynomial time)** 풀이가 없다고 증명된 적이 없어요.","**NP-완전(NP-complete)**이라는 증명도 없어요. 쉽다는 증명도, 가장 어렵다는 증명도 없는 문제예요.","**불변량(Invariant)**이 모두 같아도 동형이 아닐 수 있어요. p.3 의 $C_6$ 과 $2 \\times C_3$ 이 예예요."]},{"kind":"check","q":"왼쪽 그래프(선 5개)와 오른쪽 그래프(선 6개)가 동형이 아니라고 바로 말할 수 있는 이유는?","choices":["노드 수가 달라서","엣지 수가 달라서","노드 번호가 달라서","그림 크기가 달라서"],"a":1,"why":"엣지 수는 **불변량(Invariant)**이에요. 5 대 6 으로 다르니 바로 동형 아님. 노드 수는 둘 다 5예요."}],"pass4":[{"kind":"pyterm","name":"for 반복문과 print","say":["`for x in 목록:` 은 목록에서 하나씩 꺼내 x 에 담고, 들여 쓴 줄을 반복해요.","`print(...)` 는 화면에 출력해요. `f'...{x}...'` 처럼 f 를 붙이면 중괄호 자리에 값이 들어가요."],"example":"for x in [1, 2, 3]:\n    print(f'x = {x}')","out":"x = 1\nx = 2\nx = 3"},{"kind":"code","head":"불변량을 세고 동형인지 판정","file":"Sample_Code_3.ipynb 셀 8 (2. The Failure)","code":"C6    = nx.cycle_graph(6)\nTwoC3 = nx.disjoint_union(nx.cycle_graph(3), nx.cycle_graph(3))\n\nfor name, G in [('C6', C6), ('2 x C3', TwoC3)]:\n    print(f'{name:7s} | nodes {G.number_of_nodes()} | edges {G.number_of_edges()} '\n          f'| components {nx.number_connected_components(G)} '\n          f'| degrees {sorted(d for _, d in G.degree())} '\n          f'| triangles {sum(nx.triangles(G).values()) // 3}')\nprint(f'Isomorphic? {nx.is_isomorphic(C6, TwoC3)}')\n\n# Fixed layouts reused by later figures: a hexagon, and two triangles side by side\nPOS_C6  = nx.circular_layout(C6)\nPOS_2C3 = {}\nfor nodes, cx, start in [([0, 1, 2], -1.0, np.pi), ([3, 4, 5], 1.0, 0.0)]:\n    for i, n in enumerate(nodes):\n        a = start + 2 * np.pi * i / 3\n        POS_2C3[n] = np.array([cx + 0.55 * np.cos(a), 0.55 * np.sin(a)])\n\nfig, axes = plt.subplots(1, 2, figsize=(10, 3.8))\ndraw_graph(C6, POS_C6, axes[0], title='$C_6$  (one 6-cycle)')\ndraw_graph(TwoC3, POS_2C3, axes[1], title='$2 \\\\times C_3$  (two triangles)')\nfig.suptitle('Two non-isomorphic graphs - every node has degree 2', fontsize=13, fontweight='bold')\nplt.tight_layout(); plt.show()","lines":[{"from":1,"to":2,"say":"C6 는 점 6개가 한 바퀴 이어진 육각형, TwoC3 는 삼각형 두 개를 따로 놓은 그래프예요. `nx.` 는 networkx 기능이에요."},{"from":4,"to":4,"say":"목록 속 (이름, 그래프) 쌍 2개를 하나씩 꺼내 name, G 에 담아 반복해요."},{"from":5,"to":5,"say":"노드 수와 엣지 수를 출력해요. `G.number_of_nodes()` 처럼 점 뒤 함수로 그래프에 물어요."},{"from":6,"to":8,"say":"연결 덩어리 수, 정렬한 차수 목록, 삼각형 수도 세요. 모두 **불변량(Invariant)**이에요."},{"from":9,"to":9,"say":"`nx.is_isomorphic` 은 두 그래프가 동형인지 정확히 판정해요."},{"from":10,"to":17,"say":"뒤 그림에서 계속 쓸 좌표를 정해요. 육각형은 원 모양으로, 삼각형 두 개는 왼쪽과 오른쪽에 나란히 놓아요."},{"from":18,"to":23,"say":"그림판 두 칸을 만들어 두 그래프를 나란히 그리고 화면에 보여 줘요."}],"link":"슬라이드의 **그래프 동형(Graph isomorphism)** 질문을 함수 하나로 물어본 거예요."},{"kind":"steps","head":"노트북 출력 읽기","steps":["C6: nodes 6, edges 6, components 1, degrees 모두 2, triangles 0","2 x C3: nodes 6, edges 6, components 2, degrees 모두 2, triangles 2","Isomorphic? False"],"answer":"노드, 엣지, 차수는 같지만 덩어리 수와 삼각형 수가 달라서 동형이 아니에요."}]},{"p":6,"title":"더 쉬운 문제: 노드가 보는 나무","terms":["Local neighborhood structure","Computational graph","Rooted subtree","Root","Aggregation","Unfolding tree","Receptive field","Hop"],"pass1":[{"kind":"say","lines":["그래프 두 개를 통째로 비교하는 건 너무 어려워요. 그래서 문제를 작게 줄여요.","한 그래프 안에서 노드 두 개를 골라요. 둘의 주변 모양이 다르면 GNN이 늘 가려낼 수 있을까요?","이걸 알려면 GNN이 노드 하나를 볼 때 무엇을 보는지 알아야 해요.","GNN이 보는 건 그 노드에서 이웃, 이웃의 이웃을 차례로 펼쳐 그린 나무 그림이에요."]},{"kind":"look","head":"나무 그림 읽기","boxes":[{"x":0.37,"y":0.24,"w":0.2,"h":0.22,"say":"가운데는 점 5개짜리 예시 그래프예요. 앞으로 여러 쪽에 걸쳐 이 그래프를 계속 써요."},{"x":0.05,"y":0.49,"w":0.16,"h":0.39,"say":"아래 나무 하나가 노드 1이 보는 모습이에요. 맨 위가 노드 1, 그 아래가 이웃, 또 그 아래가 이웃의 이웃이에요."}]},{"kind":"analogy","head":"묻고 또 묻는 소식 나무","scene":"지우는 반 소식이 궁금해서 친구 2명에게 물어요. 그 친구들도 잘 몰라서 각자 자기 친구들에게 물어보고, 들은 걸 모아 지우에게 전해 줘요. 이렇게 묻고 전한 길을 그리면 지우가 맨 위에 있는 나무 모양이 돼요. 지우가 알 수 있는 건 이 나무에 담긴 이야기뿐이에요.","map":[["지우","**뿌리(Root)** 노드, 즉 나무 맨 위 주인공"],["친구에게 한 번 묻고 전해 받기","GNN 한 층"],["묻고 전한 길 전체","**계산 그래프(Computational graph)**, 다른 이름은 **뿌리 있는 부분 트리(Rooted subtree)**"]]}],"pass2":[{"kind":"look","head":"슬라이드 그림 읽기","boxes":[{"x":0.03,"y":0.14,"w":0.75,"h":0.06,"say":"이웃 구조가 다른 두 노드를 항상 가르는 GNN이 있을까? **국소 이웃 구조(Local neighborhood structure)** 질문이에요."},{"x":0.37,"y":0.24,"w":0.2,"h":0.22,"say":"가운데 그래프는 p.5 왼쪽과 같아요. p.16 까지 계속 이 그래프를 써요."},{"x":0.05,"y":0.49,"w":0.16,"h":0.39,"say":"1번 나무: 뿌리 1 아래 이웃 2, 5. 그 아래 2의 이웃 1, 5 와 5의 이웃 1, 2, 4."},{"x":0.07,"y":0.595,"w":0.1,"h":0.025,"say":"검은 막대 = GNN 한 층의 **집계(Aggregation)**. 화살표는 위로, 계산은 아래에서 위로."},{"x":0.46,"y":0.49,"w":0.23,"h":0.39,"say":"3번은 이웃 4 하나, 4번은 3, 5 둘. 모든 나무가 2단인 건 층이 2개라서예요."},{"x":0.72,"y":0.49,"w":0.2,"h":0.39,"say":"5번 나무: 이웃 1, 2, 4 아래에 각자의 이웃이 매달려 가장 넓어요."}]},{"kind":"points","head":"나무 읽는 규칙","items":["맨 위 동그라미가 **뿌리(Root)**, 임베딩을 계산할 주인공이에요.","나무 높이는 층 수가, 가지 수는 이웃 관계가 정해요.","같은 번호는 같은 노드의 복사본이에요. 맨 아래 1 은 정보가 되돌아온 거예요.","이 나무가 **계산 그래프(Computational graph)**, 노트북에선 **펼침 트리(Unfolding tree)**라 불러요."]},{"kind":"compare","head":"번호를 지우고 모양만 보면","cols":["뿌리","1층 자식","모양 코드(자식들의 차수 묶음)","잎 개수"],"rows":[["1","2, 5","{2, 3}","5"],["2","1, 5","{2, 3}","5"],["3","4","{2}","2"],["4","3, 5","{1, 3}","4"],["5","1, 2, 4","{2, 2, 2}","6"]]},{"kind":"points","head":"표에서 보이는 것","items":["1번과 2번은 모양 코드가 {2, 3} 으로 같아서 번호 없이는 구별이 안 돼요.","1번과 4번은 자식 2개로 같지만 그 아래가 {2, 3} 대 {1, 3} 으로 달라요.","모양 코드는 이웃들의 차수 묶음이에요. p.13 에서 다시 만나요.","잎 개수 5, 5, 2, 4, 6 은 p.16 합 GNN 결과와 똑같아요."]},{"kind":"prof","when":"3주차 화요일 수업","lines":["그래프 둘을 비교하는 것뿐 아니라, 한 그래프 안의 노드 1 과 2, 1 과 5 가","같은 노드인지 다른 노드인지 모델이 알아보는지도 본다고 했어요.","그래프 전체는 상상하기 어려우니 노드 수준부터 따져 본 거래요."]}],"pass3":[{"kind":"warn","head":"헷갈리기 쉬운 점","items":["나무 속 같은 번호는 복사본이에요. 나무는 두 동그라미가 같은 노드라는 걸 몰라요.","원래 그래프의 1-2-5 삼각형 같은 '도는 길'은 나무에 없어요. 대신 같은 노드가 여러 번 나와요.","대상은 이웃 구조가 다른 쌍이에요. 1번과 2번처럼 원래 같은 쌍을 못 가르는 건 실패가 아니에요."]},{"kind":"check","q":"2층 GNN에서 노드 3의 **계산 그래프(Computational graph)** 맨 아래 줄 잎은?","choices":["3, 5","4","1, 2, 4","3, 4, 5"],"a":0,"why":"3의 이웃은 4 하나, 4의 이웃은 3과 5예요. 그래서 뿌리 3, 가운데 4, 맨 아래 3, 5."}],"pass4":[{"kind":"pyterm","name":"튜플(tuple)","say":["`(0, 1, 0)` 처럼 소괄호에 값을 늘어놓은 묶음이에요. 리스트와 비슷하지만 못 바꿔요.","`t[-1]` 은 마지막 원소, `t[:-1]` 은 마지막만 뺀 앞부분이에요.","`t + (5,)` 는 뒤에 하나를 붙인 새 튜플. 원소 하나짜리는 쉼표가 꼭 필요해요."],"example":"t = (0, 1)\nprint(t[-1], t[:-1], t + (0,))","out":"1 (0,) (0, 1, 0)"},{"kind":"code","head":"계산 그래프를 만드는 함수 (1/2)","file":"Sample_Code_3.ipynb 셀 10 (3.1 What a Node Actually Sees) (1/2)","code":"def unfolding_tree(G, root, depth):\n    \"\"\"\n    Computational graph of `root` for a `depth`-layer GNN.\n    Tree nodes are walks starting at `root`; attribute 'orig' is the graph node a copy stands for.\n    Edges point child -> parent, the direction messages flow.\n    \"\"\"\n    T = nx.DiGraph()\n    T.add_node((root,), orig=root, level=0)\n    frontier = [(root,)]\n    for d in range(1, depth + 1):\n        frontier = [walk + (u,) for walk in frontier for u in sorted(G[walk[-1]])]\n        for walk in frontier:\n            T.add_node(walk, orig=walk[-1], level=d)\n            T.add_edge(walk, walk[:-1])\n    return T\n\n\ndef draw_tree(T, ax, uniform=False, title=None, node_size=460, font_size=9):\n    \"\"\"Draw a tree with the root on top. uniform=True paints every copy gray (only shape matters).\"\"\"\n    pos, next_x = {}, [0.0]\n\n    def place(n):                                   # each parent centered above its children\n        kids = sorted(T.predecessors(n))\n        if kids:\n            x = float(np.mean([place(k) for k in kids]))\n        else:\n            x, next_x[0] = next_x[0], next_x[0] + 1\n        pos[n] = (x, -T.nodes[n]['level'])\n        return x\n\n    place(next(n for n in T if T.nodes[n]['level'] == 0))\n    nodes = list(T.nodes())\n    fill = [color_of(0 if uniform else T.nodes[n]['orig'] + 1) for n in nodes]\n    nx.draw_networkx_edges(T, pos, ax=ax, arrows=False, edge_color=C_EDGE, width=1.4)\n    nx.draw_networkx_nodes(T, pos, nodelist=nodes, ax=ax, node_color=fill,\n                           edgecolors=C_DARK, linewidths=1.1, node_size=node_size)\n    for n, f in zip(nodes, fill):\n        ax.text(*pos[n], str(T.nodes[n]['orig']), ha='center', va='center',\n                fontsize=font_size, color=ink(f))\n    if title:\n        ax.set_title(title)\n    ax.set_axis_off()\n    ax.margins(0.08)\n","lines":[{"from":1,"to":1,"say":"`def 이름(재료):` 는 함수(다시 쓸 계산 묶음)를 만드는 줄. 그래프 G, 뿌리 root, 층 수 depth 를 받아요."},{"from":2,"to":6,"say":"따옴표 세 개 사이는 설명문(docstring). 실행에는 영향이 없어요."},{"from":7,"to":9,"say":"빈 방향 그래프 T 에 **뿌리(Root)** `(root,)` 를 넣어요. frontier 는 지금 맨 아래 줄 목록이에요."},{"from":10,"to":11,"say":"층마다: 맨 아래 복사본의 마지막 노드 `walk[-1]` 의 이웃 u 를 하나씩 매달아 새 맨 아래 줄을 만들어요."},{"from":12,"to":14,"say":"새 복사본마다 원래 번호 orig 와 깊이 level 을 적고, 자식에서 부모로 엣지를 그어요."},{"from":15,"to":15,"say":"`return T` 는 완성된 나무를 돌려줘요."},{"from":18,"to":31,"say":"draw_tree 함수의 시작 부분이에요. place 가 자식들을 먼저 배치하고, 부모를 그 가운데 위에 놓아 좌표를 정해요."},{"from":32,"to":44,"say":"노드 색을 정하고 선, 동그라미, 번호 글자를 그려요. uniform=True 면 모두 회색이라 모양만 보여요."}],"link":"p.6 나무 5그루를 만드는 규칙 그대로예요. 층 하나 = 맨 아래마다 이웃 복사본 매달기, 즉 **펼침 트리(Unfolding tree)**."},{"kind":"code","head":"계산 그래프를 만드는 함수 (2/2)","file":"Sample_Code_3.ipynb 셀 10 (3.1 What a Node Actually Sees) (2/2)","code":"\nG_demo = nx.Graph([(0, 1), (0, 2), (1, 2), (1, 3), (2, 4), (3, 4), (4, 5)])\nPOS_DEMO = nx.spring_layout(G_demo, seed=3)\n\nfig = plt.figure(figsize=(14, 4.4))\ngs = fig.add_gridspec(1, 3, width_ratios=[1, 1.25, 1.6])\ndraw_graph(G_demo, POS_DEMO, fig.add_subplot(gs[0]), colors={v: v + 1 for v in G_demo},\n           highlight=0, title='The graph (target node 0)')\nfor k, depth in enumerate([1, 2]):\n    T = unfolding_tree(G_demo, 0, depth)\n    draw_tree(T, fig.add_subplot(gs[k + 1]),\n              title=f'Computational graph of node 0, {depth} layer(s)\\n'\n                    f'({T.number_of_nodes()} tree nodes)')\nplt.tight_layout(); plt.show()\n\nsizes = [unfolding_tree(G_demo, 0, L).number_of_nodes() for L in range(6)]\nprint(f'Tree size for L = 0..5 layers: {sizes}   (the graph has only {G_demo.number_of_nodes()} nodes)')","lines":[{"from":1,"to":4,"say":"예시 그래프 G_demo 를 (노드, 노드) 쌍 목록으로 만들고 그릴 좌표를 정해요."},{"from":5,"to":14,"say":"그림 세 칸에 원래 그래프와 1층, 2층 계산 그래프를 나란히 그려요."},{"from":15,"to":17,"say":"층 수 0 부터 5 까지 나무 크기를 세서 출력해요. 그래프 노드는 6개뿐인데 나무는 금방 커져요."}]}]},{"p":7,"title":"복습: GNN 한 층","terms":["Message passing","Aggregation","Multiset","GIN"],"pass1":[{"kind":"say","lines":["지난주에 배운 **메시지 패싱(Message passing)** GNN의 한 층을 다시 떠올려 봐요.","첫째, 이웃들과 나는 각자 지금 가진 정보로 쪽지(메시지)를 써요.","둘째, 이웃 쪽지를 봉투 하나에 모아 내 쪽지와 합치고 나를 새로 고쳐요. 이 모으기를 **집계(Aggregation)**라고 해요.","오늘 따질 구별하는 힘은 이 둘째 단계, 쪽지를 어떻게 모으느냐에서 갈려요."]},{"kind":"analogy","head":"모둠장이 발표문 쓰기","scene":"모둠원 4명이 각자 조사한 내용을 쪽지에 적어 모둠장에게 줘요. 모둠장은 쪽지를 한데 모아 자기 생각과 합쳐서 발표문을 새로 써요. 쪽지를 꼼꼼히 합치면 정보가 다 남고, 대충 합치면 일부가 사라져요. GNN도 쪽지를 어떻게 모으느냐에 따라 남는 정보가 달라요.","map":[["쪽지 쓰기","메시지 만들기"],["쪽지를 모아 합치기","**집계(Aggregation)**"],["새로 쓴 발표문","노드를 설명하는 새 숫자 목록(임베딩)"]]}],"pass2":[{"kind":"look","head":"슬라이드 식과 그림","boxes":[{"x":0.03,"y":0.14,"w":0.29,"h":0.06,"say":"**메시지 패싱(Message passing)** GNN 에 집중해요. 오늘 표현력은 이 방식에 대한 이야기예요."},{"x":0.07,"y":0.22,"w":0.33,"h":0.045,"say":"(1) 메시지: 각 노드가 메시지를 계산해요."},{"x":0.28,"y":0.275,"w":0.36,"h":0.07,"say":"지난 층 임베딩으로 이번 층 메시지를 만들어요. u 는 v 의 이웃이거나 v 자신."},{"x":0.07,"y":0.36,"w":0.33,"h":0.05,"say":"(2) 집계: 이웃에게서 온 메시지를 모아요."},{"x":0.28,"y":0.415,"w":0.35,"h":0.08,"say":"이웃 메시지 봉투와 내 메시지를 AGG 에 넣어 새 임베딩을 만들어요."},{"x":0.3,"y":0.54,"w":0.3,"h":0.33,"say":"색 동그라미 = 이웃, 회색 막대 = 메시지, 큰 상자 = 집계, 위 황토색 = 새 임베딩."}]},{"kind":"formula","head":"(1) 메시지 식","tex":"\\mathbf{m}_u^{(l)} = \\mathrm{MSG}^{(l)}\\left(\\mathbf{h}_u^{(l-1)}\\right),\\ u \\in \\{N(v) \\cup v\\}","parts":[{"sym":"\\mathbf{h}_u^{(l-1)}","say":"노드 u 의 지난 층 임베딩(지난 라운드 점수표)"},{"sym":"(l)","say":"거듭제곱이 아니라 층 번호"},{"sym":"\\mathrm{MSG}^{(l)}","say":"l 층에서 쪽지 쓰는 규칙. 보통 가중치 행렬 곱"},{"sym":"u \\in \\{N(v) \\cup v\\}","say":"u 는 v 의 이웃이거나 v 자신"}],"whole":"이웃들과 나 자신이 지난 층 값으로 이번 층 쪽지를 써요."},{"kind":"formula","head":"(2) 집계 식","tex":"\\mathbf{h}_v^{(l)} = \\mathrm{AGG}^{(l)}\\left(\\left\\{\\mathbf{m}_u^{(l)},\\ u \\in N(v)\\right\\},\\ \\mathbf{m}_v^{(l)}\\right)","parts":[{"sym":"\\left\\{\\mathbf{m}_u^{(l)},\\ u \\in N(v)\\right\\}","say":"이웃 쪽지 봉투. 순서 없고 개수는 세는 **멀티셋(Multiset)**"},{"sym":"\\mathbf{m}_v^{(l)}","say":"내가 나에게 쓴 쪽지"},{"sym":"\\mathrm{AGG}^{(l)}","say":"봉투와 내 쪽지를 합치는 규칙. 합, 평균, 최댓값 등"},{"sym":"\\mathbf{h}_v^{(l)}","say":"노드 v 의 l 층 새 임베딩"}],"whole":"이웃 쪽지 봉투와 내 쪽지를 모아 내 새 점수표를 만들어요."},{"kind":"figure","head":"한 층의 계산 흐름","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\">\n<circle class=\"n\" cx=\"120\" cy=\"235\" r=\"16\"/>\n<circle class=\"n\" cx=\"190\" cy=\"235\" r=\"16\"/>\n<circle class=\"n\" cx=\"260\" cy=\"235\" r=\"16\"/>\n<circle class=\"n2\" cx=\"360\" cy=\"235\" r=\"16\"/>\n<text class=\"tl\" x=\"120\" y=\"240\" font-size=\"14\" text-anchor=\"middle\">1<\/text>\n<text class=\"tl\" x=\"190\" y=\"240\" font-size=\"14\" text-anchor=\"middle\">2<\/text>\n<text class=\"tl\" x=\"260\" y=\"240\" font-size=\"14\" text-anchor=\"middle\">3<\/text>\n<text class=\"tl\" x=\"360\" y=\"240\" font-size=\"14\" text-anchor=\"middle\">5<\/text>\n<text class=\"t\" x=\"10\" y=\"240\" font-size=\"14\">이웃<\/text>\n<text class=\"t\" x=\"385\" y=\"240\" font-size=\"14\">나<\/text>\n<line class=\"e b1\" x1=\"120\" y1=\"219\" x2=\"120\" y2=\"190\"/>\n<line class=\"e b1\" x1=\"190\" y1=\"219\" x2=\"190\" y2=\"190\"/>\n<line class=\"e b1\" x1=\"260\" y1=\"219\" x2=\"260\" y2=\"190\"/>\n<line class=\"e b1\" x1=\"360\" y1=\"219\" x2=\"360\" y2=\"190\"/>\n<rect class=\"box b1\" x=\"98\" y=\"160\" width=\"44\" height=\"30\" rx=\"6\"/>\n<rect class=\"box b1\" x=\"168\" y=\"160\" width=\"44\" height=\"30\" rx=\"6\"/>\n<rect class=\"box b1\" x=\"238\" y=\"160\" width=\"44\" height=\"30\" rx=\"6\"/>\n<rect class=\"box b1\" x=\"338\" y=\"160\" width=\"44\" height=\"30\" rx=\"6\"/>\n<text class=\"t b1\" x=\"120\" y=\"181\" font-size=\"14\" text-anchor=\"middle\">2<\/text>\n<text class=\"t b1\" x=\"190\" y=\"181\" font-size=\"14\" text-anchor=\"middle\">4<\/text>\n<text class=\"t b1\" x=\"260\" y=\"181\" font-size=\"14\" text-anchor=\"middle\">6<\/text>\n<text class=\"t b1\" x=\"360\" y=\"181\" font-size=\"14\" text-anchor=\"middle\">10<\/text>\n<text class=\"tm b1\" x=\"10\" y=\"181\" font-size=\"14\">(1) 메시지<\/text>\n<line class=\"e2 b2\" x1=\"120\" y1=\"160\" x2=\"190\" y2=\"120\"/>\n<line class=\"e2 b2\" x1=\"190\" y1=\"160\" x2=\"220\" y2=\"120\"/>\n<line class=\"e2 b2\" x1=\"260\" y1=\"160\" x2=\"260\" y2=\"120\"/>\n<line class=\"e2 b2\" x1=\"360\" y1=\"160\" x2=\"300\" y2=\"120\"/>\n<rect class=\"box2 b2\" x=\"150\" y=\"75\" width=\"180\" height=\"45\" rx=\"8\"/>\n<text class=\"tb b2\" x=\"240\" y=\"104\" font-size=\"16\" text-anchor=\"middle\">AGG: 2+4+6+10<\/text>\n<text class=\"tm b2\" x=\"10\" y=\"104\" font-size=\"14\">(2) 집계<\/text>\n<line class=\"e2 b3\" x1=\"240\" y1=\"75\" x2=\"240\" y2=\"52\"/>\n<circle class=\"n2 b3\" cx=\"240\" cy=\"32\" r=\"20\"/>\n<text class=\"tl b3\" x=\"240\" y=\"37\" font-size=\"14\" text-anchor=\"middle\">22<\/text>\n<text class=\"t b3\" x=\"272\" y=\"37\" font-size=\"14\">새 임베딩<\/text>\n<\/svg>","caption":"이웃 1, 2, 3 과 나 5. 메시지는 ×2, 집계는 합. 새 값 22.","builds":3},{"kind":"steps","head":"방법 A: 숫자 한 칸으로 한 층","steps":["이웃 메시지: 1×2, 2×2, 3×2 이므로 봉투 {2, 4, 6}","내 메시지: 5 × 2 = 10","집계: (2 + 4 + 6) + 10 = 22","이웃 순서를 3, 1, 2 로 바꿔도 (6 + 2 + 4) + 10 = 22"],"answer":"22. 봉투엔 순서가 없어서 이웃 순서를 바꿔도 같아요.","given":"이웃 값 1, 2, 3, 나는 5. MSG 는 ×2, AGG 는 봉투 합 + 내 메시지"},{"kind":"steps","head":"방법 B: **그래프 동형 네트워크(GIN)** 식에 맞춰 보기","steps":["MSG 는 그대로 보내기: 봉투 {1, 2, 3}","이웃 합: 1 + 2 + 3 = 6","내 몫: (1 + 0.5) × 5 = 7.5","새 값: 7.5 + 6 = 13.5"],"answer":"13.5","given":"$h_i^{(k)} = (1+\\varepsilon) h_i^{(k-1)} + \\sum_{j \\in N(i)} h_j^{(k-1)}$, $\\varepsilon = 0.5$. 이웃 1, 2, 3, 나 5. $h_i^{(k)}$ 는 노드 $i$ 의 $k$ 층 값, $\\varepsilon$ 은 내 값에 얹는 작은 무게"},{"kind":"prof","when":"3주차 화요일 수업","lines":["메시지 패싱은 세 단계: 이웃에게서 받을 정보(메시지),","그 메시지를 모으는 **집계(Aggregation)**, 모은 것으로 나를 고치는 업데이트.","누가 이웃인지는 그래프 구조가 정하고, 신경망은 모으고 고치는 일을 한대요."]}],"pass3":[{"kind":"exam","src":"GNN 2024 가을 기말 5번 (a) (10점 문항)","q":"GIN, epsilon = 0.5: h_i^(k) = (1+eps) h_i^(k-1) + sum of neighbor h_j^(k-1). Calculate the feature of each node A, B, C, D at k = 1.","qko":"노드 A, B, C, D 그래프와 초기 특징이 주어진다. $\\varepsilon = 0.5$ 인 GIN 식으로 $k = 1$ 일 때 모든 노드 특징을 구하라.","solve":["해설에서 읽은 값: A 0.2, B 0.3, C 0.2, D 0.1. 이웃: A{B,C,D}, B{A,C}, C{A,B,D}, D{A,C}","A: 1.5 × 0.2 + (0.3 + 0.2 + 0.1) = 0.3 + 0.6 = 0.9","B: 1.5 × 0.3 + (0.2 + 0.2) = 0.45 + 0.4 = 0.85","C: 1.5 × 0.2 + (0.2 + 0.3 + 0.1) = 0.3 + 0.6 = 0.9","D: 1.5 × 0.1 + (0.2 + 0.2) = 0.15 + 0.4 = 0.55"],"answer":"$h_A^{(1)} = 0.9$, $h_B^{(1)} = 0.85$, $h_C^{(1)} = 0.9$, $h_D^{(1)} = 0.55$"},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["슬라이드의 $\\{N(v) \\cup v\\}$ 는 엄밀히 $N(v) \\cup \\{v\\}$ 예요. 뜻은 같아요.","2주차엔 메시지, 집계, 업데이트 세 단계였는데 여기선 업데이트를 AGG 안에 넣었어요.","기출 계산은 이웃 목록 표부터 적으면 실수가 줄어요. 내 값 ×1.5 를 빼먹지 마세요."]},{"kind":"check","q":"GNN 한 층에서 이웃 순서를 바꿔도 결과가 같은 이유는?","choices":["메시지 함수가 없어서","이웃 메시지를 순서 없는 **멀티셋(Multiset)** 봉투로 모아서","가중치가 0이라서","층이 하나뿐이라서"],"a":1,"why":"**집계(Aggregation)**는 봉투째 모으니 순서는 뜻이 없어요. 대신 개수는 세요."}],"pass4":[{"kind":"pyterm","name":"딕셔너리(dict)와 한 줄 만들기","say":["`{키: 값}` 은 이름표로 값을 찾는 사전이에요. `d[3]` 은 키 3 의 값이에요.","`{v: v * 2 for v in 목록}` 은 목록의 v 마다 값을 넣은 사전을 한 줄로 만들어요.","리스트도 `[x * 2 for x in 목록]` 처럼 한 줄로 만들 수 있어요."],"example":"d = {v: v * 2 for v in [1, 2, 3]}\nprint(d, d[3])","out":"{1: 2, 2: 4, 3: 6} 6"},{"kind":"code","head":"집계: 내 색 + 이웃 색 봉투 (1/3)","file":"Sample_Code_3.ipynb 셀 15 (4.1 The Rule) (1/3)","code":"def aggregate(G, colors):\n    \"\"\"Step 2: aggregated color of every node = (own color, sorted tuple of neighbor colors).\"\"\"\n    return {v: (colors[v], tuple(sorted(colors[u] for u in G[v]))) for v in G}\n\n\ndef wl_refine(graphs, num_iterations=3):\n    \"\"\"\n    Color refinement run jointly on a list of graphs with one shared HASH table.\n\n    Returns `rounds`, where rounds[l] is a dict:\n        'colors' : [{node: color} per graph]             colors after round l\n        'agg'    : [{node: aggregated color} per graph]  what was hashed in round l\n        'table'  : {aggregated color: new color}         the HASH table of round l\n    rounds[0] is the initial coloring: every node gets color 1.\n    \"\"\"\n    rounds = [{'colors': [{v: 1 for v in G} for G in graphs], 'agg': None, 'table': {}}]\n    next_color = 2\n    for _ in range(num_iterations):\n        agg = [aggregate(G, c) for G, c in zip(graphs, rounds[-1]['colors'])]\n        # Step 3: injective hash. Every unseen aggregated color gets the next unused number.\n        # (Each round's inputs use fresh colors, so each round needs only its own table.)\n        table = {}\n        for a in agg:\n            for sig in a.values():\n                if sig not in table:\n                    table[sig] = next_color\n                    next_color += 1\n        colors = [{v: table[sig] for v, sig in a.items()} for a in agg]\n        rounds.append({'colors': colors, 'agg': agg, 'table': table})\n    return rounds\n","lines":[{"from":1,"to":1,"say":"`def` 로 함수를 만들어요(p.6). 그래프 G 와 노드별 색 사전 colors 를 받아요."},{"from":2,"to":2,"say":"설명문: 모든 노드의 집계 결과 = (내 색, 이웃 색을 정렬한 튜플)."},{"from":3,"to":3,"say":"`G[v]` 는 v 의 이웃들. 이웃 색을 `sorted` 로 정렬해 튜플로 묶어요. 순서가 달라도 같은 봉투면 같아져요."},{"from":5,"to":15,"say":"wl_refine 함수의 이름과 설명이에요. 여러 그래프가 HASH 표를 같이 쓰며 색 정제를 하고 rounds 목록을 돌려준대요."},{"from":16,"to":17,"say":"0라운드: 모든 노드를 색 1 로 칠해 rounds 에 넣어요. 새 번호는 2 부터 줘요."},{"from":18,"to":19,"say":"라운드 수만큼 반복하며, 지난 라운드 색으로 모든 노드의 집계 색을 만들어요."},{"from":20,"to":27,"say":"주석 두 줄 뒤, 빈 사전 table 에 처음 보는 집계 색마다 다음 번호를 적어요. 같은 조합은 같은 번호예요."},{"from":28,"to":31,"say":"표에서 새 번호를 찾아 노드를 다시 칠하고, 이번 라운드 결과를 rounds 끝에 붙여요. 다 돌면 rounds 를 돌려줘요."}],"link":"슬라이드 AGG 식의 (이웃 메시지 **멀티셋(Multiset)**, 내 메시지) 짝을 그대로 만든 거예요."},{"kind":"code","head":"집계: 내 색 + 이웃 색 봉투 (2/3)","file":"Sample_Code_3.ipynb 셀 15 (4.1 The Rule) (2/3)","code":"\ndef color_histogram(colors):\n    \"\"\"How many nodes carry each color: the graph-level fingerprint.\"\"\"\n    return dict(sorted(Counter(colors.values()).items()))\n\n\ndef wl_report(rounds, names):\n    \"\"\"The WL test: compare the two graphs' color histograms round by round.\"\"\"\n    differ = False\n    for l, r in enumerate(rounds):\n        h1, h2 = (color_histogram(c) for c in r['colors'])\n        differ = differ or h1 != h2\n        print(f\"round {l}:  {names[0]} {str(h1):<34s} {'==' if h1 == h2 else '!='}  {names[1]} {h2}\")\n    print('\\n→ NON-ISOMORPHIC (the histograms differ)' if differ else\n          '\\n→ INCONCLUSIVE (the histograms are always equal)')\n\n\n# ---- drawing -------------------------------------------------------------------------\ndef fmt_agg(sig):\n    \"\"\"(3, (3, 4)) -> '3,{3,4}'\"\"\"\n    own, nbrs = sig\n    return f\"{own},{{{','.join(map(str, nbrs))}}}\"\n\n\ndef draw_aggregated(G, pos, ax, colors, agg, title=None):\n    \"\"\"Each node is a box showing its aggregated color, filled with its current color.\"\"\"\n    nx.draw_networkx_edges(G, pos, ax=ax, edge_color=C_EDGE, width=2.0)\n    for v in G:\n        f = color_of(colors[v])\n        ax.text(*pos[v], fmt_agg(agg[v]), ha='center', va='center', fontsize=10, color=ink(f),\n                bbox=dict(boxstyle='round,pad=0.35', fc=f, ec=C_DARK, lw=1.2))\n    xs, ys = zip(*pos.values())\n    ax.set_xlim(min(xs) - 0.5, max(xs) + 0.5)\n    ax.set_ylim(min(ys) - 0.4, max(ys) + 0.4)\n    if title:\n        ax.set_title(title)\n    ax.set_axis_off()\n","lines":[{"from":1,"to":5,"say":"color_histogram 함수: Counter 로 색마다 노드가 몇 개인지 세서 번호 순으로 정리해요."},{"from":6,"to":16,"say":"wl_report 함수: 라운드마다 두 그래프의 색 개수표를 비교해 == 또는 != 를 출력하고, 마지막에 판정을 알려 줘요."},{"from":17,"to":23,"say":"그리기 부분 시작이에요. fmt_agg 는 (3, (3, 4)) 같은 집계 색을 '3,{3,4}' 글자로 바꿔요."},{"from":24,"to":38,"say":"draw_aggregated 함수: 노드마다 집계 색 글자를 지금 색으로 칠한 상자에 적어 그려요."}]},{"kind":"code","head":"집계: 내 색 + 이웃 색 봉투 (3/3)","file":"Sample_Code_3.ipynb 셀 15 (4.1 The Rule) (3/3)","code":"\ndef draw_hash_table(ax, table, title):\n    tab = ax.table(cellText=[[fmt_agg(sig), c] for sig, c in table.items()],\n                   colLabels=['aggregated color', 'new color'], loc='center', cellLoc='center')\n    tab.auto_set_font_size(False); tab.set_fontsize(11); tab.scale(1, 1.7)\n    for j in range(2):                                   # header row\n        tab[0, j].set_facecolor(C_DARK)\n        tab[0, j].get_text().set(color='white', fontweight='bold')\n    for i, c in enumerate(table.values(), start=1):      # paint each new color\n        tab[i, 1].set_facecolor(color_of(c))\n        tab[i, 1].get_text().set(color=ink(color_of(c)), fontweight='bold')\n    ax.set_title(title)\n    ax.set_axis_off()\n\n\ndef show_initial(graphs, names, positions, rounds):\n    fig, axes = plt.subplots(1, len(graphs), figsize=(11, 3))\n    for ax, G, name, pos, c in zip(axes, graphs, names, positions, rounds[0]['colors']):\n        draw_graph(G, pos, ax, colors=c, labels='color', title=name)\n    fig.suptitle('Step 1 - Assign initial colors: every node gets color 1',\n                 fontsize=13, fontweight='bold')\n    plt.tight_layout(); plt.show()\n\n\ndef show_round(graphs, names, positions, rounds, l):\n    \"\"\"One round, left to right: aggregated colors -> HASH table -> new colors.\"\"\"\n    r, prev = rounds[l], rounds[l - 1]['colors']\n    fig = plt.figure(figsize=(15, 5.6))\n    gs = fig.add_gridspec(2, 3, width_ratios=[1, 0.75, 1])\n    for i, (G, name, pos) in enumerate(zip(graphs, names, positions)):\n        draw_aggregated(G, pos, fig.add_subplot(gs[i, 0]), prev[i], r['agg'][i],\n                        title=f'{name}: aggregated colors')\n        draw_graph(G, pos, fig.add_subplot(gs[i, 2]), colors=r['colors'][i], labels='color',\n                   title=f'{name}: new colors')\n    draw_hash_table(fig.add_subplot(gs[:, 1]), r['table'], title=f'HASH table (round {l})')\n    fig.suptitle(f'Round {l}:   Step 2 - aggregate neighboring colors   →   '\n                 f'Step 3 - injectively hash   →   new colors', fontsize=13, fontweight='bold')\n    plt.tight_layout(); plt.show()","lines":[{"from":1,"to":14,"say":"draw_hash_table 함수: HASH 표를 '집계 색, 새 색' 두 열짜리 표 그림으로 그리고 새 색 칸을 그 색으로 칠해요."},{"from":15,"to":23,"say":"show_initial 함수: 모든 노드가 색 1 인 시작 그림을 그래프마다 그려요."},{"from":24,"to":38,"say":"show_round 함수: 한 라운드를 왼쪽 집계 색, 가운데 HASH 표, 오른쪽 새 색 순서로 한 장에 그려요."}]}]},{"p":8,"title":"배경: 다양한 GNN 모델","terms":["GCN","GraphSAGE","Design space","Computational graph","Receptive field"],"pass1":[{"kind":"say","lines":["GNN에는 여러 종류가 있지만, 모두 같은 모양의 나무 위에서 계산해요.","슬라이드 그림의 '?' 상자는 이웃 정보를 모으는 자리예요.","모델마다 다른 건 이 '?' 상자 안에 어떤 계산을 넣느냐뿐이에요.","그래서 상자 속 계산에 따라 **표현력(Expressive power)**이 달라질 수 있어요."]},{"kind":"look","head":"그림에서 볼 곳","boxes":[{"x":0.14,"y":0.39,"w":0.23,"h":0.38,"say":"왼쪽은 입력 그래프예요. 화살표가 가리키는 A가 주인공이에요."},{"x":0.51,"y":0.46,"w":0.15,"h":0.14,"say":"큰 '?' 상자는 A가 이웃 B, C, D의 정보를 모으는 자리예요."},{"x":0.74,"y":0.29,"w":0.05,"h":0.45,"say":"작은 '?' 상자 3개는 B, C, D가 먼저 자기 이웃 정보를 모으는 자리예요."}]},{"kind":"analogy","head":"같은 빵틀, 다른 반죽","scene":"빵집에 똑같은 모양의 빵틀이 여러 개 있어요. 틀은 모두 같은데, 어떤 반죽을 붓느냐에 따라 초코빵도 되고 우유빵도 돼요. GNN도 나무 모양의 틀은 모두 같고, '?' 상자에 붓는 계산만 모델마다 달라요. 그래서 반죽, 곧 상자 속 계산을 비교하면 모델끼리 비교할 수 있어요.","map":[["똑같은 빵틀","모든 GNN이 쓰는 같은 나무 모양"],["붓는 반죽","'?' 상자 속 계산"],["빵 이름","**그래프 합성곱 신경망(GCN)**, **그래프세이지(GraphSAGE)** 같은 모델 이름"]]}],"pass2":[{"kind":"look","head":"슬라이드 그림 읽기","boxes":[{"x":0.07,"y":0.215,"w":0.36,"h":0.05,"say":"많은 GNN: **그래프 합성곱 신경망(GCN)**, **그래프세이지(GraphSAGE)**, GAT, **설계 공간(Design space)**."},{"x":0.14,"y":0.39,"w":0.23,"h":0.38,"say":"입력 그래프: A~F 6개, 선 7개. '대상 노드' 화살표가 A 를 가리켜요."},{"x":0.51,"y":0.46,"w":0.15,"h":0.14,"say":"왼쪽 A 가 뿌리, 큰 '?' 상자가 2번째 층. B, C, D 에게서 점선이 들어와요."},{"x":0.74,"y":0.29,"w":0.05,"h":0.45,"say":"작은 '?' 상자 3개가 1번째 층. 점선은 들어오는 메시지, 실선은 나가는 결과."},{"x":0.815,"y":0.28,"w":0.045,"h":0.46,"say":"맨 오른쪽: B 의 이웃 A, C / C 의 이웃 A, B, E, F / D 의 이웃 A."},{"x":0.455,"y":0.78,"w":0.2,"h":0.09,"say":"GNN 모델마다 상자 속에 다른 신경망을 써요. 모양은 같고 내용물만 달라요."}]},{"kind":"figure","head":"A 의 2층 계산 나무를 층별로 세기","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\">\n<line class=\"e b1\" x1=\"240\" y1=\"52\" x2=\"110\" y2=\"100\"/>\n<line class=\"e b1\" x1=\"240\" y1=\"52\" x2=\"240\" y2=\"100\"/>\n<line class=\"e b1\" x1=\"240\" y1=\"52\" x2=\"380\" y2=\"100\"/>\n<line class=\"e b2\" x1=\"110\" y1=\"132\" x2=\"70\" y2=\"184\"/>\n<line class=\"e b2\" x1=\"110\" y1=\"132\" x2=\"125\" y2=\"184\"/>\n<line class=\"e b2\" x1=\"240\" y1=\"132\" x2=\"180\" y2=\"184\"/>\n<line class=\"e b2\" x1=\"240\" y1=\"132\" x2=\"225\" y2=\"184\"/>\n<line class=\"e b2\" x1=\"240\" y1=\"132\" x2=\"270\" y2=\"184\"/>\n<line class=\"e b2\" x1=\"240\" y1=\"132\" x2=\"315\" y2=\"184\"/>\n<line class=\"e b2\" x1=\"380\" y1=\"132\" x2=\"385\" y2=\"184\"/>\n<circle class=\"n2\" cx=\"240\" cy=\"36\" r=\"16\"/>\n<text class=\"tl\" x=\"240\" y=\"41\" font-size=\"14\" text-anchor=\"middle\">A<\/text>\n<text class=\"tm\" x=\"455\" y=\"41\" font-size=\"14\" text-anchor=\"middle\">1개<\/text>\n<circle class=\"n b1\" cx=\"110\" cy=\"116\" r=\"16\"/>\n<circle class=\"n b1\" cx=\"240\" cy=\"116\" r=\"16\"/>\n<circle class=\"n b1\" cx=\"380\" cy=\"116\" r=\"16\"/>\n<text class=\"tl b1\" x=\"110\" y=\"121\" font-size=\"14\" text-anchor=\"middle\">B<\/text>\n<text class=\"tl b1\" x=\"240\" y=\"121\" font-size=\"14\" text-anchor=\"middle\">C<\/text>\n<text class=\"tl b1\" x=\"380\" y=\"121\" font-size=\"14\" text-anchor=\"middle\">D<\/text>\n<text class=\"tm b1\" x=\"455\" y=\"121\" font-size=\"14\" text-anchor=\"middle\">3개<\/text>\n<circle class=\"n2 b2\" cx=\"70\" cy=\"200\" r=\"16\"/>\n<circle class=\"n b2\" cx=\"125\" cy=\"200\" r=\"16\"/>\n<circle class=\"n2 b2\" cx=\"180\" cy=\"200\" r=\"16\"/>\n<circle class=\"n b2\" cx=\"225\" cy=\"200\" r=\"16\"/>\n<circle class=\"n b2\" cx=\"270\" cy=\"200\" r=\"16\"/>\n<circle class=\"n b2\" cx=\"315\" cy=\"200\" r=\"16\"/>\n<circle class=\"n2 b2\" cx=\"385\" cy=\"200\" r=\"16\"/>\n<text class=\"tl b2\" x=\"70\" y=\"205\" font-size=\"14\" text-anchor=\"middle\">A<\/text>\n<text class=\"tl b2\" x=\"125\" y=\"205\" font-size=\"14\" text-anchor=\"middle\">C<\/text>\n<text class=\"tl b2\" x=\"180\" y=\"205\" font-size=\"14\" text-anchor=\"middle\">A<\/text>\n<text class=\"tl b2\" x=\"225\" y=\"205\" font-size=\"14\" text-anchor=\"middle\">B<\/text>\n<text class=\"tl b2\" x=\"270\" y=\"205\" font-size=\"14\" text-anchor=\"middle\">E<\/text>\n<text class=\"tl b2\" x=\"315\" y=\"205\" font-size=\"14\" text-anchor=\"middle\">F<\/text>\n<text class=\"tl b2\" x=\"385\" y=\"205\" font-size=\"14\" text-anchor=\"middle\">A<\/text>\n<text class=\"tm b2\" x=\"455\" y=\"205\" font-size=\"14\" text-anchor=\"middle\">7개<\/text>\n<text class=\"tb b3\" x=\"240\" y=\"252\" font-size=\"15\" text-anchor=\"middle\">동그라미 11개, 그중 A 복사본 4개. 노드는 6개뿐<\/text>\n<\/svg>","caption":"진한 색은 A 의 복사본이에요.","builds":3},{"kind":"steps","head":"나무 크기 세기","steps":["1층: A 의 이웃 B, C, D 로 3개","2층: B 의 이웃 2 + C 의 이웃 4 + D 의 이웃 1 = 7개","전체: 1 + 3 + 7 = 11개. 그래프엔 노드 6개뿐, A 는 4번 나와요","D 가 뿌리면: 1 + 1(A) + 3(B, C, D) = 5개"],"answer":"같은 2층 GNN이어도 노드마다 보는 범위가 달라요. A 는 11개, D 는 5개.","given":"A 의 2층 **계산 그래프(Computational graph)**"},{"kind":"points","head":"계산 순서","items":["그림은 오른쪽에서 왼쪽으로 읽어요.","먼저 작은 상자 셋: B, C, D 가 각자 이웃 입력을 모아 새 값을 만들어요.","그다음 큰 상자: B, C, D 의 새 값을 모아 A 의 최종 임베딩을 만들어요.","E 와 F 가 이어져 있다는 사실은 2층 안에 A 까지 오지 못해요."]},{"kind":"prof","when":"3주차 화요일 수업","lines":["모델마다 집계하는 법도, 업데이트하는 법도 다르다고 했어요.","그 차이가 **표현력(Expressive power)** 에 영향을 주고, 이유를 이번 주에 본대요."]}],"pass3":[{"kind":"warn","head":"헷갈리기 쉬운 점","items":["상자 개수와 연결은 그래프가 정해요. 모델이 정하는 건 상자 속 계산 방법이에요.","같은 층 작은 상자들은 보통 같은 가중치를 함께 써요. 층이 다르면 달라질 수 있어요.","뿌리가 왼쪽이라 p.6 과 방향만 달라요. 같은 **계산 그래프(Computational graph)**예요."]},{"kind":"check","q":"A 의 2층 계산 그래프에 동그라미는 모두 몇 개일까요?","choices":["6개","7개","11개","4개"],"a":2,"why":"뿌리 1 + 이웃 3 + 이웃의 이웃 7 = 11. A 복사본이 4번 나와서 노드 수 6보다 많아요."}],"pass4":[{"kind":"pyterm","name":"range 와 리스트 한 줄 만들기","say":["`range(6)` 은 0, 1, 2, 3, 4, 5 를 차례로 줘요. 6 은 안 들어가요.","`[식 for L in range(6)]` 은 L 마다 식을 계산한 결과 6개를 리스트에 담아요."],"example":"print([L * L for L in range(4)])","out":"[0, 1, 4, 9]"},{"kind":"code","head":"층이 늘면 나무가 얼마나 커지나 (1/2)","file":"Sample_Code_3.ipynb 셀 10 (3.1 What a Node Actually Sees) (1/2)","code":"def unfolding_tree(G, root, depth):\n    \"\"\"\n    Computational graph of `root` for a `depth`-layer GNN.\n    Tree nodes are walks starting at `root`; attribute 'orig' is the graph node a copy stands for.\n    Edges point child -> parent, the direction messages flow.\n    \"\"\"\n    T = nx.DiGraph()\n    T.add_node((root,), orig=root, level=0)\n    frontier = [(root,)]\n    for d in range(1, depth + 1):\n        frontier = [walk + (u,) for walk in frontier for u in sorted(G[walk[-1]])]\n        for walk in frontier:\n            T.add_node(walk, orig=walk[-1], level=d)\n            T.add_edge(walk, walk[:-1])\n    return T\n\n\ndef draw_tree(T, ax, uniform=False, title=None, node_size=460, font_size=9):\n    \"\"\"Draw a tree with the root on top. uniform=True paints every copy gray (only shape matters).\"\"\"\n    pos, next_x = {}, [0.0]\n\n    def place(n):                                   # each parent centered above its children\n        kids = sorted(T.predecessors(n))\n        if kids:\n            x = float(np.mean([place(k) for k in kids]))\n        else:\n            x, next_x[0] = next_x[0], next_x[0] + 1\n        pos[n] = (x, -T.nodes[n]['level'])\n        return x\n\n    place(next(n for n in T if T.nodes[n]['level'] == 0))\n    nodes = list(T.nodes())\n    fill = [color_of(0 if uniform else T.nodes[n]['orig'] + 1) for n in nodes]\n    nx.draw_networkx_edges(T, pos, ax=ax, arrows=False, edge_color=C_EDGE, width=1.4)\n    nx.draw_networkx_nodes(T, pos, nodelist=nodes, ax=ax, node_color=fill,\n                           edgecolors=C_DARK, linewidths=1.1, node_size=node_size)\n    for n, f in zip(nodes, fill):\n        ax.text(*pos[n], str(T.nodes[n]['orig']), ha='center', va='center',\n                fontsize=font_size, color=ink(f))\n    if title:\n        ax.set_title(title)\n    ax.set_axis_off()\n    ax.margins(0.08)\n","lines":[{"from":1,"to":6,"say":"unfolding_tree 함수의 이름과 설명(따옴표 세 개 사이 글)이에요. 뿌리에서 depth 층만큼 펼친 계산 그래프를 만들어요."},{"from":7,"to":9,"say":"빈 방향 그래프 T 를 만들고 뿌리 하나를 넣어요. frontier 는 지금 나무 맨 아래 줄 목록이에요."},{"from":10,"to":17,"say":"층마다 맨 아래 줄 노드의 이웃을 하나씩 붙여 새 줄을 만들고, 자식에서 부모로 가는 선을 그어요. 끝나면 나무를 돌려줘요."},{"from":18,"to":31,"say":"draw_tree 함수의 시작 부분이에요. place 가 자식들을 먼저 배치하고, 부모를 그 가운데 위에 놓아 좌표를 정해요."},{"from":32,"to":44,"say":"노드 색을 정하고 선, 동그라미, 번호 글자를 그려요. uniform=True 면 모두 회색이라 모양만 보여요."}]},{"kind":"code","head":"층이 늘면 나무가 얼마나 커지나 (2/2)","file":"Sample_Code_3.ipynb 셀 10 (3.1 What a Node Actually Sees) (2/2)","code":"\nG_demo = nx.Graph([(0, 1), (0, 2), (1, 2), (1, 3), (2, 4), (3, 4), (4, 5)])\nPOS_DEMO = nx.spring_layout(G_demo, seed=3)\n\nfig = plt.figure(figsize=(14, 4.4))\ngs = fig.add_gridspec(1, 3, width_ratios=[1, 1.25, 1.6])\ndraw_graph(G_demo, POS_DEMO, fig.add_subplot(gs[0]), colors={v: v + 1 for v in G_demo},\n           highlight=0, title='The graph (target node 0)')\nfor k, depth in enumerate([1, 2]):\n    T = unfolding_tree(G_demo, 0, depth)\n    draw_tree(T, fig.add_subplot(gs[k + 1]),\n              title=f'Computational graph of node 0, {depth} layer(s)\\n'\n                    f'({T.number_of_nodes()} tree nodes)')\nplt.tight_layout(); plt.show()\n\nsizes = [unfolding_tree(G_demo, 0, L).number_of_nodes() for L in range(6)]\nprint(f'Tree size for L = 0..5 layers: {sizes}   (the graph has only {G_demo.number_of_nodes()} nodes)')","lines":[{"from":2,"to":2,"say":"엣지 목록 리스트로 노드 6개, 선 7개 예제 그래프를 만들어요. p.8 그림과 크기만 같은 다른 그래프예요."},{"from":3,"to":4,"say":"예시 그래프 G_demo 를 (노드, 노드) 쌍 목록으로 만들고 그릴 좌표를 정해요."},{"from":5,"to":14,"say":"그림 세 칸에 원래 그래프와 1층, 2층 계산 그래프를 나란히 그려요."},{"from":16,"to":16,"say":"층 수 L = 0~5 마다 p.6 의 함수로 노드 0 의 나무를 만들고 동그라미 수를 세어 리스트로 모아요."},{"from":17,"to":17,"say":"출력: [1, 3, 9, 24, 63, 162]. 노드는 6개뿐인데 나무는 빠르게 커져요."}],"link":"p.8 에서 A 의 나무가 11개였듯, 층마다 **수용 영역(Receptive field)**이 넓어져요."}]},{"p":9,"title":"GCN: 평균 풀링","terms":["GCN","Mean pooling","Element-wise","ReLU","Multiset"],"pass1":[{"kind":"say","lines":["**그래프 합성곱 신경망(GCN)**은 '?' 상자에서 이웃 정보를 평균 내서 모아요.","이렇게 평균으로 모으는 방법을 **평균 풀링(Mean pooling)**이라고 해요.","평균을 내면 이웃이 몇 명이었는지는 사라져요. 이게 뒤에서 약점이 돼요."]},{"kind":"look","head":"슬라이드에서 바뀐 곳","boxes":[{"x":0.03,"y":0.145,"w":0.18,"h":0.055,"say":"제목 옆 글은 'GCN은 평균으로 모은다'는 뜻이에요."},{"x":0.44,"y":0.78,"w":0.2,"h":0.09,"say":"아래 글은 상자 속 계산 순서예요. 평균을 낸 뒤 숫자를 곱하고 손질하는 단계가 이어져요."}]},{"kind":"analogy","head":"반 평균 점수만 받은 선생님","scene":"1반은 학생이 2명, 2반은 30명이에요. 두 반 모두 수학 평균이 90점이에요. 평균 점수만 받은 선생님은 두 반이 몇 명인지 전혀 알 수 없어요. 평균은 '얼마나 잘했나'는 남기지만 '몇 명이었나'는 지워 버리거든요.","map":[["학생 한 명의 점수","이웃 한 명의 정보"],["반 평균","**평균 풀링(Mean pooling)**"],["반 인원수","이웃 수, 평균이 잊어버리는 정보"]]}],"pass2":[{"kind":"look","head":"슬라이드에서 바뀐 곳","boxes":[{"x":0.03,"y":0.145,"w":0.18,"h":0.055,"say":"**그래프 합성곱 신경망(GCN)** = **평균 풀링(Mean pooling)**. 여러 벡터를 평균으로 모아요."},{"x":0.51,"y":0.29,"w":0.35,"h":0.46,"say":"그래프, 나무, '?' 상자들은 p.8 과 같아요. 상자 네 개를 모두 GCN 으로 채워요."},{"x":0.44,"y":0.78,"w":0.2,"h":0.09,"say":"**원소별(Element-wise)** 평균 + 선형 + **렐루(ReLU)** 비선형. 세 단계를 차례로 해요."}]},{"kind":"formula","head":"GCN 상자 식","tex":"\\mathbf{h}_v^{(l)} = \\mathrm{ReLU}\\left(\\mathbf{W}^{(l)} \\cdot \\mathrm{mean}\\left(\\{\\!\\{\\mathbf{h}_u^{(l-1)} : u \\in N(v)\\}\\!\\}\\right)\\right)","parts":[{"sym":"\\{\\!\\{\\ \\}\\!\\}","say":"**멀티셋(Multiset)**: 순서 없고 개수는 세는 봉투"},{"sym":"\\mathrm{mean}","say":"칸마다 더해서 이웃 수로 나눔"},{"sym":"\\mathbf{W}^{(l)}","say":"이 층에서 학습되는 가중치 행렬(선형)"},{"sym":"\\mathrm{ReLU}","say":"칸마다 음수는 0, 양수는 그대로"}],"whole":"이웃 점수표를 칸마다 평균 내고, 가중치를 곱한 뒤, 음수를 0 으로 바꾼 게 새 임베딩이에요."},{"kind":"steps","head":"C 의 상자 계산","steps":["칸별 합: (1+0+1+2, 0+1+1+0) = (4, 2)","평균(÷4): (1, 0.5)","W 곱: (1×1 + (-1)×0.5, (-1)×1 + 1×0.5) = (0.5, -0.5)","ReLU: (0.5, 0)"],"answer":"C 의 새 임베딩은 (0.5, 0) 이에요.","given":"괄호 속 두 숫자는 특징 벡터의 두 칸이에요. 이웃 A(1, 0), B(0, 1), E(1, 1), F(2, 0). 가중치 행렬 $\\mathbf{W} = \\begin{bmatrix} 1 & -1 \\\\ -1 & 1 \\end{bmatrix}$"},{"kind":"compare","head":"평균의 약점","cols":["노드","이웃 봉투","평균","합"],"rows":[["X","{(1,0)}","(1, 0)","(1, 0)"],["Y","{(1,0), (1,0), (1,0)}","(1, 0)","(3, 0)"],["P","{(1,0), (0,1)}","(0.5, 0.5)","(1, 1)"],["Q","P 봉투를 두 배로","(0.5, 0.5)","(2, 2)"]]},{"kind":"points","head":"표에서 배울 것","items":["평균은 '종류별 비율'만 남기고 '몇 개였는지'는 잊어요.","평균이 같아진 뒤엔 어떤 W 와 **렐루(ReLU)**를 거쳐도 다시 갈라지지 않아요.","합은 개수를 그대로 남겨서 X 와 Y, P 와 Q 를 가려요."]},{"kind":"prof","when":"3주차 화요일 수업","lines":["**GCN** 은 평균 풀링으로 모으고, 선형 변환과 활성화로 업데이트한대요.","뒤에서 이 평균 때문에 서로 다른 이웃이 같아지는 예를 봐요."]}],"pass3":[{"kind":"english","head":"평균 풀링의 약점","en":"Mean pooling cannot tell a neighbor multiset from a multiset with every element repeated k times.","ko":"평균 풀링은 이웃 멀티셋과, 그 원소를 모두 k번씩 늘린 멀티셋을 구별하지 못한다.","tip":"repeated k times(k번 반복)가 핵심이에요. 비율이 같으면 평균도 같아요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["실제 GCN 은 자기 연결을 넣고 보내는 쪽과 받는 쪽 차수로 나눠요. 슬라이드는 평균으로 단순화했어요.","평균이 늘 나쁜 건 아니에요. 이웃 수가 제각각일 때 값 크기를 맞춰 줘요.","**평균 풀링(Mean pooling)**의 약점은 '구별 능력'에서의 이야기예요."]}],"pass4":[]},{"p":10,"title":"GraphSAGE: 최대 풀링","terms":["GraphSAGE","Max pooling","MLP","Element-wise","Injective","GIN","1-WL test"],"pass1":[{"kind":"say","lines":["**그래프세이지(GraphSAGE)**는 이웃 정보를 하나씩 작은 신경망(**다층 퍼셉트론(MLP)**)에 넣어 먼저 다듬어요.","그다음 다듬은 값들 중 가장 큰 값만 골라 모아요. 이걸 **최대 풀링(Max pooling)**이라고 해요.","가장 큰 값만 남기니, 이웃이 몇 명이었는지도 어떤 비율이었는지도 잊어요."]},{"kind":"compare","head":"모으는 방법마다 기억하는 것","cols":["모으는 방법","기억하는 것","잊는 것"],"rows":[["합","어떤 값이 몇 개 있었는지","거의 없음"],["평균","어떤 값이 어떤 비율로 있었는지","몇 개였는지"],["최댓값","가장 큰 값이 무엇이었는지","몇 개였는지, 비율"]]},{"kind":"say","lines":["그래서 구별하는 힘은 합이 가장 세고, 그다음이 평균, 마지막이 최댓값이에요."]}],"pass2":[{"kind":"look","head":"슬라이드에서 바뀐 곳","boxes":[{"x":0.03,"y":0.145,"w":0.25,"h":0.055,"say":"**그래프세이지(GraphSAGE)** = **최대 풀링(Max pooling)**. 여러 벡터를 최댓값으로 모아요."},{"x":0.74,"y":0.29,"w":0.05,"h":0.45,"say":"상자마다 이웃 하나하나에 MLP 를 먼저 따로 적용한 뒤 칸별 최댓값을 골라요."},{"x":0.46,"y":0.8,"w":0.19,"h":0.06,"say":"**다층 퍼셉트론(MLP)** + **원소별(Element-wise)** 최대 풀링. 순서가 GCN 과 반대예요."}]},{"kind":"formula","head":"GraphSAGE(max) 상자 식","tex":"\\mathbf{h}_v^{(l)} = \\max\\left(\\{\\!\\{\\mathrm{MLP}\\left(\\mathbf{h}_u^{(l-1)}\\right) : u \\in N(v)\\}\\!\\}\\right)","parts":[{"sym":"\\mathrm{MLP}\\left(\\mathbf{h}_u^{(l-1)}\\right)","say":"이웃 하나의 임베딩을 작은 신경망으로 요약"},{"sym":"\\{\\!\\{\\ \\}\\!\\}","say":"이웃마다 나온 요약을 담은 봉투"},{"sym":"\\max","say":"칸마다 가장 큰 값을 고름"}],"whole":"이웃마다 MLP 로 요약하고, 칸마다 최고값만 모아 새 임베딩으로 해요."},{"kind":"points","head":"왜 MLP 를 먼저?","items":["최댓값 고르기는 숫자 크기만 봐요.","MLP 로 중요한 특징이 큰 값으로 드러나게 바꿔 두면 쓸모 있는 정보가 남아요.","**다층 퍼셉트론(MLP)**도 학습으로 정해져요."]},{"kind":"steps","head":"C 의 상자 (MLP 는 값을 그대로 낸다고 가정)","steps":["첫째 칸: 1, 0, 1, 2 중 최댓값 2 (F 에서)","둘째 칸: 0, 1, 1, 0 중 최댓값 1 (B 나 E 에서)","칸마다 따로 골라서 여러 이웃의 값이 섞여 들어가요"],"answer":"C 의 새 임베딩은 (2, 1) 이에요.","given":"이웃 A(1, 0), B(0, 1), E(1, 1), F(2, 0)"},{"kind":"compare","head":"세 집계로 봉투 세 쌍 가르기","cols":["봉투 쌍","합","평균","최댓값"],"rows":[["{1} 대 {1, 1}","1 대 2, 구별","1 대 1, 못 함","1 대 1, 못 함"],["{1, 2} 대 {1, 1, 2}","3 대 4, 구별","1.5 대 1.33, 구별","2 대 2, 못 함"],["{1, 2} 대 {1, 1, 2, 2}","3 대 6, 구별","1.5 대 1.5, 못 함","2 대 2, 못 함"],["구별한 쌍 수","3","1","0"]]},{"kind":"prof","when":"3주차 화요일 수업","lines":["**GraphSAGE** 는 MLP 와 최대 풀링을 쓴다고 짚었어요.","뒤에서 최대 풀링은 평균보다도 표현력이 떨어진다고 했어요."]}],"pass3":[{"kind":"exam","src":"GNN 2024 가을 기말 5번 (b) (10점 문항)","q":"What are the reasons why GIN model achieves 1-d Weisfeiler-Lehman?","qko":"GIN 모델이 1차원 WL(1-WL) 만큼 강한 이유는 무엇인가?","solve":["**그래프 동형 네트워크(GIN)**는 이웃 특징을 합(sum)으로 모아요.","평균이나 최대 풀링과 달리 합은 집계를 **단사(Injective)**로 만들어요. 다른 입력은 다른 출력.","위 표처럼 합은 개수까지 기억해서 봉투 차이를 뭉개지 않아요.","합에 단사 **다층 퍼셉트론(MLP)**을 결합해서 **1-WL 테스트(1-WL test)**만큼 그래프를 구별해요."],"answer":"Sum aggregation is injective, unlike mean or max-pooling; with an injective MLP, GIN is as powerful as the 1-WL test."},{"kind":"english","head":"해설 핵심 문장","en":"Unlike mean or max-pooling used in other GNNs, the sum operation ensures that the aggregation function is injective.","ko":"다른 GNN이 쓰는 평균이나 최대 풀링과 달리, 합 연산은 집계 함수가 단사가 되게 한다.","tip":"injective 뒤에 (distinct inputs produce distinct outputs) 를 덧붙이면 더 좋아요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["합도 날것 숫자에선 단사가 아니에요. {1, 3} 과 {2, 2} 는 합이 둘 다 4. 그래서 **그래프 동형 네트워크(GIN)**는 MLP 를 함께 써요.","{1} 과 {1, 1} 은 MLP 를 거쳐도 최댓값으로 절대 못 갈라요. 같은 입력은 같은 출력이니까요.","≻ 는 '항상 성능이 좋다'가 아니라 MLP 가 잘 바꿔 준다는 조건에서 구별하는 쌍의 포함 관계예요."]},{"kind":"check","q":"**최대 풀링(Max pooling)**으로 구별되는 봉투 쌍은?","choices":["{1} 대 {1, 1}","{1, 2} 대 {1, 1, 2, 2}","{1, 2} 대 {1, 3}","{2} 대 {2, 2, 2}"],"a":2,"why":"최댓값이 2 대 3 으로 달라요. 나머지는 최댓값이 같아서 못 갈라요."}],"pass4":[{"kind":"pyterm","name":"sum, max, len (예시 코드, 노트북에 없음)","say":["노트북엔 없는 설명용 예시 코드예요.","`sum(리스트)` 는 합, `max(리스트)` 는 최댓값, `len(리스트)` 는 개수예요.","평균은 `sum(b) / len(b)` 로 구해요. `a, b = ..., ...` 는 두 변수에 한 번에 담기예요."],"example":"a, b = [1, 2], [1, 1, 2, 2]\nprint(sum(a), sum(b), max(a), max(b))\nprint(sum(a) / len(a), sum(b) / len(b))","out":"3 6 2 2\n1.5 1.5"},{"kind":"say","lines":["합은 3 대 6 으로 갈라요. 최댓값(2 대 2)과 평균(1.5 대 1.5)은 못 갈라요.","p.10 표의 셋째 줄을 파이썬으로 확인한 거예요."]}]},{"p":11,"title":"참고: 노드 색 = 특징","terms":["Color refinement","Expressive power","Node degree"],"pass1":[{"kind":"say","lines":["슬라이드 그림에서 노드 색은 그 노드가 처음부터 가진 정보, 즉 특징을 뜻해요.","색이 같으면 처음 가진 정보가 똑같다는 뜻이에요.","모든 노드를 같은 색으로 두면, GNN은 오직 연결 모양만 보고 구별해야 해요.","그래서 모양을 보는 눈을 시험하기에 가장 공정한 조건이에요."]},{"kind":"analogy","head":"모두 같은 운동화를 신고 달리기","scene":"친구 두 명의 달리기 실력을 비교하려고 해요. 한 명은 운동화, 한 명은 슬리퍼를 신고 달리면 누가 더 빠른지 신발 덕인지 알 수 없어요. 그래서 둘 다 같은 운동화를 신겨서 달리게 해요. 모든 노드를 같은 색으로 칠하는 것도, 처음 정보의 차이를 없애고 연결 모양만 비교하려는 거예요.","map":[["모두 같은 운동화","모든 노드가 같은 색(같은 특징)"],["달리기 실력","연결 모양을 알아보는 GNN의 눈"]]}],"pass2":[{"kind":"look","head":"슬라이드 글자와 그림","boxes":[{"x":0.03,"y":0.14,"w":0.46,"h":0.06,"say":"특징이 같은 노드는 같은 색, 다른 노드는 다른 색으로 그려요."},{"x":0.07,"y":0.215,"w":0.62,"h":0.05,"say":"예: 이 그래프는 모든 노드가 같은 특징을 공유한다고 가정해요. 그래서 모두 흰색."},{"x":0.375,"y":0.3,"w":0.24,"h":0.27,"say":"선은 p.6 과 같아요. 1~5 는 우리가 부르는 이름표일 뿐, 모델은 번호를 못 봐요."},{"x":0.03,"y":0.635,"w":0.53,"h":0.06,"say":"핵심 질문: GNN 은 서로 다른 그래프 구조를 얼마나 잘 구별할까? 같은 색 조건에서 따져요."}]},{"kind":"compare","head":"1층 합 집계, 두 경우","cols":["노드","모든 특징 1 일 때","특징 10~50 일 때"],"rows":[["1","1+1 = 2 (이웃 2, 5)","입력부터 10"],["2","2","입력부터 20"],["3","1","입력부터 30"],["4","2","입력부터 40"],["5","3","입력부터 50"]]},{"kind":"points","head":"무엇을 알 수 있나","items":["모든 특징이 같으면 1층 뒤 차이는 순전히 연결 모양, 여기선 **노드 차수(Node degree)**에서 나와요.","특징이 다 다르면 구조를 안 봐도 구별돼서 구조 시험이 안 돼요.","실제 데이터도 특징이 없으면 모든 노드에 1 을 넣고 시작하곤 해요."]},{"kind":"prof","when":"3주차 화요일 수업","lines":["WL 재라벨링은 모든 노드가 같은 레이블로 출발해도","연결 구조만으로 최소한의 성능은 보장한다고 했어요.","그래서 오늘은 모든 노드의 초기 특징이 같은 '최악의 상황'을 가정한대요."]},{"kind":"mining","src":"마이닝 9강 Graph Kernels","lines":["WL 동형 테스트의 첫 단계도 '모든 노드 라벨을 1로' 였어요.","같은 출발점이라 나중에 GNN과 WL을 나란히 비교할 수 있어요."]}],"pass3":[{"kind":"warn","head":"헷갈리기 쉬운 점","items":["여기 '색'은 입력 특징의 약속이에요. **색 정제(Color refinement)**의 색은 알고리즘이 새로 붙이는 색이에요.","다음 쪽부터 노란색은 특징이 아니라 '지금 비교하는 두 노드' 표시예요."]},{"kind":"check","q":"모든 노드 특징이 같을 때 GNN이 노드를 구별하는 유일한 단서는?","choices":["노드 번호","연결 구조","노드 색","그림 속 위치"],"a":1,"why":"번호와 위치는 모델이 못 보고 색(특징)은 모두 같아요. 남는 건 연결 구조뿐이라 **표현력(Expressive power)** 시험에 딱이에요."}],"pass4":[{"kind":"code","head":"처음엔 모든 노드가 색 1 (1/3)","file":"Sample_Code_3.ipynb 셀 15 (4.1 The Rule) (1/3)","code":"def aggregate(G, colors):\n    \"\"\"Step 2: aggregated color of every node = (own color, sorted tuple of neighbor colors).\"\"\"\n    return {v: (colors[v], tuple(sorted(colors[u] for u in G[v]))) for v in G}\n\n\ndef wl_refine(graphs, num_iterations=3):\n    \"\"\"\n    Color refinement run jointly on a list of graphs with one shared HASH table.\n\n    Returns `rounds`, where rounds[l] is a dict:\n        'colors' : [{node: color} per graph]             colors after round l\n        'agg'    : [{node: aggregated color} per graph]  what was hashed in round l\n        'table'  : {aggregated color: new color}         the HASH table of round l\n    rounds[0] is the initial coloring: every node gets color 1.\n    \"\"\"\n    rounds = [{'colors': [{v: 1 for v in G} for G in graphs], 'agg': None, 'table': {}}]\n    next_color = 2\n    for _ in range(num_iterations):\n        agg = [aggregate(G, c) for G, c in zip(graphs, rounds[-1]['colors'])]\n        # Step 3: injective hash. Every unseen aggregated color gets the next unused number.\n        # (Each round's inputs use fresh colors, so each round needs only its own table.)\n        table = {}\n        for a in agg:\n            for sig in a.values():\n                if sig not in table:\n                    table[sig] = next_color\n                    next_color += 1\n        colors = [{v: table[sig] for v, sig in a.items()} for a in agg]\n        rounds.append({'colors': colors, 'agg': agg, 'table': table})\n    return rounds\n","lines":[{"from":1,"to":4,"say":"aggregate 함수: 노드마다 (내 색, 이웃 색을 정렬해 묶은 튜플)을 만들어 사전으로 돌려줘요."},{"from":5,"to":15,"say":"wl_refine 함수의 이름과 설명이에요. 여러 그래프가 HASH 표를 같이 쓰며 색 정제를 하고 rounds 목록을 돌려준대요."},{"from":16,"to":16,"say":"`{v: 1 for v in G}` 는 노드마다 색 1 을 넣은 사전(p.7 의 한 줄 만들기). 그래프마다 담아 0라운드로 둬요."},{"from":17,"to":17,"say":"다음에 새로 줄 색 번호는 2 부터 시작해요."},{"from":18,"to":19,"say":"라운드 수만큼 반복하며, 지난 라운드 색으로 모든 노드의 집계 색을 만들어요."},{"from":20,"to":27,"say":"주석 두 줄 뒤, 빈 사전 table 에 처음 보는 집계 색마다 다음 번호를 적어요. 같은 조합은 같은 번호예요."},{"from":28,"to":31,"say":"표에서 새 번호를 찾아 노드를 다시 칠하고, 이번 라운드 결과를 rounds 끝에 붙여요. 다 돌면 rounds 를 돌려줘요."}],"link":"슬라이드의 '모든 노드가 같은 특징(같은 색)' 가정을 코드로 쓴 거예요. **색 정제(Color refinement)**의 출발점."},{"kind":"code","head":"처음엔 모든 노드가 색 1 (2/3)","file":"Sample_Code_3.ipynb 셀 15 (4.1 The Rule) (2/3)","code":"\ndef color_histogram(colors):\n    \"\"\"How many nodes carry each color: the graph-level fingerprint.\"\"\"\n    return dict(sorted(Counter(colors.values()).items()))\n\n\ndef wl_report(rounds, names):\n    \"\"\"The WL test: compare the two graphs' color histograms round by round.\"\"\"\n    differ = False\n    for l, r in enumerate(rounds):\n        h1, h2 = (color_histogram(c) for c in r['colors'])\n        differ = differ or h1 != h2\n        print(f\"round {l}:  {names[0]} {str(h1):<34s} {'==' if h1 == h2 else '!='}  {names[1]} {h2}\")\n    print('\\n→ NON-ISOMORPHIC (the histograms differ)' if differ else\n          '\\n→ INCONCLUSIVE (the histograms are always equal)')\n\n\n# ---- drawing -------------------------------------------------------------------------\ndef fmt_agg(sig):\n    \"\"\"(3, (3, 4)) -> '3,{3,4}'\"\"\"\n    own, nbrs = sig\n    return f\"{own},{{{','.join(map(str, nbrs))}}}\"\n\n\ndef draw_aggregated(G, pos, ax, colors, agg, title=None):\n    \"\"\"Each node is a box showing its aggregated color, filled with its current color.\"\"\"\n    nx.draw_networkx_edges(G, pos, ax=ax, edge_color=C_EDGE, width=2.0)\n    for v in G:\n        f = color_of(colors[v])\n        ax.text(*pos[v], fmt_agg(agg[v]), ha='center', va='center', fontsize=10, color=ink(f),\n                bbox=dict(boxstyle='round,pad=0.35', fc=f, ec=C_DARK, lw=1.2))\n    xs, ys = zip(*pos.values())\n    ax.set_xlim(min(xs) - 0.5, max(xs) + 0.5)\n    ax.set_ylim(min(ys) - 0.4, max(ys) + 0.4)\n    if title:\n        ax.set_title(title)\n    ax.set_axis_off()\n","lines":[{"from":1,"to":5,"say":"color_histogram 함수: Counter 로 색마다 노드가 몇 개인지 세서 번호 순으로 정리해요."},{"from":6,"to":16,"say":"wl_report 함수: 라운드마다 두 그래프의 색 개수표를 비교해 == 또는 != 를 출력하고, 마지막에 판정을 알려 줘요."},{"from":17,"to":23,"say":"그리기 부분 시작이에요. fmt_agg 는 (3, (3, 4)) 같은 집계 색을 '3,{3,4}' 글자로 바꿔요."},{"from":24,"to":38,"say":"draw_aggregated 함수: 노드마다 집계 색 글자를 지금 색으로 칠한 상자에 적어 그려요."}]},{"kind":"code","head":"처음엔 모든 노드가 색 1 (3/3)","file":"Sample_Code_3.ipynb 셀 15 (4.1 The Rule) (3/3)","code":"\ndef draw_hash_table(ax, table, title):\n    tab = ax.table(cellText=[[fmt_agg(sig), c] for sig, c in table.items()],\n                   colLabels=['aggregated color', 'new color'], loc='center', cellLoc='center')\n    tab.auto_set_font_size(False); tab.set_fontsize(11); tab.scale(1, 1.7)\n    for j in range(2):                                   # header row\n        tab[0, j].set_facecolor(C_DARK)\n        tab[0, j].get_text().set(color='white', fontweight='bold')\n    for i, c in enumerate(table.values(), start=1):      # paint each new color\n        tab[i, 1].set_facecolor(color_of(c))\n        tab[i, 1].get_text().set(color=ink(color_of(c)), fontweight='bold')\n    ax.set_title(title)\n    ax.set_axis_off()\n\n\ndef show_initial(graphs, names, positions, rounds):\n    fig, axes = plt.subplots(1, len(graphs), figsize=(11, 3))\n    for ax, G, name, pos, c in zip(axes, graphs, names, positions, rounds[0]['colors']):\n        draw_graph(G, pos, ax, colors=c, labels='color', title=name)\n    fig.suptitle('Step 1 - Assign initial colors: every node gets color 1',\n                 fontsize=13, fontweight='bold')\n    plt.tight_layout(); plt.show()\n\n\ndef show_round(graphs, names, positions, rounds, l):\n    \"\"\"One round, left to right: aggregated colors -> HASH table -> new colors.\"\"\"\n    r, prev = rounds[l], rounds[l - 1]['colors']\n    fig = plt.figure(figsize=(15, 5.6))\n    gs = fig.add_gridspec(2, 3, width_ratios=[1, 0.75, 1])\n    for i, (G, name, pos) in enumerate(zip(graphs, names, positions)):\n        draw_aggregated(G, pos, fig.add_subplot(gs[i, 0]), prev[i], r['agg'][i],\n                        title=f'{name}: aggregated colors')\n        draw_graph(G, pos, fig.add_subplot(gs[i, 2]), colors=r['colors'][i], labels='color',\n                   title=f'{name}: new colors')\n    draw_hash_table(fig.add_subplot(gs[:, 1]), r['table'], title=f'HASH table (round {l})')\n    fig.suptitle(f'Round {l}:   Step 2 - aggregate neighboring colors   →   '\n                 f'Step 3 - injectively hash   →   new colors', fontsize=13, fontweight='bold')\n    plt.tight_layout(); plt.show()","lines":[{"from":1,"to":14,"say":"draw_hash_table 함수: HASH 표를 '집계 색, 새 색' 두 열짜리 표 그림으로 그리고 새 색 칸을 그 색으로 칠해요."},{"from":15,"to":23,"say":"show_initial 함수: 모든 노드가 색 1 인 시작 그림을 그래프마다 그려요."},{"from":24,"to":38,"say":"show_round 함수: 한 라운드를 왼쪽 집계 색, 가운데 HASH 표, 오른쪽 새 색 순서로 한 장에 그려요."}]}]},{"p":12,"title":"국소 이웃 구조: 차수가 다른 1과 5","terms":["Local neighborhood structure","Node degree","Invariant","Aggregation","Mean pooling","Hop"],"pass1":[{"kind":"say","lines":["노드 하나를 둘러싼 가까운 주변의 연결 모양, 이걸 **국소 이웃 구조(Local neighborhood structure)**라고 해요.","가장 쉽게 보이는 차이는 이웃이 몇 명인가예요. 한 노드의 이웃 수를 **노드 차수(Node degree)**라고 해요.","노드 1은 이웃이 2명, 노드 5는 이웃이 3명이라 둘의 주변 모양은 달라요."]},{"kind":"look","head":"노란 두 노드","boxes":[{"x":0.375,"y":0.36,"w":0.05,"h":0.08,"say":"노드 1이에요. 선이 2개 붙어 있으니 이웃이 2명이에요."},{"x":0.375,"y":0.555,"w":0.05,"h":0.08,"say":"노드 5예요. 선이 3개 붙어 있으니 이웃이 3명이에요. 노란색은 '지금 비교하는 노드'라는 표시예요."}]}],"pass2":[{"kind":"look","head":"슬라이드 글자와 그림","boxes":[{"x":0.03,"y":0.14,"w":0.91,"h":0.06,"say":"**국소 이웃 구조(Local neighborhood structure)**: 그래프 전체가 아니라 노드 가까운 주변만 봐요."},{"x":0.375,"y":0.36,"w":0.05,"h":0.08,"say":"노드 1: 이웃 2, 5. 차수 2."},{"x":0.375,"y":0.555,"w":0.05,"h":0.08,"say":"노드 5: 이웃 1, 2, 4. 차수 3. 노란색은 '비교 중' 표시예요."}]},{"kind":"formula","head":"차수","tex":"\\deg(v) = |N(v)|","parts":[{"sym":"\\deg(v)","say":"노드 v 의 차수(친구 수)"},{"sym":"N(v)","say":"v 의 이웃 모음(친구 명단)"},{"sym":"|N(v)|","say":"모음 안 원소 개수"}],"whole":"차수는 이웃 모음의 크기예요. $\\deg(1) = 2$, $\\deg(5) = 3$."},{"kind":"compare","head":"1층 GNN 으로 1과 5 가르기 (모든 특징 1, {1, 1} 은 이웃 두 명의 특징 봉투)","cols":["집계","노드 1: {1, 1}","노드 5: {1, 1, 1}","구별?"],"rows":[["합","2","3","된다"],["평균","1","1","안 된다"],["최댓값","1","1","안 된다"]]},{"kind":"points","head":"정리","items":["차수는 이름표를 바꿔도 안 변하는 **불변량(Invariant)**. 그래서 1과 5는 같은 처지일 수 없어요.","모든 특징이 같을 때 1층 합 결과가 곧 차수예요.","노드 1, 2, 4 는 1층 합이 모두 2. 이 중 1과 4가 정말 같은지는 다음 쪽에서 봐요.","1층 나무는 뿌리와 첫 줄뿐이라, 1층으로 알 수 있는 구조는 차수까지예요."]},{"kind":"prof","when":"3주차 화요일 수업","lines":["노드 1 의 이웃은 2, 5 이고 노드 5 의 이웃은 1, 2, 4 예요.","그래서 1홉만 봐도 구별된다고 했어요. WL 도, GNN 도 구별해요."]},{"kind":"mining","src":"마이닝 9강 Graph Kernels","lines":["동형 판정의 첫 방법이 노드 수, 엣지 수, 차수 같은 불변량 비교였어요.","오늘 '차수가 다르면 구조가 다르다'는 그걸 노드 하나 주변에 적용한 거예요."]}],"pass3":[{"kind":"english","head":"구조 성질을 넣는 이유 (2024 가을 기말 해설 문장을 줄임)","en":"Encoding structural properties like degree or motifs increases the power of graph isomorphism tests such as the WL test.","ko":"차수나 모티프 같은 구조 성질을 넣으면 WL 테스트 같은 동형 판정의 능력이 올라간다.","tip":"structural properties, degree, isomorphism test 세 말을 기억해요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["'차수가 다르면 구조가 다르다'는 맞지만 '차수가 같으면 구조가 같다'는 틀려요. 다음 쪽 1과 4.","차수가 달라도 평균이나 최댓값 **집계(Aggregation)**는 못 알아챌 수 있어요.","방향 있는 그래프라면 들어오는 선과 나가는 선을 따로 세요."]},{"kind":"check","q":"모든 특징이 1일 때, 1층 **평균 풀링(Mean pooling)**으로 노드 1과 5를 가를 수 있나요?","choices":["가를 수 있다. 2 대 3","가를 수 없다. 둘 다 1","가를 수 있다. 1 대 3","가를 수 없다. 둘 다 0"],"a":1,"why":"평균은 2÷2 = 1, 3÷3 = 1 로 같아요. 합이라야 2 대 3 으로 갈라요."}],"pass4":[{"kind":"code","head":"차수 목록 세기","file":"Sample_Code_3.ipynb 셀 8 (2. The Failure)","code":"C6    = nx.cycle_graph(6)\nTwoC3 = nx.disjoint_union(nx.cycle_graph(3), nx.cycle_graph(3))\n\nfor name, G in [('C6', C6), ('2 x C3', TwoC3)]:\n    print(f'{name:7s} | nodes {G.number_of_nodes()} | edges {G.number_of_edges()} '\n          f'| components {nx.number_connected_components(G)} '\n          f'| degrees {sorted(d for _, d in G.degree())} '\n          f'| triangles {sum(nx.triangles(G).values()) // 3}')\nprint(f'Isomorphic? {nx.is_isomorphic(C6, TwoC3)}')\n\n# Fixed layouts reused by later figures: a hexagon, and two triangles side by side\nPOS_C6  = nx.circular_layout(C6)\nPOS_2C3 = {}\nfor nodes, cx, start in [([0, 1, 2], -1.0, np.pi), ([3, 4, 5], 1.0, 0.0)]:\n    for i, n in enumerate(nodes):\n        a = start + 2 * np.pi * i / 3\n        POS_2C3[n] = np.array([cx + 0.55 * np.cos(a), 0.55 * np.sin(a)])\n\nfig, axes = plt.subplots(1, 2, figsize=(10, 3.8))\ndraw_graph(C6, POS_C6, axes[0], title='$C_6$  (one 6-cycle)')\ndraw_graph(TwoC3, POS_2C3, axes[1], title='$2 \\\\times C_3$  (two triangles)')\nfig.suptitle('Two non-isomorphic graphs - every node has degree 2', fontsize=13, fontweight='bold')\nplt.tight_layout(); plt.show()","lines":[{"from":1,"to":2,"say":"C6 는 점 6개가 한 바퀴 이어진 육각형, TwoC3 는 삼각형 두 개를 따로 놓은 그래프예요. `nx.` 는 networkx 기능이에요."},{"from":3,"to":6,"say":"두 그래프마다 노드 수, 엣지 수, 덩어리 수, 차수 목록, 삼각형 수를 한 줄씩 출력하고, 마지막 줄에서 동형인지 물어요."},{"from":7,"to":7,"say":"`G.degree()` 는 (노드, 차수) 쌍들을 줘요. `for _, d in` 으로 차수 d 만 꺼내 `sorted` 로 정렬해요. `_` 는 안 쓰는 값 자리."},{"from":8,"to":9,"say":"두 그래프마다 노드 수, 엣지 수, 덩어리 수, 차수 목록, 삼각형 수를 한 줄씩 출력하고, 마지막 줄에서 동형인지 물어요."},{"from":10,"to":17,"say":"뒤 그림에서 계속 쓸 좌표를 정해요. 육각형은 원 모양으로, 삼각형 두 개는 왼쪽과 오른쪽에 나란히 놓아요."},{"from":18,"to":23,"say":"그림판 두 칸을 만들어 두 그래프를 나란히 그리고 화면에 보여 줘요."}],"link":"슬라이드의 **노드 차수(Node degree)** 를 모든 노드에 대해 센 거예요."},{"kind":"say","lines":["출력에서 C6 과 2 x C3 은 degrees [2, 2, 2, 2, 2, 2] 로 같았죠(p.5).","차수만으로는 못 가르는 쌍이에요. 한 층 더 깊이 봐야 할 때가 있어요."]}]},{"p":13,"title":"국소 이웃 구조: 차수 같은 1과 4","terms":["Node degree","Multiset","Color refinement","1-WL test","Hash function","Local neighborhood structure"],"pass1":[{"kind":"say","lines":["이번엔 노드 1과 노드 4를 비교해요. 둘 다 이웃이 2명이라 **노드 차수(Node degree)**는 같아요.","그런데 이웃들을 한 번 더 들여다보면 달라요.","노드 1의 두 이웃은 각자 친구가 2명, 3명이고, 노드 4의 두 이웃은 1명, 3명이에요.","이런 차이는 한 걸음 더 깊이 볼 때, 즉 GNN 2층에서 드러나요."]},{"kind":"analogy","head":"친구 수는 같은 민지와 수아","scene":"민지와 수아는 둘 다 친구가 2명이에요. 친구 수만 보면 두 사람 처지는 똑같아 보여요. 그런데 민지의 친구들은 각자 친구가 2명, 3명이고, 수아의 친구들은 1명, 3명이에요. 친구의 친구까지 살펴봐야 두 사람 주변이 다르다는 걸 알 수 있어요.","map":[["민지와 수아","노드 1과 노드 4"],["친구 수","**노드 차수(Node degree)**"],["친구의 친구까지 살펴보기","한 층 더 깊이 보기(GNN 2층)"]]}],"pass2":[{"kind":"look","head":"슬라이드 글자와 참고 상자","boxes":[{"x":0.03,"y":0.14,"w":0.91,"h":0.1,"say":"노드 1과 4는 같은 차수 2. 그러나 이웃들의 차수가 달라 이웃 구조가 달라요."},{"x":0.375,"y":0.36,"w":0.05,"h":0.08,"say":"노드 1 의 이웃: 2(차수 2), 5(차수 3)."},{"x":0.48,"y":0.555,"w":0.05,"h":0.08,"say":"노드 4 의 이웃: 3(차수 1), 5(차수 3)."},{"x":0.56,"y":0.62,"w":0.35,"h":0.25,"say":"참고 상자: 1 은 {2, 3}, 4 는 {1, 3}. 노드 자신이 아니라 이웃들의 차수예요."}]},{"kind":"formula","head":"이웃 차수 봉투","tex":"\\{\\!\\{\\deg(u) : u \\in N(1)\\}\\!\\} = \\{\\!\\{2, 3\\}\\!\\},\\quad \\{\\!\\{\\deg(u) : u \\in N(4)\\}\\!\\} = \\{\\!\\{1, 3\\}\\!\\}","parts":[{"sym":"\\{\\!\\{\\ \\}\\!\\}","say":"**멀티셋(Multiset)**: 순서 없음, 개수는 셈"},{"sym":"u \\in N(1)","say":"노드 1 의 이웃 하나하나"},{"sym":"\\deg(u)","say":"그 이웃의 차수(친구의 친구 수)"}],"whole":"봉투가 {2, 3} 대 {1, 3} 으로 달라서 두 노드의 **국소 이웃 구조(Local neighborhood structure)**가 달라요."},{"kind":"figure","head":"**색 정제(Color refinement)** 세 라운드","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\">\n<line class=\"e\" x1=\"35\" y1=\"80\" x2=\"95\" y2=\"80\"/>\n<line class=\"e\" x1=\"35\" y1=\"80\" x2=\"35\" y2=\"150\"/>\n<line class=\"e\" x1=\"95\" y1=\"80\" x2=\"35\" y2=\"150\"/>\n<line class=\"e\" x1=\"35\" y1=\"150\" x2=\"95\" y2=\"150\"/>\n<line class=\"e\" x1=\"95\" y1=\"150\" x2=\"145\" y2=\"115\"/>\n<circle class=\"n\" cx=\"35\" cy=\"80\" r=\"16\"/>\n<text class=\"tl\" x=\"35\" y=\"85\" font-size=\"14\" text-anchor=\"middle\">1<\/text>\n<circle class=\"n\" cx=\"95\" cy=\"80\" r=\"16\"/>\n<text class=\"tl\" x=\"95\" y=\"85\" font-size=\"14\" text-anchor=\"middle\">1<\/text>\n<circle class=\"n\" cx=\"145\" cy=\"115\" r=\"16\"/>\n<text class=\"tl\" x=\"145\" y=\"120\" font-size=\"14\" text-anchor=\"middle\">1<\/text>\n<circle class=\"n\" cx=\"95\" cy=\"150\" r=\"16\"/>\n<text class=\"tl\" x=\"95\" y=\"155\" font-size=\"14\" text-anchor=\"middle\">1<\/text>\n<circle class=\"n\" cx=\"35\" cy=\"150\" r=\"16\"/>\n<text class=\"tl\" x=\"35\" y=\"155\" font-size=\"14\" text-anchor=\"middle\">1<\/text>\n<text class=\"tb\" x=\"85\" y=\"40\" font-size=\"16\" text-anchor=\"middle\">0라운드<\/text>\n<text class=\"tm\" x=\"85\" y=\"200\" font-size=\"14\" text-anchor=\"middle\">모두 색 1<\/text>\n<line class=\"e b1\" x1=\"190\" y1=\"80\" x2=\"250\" y2=\"80\"/>\n<line class=\"e b1\" x1=\"190\" y1=\"80\" x2=\"190\" y2=\"150\"/>\n<line class=\"e b1\" x1=\"250\" y1=\"80\" x2=\"190\" y2=\"150\"/>\n<line class=\"e b1\" x1=\"190\" y1=\"150\" x2=\"250\" y2=\"150\"/>\n<line class=\"e b1\" x1=\"250\" y1=\"150\" x2=\"300\" y2=\"115\"/>\n<circle class=\"n3 b1\" cx=\"190\" cy=\"80\" r=\"16\"/>\n<text class=\"tl b1\" x=\"190\" y=\"85\" font-size=\"14\" text-anchor=\"middle\">2<\/text>\n<circle class=\"n3 b1\" cx=\"250\" cy=\"80\" r=\"16\"/>\n<text class=\"tl b1\" x=\"250\" y=\"85\" font-size=\"14\" text-anchor=\"middle\">2<\/text>\n<circle class=\"n3 b1\" cx=\"300\" cy=\"115\" r=\"16\"/>\n<text class=\"tl b1\" x=\"300\" y=\"120\" font-size=\"14\" text-anchor=\"middle\">3<\/text>\n<circle class=\"n3 b1\" cx=\"250\" cy=\"150\" r=\"16\"/>\n<text class=\"tl b1\" x=\"250\" y=\"155\" font-size=\"14\" text-anchor=\"middle\">2<\/text>\n<circle class=\"n3 b1\" cx=\"190\" cy=\"150\" r=\"16\"/>\n<text class=\"tl b1\" x=\"190\" y=\"155\" font-size=\"14\" text-anchor=\"middle\">4<\/text>\n<text class=\"tb b1\" x=\"240\" y=\"40\" font-size=\"16\" text-anchor=\"middle\">1라운드<\/text>\n<text class=\"tm b1\" x=\"240\" y=\"200\" font-size=\"14\" text-anchor=\"middle\">색 = 차수<\/text>\n<line class=\"e b2\" x1=\"345\" y1=\"80\" x2=\"405\" y2=\"80\"/>\n<line class=\"e b2\" x1=\"345\" y1=\"80\" x2=\"345\" y2=\"150\"/>\n<line class=\"e b2\" x1=\"405\" y1=\"80\" x2=\"345\" y2=\"150\"/>\n<line class=\"e b2\" x1=\"345\" y1=\"150\" x2=\"405\" y2=\"150\"/>\n<line class=\"e b2\" x1=\"405\" y1=\"150\" x2=\"455\" y2=\"115\"/>\n<circle class=\"n3 b2\" cx=\"345\" cy=\"80\" r=\"16\"/>\n<text class=\"tl b2\" x=\"345\" y=\"85\" font-size=\"14\" text-anchor=\"middle\">5<\/text>\n<circle class=\"n3 b2\" cx=\"405\" cy=\"80\" r=\"16\"/>\n<text class=\"tl b2\" x=\"405\" y=\"85\" font-size=\"14\" text-anchor=\"middle\">5<\/text>\n<circle class=\"n3 b2\" cx=\"455\" cy=\"115\" r=\"16\"/>\n<text class=\"tl b2\" x=\"455\" y=\"120\" font-size=\"14\" text-anchor=\"middle\">6<\/text>\n<circle class=\"n2 b2\" cx=\"405\" cy=\"150\" r=\"16\"/>\n<text class=\"tl b2\" x=\"405\" y=\"155\" font-size=\"14\" text-anchor=\"middle\">7<\/text>\n<circle class=\"n3 b2\" cx=\"345\" cy=\"150\" r=\"16\"/>\n<text class=\"tl b2\" x=\"345\" y=\"155\" font-size=\"14\" text-anchor=\"middle\">8<\/text>\n<text class=\"tb b2\" x=\"395\" y=\"40\" font-size=\"16\" text-anchor=\"middle\">2라운드<\/text>\n<text class=\"tm b2\" x=\"395\" y=\"200\" font-size=\"14\" text-anchor=\"middle\">4만 새 색 7<\/text>\n<text class=\"tb b3\" x=\"240\" y=\"245\" font-size=\"15\" text-anchor=\"middle\">노드 안 숫자 = 색 번호. 1과 2는 끝까지 같은 색 5<\/text>\n<\/svg>","caption":"1라운드는 차수로 나뉘고, 2라운드에 노드 4 만 새 색으로 갈라져요.","builds":3},{"kind":"compare","head":"색 정제 표 ('1, {1, 1}' 은 내 색, 이웃 색 봉투. 새 색 번호는 처음 나온 순서)","cols":["노드","1라운드 입력","1라운드 색","2라운드 입력","2라운드 색"],"rows":[["1","1, {1, 1}","2","2, {2, 4}","5"],["2","1, {1, 1}","2","2, {2, 4}","5"],["3","1, {1}","3","3, {2}","6"],["4","1, {1, 1}","2","2, {3, 4}","7"],["5","1, {1, 1, 1}","4","4, {2, 2, 2}","8"]]},{"kind":"points","head":"표 읽기","items":["1라운드 색은 사실 차수예요. 2 = 차수 2, 3 = 차수 1, 4 = 차수 3.","2라운드: 노드 1 봉투 {2, 4} 와 노드 4 봉투 {3, 4} 가 달라 4 에 새 색 7.","노드 1과 2는 끝까지 같은 색 5예요.","같은 입력엔 같은 번호, 다른 입력엔 다른 번호. 이게 **해시 함수(Hash function)**의 역할이에요."]},{"kind":"steps","head":"2층 합 GNN 으로 확인 (모든 특징 1)","steps":["1층 = 차수: 노드 1 은 2, 2 는 2, 3 은 1, 4 는 2, 5 는 3","노드 1 의 2층: 이웃 2 의 2 + 이웃 5 의 3 = 5","노드 4 의 2층: 이웃 3 의 1 + 이웃 5 의 3 = 4","나머지: 노드 2 는 5, 노드 3 은 2, 노드 5 는 2 + 2 + 2 = 6"],"answer":"1층에선 1과 4가 2 대 2 로 같다가 2층에서 5 대 4 로 갈라져요. 색 정제와 같은 곳에서 갈려요."},{"kind":"prof","when":"1주차 목요일 수업","lines":["주변 구조를 모를 땐 옆 노드를 참고하면 되고, 그게 WL 재라벨링이라 했어요.","'나는 B, C, D 를 이웃으로 가진 A 야' 같은 설명을 붙이고 반복한대요.","GNN은 특정 조건에서 WL 재라벨링과 작동이 똑같아 기본 표현력을 보장한대요."]},{"kind":"mining","src":"마이닝 9강 Graph Kernels","lines":["WL 절차: 모든 라벨 1 로 시작하고, 노드마다 (내 라벨, 이웃 라벨 멀티셋)을 적어요.","같은 묶음끼리 같은 새 번호로 압축해요. 이때 쓰는 게 **해시 함수(Hash function)**예요.","라벨 분포가 한 번이라도 다르면 동형 아님. 분할이 안 바뀌면 멈춰요."]}],"pass3":[{"kind":"exam","src":"그래프 마이닝 2024 봄 중간 11번 (10점), 2023 봄 기말 7번 (10점)","q":"Conduct WL relabeling with the maximum degree 3; then decide isomorphism (2023) or build WL feature vectors and cosine similarity (2024).","qko":"최대 차수 3까지 WL 재라벨링을 하고, 두 그래프가 동형인지 판정하라(2023). 또는 WL 특징 벡터로 코사인 유사도를 구하라(2024).","solve":["1단계: 모든 노드 라벨을 1 로 둬요.","2단계: 노드마다 (내 라벨, 이웃 라벨 **멀티셋(Multiset)**)을 적어요. 위 표의 '입력' 열.","3단계: 같은 묶음끼리 같은 새 번호로 압축해요. 위 표의 '색' 열.","4단계: 두 그래프의 라벨 개수 분포를 비교해요. 한 번이라도 다르면 동형 아님.","특징 벡터 문제는 라벨마다 개수를 세어 벡터로 만들고 코사인 유사도를 계산해요."],"answer":"그림이 텍스트에 없어 숫자 답은 생략해요. 핵심은 라운드별 (내 라벨, 이웃 멀티셋) 표를 빠짐없이 적는 거예요."},{"kind":"english","head":"GNN 과 WL 을 잇는 문장 (예상 서술형)","en":"Like the WL hash maps different multisets to different labels, GIN's sum and MLP map different neighbor multisets to different vectors.","ko":"WL 해시가 서로 다른 멀티셋을 다른 라벨로 보내듯, GIN 의 합과 MLP 도 서로 다른 이웃 멀티셋을 다른 벡터로 보낸다.","tip":"2024 가을 기말 5번 (b) 답의 뒷받침 문장으로 써요. **1-WL 테스트(1-WL test)** 와 연결돼요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["2층이라도 모으는 법이 봉투 차이를 뭉개면 소용없어요. {2, 3} 과 {2, 2, 3} 은 최댓값이 둘 다 3.","참고 상자의 '2와 3' 은 노드 1 자신이 아니라 이웃들의 차수예요.","색 번호 자체엔 크기 뜻이 없어요. 7 이 5 보다 '크다'는 뜻이 아니라 그냥 다른 이름표예요."]},{"kind":"check","q":"**색 정제(Color refinement)** 2라운드에서 노드 4 가 노드 1 과 다른 색을 받는 이유는?","choices":["노드 4 의 차수가 더 커서","이웃 색 봉투가 {3, 4} 로 노드 1 의 {2, 4} 와 달라서","노드 번호가 달라서","노드 4 가 그래프 끝에 있어서"],"a":1,"why":"차수는 둘 다 2(1라운드 색 2)로 같아요. 이웃 봉투가 달라서 새 색이 갈려요."}],"pass4":[{"kind":"pyterm","name":"if 와 in","say":["`if 조건:` 아래 들여 쓴 줄은 조건이 참일 때만 실행돼요.","`키 in 사전` 은 그 키가 있는지, `not in` 은 없는지 물어요.","`n += 1` 은 n 을 1 올려요."],"example":"table = {}\nif 'a' not in table:\n    table['a'] = 2\nprint(table)","out":"{'a': 2}"},{"kind":"code","head":"색 정제: 처음 보는 봉투에 새 번호 (1/3)","file":"Sample_Code_3.ipynb 셀 15 (4.1 The Rule) (1/3)","code":"def aggregate(G, colors):\n    \"\"\"Step 2: aggregated color of every node = (own color, sorted tuple of neighbor colors).\"\"\"\n    return {v: (colors[v], tuple(sorted(colors[u] for u in G[v]))) for v in G}\n\n\ndef wl_refine(graphs, num_iterations=3):\n    \"\"\"\n    Color refinement run jointly on a list of graphs with one shared HASH table.\n\n    Returns `rounds`, where rounds[l] is a dict:\n        'colors' : [{node: color} per graph]             colors after round l\n        'agg'    : [{node: aggregated color} per graph]  what was hashed in round l\n        'table'  : {aggregated color: new color}         the HASH table of round l\n    rounds[0] is the initial coloring: every node gets color 1.\n    \"\"\"\n    rounds = [{'colors': [{v: 1 for v in G} for G in graphs], 'agg': None, 'table': {}}]\n    next_color = 2\n    for _ in range(num_iterations):\n        agg = [aggregate(G, c) for G, c in zip(graphs, rounds[-1]['colors'])]\n        # Step 3: injective hash. Every unseen aggregated color gets the next unused number.\n        # (Each round's inputs use fresh colors, so each round needs only its own table.)\n        table = {}\n        for a in agg:\n            for sig in a.values():\n                if sig not in table:\n                    table[sig] = next_color\n                    next_color += 1\n        colors = [{v: table[sig] for v, sig in a.items()} for a in agg]\n        rounds.append({'colors': colors, 'agg': agg, 'table': table})\n    return rounds\n","lines":[{"from":1,"to":4,"say":"aggregate 함수: 노드마다 (내 색, 이웃 색을 정렬해 묶은 튜플)을 만들어 사전으로 돌려줘요."},{"from":5,"to":15,"say":"wl_refine 함수의 이름과 설명이에요. 여러 그래프가 HASH 표를 같이 쓰며 색 정제를 하고 rounds 목록을 돌려준대요."},{"from":16,"to":17,"say":"0라운드: 모든 노드를 색 1 로 칠해 rounds 에 넣어요. 새 번호는 2 부터 줘요."},{"from":18,"to":18,"say":"라운드 수만큼 반복해요. `_` 는 반복 번호를 안 쓴다는 표시(p.12)."},{"from":19,"to":19,"say":"지난 라운드 색으로 모든 노드의 (내 색, 이웃 색 봉투)를 만들어요. p.7 의 aggregate 함수예요."},{"from":20,"to":21,"say":"`#` 뒤는 주석, 실행 안 되는 메모예요. '단사 해시: 처음 보는 봉투에 다음 번호'."},{"from":22,"to":27,"say":"표(사전)에 봉투가 없으면(`not in`) 새 번호를 적고 번호를 1 올려요. 같은 봉투는 같은 번호."},{"from":28,"to":29,"say":"노드마다 표에서 새 색을 찾아 칠하고, 이번 라운드 결과를 `append` 로 목록 끝에 붙여요."},{"from":30,"to":31,"say":"표에서 새 번호를 찾아 노드를 다시 칠하고, 이번 라운드 결과를 rounds 끝에 붙여요. 다 돌면 rounds 를 돌려줘요."}],"link":"슬라이드 표의 '같은 봉투는 같은 새 색' 규칙, 즉 **해시 함수(Hash function)**를 사전으로 만든 거예요."},{"kind":"code","head":"색 정제: 처음 보는 봉투에 새 번호 (2/3)","file":"Sample_Code_3.ipynb 셀 15 (4.1 The Rule) (2/3)","code":"\ndef color_histogram(colors):\n    \"\"\"How many nodes carry each color: the graph-level fingerprint.\"\"\"\n    return dict(sorted(Counter(colors.values()).items()))\n\n\ndef wl_report(rounds, names):\n    \"\"\"The WL test: compare the two graphs' color histograms round by round.\"\"\"\n    differ = False\n    for l, r in enumerate(rounds):\n        h1, h2 = (color_histogram(c) for c in r['colors'])\n        differ = differ or h1 != h2\n        print(f\"round {l}:  {names[0]} {str(h1):<34s} {'==' if h1 == h2 else '!='}  {names[1]} {h2}\")\n    print('\\n→ NON-ISOMORPHIC (the histograms differ)' if differ else\n          '\\n→ INCONCLUSIVE (the histograms are always equal)')\n\n\n# ---- drawing -------------------------------------------------------------------------\ndef fmt_agg(sig):\n    \"\"\"(3, (3, 4)) -> '3,{3,4}'\"\"\"\n    own, nbrs = sig\n    return f\"{own},{{{','.join(map(str, nbrs))}}}\"\n\n\ndef draw_aggregated(G, pos, ax, colors, agg, title=None):\n    \"\"\"Each node is a box showing its aggregated color, filled with its current color.\"\"\"\n    nx.draw_networkx_edges(G, pos, ax=ax, edge_color=C_EDGE, width=2.0)\n    for v in G:\n        f = color_of(colors[v])\n        ax.text(*pos[v], fmt_agg(agg[v]), ha='center', va='center', fontsize=10, color=ink(f),\n                bbox=dict(boxstyle='round,pad=0.35', fc=f, ec=C_DARK, lw=1.2))\n    xs, ys = zip(*pos.values())\n    ax.set_xlim(min(xs) - 0.5, max(xs) + 0.5)\n    ax.set_ylim(min(ys) - 0.4, max(ys) + 0.4)\n    if title:\n        ax.set_title(title)\n    ax.set_axis_off()\n","lines":[{"from":1,"to":5,"say":"color_histogram 함수: Counter 로 색마다 노드가 몇 개인지 세서 번호 순으로 정리해요."},{"from":6,"to":16,"say":"wl_report 함수: 라운드마다 두 그래프의 색 개수표를 비교해 == 또는 != 를 출력하고, 마지막에 판정을 알려 줘요."},{"from":17,"to":23,"say":"그리기 부분 시작이에요. fmt_agg 는 (3, (3, 4)) 같은 집계 색을 '3,{3,4}' 글자로 바꿔요."},{"from":24,"to":38,"say":"draw_aggregated 함수: 노드마다 집계 색 글자를 지금 색으로 칠한 상자에 적어 그려요."}]},{"kind":"code","head":"색 정제: 처음 보는 봉투에 새 번호 (3/3)","file":"Sample_Code_3.ipynb 셀 15 (4.1 The Rule) (3/3)","code":"\ndef draw_hash_table(ax, table, title):\n    tab = ax.table(cellText=[[fmt_agg(sig), c] for sig, c in table.items()],\n                   colLabels=['aggregated color', 'new color'], loc='center', cellLoc='center')\n    tab.auto_set_font_size(False); tab.set_fontsize(11); tab.scale(1, 1.7)\n    for j in range(2):                                   # header row\n        tab[0, j].set_facecolor(C_DARK)\n        tab[0, j].get_text().set(color='white', fontweight='bold')\n    for i, c in enumerate(table.values(), start=1):      # paint each new color\n        tab[i, 1].set_facecolor(color_of(c))\n        tab[i, 1].get_text().set(color=ink(color_of(c)), fontweight='bold')\n    ax.set_title(title)\n    ax.set_axis_off()\n\n\ndef show_initial(graphs, names, positions, rounds):\n    fig, axes = plt.subplots(1, len(graphs), figsize=(11, 3))\n    for ax, G, name, pos, c in zip(axes, graphs, names, positions, rounds[0]['colors']):\n        draw_graph(G, pos, ax, colors=c, labels='color', title=name)\n    fig.suptitle('Step 1 - Assign initial colors: every node gets color 1',\n                 fontsize=13, fontweight='bold')\n    plt.tight_layout(); plt.show()\n\n\ndef show_round(graphs, names, positions, rounds, l):\n    \"\"\"One round, left to right: aggregated colors -> HASH table -> new colors.\"\"\"\n    r, prev = rounds[l], rounds[l - 1]['colors']\n    fig = plt.figure(figsize=(15, 5.6))\n    gs = fig.add_gridspec(2, 3, width_ratios=[1, 0.75, 1])\n    for i, (G, name, pos) in enumerate(zip(graphs, names, positions)):\n        draw_aggregated(G, pos, fig.add_subplot(gs[i, 0]), prev[i], r['agg'][i],\n                        title=f'{name}: aggregated colors')\n        draw_graph(G, pos, fig.add_subplot(gs[i, 2]), colors=r['colors'][i], labels='color',\n                   title=f'{name}: new colors')\n    draw_hash_table(fig.add_subplot(gs[:, 1]), r['table'], title=f'HASH table (round {l})')\n    fig.suptitle(f'Round {l}:   Step 2 - aggregate neighboring colors   →   '\n                 f'Step 3 - injectively hash   →   new colors', fontsize=13, fontweight='bold')\n    plt.tight_layout(); plt.show()","lines":[{"from":1,"to":14,"say":"draw_hash_table 함수: HASH 표를 '집계 색, 새 색' 두 열짜리 표 그림으로 그리고 새 색 칸을 그 색으로 칠해요."},{"from":15,"to":23,"say":"show_initial 함수: 모든 노드가 색 1 인 시작 그림을 그래프마다 그려요."},{"from":24,"to":38,"say":"show_round 함수: 한 라운드를 왼쪽 집계 색, 가운데 HASH 표, 오른쪽 새 색 순서로 한 장에 그려요."}]},{"kind":"steps","head":"노트북 출력 읽기 (셀 23, G1 대 G2)","steps":["round 0: 둘 다 {1: 6}. 모두 색 1","round 1: 둘 다 {2: 4, 3: 1, 4: 1}. 색이 곧 차수라 같아요","round 2: G1 {5: 3, 6: 1, 7: 1, 8: 1}, G2 {5: 2, 6: 1, 8: 1, 9: 1, 10: 1}"],"answer":"2라운드에 색 개수 분포가 달라져 NON-ISOMORPHIC. 오늘의 노드 1과 4처럼 이웃 차수 차이가 드러난 거예요."}]},{"p":14,"title":"국소 이웃 구조: 대칭인 1과 2","terms":["Symmetric","Hop","Node embedding","Color refinement","1-WL test","Local neighborhood structure"],"pass1":[{"kind":"say","lines":["노드 1과 노드 2는 이름표를 서로 바꿔 붙여도 그래프가 똑같아 보여요.","이런 두 노드를 **대칭(Symmetric)**이라고 해요. 둘의 주변 연결 모양이 완전히 같다는 뜻이에요.","그래서 어떤 GNN이든 둘에게 같은 **노드 임베딩(Node embedding)**, 즉 같은 숫자 설명을 주는 게 정답이에요."]},{"kind":"analogy","head":"자리를 바꿔도 아무도 모르는 두 자리","scene":"교실에 나란히 붙은 두 자리가 있어요. 두 학생은 서로 짝꿍이고, 둘 다 같은 뒷자리 친구 한 명과 가까워요. 그래서 두 학생이 자리를 바꿔 앉아도 교실의 친구 관계는 하나도 달라지지 않아요. 자리 배치만 보는 사람은 두 자리를 구별할 방법이 없고, 구별할 필요도 없어요.","map":[["나란히 붙은 두 자리","노드 1과 노드 2"],["바꿔 앉아도 관계가 그대로","**대칭(Symmetric)**"],["짝꿍과 뒷자리 친구","두 노드의 이웃 구조"]]}],"pass2":[{"kind":"look","head":"슬라이드 글자와 참고 상자","boxes":[{"x":0.03,"y":0.14,"w":0.91,"h":0.1,"say":"노드 1과 2는 그래프 안에서 **대칭(Symmetric)**이라 이웃 구조가 같아요."},{"x":0.375,"y":0.36,"w":0.155,"h":0.08,"say":"노란 두 노드 1, 2. 서로 이웃이고 둘 다 5 와도 이어져 있어요."},{"x":0.54,"y":0.62,"w":0.42,"h":0.14,"say":"참고: 노드 1 의 이웃 차수 2와 3, 노드 2 의 이웃도 2와 3."},{"x":0.55,"y":0.77,"w":0.3,"h":0.12,"say":"2**홉(Hop)** 이웃까지 가도 같아요. 둘 다 5 를 거쳐 노드 4(차수 2)에 닿아요."}]},{"kind":"steps","head":"이름표 1 과 2 맞바꾸기","steps":["1-2 는 2-1: 같은 선이라 있음","1-5 는 2-5: 있음","2-5 는 1-5: 있음","5-4, 4-3 은 그대로: 있음"],"answer":"선 5개가 전부 원래 목록에 다시 나와요. 그래프를 자기 자신으로 옮기는 짝짓기가 있으니 1과 2는 대칭이에요."},{"kind":"compare","head":"거리별로 보이는 노드 (괄호는 차수)","cols":["거리","노드 1 에서","노드 2 에서"],"rows":[["0 (자기)","1 (2)","2 (2)"],["1홉","2 (2), 5 (3)","1 (2), 5 (3)"],["2홉","4 (2)","4 (2)"],["3홉","3 (1)","3 (1)"]]},{"kind":"points","head":"세 방법이 같은 결론","items":["p.6 나무 모양 코드: 1과 2 모두 {2, 3}","p.13 **색 정제(Color refinement)**: 둘 다 끝까지 같은 색","p.13 2층 합: 둘 다 5","GNN 계산엔 번호가 안 들어가요. 특징과 이웃 관계가 같으니 계산도 한 글자도 안 달라요."]},{"kind":"prof","when":"3주차 화요일 수업","lines":["노드 1 과 2 는 계산 그래프가 거의 같아서 구별하기 애매하다고 했어요.","초기 특징이 다르지 않으면 둘을 분별하기가 굉장히 어렵대요.","반면 1 과 3, 1 과 5 는 계산 그래프가 달라 확실히 달라요."]},{"kind":"mining","src":"마이닝 9강 Graph Kernels","lines":["동형 예제에서 $f(a) = e$, $f(b) = a$ 처럼 노드 대응을 적었죠.","이번엔 같은 그래프 안에서 $f(1) = 2$, $f(2) = 1$, 나머지는 제자리인 짝짓기예요.","모든 선을 보존하니 1과 2는 구조적으로 구별할 수 없는 자리예요."]}],"pass3":[{"kind":"english","head":"대칭 노드 서술 (예상 서술형)","en":"Nodes 1 and 2 are symmetric, so they have identical neighborhood structures and any GNN should give them the same embedding.","ko":"노드 1과 2는 대칭이라 이웃 구조가 같고, 어떤 GNN이든 같은 임베딩을 주는 게 맞다.","tip":"symmetric, identical neighborhood structures, same embedding 세 덩어리로 외워요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["'차수가 같다'와 '이웃 구조가 같다'는 달라요. 1과 4는 차수만, 1과 2는 모든 거리에서 같아요.","'2홉까지 같다'만으로 대칭이라 단정할 수 없어요. 확실한 증거는 이름표를 바꿔도 선 목록이 그대로인지예요.","대칭인 두 노드는 **1-WL 테스트(1-WL test)**로도, 이상적인 모델로도 구별되지 않아요. 원래 같은 자리라서요."]},{"kind":"check","q":"지금까지 본 세 쌍 중, GNN 이 구별하지 않는 게 정답인 쌍은?","choices":["(1, 5)","(1, 4)","(1, 2)","셋 다 구별해야 한다"],"a":2,"why":"(1, 5) 는 차수, (1, 4) 는 이웃 차수가 달라요. (1, 2) 는 **대칭(Symmetric)**이라 같은 임베딩이 정답이에요."}],"pass4":[{"kind":"code","head":"구조적으로 구별 불가능한 노드 찾기","file":"Sample_Code_3.ipynb 셀 30 (4.4 Refinement Stabilizes Quickly)","code":"KC = nx.karate_club_graph()\nexamples = {'Path $P_7$': nx.path_graph(7), 'Ternary tree': nx.balanced_tree(3, 2),\n            '$C_6$': C6, 'Karate club': KC}\n\nfig, (ax1, ax2) = plt.subplots(1, 2, figsize=(15, 5), gridspec_kw={'width_ratios': [1, 1.3]})\nfor name, G in examples.items():\n    counts = [len(set(r['colors'][0].values())) for r in wl_refine([G], 8)]\n    ax1.plot(counts, marker='o', lw=2, label=f'{name} (n={G.number_of_nodes()})')\nax1.set(xlabel='round $\\\\ell$', ylabel='number of distinct colors',\n        title='Number of colors per round')\nax1.grid(alpha=0.3); ax1.legend(fontsize=9)\n\n# Recolor for display: classes with 2+ nodes get colors 1, 2, ...; unique nodes get 0 (gray)\nfinal = wl_refine([KC], 3)[-1]['colors'][0]\nsizes = Counter(final.values())\nshared = {c: i for i, c in enumerate(sorted(c for c in sizes if sizes[c] > 1), start=1)}\ndraw_graph(KC, nx.spring_layout(KC, seed=42, k=0.5), ax2,\n           colors={v: shared.get(c, 0) for v, c in final.items()}, node_size=260, font_size=7,\n           title=f'Karate club after 3 rounds: {len(sizes)} classes for {KC.number_of_nodes()} nodes')\nplt.tight_layout(); plt.show()\n\nfor c in shared:\n    vs = [v for v in KC if final[v] == c]\n    print(f'indistinguishable: nodes {vs}  (degrees {[KC.degree(v) for v in vs]})')","lines":[{"from":1,"to":1,"say":"34명 가라테 클럽 친구 관계 그래프를 불러와요."},{"from":2,"to":4,"say":"가라테 동아리 친구 관계 그래프 KC 와 예시 그래프 네 개를 사전 examples 에 담아요."},{"from":5,"to":12,"say":"그래프마다 색 정제를 8 라운드 돌려 라운드별 서로 다른 색 수를 세고, 꺾은선 그래프로 그려요."},{"from":13,"to":13,"say":"KC 에 3 라운드를 돌린 최종 색에서 노드가 2개 이상인 색만 골라 다시 칠해 그려요."},{"from":14,"to":14,"say":"색 정제를 3라운드 돌리고, `[-1]` 마지막 라운드의 `[0]` 첫 그래프 색 사전을 꺼내요."},{"from":15,"to":15,"say":"`Counter` 는 값마다 몇 번 나오는지 세요. 색마다 노드 수예요."},{"from":16,"to":16,"say":"노드가 2개 이상인 색만 골라 표시용 번호를 붙여요. `enumerate` 는 (번호, 값) 쌍을 줘요."},{"from":17,"to":20,"say":"KC 에 3 라운드를 돌린 최종 색에서 노드가 2개 이상인 색만 골라 다시 칠해 그려요."},{"from":22,"to":24,"say":"같은 색 노드 묶음과 차수를 출력해요. 같은 색 = 어떤 메시지 패싱 GNN도 못 가르는 노드들."}],"link":"p.14 의 노드 1, 2 처럼 같은 처지인 노드를 실제 네트워크에서 찾은 거예요."},{"kind":"steps","head":"노트북 출력 읽기","steps":["indistinguishable: nodes [4, 10] (degrees [3, 3])","nodes [5, 6] (degrees [4, 4])","nodes [14, 15, 18, 20, 22] (degrees 모두 2)","nodes [17, 21] (degrees [2, 2])"],"answer":"묶음마다 차수도, 3라운드 색도 같아요. 메시지 패싱 GNN 은 이들에게 같은 **노드 임베딩(Node embedding)**을 줘요."}]},{"p":15,"title":"핵심 질문: 언제 구별하고 언제 실패하나","terms":["Node embedding","Local neighborhood structure","Computational graph","Aggregation","1-WL test"],"pass1":[{"kind":"say","lines":["지금까지 본 세 쌍을 떠올리며 핵심 질문을 던져요.","주변 모양이 다른 두 노드에게, GNN은 늘 서로 다른 **노드 임베딩(Node embedding)**을 줄까요?","된다면 언제 되고, 안 된다면 언제 실패할까요?","이 답을 찾는 도구가 다음 쪽부터 볼 **계산 그래프(Computational graph)**예요."]},{"kind":"points","head":"세 쌍 다시 보기","items":["노드 1과 5: 이웃 수부터 달라요. 달라 보여야 해요.","노드 1과 4: 이웃 수는 같지만 이웃의 이웃이 달라요. 역시 달라 보여야 해요.","노드 1과 2: 대칭이라 주변이 완전히 같아요. 같아 보여야 맞아요."]}],"pass2":[{"kind":"look","head":"슬라이드 글자 하나씩","boxes":[{"x":0.03,"y":0.145,"w":0.71,"h":0.055,"say":"핵심 질문: **노드 임베딩(Node embedding)**이 서로 다른 **국소 이웃 구조(Local neighborhood structure)**를 구별하나?"},{"x":0.07,"y":0.26,"w":0.41,"h":0.05,"say":"'항상 된다'나 '절대 안 된다'가 아니라, 되는 조건과 실패 조건을 찾자는 힌트예요."},{"x":0.03,"y":0.33,"w":0.54,"h":0.05,"say":"다음: GNN 이 주변 정보를 임베딩에 어떻게 담는지 이해해야 해요."},{"x":0.07,"y":0.39,"w":0.22,"h":0.05,"say":"핵심 개념: **계산 그래프(Computational graph)**. 다음 쪽부터 자세히 그려요."}]},{"kind":"compare","head":"세 쌍 총정리 (모든 특징 같음)","cols":["쌍","구조","해야 할 일","1층 합","2층 합"],"rows":[["(1, 5)","다름","다른 임베딩","2 대 3 (구별)","5 대 6 (구별)"],["(1, 4)","다름","다른 임베딩","2 대 2 (못 함)","5 대 4 (구별)"],["(1, 2)","같음","같은 임베딩","2 대 2","5 대 5"]]},{"kind":"points","head":"'언제 되나'의 힌트 두 개","items":["층 수: (1, 4) 는 1층으론 못 가르고 2층에서 갈라요. 차이가 멀면 층이 더 필요해요.","모으는 법: 평균으로 다시 하면 1층은 모두 1 이라 (1, 5) 도 못 갈라요.","이웃에게 몇 번 묻는지(층 수)와 어떻게 모으는지(**집계(Aggregation)**)가 구별 능력을 정해요."]},{"kind":"prof","when":"3주차 화요일 수업","lines":["WL 과 거의 같게 동작하는 GNN 은 언제 구조 인식에 성공하고 언제 실패할까?","WL 과 GNN 이 어디가 같고 어디가 다른지 잘 봐야 한다고 했어요."]}],"pass3":[{"kind":"exam","src":"GNN 2024 가을 기말 6번 (b) (10점 문항)","q":"Why considering a set of k-hop subgraphs will make the model more expressive than only neighbor aggregation? (GNN-AK)","qko":"k홉 부분 그래프 집합을 쓰면 왜 이웃 집계만 쓸 때보다 표현력이 좋아지나? (GNN-AK 모델)","solve":["이웃 **집계(Aggregation)**는 바로 옆 이웃만 봐요.","그래서 구조적 역할이 다른 노드나 고차 구조를 구별 못 할 수 있어요. 오늘 본 실패 조건이에요.","k홉 부분 그래프는 그 범위의 엣지 배치, 모티프, 연결 모양 전체를 그대로 담아요.","사이클, 클리크 같은 고차 구조가 부분 그래프 안에 따로 담겨 모델이 활용해요. **표현력(Expressive power)** 상승."],"answer":"Neighbor aggregation sees only immediate neighbors; a k-hop subgraph keeps the whole local structure, such as motifs, cycles and cliques."},{"kind":"english","head":"해설 원문 문장","en":"Neighbor aggregation cannot distinguish nodes in different structural roles, as it focuses only on immediate neighbors.","ko":"이웃 집계는 바로 옆 이웃만 보기 때문에 구조적 역할이 다른 노드를 구별하지 못한다.","tip":"immediate neighbors(바로 옆 이웃)와 structural roles(구조적 역할)가 핵심 단어예요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["'구별 못 함 = 실패'가 아니에요. 구조가 같은 (1, 2) 는 못 가르는 게 정답, 실패는 구조가 다른데 같은 임베딩일 때.","질문 주어는 '노드 임베딩'. 그래프 전체 비교(p.5)가 아니라 노드 비교(p.6) 문제예요.","6번 (a) 의 GNN-AK 계산은 목차 6번 덩어리(천장 뚫기)에서 다뤄요."]},{"kind":"check","q":"GNN 이 '실패'했다고 말할 수 있는 경우는?","choices":["대칭인 두 노드에 같은 임베딩을 줄 때","구조가 다른 두 노드에 같은 임베딩을 줄 때","구조가 다른 두 노드에 다른 임베딩을 줄 때","층을 2개만 쌓았을 때"],"a":1,"why":"가를 수 있어야 하는데 못 가를 때가 실패예요. 대칭 쌍에 같은 임베딩은 정답이에요."}],"pass4":[{"kind":"code","head":"C6 과 2xC3 에 색 정제 돌리기","file":"Sample_Code_3.ipynb 셀 26 (4.3 The WL Test on C6 vs 2xC3)","code":"CYCLES = dict(graphs=[C6, TwoC3], names=['$C_6$', '$2 \\\\times C_3$'], positions=[POS_C6, POS_2C3])\nrounds_cyc = wl_refine(CYCLES['graphs'], num_iterations=4)\n\nfor l in [1, 2]:\n    show_round(**CYCLES, rounds=rounds_cyc, l=l)\n\nwl_report(rounds_cyc, ['C6  ', '2xC3'])","lines":[{"from":1,"to":1,"say":"`dict(키=값, ...)` 로 두 그래프, 이름, 좌표를 사전 하나에 묶어요. 이름 속 달러 기호는 그림 제목용 수식이에요."},{"from":2,"to":2,"say":"두 그래프에 색 정제를 4라운드 돌려요(p.13 코드)."},{"from":4,"to":5,"say":"라운드 1, 2 과정을 그려요. `**CYCLES` 는 사전을 '이름=값' 재료로 펼쳐 넣는 문법이에요."},{"from":7,"to":7,"say":"라운드마다 두 그래프의 색 개수 분포를 비교해 출력해요."}],"link":"p.15 의 '언제 실패하나'를 실제로 보여 주는 한 쌍이에요."},{"kind":"steps","head":"노트북 출력 읽기","steps":["round 0~4 모두 C6 {k: 6} == 2xC3 {k: 6}","라운드마다 HASH 표가 한 줄뿐: 모든 노드의 봉투가 늘 같아요","결론: INCONCLUSIVE (the histograms are always equal)"],"answer":"**1-WL 테스트(1-WL test)**도, 따라서 메시지 패싱 GNN 도 이 쌍을 못 가려요. 구조가 다른데 못 가르는 진짜 실패예요."},{"kind":"say","lines":["셀 28 확인: networkx 의 WL 해시도 C6 대 2xC3 은 같다(True), G1 대 G2 는 다르다(False).","따로 만든 두 구현이 같은 결론이에요."]}]},{"p":16,"title":"계산 그래프 (1): 노드 1 의 나무","terms":["Computational graph","Aggregation","Root","Multiset","Rooted subtree","Unfolding tree","Node embedding","Receptive field"],"pass1":[{"kind":"say","lines":["GNN은 층마다 이웃 정보를 모아서 나를 새로 고쳐요.","그 모으는 길을 나무처럼 펼쳐 그린 그림을 **계산 그래프(Computational graph)**라고 해요.","맨 위 주인공을 **뿌리(Root)**라고 하고, 아래로 내려갈수록 이웃, 이웃의 이웃이에요."]},{"kind":"look","head":"노드 1의 나무","boxes":[{"x":0.2,"y":0.53,"w":0.2,"h":0.22,"say":"왼쪽 그래프에서 테두리가 두 겹인 노드 1이 주인공이에요."},{"x":0.55,"y":0.45,"w":0.15,"h":0.23,"say":"오른쪽 나무 맨 위가 노드 1이고, 바로 아래가 이웃인 2와 5예요."},{"x":0.545,"y":0.715,"w":0.165,"h":0.12,"say":"맨 아래 줄은 2의 이웃들과 5의 이웃들이에요. 계산은 아래에서 위로 올라가요."}]},{"kind":"recap","items":["**표현력(Expressive power)**: 서로 다른 그래프 모양을 구별하는 힘. 이 강의에선 다른 그래프에 다른 답을 내는 힘이에요.","모양이 같은 그래프인지 묻는 **그래프 동형(Graph isomorphism)**은 너무 어려워서, 노드 두 개를 가르는 문제로 줄였어요.","GNN이 노드 하나에 대해 보는 건 **계산 그래프(Computational graph)** 나무뿐이에요.","모으는 방법은 합이 가장 잘 구별하고, 그다음이 평균, 마지막이 최댓값이에요.","오늘의 용어: Expressive power(표현력), Graph isomorphism(그래프 동형), Computational graph(계산 그래프), Symmetric(대칭)"]}],"pass2":[{"kind":"look","head":"슬라이드 글자와 나무","boxes":[{"x":0.03,"y":0.145,"w":0.41,"h":0.055,"say":"GNN 은 층마다 이웃 노드 임베딩을 **집계(Aggregation)**해요. p.7 복습 그대로예요."},{"x":0.03,"y":0.215,"w":0.57,"h":0.05,"say":"계산 그래프 모양은 GNN 이 아니라 '누가 누구와 이웃인가'가 정해요."},{"x":0.07,"y":0.325,"w":0.33,"h":0.05,"say":"예: 노드 1 의 계산 그래프. 2층 GNN 이라 나무도 2단이에요."},{"x":0.2,"y":0.53,"w":0.2,"h":0.22,"say":"왼쪽 그래프에서 이중 테두리 노드 1 이 주인공이에요."},{"x":0.55,"y":0.45,"w":0.15,"h":0.23,"say":"맨 위 1 이 **뿌리(Root)**, 최종 임베딩이 나오는 곳. 그 아래 막대에 이웃 2 와 5."},{"x":0.545,"y":0.715,"w":0.165,"h":0.12,"say":"맨 아래 1, 5 는 2 의 이웃, 1, 2, 4 는 5 의 이웃. 화살표는 전부 위로."}]},{"kind":"formula","head":"막대 하나의 식","tex":"\\mathbf{h}_v^{(k)} = \\mathrm{AGG}\\left(\\{\\!\\{\\mathbf{h}_u^{(k-1)} : u \\in N(v)\\}\\!\\}\\right)","parts":[{"sym":"\\mathbf{h}_v^{(k)}","say":"막대 바로 위 동그라미의 k 층 임베딩"},{"sym":"\\mathbf{h}_u^{(k-1)}","say":"막대 바로 아래 이웃들의 한 층 아래 값"},{"sym":"\\{\\!\\{\\ \\}\\!\\}","say":"막대에 매달린 동그라미 묶음, **멀티셋(Multiset)**"},{"sym":"\\mathrm{AGG}","say":"검은 막대. 모으는 계산(가중치, 비선형 포함)"},{"sym":"\\mathbf{h}^{(0)}","say":"맨 아래 줄 입력 특징"}],"whole":"막대 위 값은 막대 아래 이웃 값 봉투를 모은 거예요."},{"kind":"formula","head":"노드 1 은 두 번 계산해요","tex":"\\mathbf{h}_1^{(2)} = \\mathrm{AGG}(\\{\\!\\{\\mathbf{h}_2^{(1)}, \\mathbf{h}_5^{(1)}\\}\\!\\}),\\quad \\mathbf{h}_5^{(1)} = \\mathrm{AGG}(\\{\\!\\{\\mathbf{h}_1^{(0)}, \\mathbf{h}_2^{(0)}, \\mathbf{h}_4^{(0)}\\}\\!\\})","parts":[{"sym":"\\mathbf{h}_2^{(1)}","say":"먼저: 2 의 1층 값 = 잎 1, 5 의 입력 모으기"},{"sym":"\\mathbf{h}_5^{(1)}","say":"먼저: 5 의 1층 값 = 잎 1, 2, 4 의 입력 모으기"},{"sym":"\\mathbf{h}_1^{(2)}","say":"나중: 1 의 2층 값 = 2 와 5 의 1층 값 모으기"}],"whole":"아래 막대 둘을 먼저, 뿌리 막대를 나중에 계산해요."},{"kind":"figure","head":"노드 1 의 나무를 합으로 계산","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\">\n<line class=\"e2\" x1=\"240\" y1=\"52\" x2=\"160\" y2=\"100\"/>\n<line class=\"e2\" x1=\"240\" y1=\"52\" x2=\"320\" y2=\"100\"/>\n<line class=\"e\" x1=\"160\" y1=\"132\" x2=\"125\" y2=\"184\"/>\n<line class=\"e\" x1=\"160\" y1=\"132\" x2=\"190\" y2=\"184\"/>\n<line class=\"e\" x1=\"320\" y1=\"132\" x2=\"270\" y2=\"184\"/>\n<line class=\"e\" x1=\"320\" y1=\"132\" x2=\"320\" y2=\"184\"/>\n<line class=\"e\" x1=\"320\" y1=\"132\" x2=\"370\" y2=\"184\"/>\n<circle class=\"n2\" cx=\"240\" cy=\"36\" r=\"16\"/>\n<circle class=\"n\" cx=\"160\" cy=\"116\" r=\"16\"/>\n<circle class=\"n\" cx=\"320\" cy=\"116\" r=\"16\"/>\n<circle class=\"n\" cx=\"125\" cy=\"200\" r=\"16\"/>\n<circle class=\"n\" cx=\"190\" cy=\"200\" r=\"16\"/>\n<circle class=\"n\" cx=\"270\" cy=\"200\" r=\"16\"/>\n<circle class=\"n\" cx=\"320\" cy=\"200\" r=\"16\"/>\n<circle class=\"n\" cx=\"370\" cy=\"200\" r=\"16\"/>\n<text class=\"tl\" x=\"240\" y=\"41\" font-size=\"14\" text-anchor=\"middle\">1<\/text>\n<text class=\"tl\" x=\"160\" y=\"121\" font-size=\"14\" text-anchor=\"middle\">2<\/text>\n<text class=\"tl\" x=\"320\" y=\"121\" font-size=\"14\" text-anchor=\"middle\">5<\/text>\n<text class=\"tl\" x=\"125\" y=\"205\" font-size=\"14\" text-anchor=\"middle\">1<\/text>\n<text class=\"tl\" x=\"190\" y=\"205\" font-size=\"14\" text-anchor=\"middle\">5<\/text>\n<text class=\"tl\" x=\"270\" y=\"205\" font-size=\"14\" text-anchor=\"middle\">1<\/text>\n<text class=\"tl\" x=\"320\" y=\"205\" font-size=\"14\" text-anchor=\"middle\">2<\/text>\n<text class=\"tl\" x=\"370\" y=\"205\" font-size=\"14\" text-anchor=\"middle\">4<\/text>\n<text class=\"tm\" x=\"10\" y=\"41\" font-size=\"14\">h(2)<\/text>\n<text class=\"tm\" x=\"10\" y=\"121\" font-size=\"14\">h(1)<\/text>\n<text class=\"tm\" x=\"10\" y=\"205\" font-size=\"14\">h(0)<\/text>\n<text class=\"t b1\" x=\"125\" y=\"240\" font-size=\"14\" text-anchor=\"middle\">1<\/text>\n<text class=\"t b1\" x=\"190\" y=\"240\" font-size=\"14\" text-anchor=\"middle\">1<\/text>\n<text class=\"t b1\" x=\"270\" y=\"240\" font-size=\"14\" text-anchor=\"middle\">1<\/text>\n<text class=\"t b1\" x=\"320\" y=\"240\" font-size=\"14\" text-anchor=\"middle\">1<\/text>\n<text class=\"t b1\" x=\"370\" y=\"240\" font-size=\"14\" text-anchor=\"middle\">1<\/text>\n<text class=\"tb b2\" x=\"138\" y=\"121\" font-size=\"14\" text-anchor=\"end\">값 2<\/text>\n<text class=\"tb b2\" x=\"342\" y=\"121\" font-size=\"14\">값 3<\/text>\n<text class=\"tb b3\" x=\"262\" y=\"41\" font-size=\"14\">값 5 = 2 + 3<\/text>\n<text class=\"tm b3\" x=\"240\" y=\"264\" font-size=\"14\" text-anchor=\"middle\">노드 3은 3걸음 거리라 나무에 없어요<\/text>\n<\/svg>","caption":"특징 모두 1, AGG 는 합. 잎에서 뿌리로 올라가며 1, 2와 3, 5.","builds":3},{"kind":"compare","head":"모든 노드 2층 합 (특징 모두 1)","cols":["노드","h(0)","h(1) = 이웃 h(0) 합","h(2) = 이웃 h(1) 합"],"rows":[["1","1","2","2 + 3 = 5"],["2","1","2","2 + 3 = 5"],["3","1","1","2"],["4","1","2","1 + 3 = 4"],["5","1","3","2 + 2 + 2 = 6"]]},{"kind":"points","head":"기억할 것","items":["$h^{(2)}$ 는 나무 잎 개수와 같아요. p.6 의 5, 5, 2, 4, 6 과 일치해요.","임베딩은 **뿌리 있는 부분 트리(Rooted subtree)** 모양을 요약한 숫자. 나무가 같으면 결과도 같아요.","노드 3 은 1 에서 3걸음이라 2층 나무에 없어요. 3 의 특징이 바뀌어도 $h_1^{(2)}$ 는 그대로."]},{"kind":"prof","when":"3주차 화요일 수업","lines":["2층 GNN 에서 노드 1 은 1층에서 이웃 2, 5 를 보고,","2층에서 2 의 이웃 1, 5 와 5 의 이웃 1, 2, 4 를 본다고 했어요.","WL 로 말하면 '나는 1' 에서 '나는 2, 5 의 친구인 1' 로 커지는 과정이에요.","이걸 반복하면 담기는 모양이 GNN 의 **계산 그래프(Computational graph)** 와 같대요."]}],"pass3":[{"kind":"english","head":"슬라이드 원문 문장","en":"A GNN generates node embeddings through a computational graph defined by the neighborhood.","ko":"GNN 은 이웃이 정의하는 계산 그래프를 통해 노드 임베딩을 만든다.","tip":"서술형에 그대로 쓸 수 있어요. defined by the neighborhood 가 핵심이에요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["슬라이드 나무엔 막대 아래 자기 자신이 없어요. GCN, GIN 처럼 자기 값도 섞으면 복사본이 하나씩 더 매달려요.","맨 아래 1 이 또 나오는 건 오류가 아니라 정보가 되돌아오는 경로예요.","기출 GIN 계산(2024 가을 기말 5번 (a))도 같은 순서: 이웃 표, 지난 층 합, 내 값 ×1.5 더하기."]},{"kind":"check","q":"모든 특징 1, 합 집계일 때 노드 4 의 $h^{(2)}$ 는?","choices":["2","3","4","5"],"a":2,"why":"4 의 이웃 3(1층 값 1)과 5(1층 값 3)를 더해 1 + 3 = 4. 나무 잎도 4개예요."}],"pass4":[{"kind":"code","head":"노드 0 의 1층, 2층 계산 그래프 그리기 (1/2)","file":"Sample_Code_3.ipynb 셀 10 (3.1 What a Node Actually Sees) (1/2)","code":"def unfolding_tree(G, root, depth):\n    \"\"\"\n    Computational graph of `root` for a `depth`-layer GNN.\n    Tree nodes are walks starting at `root`; attribute 'orig' is the graph node a copy stands for.\n    Edges point child -> parent, the direction messages flow.\n    \"\"\"\n    T = nx.DiGraph()\n    T.add_node((root,), orig=root, level=0)\n    frontier = [(root,)]\n    for d in range(1, depth + 1):\n        frontier = [walk + (u,) for walk in frontier for u in sorted(G[walk[-1]])]\n        for walk in frontier:\n            T.add_node(walk, orig=walk[-1], level=d)\n            T.add_edge(walk, walk[:-1])\n    return T\n\n\ndef draw_tree(T, ax, uniform=False, title=None, node_size=460, font_size=9):\n    \"\"\"Draw a tree with the root on top. uniform=True paints every copy gray (only shape matters).\"\"\"\n    pos, next_x = {}, [0.0]\n\n    def place(n):                                   # each parent centered above its children\n        kids = sorted(T.predecessors(n))\n        if kids:\n            x = float(np.mean([place(k) for k in kids]))\n        else:\n            x, next_x[0] = next_x[0], next_x[0] + 1\n        pos[n] = (x, -T.nodes[n]['level'])\n        return x\n\n    place(next(n for n in T if T.nodes[n]['level'] == 0))\n    nodes = list(T.nodes())\n    fill = [color_of(0 if uniform else T.nodes[n]['orig'] + 1) for n in nodes]\n    nx.draw_networkx_edges(T, pos, ax=ax, arrows=False, edge_color=C_EDGE, width=1.4)\n    nx.draw_networkx_nodes(T, pos, nodelist=nodes, ax=ax, node_color=fill,\n                           edgecolors=C_DARK, linewidths=1.1, node_size=node_size)\n    for n, f in zip(nodes, fill):\n        ax.text(*pos[n], str(T.nodes[n]['orig']), ha='center', va='center',\n                fontsize=font_size, color=ink(f))\n    if title:\n        ax.set_title(title)\n    ax.set_axis_off()\n    ax.margins(0.08)\n","lines":[{"from":1,"to":6,"say":"unfolding_tree 함수의 이름과 설명(따옴표 세 개 사이 글)이에요. 뿌리에서 depth 층만큼 펼친 계산 그래프를 만들어요."},{"from":7,"to":9,"say":"빈 방향 그래프 T 를 만들고 뿌리 하나를 넣어요. frontier 는 지금 나무 맨 아래 줄 목록이에요."},{"from":10,"to":17,"say":"층마다 맨 아래 줄 노드의 이웃을 하나씩 붙여 새 줄을 만들고, 자식에서 부모로 가는 선을 그어요. 끝나면 나무를 돌려줘요."},{"from":18,"to":31,"say":"draw_tree 함수의 시작 부분이에요. place 가 자식들을 먼저 배치하고, 부모를 그 가운데 위에 놓아 좌표를 정해요."},{"from":32,"to":44,"say":"노드 색을 정하고 선, 동그라미, 번호 글자를 그려요. uniform=True 면 모두 회색이라 모양만 보여요."}]},{"kind":"code","head":"노드 0 의 1층, 2층 계산 그래프 그리기 (2/2)","file":"Sample_Code_3.ipynb 셀 10 (3.1 What a Node Actually Sees) (2/2)","code":"\nG_demo = nx.Graph([(0, 1), (0, 2), (1, 2), (1, 3), (2, 4), (3, 4), (4, 5)])\nPOS_DEMO = nx.spring_layout(G_demo, seed=3)\n\nfig = plt.figure(figsize=(14, 4.4))\ngs = fig.add_gridspec(1, 3, width_ratios=[1, 1.25, 1.6])\ndraw_graph(G_demo, POS_DEMO, fig.add_subplot(gs[0]), colors={v: v + 1 for v in G_demo},\n           highlight=0, title='The graph (target node 0)')\nfor k, depth in enumerate([1, 2]):\n    T = unfolding_tree(G_demo, 0, depth)\n    draw_tree(T, fig.add_subplot(gs[k + 1]),\n              title=f'Computational graph of node 0, {depth} layer(s)\\n'\n                    f'({T.number_of_nodes()} tree nodes)')\nplt.tight_layout(); plt.show()\n\nsizes = [unfolding_tree(G_demo, 0, L).number_of_nodes() for L in range(6)]\nprint(f'Tree size for L = 0..5 layers: {sizes}   (the graph has only {G_demo.number_of_nodes()} nodes)')","lines":[{"from":1,"to":4,"say":"예시 그래프 G_demo 를 (노드, 노드) 쌍 목록으로 만들고 그릴 좌표를 정해요."},{"from":5,"to":8,"say":"그림 세 칸에 원래 그래프와 1층, 2층 계산 그래프를 나란히 그려요."},{"from":9,"to":9,"say":"`enumerate([1, 2])` 는 (0, 1), (1, 2) 쌍을 차례로 줘요. k 는 그림 칸 번호, depth 는 층 수."},{"from":10,"to":10,"say":"p.6 의 함수로 노드 0 을 뿌리로 depth 층 **펼침 트리(Unfolding tree)**를 만들어요."},{"from":11,"to":13,"say":"나무를 그림 칸에 그리고 제목에 층 수와 동그라미 수를 적어요. 1층은 3개, 2층은 9개예요."},{"from":14,"to":14,"say":"그림 세 칸에 원래 그래프와 1층, 2층 계산 그래프를 나란히 그려요."},{"from":15,"to":17,"say":"층 수 0 부터 5 까지 나무 크기를 세서 출력해요. 그래프 노드는 6개뿐인데 나무는 금방 커져요."}],"link":"슬라이드의 '노드 1 의 2층 **계산 그래프(Computational graph)**'를 예제 그래프의 노드 0 으로 그린 거예요."},{"kind":"code","head":"모양만 같으면 같은 나무","file":"Sample_Code_3.ipynb 셀 12 (3.2 The Key Lemma)","code":"fig, axes = plt.subplots(2, 2, figsize=(14, 7), gridspec_kw={'width_ratios': [1, 2.4]})\nfor row, (name, G, pos) in enumerate([('$C_6$', C6, POS_C6), ('$2 \\\\times C_3$', TwoC3, POS_2C3)]):\n    draw_graph(G, pos, axes[row, 0], highlight=0, title=f'{name}  (node 0 outlined)')\n    draw_tree(unfolding_tree(G, 0, 3), axes[row, 1], uniform=True, node_size=330, font_size=7,\n              title=f'Computational graph of node 0 in {name}, 3 layers')\nfig.suptitle('Identical computational graphs → identical embeddings', fontsize=13, fontweight='bold')\nplt.tight_layout(); plt.show()\n\n\ndef tree_shape(T, n):\n    \"\"\"Canonical form of the subtree at n, ignoring which graph node each copy is.\"\"\"\n    return tuple(sorted(tree_shape(T, k) for k in T.predecessors(n)))\n\nsame = all(tree_shape(unfolding_tree(C6, u, L), (u,)) == tree_shape(unfolding_tree(TwoC3, v, L), (v,))\n           for L in range(1, 5) for u in C6 for v in TwoC3)\nprint(f'All 6 x 6 node pairs (C6 node, 2xC3 node) have identical trees for L = 1..4: {same}')","lines":[{"from":1,"to":7,"say":"C6 와 TwoC3 에서 노드 0 을 표시하고, 각각의 3층 계산 그래프를 모양만(회색) 그려 나란히 보여 줘요."},{"from":10,"to":12,"say":"자식들의 모양을 구해 정렬한 튜플로 묶어요. 함수가 자기 자신을 부르는 재귀. 번호는 버리고 모양만 남겨요."},{"from":14,"to":15,"say":"층 1~4, C6 노드 6개, 2xC3 노드 6개의 모든 조합에서 나무 모양이 같은지 `all` 로 검사해요."},{"from":16,"to":16,"say":"출력은 True. 모든 쌍의 나무가 같아요."}],"link":"핵심 보조정리: 계산 그래프가 같으면 모든 GNN 이 같은 **노드 임베딩(Node embedding)**을 줘요."}]},{"p":17,"title":"계산 그래프 (2): 노드 1 과 노드 2 의 나무","terms":["Computational graph","Embedding","Aggregation"],"pass1":[{"kind":"say","lines":["이번엔 노드 1 과 노드 2 의 **계산 그래프(Computational graph)** 를 나란히 그려 봐요.","계산 그래프는 한 노드가 이웃, 이웃의 이웃에게서 정보를 모으는 길을 나무로 그린 거예요.","두 나무를 보면 동그라미 안 번호만 다르고, 가지가 뻗은 모양은 똑같아요.","그럼 GNN 은 이 쌍둥이 나무의 주인공 둘을 구별할 수 있을까요?"]},{"kind":"look","head":"쌍둥이 나무 두 그루","boxes":[{"x":0.515,"y":0.32,"w":0.16,"h":0.39,"say":"노드 1 의 나무예요. 맨 위 1 아래에 이웃 2개가 있고, 그 아래에 다시 2개와 3개가 매달려 있어요."},{"x":0.715,"y":0.33,"w":0.17,"h":0.4,"say":"노드 2 의 나무예요. 적힌 번호만 다르고, 매달린 개수는 노드 1 의 나무와 똑같아요."}]},{"kind":"analogy","head":"친구 족보가 똑같은 두 학생","scene":"같은 반에 하준이와 서윤이가 있어요. 둘은 서로 친구이고, 친구 수도 같고, 친구들의 친구 수까지 똑같아요. 다른 건 이름표뿐이에요. 친구 관계 족보를 그린 뒤 이름을 지우면 두 사람의 족보는 완전히 같은 그림이 돼요.","map":[["하준이와 서윤이","노드 1, 노드 2"],["친구 관계 족보","**계산 그래프(Computational graph)**"],["이름표","노드 번호"]]}],"pass2":[{"kind":"look","head":"슬라이드를 차례로 짚어 볼게요","boxes":[{"x":0.07,"y":0.14,"w":0.3,"h":0.07,"say":"불릿 한 줄: 노드 1 과 2 의 계산 그래프를 예로 들어요."},{"x":0.17,"y":0.4,"w":0.21,"h":0.23,"say":"원래 그래프예요. 선은 1-2, 1-5, 2-5, 5-4, 4-3. 노드 1, 2 가 두 겹 동그라미(주인공)예요."},{"x":0.515,"y":0.32,"w":0.16,"h":0.39,"say":"노드 1 의 나무. 뿌리 1 아래 이웃 2, 5. 그 아래 2 의 이웃 1, 5 와 5 의 이웃 1, 2, 4."},{"x":0.715,"y":0.33,"w":0.17,"h":0.4,"say":"노드 2 의 나무. 뿌리 2 아래 1, 5. 그 아래 1 의 이웃 2, 5 와 5 의 이웃 1, 2, 4."},{"x":0.715,"y":0.6,"w":0.17,"h":0.07,"say":"검은 막대는 **집계(Aggregation)** 자리예요. 막대 아래 정보를 하나로 모아 위로 올려요."}]},{"kind":"points","head":"나무 읽는 규칙","items":["동그라미 하나 = 어떤 노드의 **임베딩(Embedding)** 하나.","검은 막대 = **집계(Aggregation)** 가 일어나는 곳.","화살표는 전부 위로. 계산은 맨 아래에서 시작해 뿌리로 올라가요.","맨 아래 줄은 입력 $h^{(0)}$, 가운데 줄은 $h^{(1)}$, 뿌리는 $h^{(2)}$ 예요.","GNN 층(layer) 하나 = 나무의 막대 한 줄."]},{"kind":"figure","head":"번호를 빼고 모양만 비교하기","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\"><line x1=\"40\" y1=\"184\" x2=\"59\" y2=\"136\" class=\"e b2\"/><circle cx=\"40\" cy=\"200\" r=\"16\" class=\"n b1\"/><text x=\"40\" y=\"205\" font-size=\"15\" text-anchor=\"middle\" class=\"tl b1\">1<\/text><line x1=\"78\" y1=\"184\" x2=\"59\" y2=\"136\" class=\"e b2\"/><circle cx=\"78\" cy=\"200\" r=\"16\" class=\"n b1\"/><text x=\"78\" y=\"205\" font-size=\"15\" text-anchor=\"middle\" class=\"tl b1\">5<\/text><line x1=\"59\" y1=\"104\" x2=\"106.5\" y2=\"56\" class=\"e b3\"/><circle cx=\"59\" cy=\"120\" r=\"16\" class=\"n b2\"/><text x=\"59\" y=\"125\" font-size=\"15\" text-anchor=\"middle\" class=\"tl b2\">2<\/text><line x1=\"116\" y1=\"184\" x2=\"154\" y2=\"136\" class=\"e b2\"/><circle cx=\"116\" cy=\"200\" r=\"16\" class=\"n b1\"/><text x=\"116\" y=\"205\" font-size=\"15\" text-anchor=\"middle\" class=\"tl b1\">1<\/text><line x1=\"154\" y1=\"184\" x2=\"154\" y2=\"136\" class=\"e b2\"/><circle cx=\"154\" cy=\"200\" r=\"16\" class=\"n b1\"/><text x=\"154\" y=\"205\" font-size=\"15\" text-anchor=\"middle\" class=\"tl b1\">2<\/text><line x1=\"192\" y1=\"184\" x2=\"154\" y2=\"136\" class=\"e b2\"/><circle cx=\"192\" cy=\"200\" r=\"16\" class=\"n b1\"/><text x=\"192\" y=\"205\" font-size=\"15\" text-anchor=\"middle\" class=\"tl b1\">4<\/text><line x1=\"154\" y1=\"104\" x2=\"106.5\" y2=\"56\" class=\"e b3\"/><circle cx=\"154\" cy=\"120\" r=\"16\" class=\"n b2\"/><text x=\"154\" y=\"125\" font-size=\"15\" text-anchor=\"middle\" class=\"tl b2\">5<\/text><circle cx=\"106.5\" cy=\"40\" r=\"16\" class=\"n2 b3\"/><text x=\"106.5\" y=\"45\" font-size=\"15\" text-anchor=\"middle\" class=\"tl b3\">1<\/text><line x1=\"280\" y1=\"184\" x2=\"299\" y2=\"136\" class=\"e b2\"/><circle cx=\"280\" cy=\"200\" r=\"16\" class=\"n b1\"/><text x=\"280\" y=\"205\" font-size=\"15\" text-anchor=\"middle\" class=\"tl b1\">2<\/text><line x1=\"318\" y1=\"184\" x2=\"299\" y2=\"136\" class=\"e b2\"/><circle cx=\"318\" cy=\"200\" r=\"16\" class=\"n b1\"/><text x=\"318\" y=\"205\" font-size=\"15\" text-anchor=\"middle\" class=\"tl b1\">5<\/text><line x1=\"299\" y1=\"104\" x2=\"346.5\" y2=\"56\" class=\"e b3\"/><circle cx=\"299\" cy=\"120\" r=\"16\" class=\"n b2\"/><text x=\"299\" y=\"125\" font-size=\"15\" text-anchor=\"middle\" class=\"tl b2\">1<\/text><line x1=\"356\" y1=\"184\" x2=\"394\" y2=\"136\" class=\"e b2\"/><circle cx=\"356\" cy=\"200\" r=\"16\" class=\"n b1\"/><text x=\"356\" y=\"205\" font-size=\"15\" text-anchor=\"middle\" class=\"tl b1\">1<\/text><line x1=\"394\" y1=\"184\" x2=\"394\" y2=\"136\" class=\"e b2\"/><circle cx=\"394\" cy=\"200\" r=\"16\" class=\"n b1\"/><text x=\"394\" y=\"205\" font-size=\"15\" text-anchor=\"middle\" class=\"tl b1\">2<\/text><line x1=\"432\" y1=\"184\" x2=\"394\" y2=\"136\" class=\"e b2\"/><circle cx=\"432\" cy=\"200\" r=\"16\" class=\"n b1\"/><text x=\"432\" y=\"205\" font-size=\"15\" text-anchor=\"middle\" class=\"tl b1\">4<\/text><line x1=\"394\" y1=\"104\" x2=\"346.5\" y2=\"56\" class=\"e b3\"/><circle cx=\"394\" cy=\"120\" r=\"16\" class=\"n b2\"/><text x=\"394\" y=\"125\" font-size=\"15\" text-anchor=\"middle\" class=\"tl b2\">5<\/text><circle cx=\"346.5\" cy=\"40\" r=\"16\" class=\"n2 b3\"/><text x=\"346.5\" y=\"45\" font-size=\"15\" text-anchor=\"middle\" class=\"tl b3\">2<\/text><text x=\"240\" y=\"125\" font-size=\"20\" text-anchor=\"middle\" class=\"tb b4\">=<\/text><text x=\"116\" y=\"248\" font-size=\"15\" text-anchor=\"middle\" class=\"tb b4\">2 → (2, 3)<\/text><text x=\"356\" y=\"248\" font-size=\"15\" text-anchor=\"middle\" class=\"tb b4\">2 → (2, 3)<\/text><\/svg>","caption":"두 **계산 그래프(Computational graph)** 모두 뿌리 아래 2개, 그 아래 2개와 3개. 모양이 같아요. 아래 '2 → (2, 3)' 은 이 개수를 줄여 적은 표시예요.","builds":4},{"kind":"compare","head":"줄마다 비교 (개수 = 막대 하나에 매달린 동그라미 수)","cols":["줄","노드 1 의 나무","노드 2 의 나무"],"rows":[["뿌리","1","2 (번호만 다름)"],["가운데 줄","2, 5 (2개)","1, 5 (2개)"],["아래 왼쪽 가지","1, 5 (2개)","2, 5 (2개)"],["아래 오른쪽 가지","1, 2, 4 (3개)","1, 2, 4 (3개)"],["맨 아래 줄 전체","5개","5개"]]},{"kind":"prof","when":"3주차 화요일 수업","lines":["2층 GNN 에서 노드 1 과 2 는 완전히 같은 계산 그래프를 가진다고 했어요.","그래서 GNN 이 둘을 분별하기는 굉장히 어렵거나 거의 불가능하대요."]},{"kind":"mining","src":"마이닝 7강, 9강 (그래프 동형)","lines":["이름표 1 과 2 를 바꿔 붙여도 선 다섯 개가 그대로예요.","이름만 다르고 모양은 같다, 즉 그래프 동형(graph isomorphism) 과 같은 생각이에요.","그래서 두 노드는 구조상 구별할 이유가 없는 자리예요."]}],"pass3":[{"kind":"warn","head":"헷갈리기 쉬운 점","items":["같은 막대에 매달린 동그라미의 좌우 순서에는 뜻이 없어요. 이웃에게는 순서가 없으니까요.","나무에 같은 번호가 여러 번 나와도 맞는 그림이에요. 정보가 이웃을 거쳐 돌아오는 길을 복사본으로 그린 거예요.","이 그림은 자기 자신을 막대 아래에 따로 매달지 않았어요. 매달아도 두 나무 모양이 같다는 결론은 그대로예요."]}],"pass4":[{"kind":"code","head":"계산 그래프를 만드는 함수 (1/2)","file":"Sample_Code_3_번역.ipynb 셀 12 (원본 Sample_Code_3.ipynb 셀 9) (1/2)","code":"def unfolding_tree(G, root, depth):\n    \"\"\"\n    Computational graph of `root` for a `depth`-layer GNN.\n    Tree nodes are walks starting at `root`; attribute 'orig' is the graph node a copy stands for.\n    Edges point child -> parent, the direction messages flow.\n    \"\"\"\n    T = nx.DiGraph()\n    T.add_node((root,), orig=root, level=0)\n    frontier = [(root,)]\n    for d in range(1, depth + 1):\n        frontier = [walk + (u,) for walk in frontier for u in sorted(G[walk[-1]])]\n        for walk in frontier:\n            T.add_node(walk, orig=walk[-1], level=d)\n            T.add_edge(walk, walk[:-1])\n    return T\n\n\ndef draw_tree(T, ax, uniform=False, title=None, node_size=460, font_size=9):\n    \"\"\"Draw a tree with the root on top. uniform=True paints every copy gray (only shape matters).\"\"\"\n    pos, next_x = {}, [0.0]\n\n    def place(n):                                   # 각 부모를 자식들의 가운데 위에 놓는다\n        kids = sorted(T.predecessors(n))\n        if kids:\n            x = float(np.mean([place(k) for k in kids]))\n        else:\n            x, next_x[0] = next_x[0], next_x[0] + 1\n        pos[n] = (x, -T.nodes[n]['level'])\n        return x\n\n    place(next(n for n in T if T.nodes[n]['level'] == 0))\n    nodes = list(T.nodes())\n    fill = [color_of(0 if uniform else T.nodes[n]['orig'] + 1) for n in nodes]\n    nx.draw_networkx_edges(T, pos, ax=ax, arrows=False, edge_color=C_EDGE, width=1.4)\n    nx.draw_networkx_nodes(T, pos, nodelist=nodes, ax=ax, node_color=fill,\n                           edgecolors=C_DARK, linewidths=1.1, node_size=node_size)\n    for n, f in zip(nodes, fill):\n        ax.text(*pos[n], str(T.nodes[n]['orig']), ha='center', va='center',\n                fontsize=font_size, color=ink(f))\n    if title:\n        ax.set_title(title)\n    ax.set_axis_off()\n    ax.margins(0.08)\n","lines":[{"from":1,"to":1,"say":"`def 이름(재료들):` 은 함수를 만드는 문법이에요. 그래프 G, 뿌리 root, 층 수 depth 를 받아요."},{"from":2,"to":6,"say":"따옴표 세 개 사이는 설명문(docstring)이에요. 실행되지 않는 긴 주석이에요."},{"from":7,"to":8,"say":"`nx.DiGraph()` 로 빈 방향 그래프 T 를 만들고 뿌리를 넣어요. `(root,)` 는 원소 하나짜리 튜플이에요."},{"from":9,"to":9,"say":"`frontier` 는 지금 맨 아래 줄 목록(리스트)이에요. 처음엔 뿌리 하나뿐이에요."},{"from":10,"to":11,"say":"`for` 로 층마다 반복해요. 맨 아래 동그라미마다 그 노드의 이웃 `G[...]` 을 전부 복사해 매달아요."},{"from":12,"to":14,"say":"새로 매단 복사본을 T 에 넣고, 자식에서 부모로 가는 선을 그어요. 메시지가 흐르는 방향이에요."},{"from":15,"to":15,"say":"`return T` 로 완성된 나무를 돌려줘요."},{"from":18,"to":31,"say":"draw_tree 함수의 시작 부분이에요. place 가 자식들을 먼저 배치하고, 부모를 그 가운데 위에 놓아 좌표를 정해요."},{"from":32,"to":44,"say":"노드 색을 정하고 선, 동그라미, 번호 글자를 그려요. uniform=True 면 모두 회색이라 모양만 보여요."}],"link":"슬라이드의 나무 = 이 함수가 만드는 T. depth 가 GNN 층 수예요."},{"kind":"code","head":"계산 그래프를 만드는 함수 (2/2)","file":"Sample_Code_3_번역.ipynb 셀 12 (원본 Sample_Code_3.ipynb 셀 9) (2/2)","code":"\nG_demo = nx.Graph([(0, 1), (0, 2), (1, 2), (1, 3), (2, 4), (3, 4), (4, 5)])\nPOS_DEMO = nx.spring_layout(G_demo, seed=3)\n\nfig = plt.figure(figsize=(14, 4.4))\ngs = fig.add_gridspec(1, 3, width_ratios=[1, 1.25, 1.6])\ndraw_graph(G_demo, POS_DEMO, fig.add_subplot(gs[0]), colors={v: v + 1 for v in G_demo},\n           highlight=0, title='The graph (target node 0)')\nfor k, depth in enumerate([1, 2]):\n    T = unfolding_tree(G_demo, 0, depth)\n    draw_tree(T, fig.add_subplot(gs[k + 1]),\n              title=f'Computational graph of node 0, {depth} layer(s)\\n'\n                    f'({T.number_of_nodes()} tree nodes)')\nplt.tight_layout(); plt.show()\n\nsizes = [unfolding_tree(G_demo, 0, L).number_of_nodes() for L in range(6)]\nprint(f'Tree size for L = 0..5 layers: {sizes}   (the graph has only {G_demo.number_of_nodes()} nodes)')","lines":[{"from":1,"to":4,"say":"예시 그래프 G_demo 를 (노드, 노드) 쌍 목록으로 만들고 그릴 좌표를 정해요."},{"from":5,"to":14,"say":"그림 세 칸에 원래 그래프와 1층, 2층 계산 그래프를 나란히 그려요."},{"from":15,"to":17,"say":"층 수 0 부터 5 까지 나무 크기를 세서 출력해요. 그래프 노드는 6개뿐인데 나무는 금방 커져요."}]},{"kind":"pyterm","name":"튜플(tuple)","say":["괄호로 묶은 값 목록이에요. 리스트와 비슷하지만 만든 뒤 못 바꿔요.","`walk + (u,)` 는 튜플 끝에 u 를 하나 덧붙인 새 튜플이에요.","`walk[-1]` 은 마지막 원소, `walk[:-1]` 은 마지막만 뺀 나머지예요."],"example":"walk = (1, 5)\nprint(walk + (4,))\nprint(walk[-1], walk[:-1])","out":"(1, 5, 4)\n5 (1,)"}]},{"p":18,"title":"계산 그래프 (3): GNN 은 번호를 못 봐요","terms":["Node feature","Computational graph","Permutation invariance"],"pass1":[{"kind":"say","lines":["중요한 사실이 하나 있어요. GNN 은 노드 번호, 즉 1번, 2번 같은 이름표를 보지 못해요.","GNN 이 보는 건 노드가 처음 가진 정보인 **노드 특징(Node feature)** 과 연결 모양뿐이에요.","그래서 나무에서 번호를 모두 지운 그림이 GNN 이 실제로 보는 모습이에요.","번호를 지우면 노드 1 과 노드 2 의 나무는 똑같은 그림이 돼요."]},{"kind":"look","head":"번호가 사라진 나무","boxes":[{"x":0.515,"y":0.32,"w":0.37,"h":0.4,"say":"오른쪽 두 나무는 번호를 전부 지운 모습이에요. GNN 눈에는 두 나무가 이렇게 똑같이 보여요."}]},{"kind":"analogy","head":"이름 칸을 가리고 채점하기","scene":"선생님이 공정하게 채점하려고 답안지의 이름 칸을 가리고 채점해요. 선생님은 답안 내용만 보고 점수를 줘요. 그래서 두 학생이 똑같은 답을 썼다면 누구 답안인지 몰라도 같은 점수가 나와요. GNN 도 번호 칸은 가린 채 특징과 연결 모양만 보고 계산해요.","map":[["가려진 이름 칸","노드 번호"],["답안 내용","**노드 특징(Node feature)** 과 연결 모양"],["같은 답이면 같은 점수","같은 나무면 같은 결과"]]}],"pass2":[{"kind":"look","head":"무엇이 달라졌나 볼게요","boxes":[{"x":0.07,"y":0.21,"w":0.42,"h":0.06,"say":"새 불릿: 하지만 GNN 은 노드 특징만 봐요. ID(번호)는 못 봐요."},{"x":0.17,"y":0.4,"w":0.21,"h":0.23,"say":"왼쪽 그래프는 번호가 그대로예요. 사람인 우리가 보는 그림이니까요."},{"x":0.515,"y":0.32,"w":0.37,"h":0.4,"say":"오른쪽 두 나무는 선, 막대, 화살표는 p.17 과 같고 번호만 전부 비었어요."}]},{"kind":"points","head":"단어 풀기","items":["**노드 특징(Node feature)**: 노드마다 처음부터 붙은 정보. 사람이면 나이, 키 같은 숫자예요.","그 숫자 목록을 특징 벡터 $x_v$ 라고 불러요.","ID: 1, 2, 3 같은 이름표. 설명하려고 붙인 이름일 뿐이에요."]},{"kind":"formula","head":"메시지 패싱 한 층 (2주차 복습)","tex":"h_v^{(k)} = \\sigma\\left( W^{(k)} \\cdot \\text{AGG}\\left( \\{\\!\\{ h_u^{(k-1)} : u \\in N(v) \\}\\!\\} \\right) \\right)","parts":[{"sym":"h_v^{(k)}","say":"노드 $v$ 의 $k$ 층 임베딩"},{"sym":"N(v)","say":"$v$ 의 이웃 목록 (친구 명단)"},{"sym":"h_u^{(k-1)}","say":"이웃 $u$ 가 보낸 지난 층 값 (쪽지)"},{"sym":"\\{\\!\\{ \\cdots \\}\\!\\}","say":"멀티셋: 순서 없이 개수는 세는 봉투"},{"sym":"W^{(k)}","say":"모든 노드가 같이 쓰는 가중치 행렬"},{"sym":"\\sigma","say":"활성화 함수 (예: ReLU)"}],"whole":"이웃 쪽지를 봉투에 담아 요약하고, 같은 $W$ 를 곱하고, 손질해요. 번호가 들어갈 자리는 없어요."},{"kind":"figure","head":"GNN 이 보는 나무","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\"><line x1=\"40\" y1=\"184\" x2=\"59\" y2=\"136\" class=\"e b2\"/><circle cx=\"40\" cy=\"200\" r=\"16\" class=\"n b1\"/><line x1=\"78\" y1=\"184\" x2=\"59\" y2=\"136\" class=\"e b2\"/><circle cx=\"78\" cy=\"200\" r=\"16\" class=\"n b1\"/><line x1=\"59\" y1=\"104\" x2=\"106.5\" y2=\"56\" class=\"e b3\"/><circle cx=\"59\" cy=\"120\" r=\"16\" class=\"n b2\"/><line x1=\"116\" y1=\"184\" x2=\"154\" y2=\"136\" class=\"e b2\"/><circle cx=\"116\" cy=\"200\" r=\"16\" class=\"n b1\"/><line x1=\"154\" y1=\"184\" x2=\"154\" y2=\"136\" class=\"e b2\"/><circle cx=\"154\" cy=\"200\" r=\"16\" class=\"n b1\"/><line x1=\"192\" y1=\"184\" x2=\"154\" y2=\"136\" class=\"e b2\"/><circle cx=\"192\" cy=\"200\" r=\"16\" class=\"n b1\"/><line x1=\"154\" y1=\"104\" x2=\"106.5\" y2=\"56\" class=\"e b3\"/><circle cx=\"154\" cy=\"120\" r=\"16\" class=\"n b2\"/><circle cx=\"106.5\" cy=\"40\" r=\"16\" class=\"n b3\"/><line x1=\"280\" y1=\"184\" x2=\"299\" y2=\"136\" class=\"e b2\"/><circle cx=\"280\" cy=\"200\" r=\"16\" class=\"n b1\"/><line x1=\"318\" y1=\"184\" x2=\"299\" y2=\"136\" class=\"e b2\"/><circle cx=\"318\" cy=\"200\" r=\"16\" class=\"n b1\"/><line x1=\"299\" y1=\"104\" x2=\"346.5\" y2=\"56\" class=\"e b3\"/><circle cx=\"299\" cy=\"120\" r=\"16\" class=\"n b2\"/><line x1=\"356\" y1=\"184\" x2=\"394\" y2=\"136\" class=\"e b2\"/><circle cx=\"356\" cy=\"200\" r=\"16\" class=\"n b1\"/><line x1=\"394\" y1=\"184\" x2=\"394\" y2=\"136\" class=\"e b2\"/><circle cx=\"394\" cy=\"200\" r=\"16\" class=\"n b1\"/><line x1=\"432\" y1=\"184\" x2=\"394\" y2=\"136\" class=\"e b2\"/><circle cx=\"432\" cy=\"200\" r=\"16\" class=\"n b1\"/><line x1=\"394\" y1=\"104\" x2=\"346.5\" y2=\"56\" class=\"e b3\"/><circle cx=\"394\" cy=\"120\" r=\"16\" class=\"n b2\"/><circle cx=\"346.5\" cy=\"40\" r=\"16\" class=\"n b3\"/><text x=\"116\" y=\"248\" font-size=\"15\" text-anchor=\"middle\" class=\"tm b4\">노드 1 의 나무?<\/text><text x=\"356\" y=\"248\" font-size=\"15\" text-anchor=\"middle\" class=\"tm b4\">노드 2 의 나무?<\/text><text x=\"240\" y=\"125\" font-size=\"20\" text-anchor=\"middle\" class=\"tb b4\">=<\/text><\/svg>","caption":"번호를 지우면 두 **계산 그래프(Computational graph)** 는 구별할 단서가 없어요.","builds":4},{"kind":"steps","head":"번호를 바꿔 붙여도 입력이 같을까?","steps":["모든 **노드 특징(Node feature)** 을 $x = 1$ 로 둬요.","선 목록: 1-2, 1-5, 2-5, 5-4, 4-3.","이름표 1 과 2 를 바꿔요: 2-1, 2-5, 1-5, 5-4, 4-3.","정리하면 1-2, 1-5, 2-5, 4-5, 3-4. 원래 목록과 똑같아요.","입력(선 목록 + 특징)이 같으니 출력도 같아요. 즉 노드 1 과 노드 2 의 임베딩이 같아요."],"answer":"번호를 바꿔도 GNN 의 답은 그대로예요."},{"kind":"prof","when":"3주차 화요일 수업","lines":["모든 노드 이름이 그냥 '1' 이어도 WL 은 차이를 잡을 수 있대요.","'1 과 1 의 친구인 1' 과 '1, 1, 1 의 친구인 1' 은 벌써 다르니까요."]}],"pass3":[{"kind":"check","q":"**노드 특징(Node feature)** 에 해당하는 것은?","choices":["노드 번호 1, 2, 3","노드마다 붙은 나이, 원자 종류 같은 정보","막대 한 줄","선의 개수"],"a":1,"why":"특징은 노드 자체의 정보예요. 번호는 이름표일 뿐이라 GNN 이 보지 않아요."},{"kind":"warn","head":"오해 주의","items":["특징만 본다고 해서 구조를 안 보는 게 아니에요. 누구 쪽지를 봉투에 넣을지 고를 때 구조를 써요.","여기선 특징이 모두 같다고 가정했어요. 특징(색)이 다르면 나무 모양이 같아도 구별될 수 있어요."]}],"pass4":[{"kind":"code","head":"번호를 버리고 모양만 남기기","file":"Sample_Code_3_번역.ipynb 셀 15 (원본 셀 11)","code":"fig, axes = plt.subplots(2, 2, figsize=(14, 7), gridspec_kw={'width_ratios': [1, 2.4]})\nfor row, (name, G, pos) in enumerate([('$C_6$', C6, POS_C6), ('$2 \\\\times C_3$', TwoC3, POS_2C3)]):\n    draw_graph(G, pos, axes[row, 0], highlight=0, title=f'{name}  (node 0 outlined)')\n    draw_tree(unfolding_tree(G, 0, 3), axes[row, 1], uniform=True, node_size=330, font_size=7,\n              title=f'Computational graph of node 0 in {name}, 3 layers')\nfig.suptitle('Identical computational graphs → identical embeddings', fontsize=13, fontweight='bold')\nplt.tight_layout(); plt.show()\n\n\ndef tree_shape(T, n):\n    \"\"\"Canonical form of the subtree at n, ignoring which graph node each copy is.\"\"\"\n    return tuple(sorted(tree_shape(T, k) for k in T.predecessors(n)))\n\nsame = all(tree_shape(unfolding_tree(C6, u, L), (u,)) == tree_shape(unfolding_tree(TwoC3, v, L), (v,))\n           for L in range(1, 5) for u in C6 for v in TwoC3)\nprint(f'All 6 x 6 node pairs (C6 node, 2xC3 node) have identical trees for L = 1..4: {same}')","lines":[{"from":1,"to":7,"say":"C6 와 TwoC3 에서 노드 0 을 표시하고, 각각의 3층 계산 그래프를 모양만(회색) 그려 나란히 보여 줘요."},{"from":10,"to":11,"say":"노드 n 아래 부분 나무의 모양을 돌려주는 함수예요. 설명문에 '어느 노드의 복사본인지 무시한다'고 적혀 있어요."},{"from":12,"to":12,"say":"자식들 모양을 먼저 구해(자기 자신을 다시 부르는 재귀) 정렬해 튜플로 묶어요. 번호는 한 번도 안 써요."},{"from":13,"to":16,"say":"층 1 부터 4 까지, C6 의 모든 노드와 TwoC3 의 모든 노드의 나무 모양이 같은지 all 로 확인하고 출력해요."}],"link":"p.18 의 '번호를 지운 나무' 가 바로 tree_shape 의 결과예요."},{"kind":"pyterm","name":"예시 코드: 슬라이드 그래프에 적용","say":["노트북 함수 unfolding_tree, tree_shape 를 슬라이드 그래프에 써 본 짧은 예시예요.","`==` 는 두 값이 같은지 묻고 True/False 를 돌려줘요."],"example":"G = nx.Graph([(1, 2), (1, 5), (2, 5), (5, 4), (4, 3)])\nprint(tree_shape(unfolding_tree(G, 1, 2), (1,)) == tree_shape(unfolding_tree(G, 2, 2), (2,)))","out":"True"}]},{"p":19,"title":"계산 그래프 (3): 그래서 같은 임베딩","terms":["Computational graph","Node feature","Embedding","Aggregation"],"pass1":[{"kind":"say","lines":["노드 1 과 노드 2 는 나무 모양이 같고, 동그라미마다 든 **노드 특징(Node feature)** 도 모두 같아요.","GNN 이 노드마다 만들어 주는 숫자 설명을 **임베딩(Embedding)** 이라고 하죠.","재료도 같고 계산 순서도 같으니, 어떤 GNN 이든 두 노드에 똑같은 임베딩을 줄 수밖에 없어요."]},{"kind":"look","head":"결론이 적힌 상자","boxes":[{"x":0.09,"y":0.69,"w":0.3,"h":0.1,"say":"주황 상자에는 'GNN 은 노드 1 과 노드 2 를 구별하지 못한다' 고 적혀 있어요."}]},{"kind":"analogy","head":"같은 재료, 같은 레시피","scene":"두 요리사가 똑같은 재료를 받았어요. 둘 다 같은 레시피를 보고 같은 순서로 요리해요. 그러면 누가 만들었든 맛이 똑같겠죠. GNN 도 재료인 특징과 순서인 나무 모양이 같으면 같은 임베딩이 나와요.","map":[["재료","**노드 특징(Node feature)**"],["레시피의 순서","나무 모양(계산 그래프)"],["완성된 요리의 맛","**임베딩(Embedding)**"]]}],"pass2":[{"kind":"look","head":"이유 두 가지와 상자 두 개","boxes":[{"x":0.03,"y":0.14,"w":0.45,"h":0.19,"say":"GNN 은 노드 1, 2 에 같은 임베딩을 만들어요. 이유: 계산 그래프가 같고, 특징(색)이 같아요."},{"x":0.515,"y":0.32,"w":0.37,"h":0.4,"say":"뿌리에만 1, 2 가 적혀 있어요. 어느 나무인지 알려 주는 표시일 뿐이에요. 동그라미가 모두 흰색 = 특징이 모두 같아요."},{"x":0.09,"y":0.69,"w":0.3,"h":0.1,"say":"주황 상자: GNN 은 노드 1 과 2 를 구별하지 못해요."},{"x":0.475,"y":0.73,"w":0.46,"h":0.17,"say":"참고 상자: GNN 은 노드 ID 를 신경 쓰지 않고, 특징 벡터를 **집계(Aggregation)** 할 뿐이에요."}]},{"kind":"figure","head":"숫자로 직접: 특징 1, 집계는 합","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\"><line x1=\"40\" y1=\"184\" x2=\"59\" y2=\"136\" class=\"e b2\"/><circle cx=\"40\" cy=\"200\" r=\"16\" class=\"n b1\"/><text x=\"40\" y=\"205\" font-size=\"15\" text-anchor=\"middle\" class=\"tl b1\">1<\/text><line x1=\"78\" y1=\"184\" x2=\"59\" y2=\"136\" class=\"e b2\"/><circle cx=\"78\" cy=\"200\" r=\"16\" class=\"n b1\"/><text x=\"78\" y=\"205\" font-size=\"15\" text-anchor=\"middle\" class=\"tl b1\">1<\/text><line x1=\"59\" y1=\"104\" x2=\"106.5\" y2=\"56\" class=\"e b3\"/><circle cx=\"59\" cy=\"120\" r=\"16\" class=\"n3 b2\"/><text x=\"59\" y=\"125\" font-size=\"15\" text-anchor=\"middle\" class=\"tl b2\">2<\/text><line x1=\"116\" y1=\"184\" x2=\"154\" y2=\"136\" class=\"e b2\"/><circle cx=\"116\" cy=\"200\" r=\"16\" class=\"n b1\"/><text x=\"116\" y=\"205\" font-size=\"15\" text-anchor=\"middle\" class=\"tl b1\">1<\/text><line x1=\"154\" y1=\"184\" x2=\"154\" y2=\"136\" class=\"e b2\"/><circle cx=\"154\" cy=\"200\" r=\"16\" class=\"n b1\"/><text x=\"154\" y=\"205\" font-size=\"15\" text-anchor=\"middle\" class=\"tl b1\">1<\/text><line x1=\"192\" y1=\"184\" x2=\"154\" y2=\"136\" class=\"e b2\"/><circle cx=\"192\" cy=\"200\" r=\"16\" class=\"n b1\"/><text x=\"192\" y=\"205\" font-size=\"15\" text-anchor=\"middle\" class=\"tl b1\">1<\/text><line x1=\"154\" y1=\"104\" x2=\"106.5\" y2=\"56\" class=\"e b3\"/><circle cx=\"154\" cy=\"120\" r=\"16\" class=\"n3 b2\"/><text x=\"154\" y=\"125\" font-size=\"15\" text-anchor=\"middle\" class=\"tl b2\">3<\/text><circle cx=\"106.5\" cy=\"40\" r=\"16\" class=\"n2 b3\"/><text x=\"106.5\" y=\"45\" font-size=\"15\" text-anchor=\"middle\" class=\"tl b3\">5<\/text><line x1=\"280\" y1=\"184\" x2=\"299\" y2=\"136\" class=\"e b2\"/><circle cx=\"280\" cy=\"200\" r=\"16\" class=\"n b1\"/><text x=\"280\" y=\"205\" font-size=\"15\" text-anchor=\"middle\" class=\"tl b1\">1<\/text><line x1=\"318\" y1=\"184\" x2=\"299\" y2=\"136\" class=\"e b2\"/><circle cx=\"318\" cy=\"200\" r=\"16\" class=\"n b1\"/><text x=\"318\" y=\"205\" font-size=\"15\" text-anchor=\"middle\" class=\"tl b1\">1<\/text><line x1=\"299\" y1=\"104\" x2=\"346.5\" y2=\"56\" class=\"e b3\"/><circle cx=\"299\" cy=\"120\" r=\"16\" class=\"n3 b2\"/><text x=\"299\" y=\"125\" font-size=\"15\" text-anchor=\"middle\" class=\"tl b2\">2<\/text><line x1=\"356\" y1=\"184\" x2=\"394\" y2=\"136\" class=\"e b2\"/><circle cx=\"356\" cy=\"200\" r=\"16\" class=\"n b1\"/><text x=\"356\" y=\"205\" font-size=\"15\" text-anchor=\"middle\" class=\"tl b1\">1<\/text><line x1=\"394\" y1=\"184\" x2=\"394\" y2=\"136\" class=\"e b2\"/><circle cx=\"394\" cy=\"200\" r=\"16\" class=\"n b1\"/><text x=\"394\" y=\"205\" font-size=\"15\" text-anchor=\"middle\" class=\"tl b1\">1<\/text><line x1=\"432\" y1=\"184\" x2=\"394\" y2=\"136\" class=\"e b2\"/><circle cx=\"432\" cy=\"200\" r=\"16\" class=\"n b1\"/><text x=\"432\" y=\"205\" font-size=\"15\" text-anchor=\"middle\" class=\"tl b1\">1<\/text><line x1=\"394\" y1=\"104\" x2=\"346.5\" y2=\"56\" class=\"e b3\"/><circle cx=\"394\" cy=\"120\" r=\"16\" class=\"n3 b2\"/><text x=\"394\" y=\"125\" font-size=\"15\" text-anchor=\"middle\" class=\"tl b2\">3<\/text><circle cx=\"346.5\" cy=\"40\" r=\"16\" class=\"n2 b3\"/><text x=\"346.5\" y=\"45\" font-size=\"15\" text-anchor=\"middle\" class=\"tl b3\">5<\/text><text x=\"240\" y=\"125\" font-size=\"20\" text-anchor=\"middle\" class=\"tb b3\">=<\/text><text x=\"116\" y=\"248\" font-size=\"15\" text-anchor=\"middle\" class=\"tb b3\">노드 1 → 5<\/text><text x=\"356\" y=\"248\" font-size=\"15\" text-anchor=\"middle\" class=\"tb b3\">노드 2 → 5<\/text><\/svg>","caption":"맨 아래 1 → 가운데 2 와 3 → 뿌리 5. 두 **계산 그래프(Computational graph)** 에서 같은 숫자가 나와요.","builds":3},{"kind":"steps","head":"가중치까지 넣어 계산하기","steps":["규칙: $h_v^{(k)} = \\text{ReLU}(w \\cdot \\sum_{u \\in N(v)} h_u^{(k-1)})$, $w = 0.5$, 특징은 모두 1.","1층 왼쪽: 봉투 {1, 1} 합 2, $0.5 \\times 2 = 1$.","1층 오른쪽: 봉투 {1, 1, 1} 합 3, $0.5 \\times 3 = 1.5$.","2층 뿌리: 봉투 {1, 1.5} 합 2.5, $0.5 \\times 2.5 = 1.25$.","노드 2 의 나무도 줄마다 같은 계산이라 1.25.","$w = -1$ 이면 둘 다 0. 합 대신 평균, 최대를 써도 두 나무는 같은 값이에요."],"answer":"노드 1 과 노드 2 의 임베딩은 반드시 같아요."},{"kind":"prof","when":"3주차 화요일 수업","lines":["초기 특징이 다르면 노드 1 과 2 도 구별되겠지만,","초기 특징이 같으면 둘은 구별할 수 없다고 했어요."]}],"pass3":[{"kind":"english","head":"서술형 답안 문장","en":"Nodes 1 and 2 have the same computational graph and identical node features, so a GNN, which aggregates feature vectors without using node IDs, outputs the same embedding for both.","ko":"노드 1 과 2 는 계산 그래프와 노드 특징이 같아요. GNN 은 ID 없이 특징 벡터만 집계하니 둘에게 같은 임베딩을 내요.","tip":"이유 두 개(same computational graph, identical node features)를 꼭 둘 다 써요."},{"kind":"check","q":"노드 1 과 2 가 같은 **임베딩(Embedding)** 을 받는 이유로 맞는 것은?","choices":["학습이 덜 돼서","계산 그래프와 노드 특징이 같아서","노드 번호가 가까워서","합 집계를 써서"],"a":1,"why":"나무 모양과 특징이 같으면 같은 $W$ 로 같은 계산을 하니 결과가 같아요. 집계 종류와도 무관해요."},{"kind":"warn","head":"슬라이드 확인","items":["제목이 p.18 과 똑같이 '(3)' 이에요. 순서로는 '(4)' 가 맞아요. 내용은 문제없어요.","노드 1, 2 는 정말 대칭인 자리라 같은 임베딩이 자연스러워요. 진짜 문제는 모양이 다른데 같게 보는 경우예요 (p.27 이후)."]}],"pass4":[{"kind":"say","lines":["노트북의 **핵심 보조정리(Key Lemma)** 가 이 슬라이드와 같은 말이에요 (Sample_Code_3_번역.ipynb 셀 13).","메시지 패싱 GNN 은 깊이 L 계산 그래프로부터만 임베딩을 계산하고, 그 외의 것은 보지 않아요.","두 노드의 계산 그래프가 같으면, 가중치가 무엇이든 모든 GNN 이 같은 임베딩을 줘요."]},{"kind":"code","head":"모든 노드 쌍의 나무가 같은지 한 번에 검사","file":"Sample_Code_3_번역.ipynb 셀 15 (원본 셀 11)","code":"fig, axes = plt.subplots(2, 2, figsize=(14, 7), gridspec_kw={'width_ratios': [1, 2.4]})\nfor row, (name, G, pos) in enumerate([('$C_6$', C6, POS_C6), ('$2 \\\\times C_3$', TwoC3, POS_2C3)]):\n    draw_graph(G, pos, axes[row, 0], highlight=0, title=f'{name}  (node 0 outlined)')\n    draw_tree(unfolding_tree(G, 0, 3), axes[row, 1], uniform=True, node_size=330, font_size=7,\n              title=f'Computational graph of node 0 in {name}, 3 layers')\nfig.suptitle('Identical computational graphs → identical embeddings', fontsize=13, fontweight='bold')\nplt.tight_layout(); plt.show()\n\n\ndef tree_shape(T, n):\n    \"\"\"Canonical form of the subtree at n, ignoring which graph node each copy is.\"\"\"\n    return tuple(sorted(tree_shape(T, k) for k in T.predecessors(n)))\n\nsame = all(tree_shape(unfolding_tree(C6, u, L), (u,)) == tree_shape(unfolding_tree(TwoC3, v, L), (v,))\n           for L in range(1, 5) for u in C6 for v in TwoC3)\nprint(f'All 6 x 6 node pairs (C6 node, 2xC3 node) have identical trees for L = 1..4: {same}')","lines":[{"from":1,"to":7,"say":"C6 와 TwoC3 에서 노드 0 을 표시하고, 각각의 3층 계산 그래프를 모양만(회색) 그려 나란히 보여 줘요."},{"from":8,"to":12,"say":"tree_shape 함수는 번호를 무시하고 나무 모양만 튜플로 적어요. 자식 모양들을 정렬해 묶으니 모양이 같으면 결과도 같아요."},{"from":14,"to":15,"say":"`all(...)` 은 안의 비교가 전부 True 인지 봐요. 층 1~4, 육각형 노드 u, 삼각형 두 개 노드 v 의 모든 조합을 검사해요."},{"from":16,"to":16,"say":"`f'...{same}'` 은 f-문자열이에요. 중괄호 안 변수 값을 글자 속에 끼워 넣어요. 출력은 ... L = 1..4: True 예요."}],"link":"나무가 같다 → 어떤 GNN 이든 같은 임베딩. 노트북은 서로 다른 그래프에서도 이게 일어난다는 걸 보여 줘요."}]},{"p":20,"title":"계산 그래프: 동네가 다르면 나무도 달라요","terms":["Local neighborhood","Computational graph","Receptive field"],"pass1":[{"kind":"say","lines":["이번엔 다섯 노드 모두의 **계산 그래프(Computational graph)** 를 그려 봐요.","한 노드의 가까운 동네, 곧 **국소 이웃(Local neighborhood)** 모양이 다르면 나무 모양도 대개 달라져요.","다섯 그루 중 노드 1 과 노드 2 의 나무만 같고, 노드 3, 4, 5 는 저마다 다른 모양이에요."]},{"kind":"look","head":"나무 다섯 그루 비교","boxes":[{"x":0.05,"y":0.49,"w":0.37,"h":0.39,"say":"노드 1, 2 의 나무예요. 앞에서 본 쌍둥이 나무 그대로예요."},{"x":0.465,"y":0.49,"w":0.07,"h":0.39,"say":"노드 3 의 나무는 가늘어요. 이웃이 한 명뿐이라서 가지가 적어요."},{"x":0.72,"y":0.49,"w":0.19,"h":0.39,"say":"노드 5 의 나무가 가장 넓어요. 이웃이 세 명이라서 가지가 많아요."}]}],"pass2":[{"kind":"look","head":"나무 다섯 그루","boxes":[{"x":0.03,"y":0.14,"w":0.47,"h":0.06,"say":"불릿: 일반적으로 국소 이웃이 다르면 계산 그래프도 달라요. '일반적으로' 는 예외가 있다는 뜻이에요."},{"x":0.06,"y":0.24,"w":0.2,"h":0.22,"say":"늘 보던 다섯 노드 그래프예요."},{"x":0.05,"y":0.49,"w":0.37,"h":0.39,"say":"노드 1, 2 의 나무는 p.17 과 같아요. 뿌리 아래 2개, 그 아래 2개와 3개."},{"x":0.465,"y":0.49,"w":0.07,"h":0.39,"say":"노드 3 의 나무는 가늘어요. 이웃이 4 하나뿐이라 뿌리 아래 1개, 그 아래 3, 5."},{"x":0.545,"y":0.49,"w":0.135,"h":0.39,"say":"노드 4 의 나무: 뿌리 아래 3, 5. 3 아래 4 하나, 5 아래 1, 2, 4."},{"x":0.72,"y":0.49,"w":0.19,"h":0.39,"say":"노드 5 의 나무가 가장 넓어요. 뿌리 아래 1, 2, 4. 맨 아래가 6개예요."}]},{"kind":"compare","head":"번호를 지우고 모양만 세기","cols":["노드","이웃 (차수)","모양 요약(뿌리 아래 개수 → 그 아래 개수들)","그룹"],"rows":[["1","2, 5 (2)","2 → (2, 3)","가"],["2","1, 5 (2)","2 → (2, 3)","가"],["3","4 (1)","1 → (2)","나"],["4","3, 5 (2)","2 → (1, 3)","다"],["5","1, 2, 4 (3)","3 → (2, 2, 2)","라"]]},{"kind":"points","head":"표 읽는 법","items":["차수(degree) = 한 노드에 붙은 선의 개수, 즉 이웃 수예요.","괄호 속 숫자는 사실 '이웃들의 차수' 예요. 노드 1 의 이웃 2, 5 의 차수가 2, 3 이니까요.","모양 그룹은 네 개. 대칭인 노드 1, 2 만 같은 그룹이에요."]},{"kind":"steps","head":"1층 GNN 이라면?","steps":["1층 나무는 뿌리와 가운데 줄뿐이라 모양 = 가운데 줄 개수(차수)예요.","노드 1: 2, 노드 2: 2, 노드 3: 1, 노드 4: 2, 노드 5: 3.","노드 1, 2, 4 가 모두 '2' 로 겹쳐요.","2층이 되어야 '(2, 3)' 대 '(1, 3)' 으로 노드 4 가 갈라져요."],"answer":"층이 깊어질수록 **수용 영역(Receptive field)** 이 넓어지고 구별할 기회가 늘어요."},{"kind":"prof","when":"3주차 화요일 수업","lines":["노드 1, 2 말고 다른 노드들은 초기 특징이 같아도 구분된다고 했어요.","여기서 힌트: GNN 이 잘 구별하지 못하는 건 **사이클(Cycle)** 이 있는 구조래요."]},{"kind":"mining","src":"마이닝 9강 Graph Kernels","lines":["불변량(invariant) 하나라도 다르면 동형이 아니지만, 전부 같다고 동형인 건 아니었어요.","노드 1 과 4 는 차수(2)가 같지만 동네 모양은 달라요. 더 깊이 펼쳐 봐야 차이가 보여요."]}],"pass3":[{"kind":"english","head":"서술형에 쓸 문장","en":"With only one layer, the computational graph is shallow, so nodes with the same degree, such as nodes 1 and 4, cannot be distinguished.","ko":"층이 하나면 계산 그래프가 얕아서, 노드 1 과 4 처럼 차수가 같은 노드를 구별하지 못해요.","tip":"2024 가을 기말 6번 해설의 'neighbor aggregation focuses only on immediate neighbors' 와 같은 줄기예요."},{"kind":"warn","head":"주의","items":["'일반적으로' 를 놓치지 마세요. **국소 이웃(Local neighborhood)** 이 달라도 나무가 똑같이 나오는 예외가 있어요 (1-WL 이 실패하는 곳).","나무가 다르다 = 구별할 '기회' 가 생겼다는 뜻이지, 반드시 구별한다는 뜻은 아니에요. 집계 방법에 달렸어요."]}],"pass4":[{"kind":"pyterm","name":"예시 코드: 다섯 노드의 맨 아래 줄 개수","say":["노트북의 unfolding_tree 로 슬라이드 그래프의 2층 나무를 만들어 맨 아래 줄을 세 본 예시예요.","트리 노드는 걸음 튜플이라, 길이가 3 이면 뿌리에서 두 걸음 간 맨 아래 줄이에요.","`[... for v in [1, 2, 3, 4, 5]]` 는 리스트 컴프리헨션: 반복 결과를 바로 리스트로 모아요."],"example":"G = nx.Graph([(1, 2), (1, 5), (2, 5), (5, 4), (4, 3)])\nprint([sum(1 for t in unfolding_tree(G, v, 2) if len(t) == 3) for v in [1, 2, 3, 4, 5]])","out":"[5, 5, 2, 4, 6]"},{"kind":"say","lines":["출력 5, 5, 2, 4, 6 은 표의 '맨 아래 줄 합계' 와 똑같아요.","노드 1 과 4 의 차이를 코드로도 확인하려면 tree_shape 비교가 False 로 나와요 (예시로 돌려 본 결과)."]}]},{"p":21,"title":"계산 그래프 = 뿌리 있는 부분 트리","terms":["Rooted subtree","Computational graph"],"pass1":[{"kind":"say","lines":["앞에서 그린 나무들에 수학 이름을 붙여요.","주인공 노드를 맨 위에 두고, 아래로 이웃을 매달고, 또 그 이웃의 이웃을 매달아 만든 나무,","이걸 **뿌리 있는 부분 트리(Rooted subtree)** 라고 해요. 맨 위 주인공이 뿌리예요.","만드는 방법이 같아서 **계산 그래프(Computational graph)** 와 같은 것을 가리키는 이름이에요."]},{"kind":"look","head":"정의가 적힌 상자","boxes":[{"x":0.39,"y":0.23,"w":0.405,"h":0.14,"say":"회색 상자는 정의예요. 뿌리 노드에서 시작해 이웃을 되풀이해서 펼쳐 만든다고 적혀 있어요."},{"x":0.12,"y":0.36,"w":0.72,"h":0.12,"say":"주황 점선 화살표 다섯 개는 다섯 나무가 모두 뿌리 있는 부분 트리라는 표시예요."}]},{"kind":"analogy","head":"나부터 적어 내려가는 족보","scene":"가족 족보를 그릴 때 맨 위에 나를 적어요. 아래 줄에는 부모님을, 그 아래 줄에는 부모님의 부모님을 적어요. 줄을 하나 더할 때마다 바로 윗줄 사람마다 같은 일을 되풀이하죠. 한 사람에서 시작해 같은 규칙으로 계속 매달아 만든 이 그림이 뿌리 있는 부분 트리와 닮았어요.","map":[["맨 위의 나","뿌리(주인공 노드)"],["줄마다 같은 규칙으로 매달기","이웃을 되풀이해서 펼치기"],["완성된 족보","**뿌리 있는 부분 트리(Rooted subtree)**"]]}],"pass2":[{"kind":"look","head":"새 이름과 정의 상자","boxes":[{"x":0.03,"y":0.14,"w":0.55,"h":0.06,"say":"빨간 글씨가 새 이름: 뿌리 있는 부분 트리 구조. '같다' 는 완전히 같은 것이라는 뜻이에요."},{"x":0.39,"y":0.23,"w":0.405,"h":0.14,"say":"회색 상자 정의: 뿌리 노드에서 이웃 노드를 재귀적으로 펼쳐서 정의해요."},{"x":0.12,"y":0.36,"w":0.72,"h":0.12,"say":"주황 점선 화살표 다섯 개가 나무 다섯 그루의 뿌리를 가리켜요. 전부 뿌리 있는 부분 트리라는 뜻이에요."}]},{"kind":"points","head":"이름을 네 조각으로","items":["트리(tree): 갈라지기만 하고 다시 합쳐지거나 빙 도는 길이 없는 그림.","뿌리 있는(rooted): 꼭대기(주인공 노드)가 정해져 있음.","부분(sub): 그래프 전체가 아니라 그 노드 주변 조각.","구조(structure): 번호를 빼고 남은 모양.","펼친다 = 이웃을 아래에 매단다. 재귀적 = 새로 매단 것에 같은 일을 또 한다."]},{"kind":"figure","head":"노드 3 을 뿌리로 펼치기","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\"><circle cx=\"80\" cy=\"60\" r=\"16\" class=\"n2\"/><text x=\"80\" y=\"65\" font-size=\"15\" text-anchor=\"middle\" class=\"tl\">3<\/text><text x=\"80\" y=\"258\" font-size=\"15\" text-anchor=\"middle\" class=\"tb\">0번 펼침<\/text><line x1=\"112\" y1=\"140\" x2=\"181\" y2=\"140\" class=\"e b1\"/><polygon points=\"190,140 181,145 181,135\" class=\"arrow b1\"/><circle cx=\"240\" cy=\"60\" r=\"16\" class=\"n2 b1\"/><text x=\"240\" y=\"65\" font-size=\"15\" text-anchor=\"middle\" class=\"tl b1\">3<\/text><line x1=\"240\" y1=\"76\" x2=\"240\" y2=\"124\" class=\"e b1\"/><circle cx=\"240\" cy=\"140\" r=\"16\" class=\"n3 b1\"/><text x=\"240\" y=\"145\" font-size=\"15\" text-anchor=\"middle\" class=\"tl b1\">4<\/text><text x=\"240\" y=\"258\" font-size=\"15\" text-anchor=\"middle\" class=\"tb b1\">1번 펼침<\/text><line x1=\"272\" y1=\"140\" x2=\"341\" y2=\"140\" class=\"e b2\"/><polygon points=\"350,140 341,145 341,135\" class=\"arrow b2\"/><circle cx=\"400\" cy=\"60\" r=\"16\" class=\"n2 b2\"/><text x=\"400\" y=\"65\" font-size=\"15\" text-anchor=\"middle\" class=\"tl b2\">3<\/text><line x1=\"400\" y1=\"76\" x2=\"400\" y2=\"124\" class=\"e b2\"/><circle cx=\"400\" cy=\"140\" r=\"16\" class=\"n3 b2\"/><text x=\"400\" y=\"145\" font-size=\"15\" text-anchor=\"middle\" class=\"tl b2\">4<\/text><line x1=\"392\" y1=\"154\" x2=\"374\" y2=\"201\" class=\"e2 b2\"/><line x1=\"408\" y1=\"154\" x2=\"426\" y2=\"201\" class=\"e2 b2\"/><circle cx=\"370\" cy=\"215\" r=\"16\" class=\"n4 b2\"/><text x=\"370\" y=\"220\" font-size=\"15\" text-anchor=\"middle\" class=\"tl b2\">3<\/text><circle cx=\"430\" cy=\"215\" r=\"16\" class=\"n4 b2\"/><text x=\"430\" y=\"220\" font-size=\"15\" text-anchor=\"middle\" class=\"tl b2\">5<\/text><text x=\"400\" y=\"258\" font-size=\"15\" text-anchor=\"middle\" class=\"tb b2\">2번 펼침<\/text><\/svg>","caption":"2번 펼치면 2층 GNN 의 **계산 그래프(Computational graph)** 가 돼요. 펼친 횟수 = 층 수.","builds":2},{"kind":"compare","head":"펼칠 때마다 맨 아래 줄 개수","cols":["펼친 횟수","노드 3","노드 5"],"rows":[["0번","3 (1개)","5 (1개)"],["1번","4 (1개)","1, 2, 4 (3개)"],["2번","3, 5 (2개)","2, 5, 1, 5, 3, 5 (6개)"],["3번","4, 1, 2, 4 (4개)","2+3+2+3+1+3 = 14개"]]},{"kind":"prof","when":"3주차 화요일 수업","lines":["GNN 은 노드의 구조를 **뿌리 있는 부분 트리(Rooted subtree)** 로 파악한대요.","타깃 노드를 뿌리로 삼는 트리라서 '뿌리 있는' 이라고 불러요."]},{"kind":"mining","src":"마이닝 7강 Subgraph Mining","lines":["노드 유도 부분그래프는 원래 그래프에서 노드를 골라 그 사이 선을 전부 가져온 조각이었어요.","뿌리 있는 부분 트리는 달라요. 삼각형 1-2-5 같은 도는 길 대신 같은 노드의 복사본이 여러 번 나와요."]}],"pass3":[{"kind":"check","q":"**뿌리 있는 부분 트리(Rooted subtree)** 에 대한 설명으로 맞는 것은?","choices":["원래 그래프에서 선 몇 개를 오려 낸 조각","뿌리에서 이웃을 층 수만큼 반복해 매단 나무로, 계산 그래프와 같다","그래프 전체를 나무로 바꾼 것","사이클을 그대로 보존한 그림"],"a":1,"why":"복사본이 반복해서 들어가는 펼침 그림이에요. 노드 1 의 나무에 1 이 세 번 나오는 게 증거예요."},{"kind":"warn","head":"이름 정리","items":["계산 그래프, 뿌리 있는 부분 트리, 펼침 트리(unfolding tree)는 같은 나무의 세 이름이에요.","계산 그래프는 'GNN 계산 순서' 관점, 뿌리 있는 부분 트리는 '동네 모양' 관점일 뿐이에요."]}],"pass4":[{"kind":"code","head":"나무가 얼마나 빨리 커지나 (1/2)","file":"Sample_Code_3_번역.ipynb 셀 12 (원본 셀 9) (1/2)","code":"def unfolding_tree(G, root, depth):\n    \"\"\"\n    Computational graph of `root` for a `depth`-layer GNN.\n    Tree nodes are walks starting at `root`; attribute 'orig' is the graph node a copy stands for.\n    Edges point child -> parent, the direction messages flow.\n    \"\"\"\n    T = nx.DiGraph()\n    T.add_node((root,), orig=root, level=0)\n    frontier = [(root,)]\n    for d in range(1, depth + 1):\n        frontier = [walk + (u,) for walk in frontier for u in sorted(G[walk[-1]])]\n        for walk in frontier:\n            T.add_node(walk, orig=walk[-1], level=d)\n            T.add_edge(walk, walk[:-1])\n    return T\n\n\ndef draw_tree(T, ax, uniform=False, title=None, node_size=460, font_size=9):\n    \"\"\"Draw a tree with the root on top. uniform=True paints every copy gray (only shape matters).\"\"\"\n    pos, next_x = {}, [0.0]\n\n    def place(n):                                   # 각 부모를 자식들의 가운데 위에 놓는다\n        kids = sorted(T.predecessors(n))\n        if kids:\n            x = float(np.mean([place(k) for k in kids]))\n        else:\n            x, next_x[0] = next_x[0], next_x[0] + 1\n        pos[n] = (x, -T.nodes[n]['level'])\n        return x\n\n    place(next(n for n in T if T.nodes[n]['level'] == 0))\n    nodes = list(T.nodes())\n    fill = [color_of(0 if uniform else T.nodes[n]['orig'] + 1) for n in nodes]\n    nx.draw_networkx_edges(T, pos, ax=ax, arrows=False, edge_color=C_EDGE, width=1.4)\n    nx.draw_networkx_nodes(T, pos, nodelist=nodes, ax=ax, node_color=fill,\n                           edgecolors=C_DARK, linewidths=1.1, node_size=node_size)\n    for n, f in zip(nodes, fill):\n        ax.text(*pos[n], str(T.nodes[n]['orig']), ha='center', va='center',\n                fontsize=font_size, color=ink(f))\n    if title:\n        ax.set_title(title)\n    ax.set_axis_off()\n    ax.margins(0.08)\n","lines":[{"from":1,"to":6,"say":"unfolding_tree 함수의 이름과 설명(따옴표 세 개 사이 글)이에요. 뿌리에서 depth 층만큼 펼친 계산 그래프를 만들어요."},{"from":7,"to":9,"say":"빈 방향 그래프 T 를 만들고 뿌리 하나를 넣어요. frontier 는 지금 나무 맨 아래 줄 목록이에요."},{"from":10,"to":17,"say":"층마다 맨 아래 줄 노드의 이웃을 하나씩 붙여 새 줄을 만들고, 자식에서 부모로 가는 선을 그어요. 끝나면 나무를 돌려줘요."},{"from":18,"to":31,"say":"draw_tree 함수의 시작 부분이에요. place 가 자식들을 먼저 배치하고, 부모를 그 가운데 위에 놓아 좌표를 정해요."},{"from":32,"to":44,"say":"노드 색을 정하고 선, 동그라미, 번호 글자를 그려요. uniform=True 면 모두 회색이라 모양만 보여요."}]},{"kind":"code","head":"나무가 얼마나 빨리 커지나 (2/2)","file":"Sample_Code_3_번역.ipynb 셀 12 (원본 셀 9) (2/2)","code":"\nG_demo = nx.Graph([(0, 1), (0, 2), (1, 2), (1, 3), (2, 4), (3, 4), (4, 5)])\nPOS_DEMO = nx.spring_layout(G_demo, seed=3)\n\nfig = plt.figure(figsize=(14, 4.4))\ngs = fig.add_gridspec(1, 3, width_ratios=[1, 1.25, 1.6])\ndraw_graph(G_demo, POS_DEMO, fig.add_subplot(gs[0]), colors={v: v + 1 for v in G_demo},\n           highlight=0, title='The graph (target node 0)')\nfor k, depth in enumerate([1, 2]):\n    T = unfolding_tree(G_demo, 0, depth)\n    draw_tree(T, fig.add_subplot(gs[k + 1]),\n              title=f'Computational graph of node 0, {depth} layer(s)\\n'\n                    f'({T.number_of_nodes()} tree nodes)')\nplt.tight_layout(); plt.show()\n\nsizes = [unfolding_tree(G_demo, 0, L).number_of_nodes() for L in range(6)]\nprint(f'Tree size for L = 0..5 layers: {sizes}   (the graph has only {G_demo.number_of_nodes()} nodes)')","lines":[{"from":1,"to":4,"say":"예시 그래프 G_demo 를 (노드, 노드) 쌍 목록으로 만들고 그릴 좌표를 정해요."},{"from":5,"to":14,"say":"그림 세 칸에 원래 그래프와 1층, 2층 계산 그래프를 나란히 그려요."},{"from":16,"to":16,"say":"`range(6)` 은 0, 1, ..., 5. 층 수 L 마다 나무를 만들어 `.number_of_nodes()` 로 동그라미 수를 세요."},{"from":17,"to":17,"say":"출력: Tree size for L = 0..5 layers: [1, 3, 9, 24, 63, 162]. 그래프는 노드 6개뿐인데 나무는 162개까지 커져요."}],"link":"p.21 표의 1, 3, 6, 14 처럼 펼칠수록 불어나는 것을 코드로 확인해요."},{"kind":"warn","head":"코드와 슬라이드의 차이","items":["노트북의 개수는 나무 전체 동그라미 수(누적)예요. 표는 맨 아래 줄 개수만 셌어요.","예시로 슬라이드 그래프의 노드 3 에 L = 0..3 을 넣으면 누적 1, 2, 4, 8 이 나와요 (줄별 1, 1, 2, 4)."]}]},{"p":22,"title":"GNN 임베딩은 나무 모양을 담아요","terms":["Rooted subtree","Embedding","Expressive power"],"pass1":[{"kind":"say","lines":["GNN 이 노드마다 만드는 숫자 설명, 곧 **임베딩(Embedding)** 에는 그 노드의 나무 모양이 담겨요.","나무 밖에 있는 정보는 임베딩에 담기지 않아요.","구별을 가장 잘하는 GNN, 즉 **표현력(Expressive power)** 이 가장 큰 GNN 은 모양이 다른 나무마다 다른 임베딩을 줘요."]},{"kind":"look","head":"색 동그라미 줄","boxes":[{"x":0.1,"y":0.4,"w":0.25,"h":0.07,"say":"노드 1 과 2 위 동그라미는 둘 다 주황이에요. 나무가 같으니 임베딩도 같다는 뜻이에요."},{"x":0.46,"y":0.4,"w":0.4,"h":0.07,"say":"노드 3, 4, 5 는 파랑, 초록, 보라로 모두 달라요. 나무 모양이 서로 다르니까요."}]},{"kind":"analogy","head":"상품마다 다른 바코드","scene":"마트의 상품마다 바코드가 붙어 있어요. 잘 만든 바코드 체계는 다른 상품에는 반드시 다른 바코드를 붙이고, 같은 상품끼리는 같은 바코드를 붙여요. 그래야 계산대에서 헷갈리지 않죠. 가장 좋은 GNN 도 나무 모양마다 서로 다른 임베딩을 붙여 줘요.","map":[["상품","노드의 나무 모양"],["바코드","**임베딩(Embedding)**"],["다른 상품엔 다른 바코드","**표현력(Expressive power)** 이 가장 큰 GNN"]]}],"pass2":[{"kind":"look","head":"색 동그라미 줄","boxes":[{"x":0.03,"y":0.14,"w":0.5,"h":0.06,"say":"첫 불릿: GNN 노드 임베딩은 뿌리 있는 부분 트리 구조를 담아요. 나무 밖 정보는 못 담아요."},{"x":0.03,"y":0.21,"w":0.8,"h":0.1,"say":"둘째 불릿: 가장 표현력 있는 GNN 은 서로 다른 나무를 서로 다른 임베딩으로 보내요."},{"x":0.025,"y":0.37,"w":0.92,"h":0.1,"say":"임베딩 상자. 색은 입력 특징이 아니라 결과 임베딩이 같은지 다른지를 뜻해요."},{"x":0.1,"y":0.4,"w":0.25,"h":0.07,"say":"노드 1 과 2 위는 둘 다 주황. 나무가 같으니 임베딩도 같아요."},{"x":0.46,"y":0.4,"w":0.4,"h":0.07,"say":"노드 3 파랑, 4 초록, 5 보라. p.20 의 모양 그룹 네 개와 색 네 개가 딱 맞아요."}]},{"kind":"points","head":"단어 풀기","items":["**표현력(Expressive power)**: 서로 다른 것을 서로 다르게 나타내는 능력.","'보낸다(map)' = 그 나무를 넣으면 그 임베딩이 나온다.","목표: 나무 종류 수만큼 임베딩 종류가 나와야 해요. 이 예에서는 네 가지."]},{"kind":"figure","head":"특징 1, 가중치 없이 집계만 두 번","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\"><text x=\"30\" y=\"30\" font-size=\"15\" text-anchor=\"start\" class=\"tb\">합 집계의 뿌리 값<\/text><line x1=\"40\" y1=\"90\" x2=\"440\" y2=\"90\" class=\"e\"/><line x1=\"40\" y1=\"84\" x2=\"40\" y2=\"96\" class=\"e\"/><line x1=\"95\" y1=\"84\" x2=\"95\" y2=\"96\" class=\"e\"/><line x1=\"150\" y1=\"84\" x2=\"150\" y2=\"96\" class=\"e\"/><line x1=\"205\" y1=\"84\" x2=\"205\" y2=\"96\" class=\"e\"/><line x1=\"260\" y1=\"84\" x2=\"260\" y2=\"96\" class=\"e\"/><line x1=\"315\" y1=\"84\" x2=\"315\" y2=\"96\" class=\"e\"/><line x1=\"370\" y1=\"84\" x2=\"370\" y2=\"96\" class=\"e\"/><line x1=\"425\" y1=\"84\" x2=\"425\" y2=\"96\" class=\"e\"/><text x=\"40\" y=\"116\" font-size=\"14\" text-anchor=\"middle\" class=\"tm\">0<\/text><text x=\"95\" y=\"116\" font-size=\"14\" text-anchor=\"middle\" class=\"tm\">1<\/text><text x=\"150\" y=\"116\" font-size=\"14\" text-anchor=\"middle\" class=\"tm\">2<\/text><text x=\"205\" y=\"116\" font-size=\"14\" text-anchor=\"middle\" class=\"tm\">3<\/text><text x=\"260\" y=\"116\" font-size=\"14\" text-anchor=\"middle\" class=\"tm\">4<\/text><text x=\"315\" y=\"116\" font-size=\"14\" text-anchor=\"middle\" class=\"tm\">5<\/text><text x=\"370\" y=\"116\" font-size=\"14\" text-anchor=\"middle\" class=\"tm\">6<\/text><text x=\"425\" y=\"116\" font-size=\"14\" text-anchor=\"middle\" class=\"tm\">7<\/text><circle cx=\"150\" cy=\"90\" r=\"16\" class=\"n3 b1\"/><text x=\"150\" y=\"62\" font-size=\"15\" text-anchor=\"middle\" class=\"t b1\">3<\/text><circle cx=\"260\" cy=\"90\" r=\"16\" class=\"n4 b1\"/><text x=\"260\" y=\"62\" font-size=\"15\" text-anchor=\"middle\" class=\"t b1\">4<\/text><circle cx=\"315\" cy=\"90\" r=\"16\" class=\"n2 b1\"/><text x=\"315\" y=\"62\" font-size=\"15\" text-anchor=\"middle\" class=\"t b1\">1, 2<\/text><circle cx=\"370\" cy=\"90\" r=\"16\" class=\"n b1\"/><text x=\"370\" y=\"62\" font-size=\"15\" text-anchor=\"middle\" class=\"t b1\">5<\/text><text x=\"30\" y=\"160\" font-size=\"15\" text-anchor=\"start\" class=\"tb b2\">평균, 최대 집계의 뿌리 값<\/text><line x1=\"40\" y1=\"220\" x2=\"440\" y2=\"220\" class=\"e b2\"/><line x1=\"40\" y1=\"214\" x2=\"40\" y2=\"226\" class=\"e b2\"/><line x1=\"95\" y1=\"214\" x2=\"95\" y2=\"226\" class=\"e b2\"/><line x1=\"150\" y1=\"214\" x2=\"150\" y2=\"226\" class=\"e b2\"/><line x1=\"205\" y1=\"214\" x2=\"205\" y2=\"226\" class=\"e b2\"/><line x1=\"260\" y1=\"214\" x2=\"260\" y2=\"226\" class=\"e b2\"/><line x1=\"315\" y1=\"214\" x2=\"315\" y2=\"226\" class=\"e b2\"/><line x1=\"370\" y1=\"214\" x2=\"370\" y2=\"226\" class=\"e b2\"/><line x1=\"425\" y1=\"214\" x2=\"425\" y2=\"226\" class=\"e b2\"/><text x=\"40\" y=\"246\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b2\">0<\/text><text x=\"95\" y=\"246\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b2\">1<\/text><text x=\"150\" y=\"246\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b2\">2<\/text><text x=\"205\" y=\"246\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b2\">3<\/text><text x=\"260\" y=\"246\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b2\">4<\/text><text x=\"315\" y=\"246\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b2\">5<\/text><text x=\"370\" y=\"246\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b2\">6<\/text><text x=\"425\" y=\"246\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b2\">7<\/text><circle cx=\"95\" cy=\"220\" r=\"16\" class=\"n b2\"/><text x=\"125\" y=\"196\" font-size=\"15\" text-anchor=\"start\" class=\"t b2\">노드 1, 2, 3, 4, 5 전부 여기<\/text><\/svg>","caption":"합은 5, 5, 2, 4, 6 으로 네 점에 갈리고, 평균과 최대는 다섯 노드 모두 1 에 모여요.","builds":2},{"kind":"compare","head":"뿌리 값 계산 (특징은 모두 1)","cols":["노드","가운데 줄 (합)","뿌리 (합)","뿌리 (평균, 최대)"],"rows":[["1","2, 3","5","1"],["2","2, 3","5","1"],["3","2","2","1"],["4","1, 3","4","1"],["5","2, 2, 2","6","1"]]},{"kind":"prof","when":"3주차 화요일 수업","lines":["GNN 과 WL 은 타깃 노드를 뿌리로 한 깊이 k 트리로 구조를 본대요. k 는 층 수예요.","트리가 같으면 초기 특징이 다르지 않은 한 표현도 같아요. 이건 방식의 한계래요.","그런데 실제 모델은 3, 4, 5 조차 못 가를 때가 있어요. 왜일까요?"]},{"kind":"mining","src":"마이닝 9강 Graph Kernels","lines":["그래프 커널은 부분 구조가 얼마나 겹치는지로 유사도를 쟀고, 좋은 커널의 첫 조건이 표현력이었어요.","서로 다른 나무를 같은 임베딩으로 만들면 좋은 GNN 이 아니에요."]}],"pass3":[{"kind":"english","head":"서술형 답안 문장","en":"A maximally expressive GNN maps different rooted subtrees to different node embeddings.","ko":"가장 표현력 있는 GNN 은 서로 다른 뿌리 있는 부분 트리를 서로 다른 노드 임베딩으로 보내요.","tip":"maps A to B = A 를 B 로 보낸다. 'different ... different' 를 짝으로 외워요."},{"kind":"check","q":"**표현력(Expressive power)** 의 뜻으로 가장 알맞은 것은?","choices":["계산이 빠른 정도","서로 다른 것을 서로 다르게 나타내는 능력","층의 개수","파라미터 수"],"a":1,"why":"구별하는 능력이에요. 그래서 나무가 다르면 임베딩도 달라야 해요."},{"kind":"warn","head":"헷갈리는 점","items":["이 슬라이드의 색은 출력 임베딩이에요. p.19 의 흰 동그라미(입력 특징)와 다른 뜻이에요.","가장 표현력 있는 GNN 도 노드 1, 2 에는 같은 색을 줘요. '다른 나무만큼은 다르게' 가 목표예요.","숫자 하나짜리 합이 늘 구별하는 건 아니에요. {1, 3} 과 {2, 2} 는 둘 다 합 4 예요."]}],"pass4":[]},{"p":23,"title":"복습: 단사 함수","terms":["Injective"],"pass1":[{"kind":"say","lines":["함수는 무언가를 넣으면 결과 하나를 내주는 규칙이에요.","서로 다른 것을 넣으면 반드시 서로 다른 결과가 나오는 함수, 이걸 **단사(Injective)** 함수라고 해요.","그래서 결과만 보고도 무엇을 넣었는지 거꾸로 알 수 있어요. 정보를 하나도 잃지 않는 거죠."]},{"kind":"look","head":"화살표 그림","boxes":[{"x":0.39,"y":0.4,"w":0.19,"h":0.28,"say":"분홍 화살표가 함수예요. 왼쪽 1, 2, 3 이 오른쪽에서 서로 다른 곳에 도착해서 겹치는 곳이 없어요."}]},{"kind":"analogy","head":"버튼마다 다른 음료가 나오는 자판기","scene":"학교 자판기에 버튼이 여러 개 있어요. 좋은 자판기는 버튼마다 다른 음료가 나와서, 나온 음료만 보고도 어떤 버튼을 눌렀는지 알 수 있어요. 고장 난 자판기는 두 버튼에서 똑같이 콜라가 나와서, 콜라만 보고는 어느 버튼이었는지 알 수 없어요. 좋은 자판기처럼 입력마다 결과가 다른 것이 단사예요.","map":[["버튼","함수에 넣는 입력"],["나온 음료","함수의 결과(출력)"],["버튼마다 음료가 다름","**단사(Injective)**"]]}],"pass2":[{"kind":"look","head":"정의와 그림","boxes":[{"x":0.03,"y":0.14,"w":0.6,"h":0.06,"say":"함수 $f: X \\to Y$ 가 서로 다른 원소를 서로 다른 출력으로 보내면 단사예요."},{"x":0.03,"y":0.21,"w":0.36,"h":0.06,"say":"직관: $f$ 는 입력의 정보를 모두 보존해요."},{"x":0.32,"y":0.35,"w":0.13,"h":0.38,"say":"왼쪽 타원 X: 입력 1, 2, 3."},{"x":0.39,"y":0.4,"w":0.19,"h":0.28,"say":"분홍 화살표가 함수 $f$ 예요. 1 → D, 2 → B, 3 → A. 도착지가 겹치지 않아요."},{"x":0.515,"y":0.35,"w":0.13,"h":0.38,"say":"오른쪽 타원 Y: D, B, C, A. C 로 오는 화살표는 없지만 그래도 단사예요."}]},{"kind":"formula","head":"단사의 식","tex":"x_1 \\neq x_2 \\;\\Rightarrow\\; f(x_1) \\neq f(x_2)","parts":[{"sym":"x_1, x_2","say":"X 에서 고른 입력 두 개"},{"sym":"\\neq","say":"같지 않다"},{"sym":"\\Rightarrow","say":"앞이 참이면 뒤도 반드시 참"},{"sym":"f(x_1)","say":"$x_1$ 을 넣었을 때의 출력"}],"whole":"입력이 다르면 출력도 반드시 달라요. 뒤집으면 '출력이 같았다면 입력도 같았다' 예요."},{"kind":"figure","head":"단사인 것과 아닌 것","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\"><text x=\"110\" y=\"24\" font-size=\"16\" text-anchor=\"middle\" class=\"tb b1\">단사 O<\/text><rect x=\"20\" y=\"44\" width=\"60\" height=\"190\" rx=\"8\" class=\"box b1\"/><rect x=\"150\" y=\"34\" width=\"60\" height=\"210\" rx=\"8\" class=\"box b1\"/><text x=\"50\" y=\"64\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b1\">X<\/text><text x=\"180\" y=\"54\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b1\">Y<\/text><text x=\"50\" y=\"100\" font-size=\"16\" text-anchor=\"middle\" class=\"t b1\">1<\/text><text x=\"50\" y=\"150\" font-size=\"16\" text-anchor=\"middle\" class=\"t b1\">2<\/text><text x=\"50\" y=\"200\" font-size=\"16\" text-anchor=\"middle\" class=\"t b1\">3<\/text><text x=\"180\" y=\"85\" font-size=\"16\" text-anchor=\"middle\" class=\"t b1\">D<\/text><text x=\"180\" y=\"130\" font-size=\"16\" text-anchor=\"middle\" class=\"t b1\">B<\/text><text x=\"180\" y=\"175\" font-size=\"16\" text-anchor=\"middle\" class=\"t b1\">C<\/text><text x=\"180\" y=\"220\" font-size=\"16\" text-anchor=\"middle\" class=\"t b1\">A<\/text><line x1=\"62\" y1=\"95\" x2=\"157.1\" y2=\"81.3\" class=\"e2 b1\"/><polygon points=\"166,80 157.8,86.2 156.4,76.3\" class=\"arrow b1\"/><line x1=\"62\" y1=\"145\" x2=\"157.2\" y2=\"126.7\" class=\"e2 b1\"/><polygon points=\"166,125 158.1,131.6 156.2,121.8\" class=\"arrow b1\"/><line x1=\"62\" y1=\"195\" x2=\"157.2\" y2=\"213.3\" class=\"e2 b1\"/><polygon points=\"166,215 156.2,218.2 158.1,208.4\" class=\"arrow b1\"/><text x=\"350\" y=\"24\" font-size=\"16\" text-anchor=\"middle\" class=\"tb b2\">단사 X<\/text><rect x=\"260\" y=\"44\" width=\"60\" height=\"190\" rx=\"8\" class=\"box b2\"/><rect x=\"390\" y=\"34\" width=\"60\" height=\"210\" rx=\"8\" class=\"box b2\"/><text x=\"290\" y=\"64\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b2\">X<\/text><text x=\"420\" y=\"54\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b2\">Y<\/text><text x=\"290\" y=\"100\" font-size=\"16\" text-anchor=\"middle\" class=\"t b2\">1<\/text><text x=\"290\" y=\"150\" font-size=\"16\" text-anchor=\"middle\" class=\"t b2\">2<\/text><text x=\"290\" y=\"200\" font-size=\"16\" text-anchor=\"middle\" class=\"t b2\">3<\/text><text x=\"420\" y=\"85\" font-size=\"16\" text-anchor=\"middle\" class=\"t b2\">D<\/text><text x=\"420\" y=\"130\" font-size=\"16\" text-anchor=\"middle\" class=\"t b2\">B<\/text><text x=\"420\" y=\"175\" font-size=\"16\" text-anchor=\"middle\" class=\"t b2\">C<\/text><text x=\"420\" y=\"220\" font-size=\"16\" text-anchor=\"middle\" class=\"t b2\">A<\/text><line x1=\"302\" y1=\"95\" x2=\"397.1\" y2=\"81.3\" class=\"e2 b2\"/><polygon points=\"406,80 397.8,86.2 396.4,76.3\" class=\"arrow b2\"/><line x1=\"302\" y1=\"145\" x2=\"398.4\" y2=\"84.8\" class=\"e2 b2\"/><polygon points=\"406,80 401,89 395.7,80.5\" class=\"arrow b2\"/><line x1=\"302\" y1=\"195\" x2=\"397.2\" y2=\"213.3\" class=\"e2 b2\"/><polygon points=\"406,215 396.2,218.2 398.1,208.4\" class=\"arrow b2\"/><\/svg>","caption":"오른쪽은 1 과 2 가 D 에서 부딪혀요. D 만 보고는 1 인지 2 인지 몰라요.","builds":2},{"kind":"compare","head":"여러 함수를 확인해 봐요","cols":["함수","입력","출력","단사?"],"rows":[["슬라이드의 $f$","1, 2, 3","D, B, A","단사"],["$g(x) = 2x$","1, 2, 3","2, 4, 6","단사"],["$s(x) = x^2$","-1, 1, 2","1, 1, 4","아님 (-1 과 1 이 부딪힘)"],["봉투의 평균","{1, 1}, {1}","1, 1","아님"],["봉투의 합","{1, 3}, {2, 2}","4, 4","아님"]]},{"kind":"prof","when":"3주차 화요일 수업","lines":["WL 은 친구들 이름을 보고 나에게 새 이름을 줘요.","구조마다 고유한 이름이 붙으니, 구조를 이름으로 보내는 **단사(Injective)** 함수가 있는 셈이래요.","그래서 WL 은 그 범위 안의 구조 차이를 하나하나 분별해요."]},{"kind":"mining","src":"마이닝 9강 Graph Kernels","lines":["그래프를 벡터로 바꾸는 사상이 단사(one-to-one)이면 완전한 그래프 커널이라고 했어요.","WL 의 해시 함수도 서로 다른 이웃 묶음이 같은 라벨로 부딪히지 않아야 제대로 작동해요."]}],"pass3":[{"kind":"english","head":"단사를 서술할 때 괄호로 뜻 붙이기","en":"A function is injective if distinct inputs always produce distinct outputs, so no information about the input is lost.","ko":"함수가 서로 다른 입력에 항상 서로 다른 출력을 내면 단사예요. 그래서 입력 정보를 잃지 않아요.","tip":"2024 가을 기말 5번 해설: injective (i.e., distinct input features produce distinct outputs)."},{"kind":"check","q":"**단사(Injective)** 가 아님을 보이려면 무엇을 찾으면 되나요?","choices":["출력이 같은 같은 입력 두 개","출력이 같은 서로 다른 입력 두 개","아무도 안 오는 출력 하나","출력이 다른 입력 두 개"],"a":1,"why":"서로 다른 입력인데 출력이 같은 반례 하나면 충분해요. 아무도 안 오는 출력(C)은 단사와 무관해요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["'같은 입력이면 같은 출력' 은 모든 함수의 규칙이에요. 단사의 핵심은 '다른 입력이 합쳐지지 않는다' 예요.","Y 의 원소가 다 쓰일 필요는 없어요. 다 쓰이는 성질은 전사라고 따로 불러요."]}],"pass4":[{"kind":"code","head":"노트북 속 단사 함수: HASH 표 (1/3)","file":"Sample_Code_3_번역.ipynb 셀 19 (원본 셀 14) (1/3)","code":"def aggregate(G, colors):\n    \"\"\"Step 2: aggregated color of every node = (own color, sorted tuple of neighbor colors).\"\"\"\n    return {v: (colors[v], tuple(sorted(colors[u] for u in G[v]))) for v in G}\n\n\ndef wl_refine(graphs, num_iterations=3):\n    \"\"\"\n    Color refinement run jointly on a list of graphs with one shared HASH table.\n\n    Returns `rounds`, where rounds[l] is a dict:\n        'colors' : [{node: color} per graph]             colors after round l\n        'agg'    : [{node: aggregated color} per graph]  what was hashed in round l\n        'table'  : {aggregated color: new color}         the HASH table of round l\n    rounds[0] is the initial coloring: every node gets color 1.\n    \"\"\"\n    rounds = [{'colors': [{v: 1 for v in G} for G in graphs], 'agg': None, 'table': {}}]\n    next_color = 2\n    for _ in range(num_iterations):\n        agg = [aggregate(G, c) for G, c in zip(graphs, rounds[-1]['colors'])]\n        # Step 3: 단사 해시. 처음 보는 집계된 색마다 아직 안 쓴 다음 번호를 준다.\n        # (매 라운드의 입력은 새 색들이므로 라운드마다 자기 표 하나만 있으면 된다.)\n        table = {}\n        for a in agg:\n            for sig in a.values():\n                if sig not in table:\n                    table[sig] = next_color\n                    next_color += 1\n        colors = [{v: table[sig] for v, sig in a.items()} for a in agg]\n        rounds.append({'colors': colors, 'agg': agg, 'table': table})\n    return rounds\n","lines":[{"from":1,"to":4,"say":"aggregate 함수: 노드마다 (내 색, 이웃 색을 정렬해 묶은 튜플)을 만들어 사전으로 돌려줘요."},{"from":5,"to":15,"say":"wl_refine 함수의 이름과 설명이에요. 여러 그래프가 HASH 표를 같이 쓰며 색 정제를 하고 rounds 목록을 돌려준대요."},{"from":16,"to":17,"say":"0라운드: 모든 노드를 색 1 로 칠해 rounds 에 넣어요. 새 번호는 2 부터 줘요."},{"from":18,"to":19,"say":"라운드 수만큼 반복하며, 지난 라운드 색으로 모든 노드의 집계 색을 만들어요."},{"from":20,"to":21,"say":"`#` 뒤는 주석이에요. 이 부분이 '단사 해시' 라고 적혀 있어요."},{"from":22,"to":22,"say":"`{}` 는 빈 딕셔너리. 열쇠(집계된 색) → 값(새 색 번호) 표예요."},{"from":23,"to":24,"say":"모든 노드의 집계된 색 sig 를 하나씩 봐요."},{"from":25,"to":27,"say":"표에 없는 새 입력이면 아직 안 쓴 번호를 주고 번호를 1 올려요. 다른 입력이 같은 번호를 받는 일이 없어요."},{"from":28,"to":31,"say":"표에서 새 번호를 찾아 노드를 다시 칠하고, 이번 라운드 결과를 rounds 끝에 붙여요. 다 돌면 rounds 를 돌려줘요."}],"link":"서로 다른 입력 → 서로 다른 번호. 슬라이드의 단사 함수 $f$ 를 딕셔너리로 만든 거예요."},{"kind":"code","head":"노트북 속 단사 함수: HASH 표 (2/3)","file":"Sample_Code_3_번역.ipynb 셀 19 (원본 셀 14) (2/3)","code":"\ndef color_histogram(colors):\n    \"\"\"How many nodes carry each color: the graph-level fingerprint.\"\"\"\n    return dict(sorted(Counter(colors.values()).items()))\n\n\ndef wl_report(rounds, names):\n    \"\"\"The WL test: compare the two graphs' color histograms round by round.\"\"\"\n    differ = False\n    for l, r in enumerate(rounds):\n        h1, h2 = (color_histogram(c) for c in r['colors'])\n        differ = differ or h1 != h2\n        print(f\"round {l}:  {names[0]} {str(h1):<34s} {'==' if h1 == h2 else '!='}  {names[1]} {h2}\")\n    print('\\n→ NON-ISOMORPHIC (the histograms differ)' if differ else\n          '\\n→ INCONCLUSIVE (the histograms are always equal)')\n\n\n# ---- 그리기 -------------------------------------------------------------------------\ndef fmt_agg(sig):\n    \"\"\"(3, (3, 4)) -> '3,{3,4}'\"\"\"\n    own, nbrs = sig\n    return f\"{own},{{{','.join(map(str, nbrs))}}}\"\n\n\ndef draw_aggregated(G, pos, ax, colors, agg, title=None):\n    \"\"\"Each node is a box showing its aggregated color, filled with its current color.\"\"\"\n    nx.draw_networkx_edges(G, pos, ax=ax, edge_color=C_EDGE, width=2.0)\n    for v in G:\n        f = color_of(colors[v])\n        ax.text(*pos[v], fmt_agg(agg[v]), ha='center', va='center', fontsize=10, color=ink(f),\n                bbox=dict(boxstyle='round,pad=0.35', fc=f, ec=C_DARK, lw=1.2))\n    xs, ys = zip(*pos.values())\n    ax.set_xlim(min(xs) - 0.5, max(xs) + 0.5)\n    ax.set_ylim(min(ys) - 0.4, max(ys) + 0.4)\n    if title:\n        ax.set_title(title)\n    ax.set_axis_off()\n","lines":[{"from":1,"to":5,"say":"color_histogram 함수: Counter 로 색마다 노드가 몇 개인지 세서 번호 순으로 정리해요."},{"from":6,"to":16,"say":"wl_report 함수: 라운드마다 두 그래프의 색 개수표를 비교해 == 또는 != 를 출력하고, 마지막에 판정을 알려 줘요."},{"from":17,"to":23,"say":"그리기 부분 시작이에요. fmt_agg 는 (3, (3, 4)) 같은 집계 색을 '3,{3,4}' 글자로 바꿔요."},{"from":24,"to":38,"say":"draw_aggregated 함수: 노드마다 집계 색 글자를 지금 색으로 칠한 상자에 적어 그려요."}]},{"kind":"code","head":"노트북 속 단사 함수: HASH 표 (3/3)","file":"Sample_Code_3_번역.ipynb 셀 19 (원본 셀 14) (3/3)","code":"\ndef draw_hash_table(ax, table, title):\n    tab = ax.table(cellText=[[fmt_agg(sig), c] for sig, c in table.items()],\n                   colLabels=['aggregated color', 'new color'], loc='center', cellLoc='center')\n    tab.auto_set_font_size(False); tab.set_fontsize(11); tab.scale(1, 1.7)\n    for j in range(2):                                   # 머리글 행\n        tab[0, j].set_facecolor(C_DARK)\n        tab[0, j].get_text().set(color='white', fontweight='bold')\n    for i, c in enumerate(table.values(), start=1):      # 새 색마다 칸을 그 색으로 칠한다\n        tab[i, 1].set_facecolor(color_of(c))\n        tab[i, 1].get_text().set(color=ink(color_of(c)), fontweight='bold')\n    ax.set_title(title)\n    ax.set_axis_off()\n\n\ndef show_initial(graphs, names, positions, rounds):\n    fig, axes = plt.subplots(1, len(graphs), figsize=(11, 3))\n    for ax, G, name, pos, c in zip(axes, graphs, names, positions, rounds[0]['colors']):\n        draw_graph(G, pos, ax, colors=c, labels='color', title=name)\n    fig.suptitle('Step 1 - Assign initial colors: every node gets color 1',\n                 fontsize=13, fontweight='bold')\n    plt.tight_layout(); plt.show()\n\n\ndef show_round(graphs, names, positions, rounds, l):\n    \"\"\"One round, left to right: aggregated colors -> HASH table -> new colors.\"\"\"\n    r, prev = rounds[l], rounds[l - 1]['colors']\n    fig = plt.figure(figsize=(15, 5.6))\n    gs = fig.add_gridspec(2, 3, width_ratios=[1, 0.75, 1])\n    for i, (G, name, pos) in enumerate(zip(graphs, names, positions)):\n        draw_aggregated(G, pos, fig.add_subplot(gs[i, 0]), prev[i], r['agg'][i],\n                        title=f'{name}: aggregated colors')\n        draw_graph(G, pos, fig.add_subplot(gs[i, 2]), colors=r['colors'][i], labels='color',\n                   title=f'{name}: new colors')\n    draw_hash_table(fig.add_subplot(gs[:, 1]), r['table'], title=f'HASH table (round {l})')\n    fig.suptitle(f'Round {l}:   Step 2 - aggregate neighboring colors   →   '\n                 f'Step 3 - injectively hash   →   new colors', fontsize=13, fontweight='bold')\n    plt.tight_layout(); plt.show()","lines":[{"from":1,"to":14,"say":"draw_hash_table 함수: HASH 표를 '집계 색, 새 색' 두 열짜리 표 그림으로 그리고 새 색 칸을 그 색으로 칠해요."},{"from":15,"to":23,"say":"show_initial 함수: 모든 노드가 색 1 인 시작 그림을 그래프마다 그려요."},{"from":24,"to":38,"say":"show_round 함수: 한 라운드를 왼쪽 집계 색, 가운데 HASH 표, 오른쪽 새 색 순서로 한 장에 그려요."}]},{"kind":"pyterm","name":"딕셔너리(dict)","say":["열쇠: 값 쌍을 모아 둔 표예요. `table[열쇠]` 로 값을 꺼내요.","`열쇠 in table` 은 그 열쇠가 이미 있는지 True/False 로 알려 줘요."],"example":"table = {}\ntable['D'] = 1\nprint('D' in table, 'C' in table)","out":"True False"}]},{"p":24,"title":"GNN 의 표현력: 나무 → 임베딩이 단사여야","terms":["Expressive power","Injective","Rooted subtree","Embedding"],"pass1":[{"kind":"say","lines":["앞 쪽에서 배운 **단사(Injective)** 를 GNN 에 적용해 봐요.","GNN 을 '나무를 넣으면 **임베딩(Embedding)** 이 나오는 함수' 로 생각할 수 있어요.","이 함수가 단사라면, 나무 모양이 다를 때 반드시 다른 임베딩이 나와요.","이런 GNN 이 **표현력(Expressive power)** 이 가장 큰, 구별을 가장 잘하는 GNN 이에요."]},{"kind":"look","head":"나무에서 점으로 가는 화살표","boxes":[{"x":0.11,"y":0.35,"w":0.23,"h":0.15,"say":"노드 1 과 2 의 나무에서 나온 화살표는 같은 주황 점에 모여요. 원래 같은 나무라서 괜찮아요."},{"x":0.44,"y":0.35,"w":0.4,"h":0.15,"say":"노드 3, 4, 5 의 나무는 각자 다른 점으로 가요. 다른 나무끼리 겹치지 않아요."}]}],"pass2":[{"kind":"look","head":"화살표를 따라가요","boxes":[{"x":0.03,"y":0.14,"w":0.7,"h":0.06,"say":"불릿: 가장 표현력 있는 GNN 은 부분 트리를 노드 임베딩으로 '단사적으로' 보내야 해요."},{"x":0.145,"y":0.28,"w":0.755,"h":0.13,"say":"임베딩 상자. 오른쪽 끝 $\\mathbb{R}^d$ 는 이 상자가 결과 모음 Y 라는 표시예요."},{"x":0.11,"y":0.35,"w":0.23,"h":0.15,"say":"노드 1 과 2 의 뿌리에서 나온 화살표가 같은 주황 점에 모여요. 나무가 원래 같으니까요."},{"x":0.44,"y":0.35,"w":0.4,"h":0.15,"say":"노드 3 은 파랑, 4 는 초록, 5 는 보라 점으로. 점은 모두 네 개예요."}]},{"kind":"formula","head":"나무에서 임베딩으로 가는 함수","tex":"f : \\mathcal{T} \\to \\mathbb{R}^d, \\qquad T_1 \\neq T_2 \\;\\Rightarrow\\; f(T_1) \\neq f(T_2)","parts":[{"sym":"f","say":"GNN 전체. 나무를 넣으면 뿌리 임베딩이 나와요"},{"sym":"\\mathcal{T}","say":"나올 수 있는 모든 뿌리 있는 부분 트리 (나무 도감)"},{"sym":"T_1, T_2","say":"도감에서 고른 나무 두 그루"},{"sym":"\\mathbb{R}^d","say":"칸이 $d$ 개인 숫자 목록 전부 (d 칸 점수표)"}],"whole":"나무가 다르면 GNN 이 내놓는 임베딩도 반드시 달라요. p.23 식에서 $x$ 를 나무 $T$ 로 바꿨을 뿐이에요."},{"kind":"compare","head":"d = 2 임베딩을 직접 만들기 (특징 1, 임베딩 = (1층 합, 2층 합) 두 칸)","cols":["노드","나무 모양","1층 합","2층 합","임베딩"],"rows":[["1","2 → (2, 3)","2","5","(2, 5)"],["2","2 → (2, 3)","2","5","(2, 5)"],["3","1 → (2)","1","2","(1, 2)"],["4","2 → (1, 3)","2","4","(2, 4)"],["5","3 → (2, 2, 2)","3","6","(3, 6)"]]},{"kind":"steps","head":"단사인지 세어 보기","steps":["나무 종류: 네 가지.","임베딩 종류: (2, 5), (1, 2), (2, 4), (3, 6) 네 가지.","나무마다 점 하나씩, 겹침 없음. 이 다섯 노드에서는 단사예요.","첫째 칸만 쓰면 2, 2, 1, 2, 3. 노드 1 과 4 의 서로 다른 나무가 2 로 부딪혀요."],"answer":"1층만 쓰면 단사가 깨지고, 2층까지 쓰면 이 예에서는 단사예요."},{"kind":"prof","when":"3주차 화요일 수업","lines":["GNN 이 WL 만큼 못 하는 이유는 집계와 업데이트가 단사가 아닐 수 있어서래요.","단사란: 같은 구조의 트리엔 같은 표현, 다른 구조의 트리엔 다른 표현을 주는 것.","모델이 확실히 그렇게 작동하느냐가 문제라고 했어요."]},{"kind":"mining","src":"마이닝 7강 Subgraph Mining (gSpan)","lines":["최소 DFS 코드를 그래프의 정규 표현으로 삼았고, 동형 ⇔ 최소 코드가 같다고 했어요.","모양 → 코드 함수가 단사라는 뜻이에요. GNN 은 이 역할을 숫자 벡터로 해 주는 게 목표예요."]}],"pass3":[{"kind":"english","head":"서술형 답안 문장","en":"The most expressive GNN must map rooted subtrees to node embeddings injectively.","ko":"가장 표현력 있는 GNN 은 뿌리 있는 부분 트리를 노드 임베딩으로 단사적으로 보내야 해요.","tip":"injectively 뒤에 '서로 다른 두 나무가 d차원 공간의 같은 점으로 가면 안 된다' 를 덧붙이면 좋아요."},{"kind":"check","q":"노드 1 과 2 의 화살표가 한 점에 모이는 것은 단사를 어긴 걸까요?","choices":["네, 두 노드가 부딪혔으니까요","아니요, 두 노드의 나무(입력)가 원래 같아서예요","네, d 가 작아서요"],"a":1,"why":"**단사(Injective)** 는 '나무 → 임베딩' 에 대해 따져요. 같은 나무가 같은 점으로 가는 건 정상이에요."},{"kind":"warn","head":"주의","items":["단사는 노드 번호 기준이 아니라 나무 기준이에요.","그림의 점은 한 줄로 늘어섰지만 실제 임베딩은 d 칸 벡터예요. 여기선 거리보다 '겹치느냐' 만 봐요."]}],"pass4":[]},{"p":25,"title":"잎에서 뿌리로: 노드 1 과 노드 4","terms":["Injective","Node feature","Receptive field"],"pass1":[{"kind":"say","lines":["나무 맨 아래 끝을 잎, 맨 위를 뿌리라고 해요. 계산은 잎에서 시작해 뿌리로 올라가요.","모든 노드가 처음 가진 정보, 즉 **노드 특징(Node feature)** 이 똑같아도 괜찮아요.","층마다 '이웃이 몇 명이었는지' 를 빠뜨리지 않고 위로 전하면,","노드 1 과 노드 4 의 나무 모양 차이가 뿌리까지 전해져서 둘을 구별할 수 있어요."]},{"kind":"look","head":"빨간 글씨 읽기","boxes":[{"x":0.08,"y":0.6,"w":0.08,"h":0.06,"say":"빨간 '이웃 2개' 는 이 동그라미가 아래에서 쪽지 2장을 받았다는 뜻이에요."},{"x":0.6,"y":0.36,"w":0.19,"h":0.47,"say":"노드 4 의 나무에는 '이웃 1개' 와 '이웃 3개' 가 적혀 있어요. 노드 1 쪽과 달라요."}]},{"kind":"analogy","head":"모둠 인원을 빠짐없이 보고하기","scene":"운동회 날 반마다 인원을 보고해요. 모둠장은 '우리 모둠은 2명' 이라고 반장에게 알리고, 반장은 모둠 보고를 모아 선생님께 전해요. 중간에 누가 인원수를 빼먹으면 선생님은 두 반이 다르다는 걸 알 수 없어요. 층마다 개수를 빠짐없이 전해야 맨 위에서 차이를 알 수 있어요.","map":[["모둠 인원","가운데 줄 노드가 받은 이웃 수"],["반장이 모아 전한 보고","뿌리가 받은 정보 묶음"],["빠짐없이 전하기","정보를 잃지 않는 모으기"]]}],"pass2":[{"kind":"look","head":"두 나무의 라벨","boxes":[{"x":0.04,"y":0.29,"w":0.12,"h":0.55,"say":"주황 화살표: 잎에서 뿌리 방향으로. 계산은 아래에서 시작해 위로 올라가요."},{"x":0.18,"y":0.36,"w":0.21,"h":0.47,"say":"노드 1 의 나무. 아래 '입력 특징은 모두 같음' 이라 구별 단서는 모양뿐이에요."},{"x":0.08,"y":0.6,"w":0.08,"h":0.06,"say":"빨간 '이웃 2개': 가운데 줄 노드 2 복사본이 쪽지 2장을 받았어요."},{"x":0.6,"y":0.36,"w":0.19,"h":0.47,"say":"노드 4 의 나무. 빨간 '이웃 1개' (노드 3 복사본), 파란 '이웃 3개' (노드 5 복사본)."},{"x":0.29,"y":0.36,"w":0.1,"h":0.08,"say":"뿌리 옆: (2개 이웃, 3개 이웃). 뿌리가 받은 봉투 내용이에요. 노드 4 쪽은 (1개 이웃, 3개 이웃)."},{"x":0.46,"y":0.48,"w":0.05,"h":0.08,"say":"빨간 ≠ : 두 뿌리가 받은 봉투가 달라요."}]},{"kind":"compare","head":"잎에서 한 줄씩 올라가기 (흰색 = 같은 특징)","cols":["단계","노드 1 의 나무","노드 4 의 나무"],"rows":[["잎","흰 5개","흰 4개 (개별로는 구별 불가)"],["1층 왼쪽 막대","{흰, 흰} 2장","{흰} 1장 (첫 차이)"],["1층 오른쪽 막대","{흰, 흰, 흰} 3장","{흰, 흰, 흰} 3장"],["새 이름표","2장색, 3장색","1장색, 3장색"],["뿌리 봉투","{2장색, 3장색}","{1장색, 3장색}"]]},{"kind":"steps","head":"숫자로 확인 (흰색 = 1, 집계 = 합)","steps":["가운데 줄: 노드 1 쪽 (2, 3), 노드 4 쪽 (1, 3).","뿌리: 2 + 3 = 5, 1 + 3 = 4. 달라요.","1층뿐이라면 뿌리 봉투는 둘 다 '흰 2장' 이라 같아요.","2층까지 가야 비로소 구별돼요."],"answer":"차이는 뿌리 바로 아래가 아니라 한 줄 더 아래에서 생겨요."},{"kind":"prof","when":"2주차 화요일 수업","lines":["레이어 하나가 보는 범위는 1홉 이웃이고, 두 장, 세 장 깔면 **수용 영역(Receptive field)** 이 넓어진다고 했어요.","1장이면 노드 1, 4 가 '이웃 2개' 로 똑같고, 2장이어야 이웃들의 이웃 수까지 보여요."]},{"kind":"mining","src":"마이닝 9강 WL 동형 테스트","lines":["모든 라벨 1 → 이웃 라벨 멀티셋 적기 {1, 1}, {1, 1, 1} → 새 라벨로 압축 → 반복.","'이웃 2개', '이웃 3개', 뿌리의 (2개짜리, 3개짜리)가 바로 이 과정이에요."]}],"pass3":[{"kind":"check","q":"노드 1 과 노드 4 를 구별하려면 GNN 층이 최소 몇 개 필요할까요?","choices":["1개","2개","5개","몇 개든 구별 불가"],"a":1,"why":"1층이면 둘 다 이웃 2개라 같아요. 2층에서 이웃들의 이웃 수 (2, 3) 대 (1, 3) 이 보여요."},{"kind":"warn","head":"라벨 주의","items":["영어 원본 '1 neighbors' 는 문법상 '1 neighbor' 가 맞아요. 뜻은 같아요.","한글 슬라이드 뿌리 옆 글자는 '개 이웃, 3개 이웃)' 처럼 앞이 잘려 보여요. 원래는 '(2개 이웃, 3개 이웃)' 이에요.","빨간 '이웃 2개' 는 뿌리가 아니라 가운데 줄 복사본의 이웃 수예요. 뿌리 1 과 4 의 이웃 수는 둘 다 2 예요."]}],"pass4":[{"kind":"pyterm","name":"예시 코드: 노트북 wl_refine 을 슬라이드 그래프에","say":["노트북 셀 19 의 wl_refine(색 정제)을 슬라이드 그래프에 2라운드 돌려 본 예시예요.","rounds[1] 은 1라운드(1층), rounds[2] 는 2라운드(2층) 뒤 노드별 색이에요."],"example":"G = nx.Graph([(1, 2), (1, 5), (2, 5), (5, 4), (4, 3)])\nrounds = wl_refine([G], num_iterations=2)\nprint(rounds[1]['colors'][0])\nprint(rounds[2]['colors'][0])","out":"{1: 2, 2: 2, 5: 3, 4: 2, 3: 4}\n{1: 5, 2: 5, 5: 6, 4: 7, 3: 8}"},{"kind":"points","head":"출력 읽기","items":["1라운드: 노드 1, 2, 4 가 모두 색 2. 차수만 본 결과라 1층 GNN 처럼 못 갈라요.","2라운드: 노드 1, 2 는 색 5, 노드 4 는 색 7. 이웃의 이웃 수까지 보니 갈라졌어요.","색 번호 자체에는 크기 뜻이 없어요. 같으냐 다르냐만 봐요."]}]},{"p":26,"title":"매 단계가 정보를 온전히 보존하면","terms":["Injective","Aggregation","Rooted subtree","Multi-set"],"pass1":[{"kind":"say","lines":["나무의 막대마다 이웃 정보를 모으는 **집계(Aggregation)** 가 일어나요.","모든 막대에서 정보를 하나도 잃지 않고 모으면, 모양이 다른 **뿌리 있는 부분 트리(Rooted subtree)** 를 모두 구별할 수 있어요.","반대로 한 층에서라도 정보가 새면, 위층에서는 절대 되살릴 수 없어요.","정보를 하나도 잃지 않는다는 건 앞에서 배운 단사와 같은 뜻이에요."]},{"kind":"look","head":"초록 상자 두 개","boxes":[{"x":0.14,"y":0.32,"w":0.69,"h":0.175,"say":"위 초록 상자는 뿌리 쪽에서 모으는 자리예요."},{"x":0.085,"y":0.585,"w":0.76,"h":0.09,"say":"아래 초록 상자는 그 아래 줄에서 모으는 자리예요. 위아래 두 줄 모두 정보를 온전히 지켜야 해요."}]},{"kind":"analogy","head":"귓속말 전달 게임","scene":"친구 다섯 명이 줄지어 귓속말 전달 게임을 해요. 첫 친구가 '사과 세 개' 라고 전했는데, 두 번째 친구가 '사과 몇 개' 라고 흐리게 전했어요. 그러면 뒤에서 아무리 또박또박 전해도 '세 개' 는 되살아나지 않아요. 그래서 모든 친구가 빠짐없이 전해야 끝까지 정확한 말이 도착해요.","map":[["줄 선 친구 한 명","나무 한 층의 모으기"],["흐리게 전하기","정보가 새는 모으기"],["모두 빠짐없이 전하기","모든 층이 단사인 **집계(Aggregation)**"]]}],"pass2":[{"kind":"look","head":"초록 상자 두 개","boxes":[{"x":0.03,"y":0.14,"w":0.86,"h":0.1,"say":"불릿: 각 단계가 이웃 정보를 온전히 보존할 수 있다면, 서로 다른 나무를 구별할 수 있어요."},{"x":0.085,"y":0.585,"w":0.76,"h":0.09,"say":"아래 초록 상자: 1층 집계 네 개를 한꺼번에 감싸요."},{"x":0.14,"y":0.32,"w":0.69,"h":0.175,"say":"위 초록 상자: 뿌리 막대, 즉 2층 집계를 감싸요. 조건이 두 줄 모두에 붙어요."},{"x":0.855,"y":0.58,"w":0.115,"h":0.09,"say":"초록 글씨 '이웃 정보 온전히 보존 함' = 이 줄의 집계가 단사여야 한다는 표시예요."}]},{"kind":"formula","head":"집계 한 번","tex":"h_v^{(k)} = \\text{AGG}^{(k)}\\left( \\{\\!\\{ h_u^{(k-1)} : u \\in N(v) \\}\\!\\} \\right)","parts":[{"sym":"\\text{AGG}^{(k)}","say":"$k$ 층에서 쓰는 집계 함수 (봉투 요약 기계)"},{"sym":"\\{\\!\\{ \\cdots \\}\\!\\}","say":"**멀티셋(Multi-set)**: 순서 무시, 개수는 셈"},{"sym":"h_u^{(k-1)}","say":"이웃 $u$ 의 지난 층 결과"}],"whole":"조건은 $\\text{AGG}^{(1)}$ 도, $\\text{AGG}^{(2)}$ 도 단사라는 거예요."},{"kind":"points","head":"왜 모든 층이 단사면 나무 전체가 구별될까? (거꾸로 따라가기)","items":["두 뿌리 결과가 같았다고 해 봐요.","2층이 단사니까 두 뿌리 봉투가 같았어야 해요.","봉투가 같다 = 가운데 줄 결과가 개수까지 같다. 1층도 단사니 그 아래 봉투도 같았어야 해요.","결국 나무 전체가 같았어야 해요. 그러니 나무가 다르면 결과도 달라요."]},{"kind":"figure","head":"단사 집계 대 1층 평균","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\"><text x=\"20\" y=\"22\" font-size=\"15\" text-anchor=\"start\" class=\"tb b1\">층마다 단사 집계<\/text><rect x=\"20\" y=\"32\" width=\"140\" height=\"88\" rx=\"8\" class=\"box b1\"/><rect x=\"185\" y=\"32\" width=\"140\" height=\"88\" rx=\"8\" class=\"box b1\"/><rect x=\"350\" y=\"32\" width=\"115\" height=\"88\" rx=\"8\" class=\"box2 b1\"/><text x=\"90\" y=\"56\" font-size=\"14\" text-anchor=\"middle\" class=\"t b1\">{1, 1} → a<\/text><text x=\"90\" y=\"80\" font-size=\"14\" text-anchor=\"middle\" class=\"t b1\">{1} → c<\/text><text x=\"90\" y=\"104\" font-size=\"14\" text-anchor=\"middle\" class=\"t b1\">{1, 1, 1} → b<\/text><text x=\"255\" y=\"66\" font-size=\"14\" text-anchor=\"middle\" class=\"t b1\">노드 1: {a, b}<\/text><text x=\"255\" y=\"94\" font-size=\"14\" text-anchor=\"middle\" class=\"t b1\">노드 4: {c, b}<\/text><text x=\"407\" y=\"82\" font-size=\"16\" text-anchor=\"middle\" class=\"tb b1\">다름<\/text><line x1=\"162\" y1=\"76\" x2=\"173\" y2=\"76\" class=\"e b1\"/><polygon points=\"182,76 173,81 173,71\" class=\"arrow b1\"/><line x1=\"327\" y1=\"76\" x2=\"338\" y2=\"76\" class=\"e b1\"/><polygon points=\"347,76 338,81 338,71\" class=\"arrow b1\"/><text x=\"20\" y=\"148\" font-size=\"15\" text-anchor=\"start\" class=\"tb b2\">1층에서 평균<\/text><rect x=\"20\" y=\"158\" width=\"140\" height=\"88\" rx=\"8\" class=\"box b2\"/><rect x=\"185\" y=\"158\" width=\"140\" height=\"88\" rx=\"8\" class=\"box b2\"/><rect x=\"350\" y=\"158\" width=\"115\" height=\"88\" rx=\"8\" class=\"box2 b2\"/><text x=\"90\" y=\"182\" font-size=\"14\" text-anchor=\"middle\" class=\"t b2\">{1, 1} → 1<\/text><text x=\"90\" y=\"206\" font-size=\"14\" text-anchor=\"middle\" class=\"t b2\">{1} → 1<\/text><text x=\"90\" y=\"230\" font-size=\"14\" text-anchor=\"middle\" class=\"t b2\">{1, 1, 1} → 1<\/text><text x=\"255\" y=\"192\" font-size=\"14\" text-anchor=\"middle\" class=\"t b2\">노드 1: {1, 1}<\/text><text x=\"255\" y=\"220\" font-size=\"14\" text-anchor=\"middle\" class=\"t b2\">노드 4: {1, 1}<\/text><text x=\"407\" y=\"208\" font-size=\"16\" text-anchor=\"middle\" class=\"tb b2\">같아짐<\/text><line x1=\"162\" y1=\"202\" x2=\"173\" y2=\"202\" class=\"e b2\"/><polygon points=\"182,202 173,207 173,197\" class=\"arrow b2\"/><line x1=\"327\" y1=\"202\" x2=\"338\" y2=\"202\" class=\"e b2\"/><polygon points=\"347,202 338,207 338,197\" class=\"arrow b2\"/><\/svg>","caption":"평균이 1층에서 {1, 1} 과 {1} 을 같은 1 로 뭉개면, 2층이 아무리 좋아도 되살리지 못해요.","builds":2},{"kind":"steps","head":"경우 C: 1층은 합, 2층은 평균","steps":["1층 결과: 노드 1 쪽 {2, 3}, 노드 4 쪽 {1, 3}.","2층 평균: (2 + 3)/2 = 2.5, (1 + 3)/2 = 2. 이 예에서는 달라요.","하지만 평균은 {2, 3} 과 {2, 3, 2, 3} 을 똑같이 2.5 로 만들어요.","그래서 일반적인 보장은 '모든 층이 단사' 일 때만 있어요."],"answer":"조건은 마지막 층만이 아니라 모든 층이에요."},{"kind":"prof","when":"3주차 화요일 수업","lines":["그래야 하는데 못 하는 이유는 레이어에 있대요.","집계하고 업데이트하는 과정이 단사 함수를 구현할 만큼 표현력이 없어서예요."]},{"kind":"mining","src":"마이닝 9강 WL 테스트","lines":["이웃 라벨 멀티셋을 해시로 새 라벨로 압축했어요.","서로 다른 멀티셋에 같은 라벨을 붙이면 그 순간부터 두 구조를 영영 같게 취급해요."]}],"pass3":[{"kind":"english","head":"답안에 'every layer' 넣기","en":"If the aggregation at every layer is injective, different rooted subtrees are always mapped to different embeddings, because no neighborhood information is lost at any step.","ko":"모든 층의 집계가 단사면 어느 단계에서도 이웃 정보를 잃지 않으니, 서로 다른 나무는 항상 다른 임베딩으로 가요.","tip":"2024 가을 기말 5번 (b) 해설: sum operator + injective MLP → as powerful as 1-WL."},{"kind":"warn","head":"주의","items":["조건은 '모든 층이 단사' 예요. 그래서 초록 상자가 두 개예요.","단사 집계를 써도 나무가 같은 노드 1, 2 는 여전히 같은 임베딩이에요. 나무 자체의 한계는 못 넘어요."]}],"pass4":[{"kind":"code","head":"라운드마다 새 표로 단사 해시 반복 (1/3)","file":"Sample_Code_3_번역.ipynb 셀 19 (원본 셀 14) (1/3)","code":"def aggregate(G, colors):\n    \"\"\"Step 2: aggregated color of every node = (own color, sorted tuple of neighbor colors).\"\"\"\n    return {v: (colors[v], tuple(sorted(colors[u] for u in G[v]))) for v in G}\n\n\ndef wl_refine(graphs, num_iterations=3):\n    \"\"\"\n    Color refinement run jointly on a list of graphs with one shared HASH table.\n\n    Returns `rounds`, where rounds[l] is a dict:\n        'colors' : [{node: color} per graph]             colors after round l\n        'agg'    : [{node: aggregated color} per graph]  what was hashed in round l\n        'table'  : {aggregated color: new color}         the HASH table of round l\n    rounds[0] is the initial coloring: every node gets color 1.\n    \"\"\"\n    rounds = [{'colors': [{v: 1 for v in G} for G in graphs], 'agg': None, 'table': {}}]\n    next_color = 2\n    for _ in range(num_iterations):\n        agg = [aggregate(G, c) for G, c in zip(graphs, rounds[-1]['colors'])]\n        # Step 3: 단사 해시. 처음 보는 집계된 색마다 아직 안 쓴 다음 번호를 준다.\n        # (매 라운드의 입력은 새 색들이므로 라운드마다 자기 표 하나만 있으면 된다.)\n        table = {}\n        for a in agg:\n            for sig in a.values():\n                if sig not in table:\n                    table[sig] = next_color\n                    next_color += 1\n        colors = [{v: table[sig] for v, sig in a.items()} for a in agg]\n        rounds.append({'colors': colors, 'agg': agg, 'table': table})\n    return rounds\n","lines":[{"from":1,"to":4,"say":"aggregate 함수: 노드마다 (내 색, 이웃 색을 정렬해 묶은 튜플)을 만들어 사전으로 돌려줘요."},{"from":5,"to":15,"say":"wl_refine 함수의 이름과 설명이에요. 여러 그래프가 HASH 표를 같이 쓰며 색 정제를 하고 rounds 목록을 돌려준대요."},{"from":16,"to":17,"say":"처음엔 모든 노드 색 1 (특징이 모두 같음). 다음에 줄 번호는 2 부터예요."},{"from":18,"to":19,"say":"라운드(층)마다 반복. `rounds[-1]` 은 바로 앞 라운드 결과이고, 그 색으로 이웃 묶음을 모아요."},{"from":20,"to":27,"say":"p.23 에서 본 단사 HASH 표. 매 라운드 새로 만들어요."},{"from":28,"to":29,"say":"새 색을 칠해 rounds 리스트 끝에 `.append` 로 붙여요. 이번 결과가 다음 라운드의 입력이에요."},{"from":30,"to":30,"say":"모든 라운드 기록을 돌려줘요."}],"link":"라운드마다 단사 해시 = p.26 의 '매 단계가 정보를 온전히 보존' 조건을 그대로 코드로 지킨 거예요."},{"kind":"code","head":"라운드마다 새 표로 단사 해시 반복 (2/3)","file":"Sample_Code_3_번역.ipynb 셀 19 (원본 셀 14) (2/3)","code":"\ndef color_histogram(colors):\n    \"\"\"How many nodes carry each color: the graph-level fingerprint.\"\"\"\n    return dict(sorted(Counter(colors.values()).items()))\n\n\ndef wl_report(rounds, names):\n    \"\"\"The WL test: compare the two graphs' color histograms round by round.\"\"\"\n    differ = False\n    for l, r in enumerate(rounds):\n        h1, h2 = (color_histogram(c) for c in r['colors'])\n        differ = differ or h1 != h2\n        print(f\"round {l}:  {names[0]} {str(h1):<34s} {'==' if h1 == h2 else '!='}  {names[1]} {h2}\")\n    print('\\n→ NON-ISOMORPHIC (the histograms differ)' if differ else\n          '\\n→ INCONCLUSIVE (the histograms are always equal)')\n\n\n# ---- 그리기 -------------------------------------------------------------------------\ndef fmt_agg(sig):\n    \"\"\"(3, (3, 4)) -> '3,{3,4}'\"\"\"\n    own, nbrs = sig\n    return f\"{own},{{{','.join(map(str, nbrs))}}}\"\n\n\ndef draw_aggregated(G, pos, ax, colors, agg, title=None):\n    \"\"\"Each node is a box showing its aggregated color, filled with its current color.\"\"\"\n    nx.draw_networkx_edges(G, pos, ax=ax, edge_color=C_EDGE, width=2.0)\n    for v in G:\n        f = color_of(colors[v])\n        ax.text(*pos[v], fmt_agg(agg[v]), ha='center', va='center', fontsize=10, color=ink(f),\n                bbox=dict(boxstyle='round,pad=0.35', fc=f, ec=C_DARK, lw=1.2))\n    xs, ys = zip(*pos.values())\n    ax.set_xlim(min(xs) - 0.5, max(xs) + 0.5)\n    ax.set_ylim(min(ys) - 0.4, max(ys) + 0.4)\n    if title:\n        ax.set_title(title)\n    ax.set_axis_off()\n","lines":[{"from":1,"to":5,"say":"color_histogram 함수: Counter 로 색마다 노드가 몇 개인지 세서 번호 순으로 정리해요."},{"from":6,"to":16,"say":"wl_report 함수: 라운드마다 두 그래프의 색 개수표를 비교해 == 또는 != 를 출력하고, 마지막에 판정을 알려 줘요."},{"from":17,"to":23,"say":"그리기 부분 시작이에요. fmt_agg 는 (3, (3, 4)) 같은 집계 색을 '3,{3,4}' 글자로 바꿔요."},{"from":24,"to":38,"say":"draw_aggregated 함수: 노드마다 집계 색 글자를 지금 색으로 칠한 상자에 적어 그려요."}]},{"kind":"code","head":"라운드마다 새 표로 단사 해시 반복 (3/3)","file":"Sample_Code_3_번역.ipynb 셀 19 (원본 셀 14) (3/3)","code":"\ndef draw_hash_table(ax, table, title):\n    tab = ax.table(cellText=[[fmt_agg(sig), c] for sig, c in table.items()],\n                   colLabels=['aggregated color', 'new color'], loc='center', cellLoc='center')\n    tab.auto_set_font_size(False); tab.set_fontsize(11); tab.scale(1, 1.7)\n    for j in range(2):                                   # 머리글 행\n        tab[0, j].set_facecolor(C_DARK)\n        tab[0, j].get_text().set(color='white', fontweight='bold')\n    for i, c in enumerate(table.values(), start=1):      # 새 색마다 칸을 그 색으로 칠한다\n        tab[i, 1].set_facecolor(color_of(c))\n        tab[i, 1].get_text().set(color=ink(color_of(c)), fontweight='bold')\n    ax.set_title(title)\n    ax.set_axis_off()\n\n\ndef show_initial(graphs, names, positions, rounds):\n    fig, axes = plt.subplots(1, len(graphs), figsize=(11, 3))\n    for ax, G, name, pos, c in zip(axes, graphs, names, positions, rounds[0]['colors']):\n        draw_graph(G, pos, ax, colors=c, labels='color', title=name)\n    fig.suptitle('Step 1 - Assign initial colors: every node gets color 1',\n                 fontsize=13, fontweight='bold')\n    plt.tight_layout(); plt.show()\n\n\ndef show_round(graphs, names, positions, rounds, l):\n    \"\"\"One round, left to right: aggregated colors -> HASH table -> new colors.\"\"\"\n    r, prev = rounds[l], rounds[l - 1]['colors']\n    fig = plt.figure(figsize=(15, 5.6))\n    gs = fig.add_gridspec(2, 3, width_ratios=[1, 0.75, 1])\n    for i, (G, name, pos) in enumerate(zip(graphs, names, positions)):\n        draw_aggregated(G, pos, fig.add_subplot(gs[i, 0]), prev[i], r['agg'][i],\n                        title=f'{name}: aggregated colors')\n        draw_graph(G, pos, fig.add_subplot(gs[i, 2]), colors=r['colors'][i], labels='color',\n                   title=f'{name}: new colors')\n    draw_hash_table(fig.add_subplot(gs[:, 1]), r['table'], title=f'HASH table (round {l})')\n    fig.suptitle(f'Round {l}:   Step 2 - aggregate neighboring colors   →   '\n                 f'Step 3 - injectively hash   →   new colors', fontsize=13, fontweight='bold')\n    plt.tight_layout(); plt.show()","lines":[{"from":1,"to":14,"say":"draw_hash_table 함수: HASH 표를 '집계 색, 새 색' 두 열짜리 표 그림으로 그리고 새 색 칸을 그 색으로 칠해요."},{"from":15,"to":23,"say":"show_initial 함수: 모든 노드가 색 1 인 시작 그림을 그래프마다 그려요."},{"from":24,"to":38,"say":"show_round 함수: 한 라운드를 왼쪽 집계 색, 가운데 HASH 표, 오른쪽 새 색 순서로 한 장에 그려요."}]}]},{"p":27,"title":"단사 이웃 집계","terms":["Neighbor aggregation","Injective","Expressive power"],"pass1":[{"kind":"say","lines":["앞 쪽의 조건에 이름을 붙여요.","이웃 정보를 봉투 하나에 모아 요약하는 단계를 **이웃 집계(Neighbor aggregation)** 라고 하죠.","봉투 속 구성이 다르면 요약도 반드시 달라지는 집계, 이걸 '**단사(Injective)** 이웃 집계' 라고 불러요.","구별을 가장 잘하는 GNN, 곧 **표현력(Expressive power)** 이 가장 큰 GNN 은 모든 층에서 이걸 써요."]},{"kind":"look","head":"주황 상자 두 개","boxes":[{"x":0.06,"y":0.43,"w":0.68,"h":0.08,"say":"위 주황 상자는 뿌리 쪽에서 모으는 자리예요. 여기에 단사 이웃 집계를 써요."},{"x":0.15,"y":0.59,"w":0.71,"h":0.08,"say":"아래 주황 상자는 그 아래 줄에서 모으는 자리예요. 여기도 마찬가지로 단사 이웃 집계를 써요."}]}],"pass2":[{"kind":"look","head":"이름표만 바뀐 그림","boxes":[{"x":0.03,"y":0.14,"w":0.62,"h":0.06,"say":"즉(In other words): 앞 슬라이드를 다른 말로. 매 단계에서 단사 이웃 집계 함수를 써요."},{"x":0.07,"y":0.26,"w":0.47,"h":0.06,"say":"서로 다른 이웃 묶음을 서로 다른 임베딩으로 보내요."},{"x":0.06,"y":0.43,"w":0.68,"h":0.08,"say":"위 주황 상자: 2층(뿌리) 집계 자리. 단사 이웃 집계여야 해요."},{"x":0.15,"y":0.59,"w":0.71,"h":0.08,"say":"아래 주황 상자: 1층 집계 자리. p.26 의 초록 상자가 이름만 바뀌었어요."}]},{"kind":"points","head":"왜 새 이름을 붙이나","items":["**이웃 집계(Neighbor aggregation)**: 이웃 쪽지를 한 봉투에 모아 요약하는 단계.","단사 이웃 집계: 봉투 구성이 다르면 요약도 반드시 다른 집계.","이제 '이 모델의 집계는 단사인가?' 한 줄로 물을 수 있어요.","확인법은 p.23 그대로: 결과가 같은 서로 다른 봉투를 하나라도 찾으면 단사가 아니에요."]},{"kind":"compare","head":"노드 1 과 노드 4 에 세 집계 넣기 (특징 1)","cols":["집계","1층 결과","노드 1 뿌리","노드 4 뿌리","구별?"],"rows":[["합","2, 3 / 1, 3","5","4","된다"],["평균","1, 1 / 1, 1","1","1","안 된다"],["최대","1, 1 / 1, 1","1","1","안 된다"]]},{"kind":"compare","head":"벡터로 한 번 더: 이웃 특징이 모두 두 칸짜리 벡터 (1, 2)","cols":["봉투","합","평균"],"rows":[["(1, 2) 1개","(1, 2)","(1, 2)"],["(1, 2) 2개","(2, 4)","(1, 2)"],["(1, 2) 3개","(3, 6)","(1, 2)"]]},{"kind":"prof","when":"3주차 화요일 수업","lines":["결국 문제는 다른 구조에 다른 이름을 붙일 만큼 표현력이 있느냐래요.","**단사(Injective)** 이웃 집계가 그걸 보장하는 장치예요."]}],"pass3":[{"kind":"exam","src":"2024 가을 기말 5번 (GIN, 10점)","q":"GIN with a fixed scalar $\\epsilon = 0.5$: $h_i^{(k)} = (1+\\epsilon) h_i^{(k-1)} + \\sum_{j \\in N(i)} h_j^{(k-1)}$. (a) Calculate the feature of each node at $k = 1$. (b) Why does GIN achieve the 1-d Weisfeiler-Lehman test?","qko":"GIN 식으로 각 노드의 $k = 1$ 특징을 계산하고, GIN 이 1차원 WL 만큼 강한 이유를 서술하세요.","solve":["해설 풀이에서 읽은 값: A 0.2, B 0.3, C 0.2, D 0.1. 이웃은 A: B, C, D / B: A, C / C: A, B, D / D: A, C.","순서: 내 값 × 1.5, 이웃 값 전부 더하기, 둘을 더하기.","A: $1.5 \\times 0.2 + (0.3 + 0.2 + 0.1) = 0.3 + 0.6 = 0.9$","B: $1.5 \\times 0.3 + (0.2 + 0.2) = 0.85$, C: $1.5 \\times 0.2 + (0.2 + 0.3 + 0.1) = 0.9$","D: $1.5 \\times 0.1 + (0.2 + 0.2) = 0.55$","(b) 합 집계는 평균, 최대와 달리 단사라서 서로 다른 이웃 멀티셋을 다르게 요약해요."],"answer":"(a) A 0.9, B 0.85, C 0.9, D 0.55. (b) GIN uses sum aggregation; unlike mean or max-pooling, sum is injective (distinct inputs produce distinct outputs), and sum with an injective MLP makes GIN as powerful as the 1-WL test."},{"kind":"warn","head":"이 기출에서 배울 점","items":["A 와 C 가 0.9 로 같아요. 둘 다 자기 값 0.2, 이웃 봉투 {0.3, 0.2, 0.1} 이 같아서예요. 단사를 어긴 게 아니에요.","숫자 하나짜리 합이 모든 봉투에서 단사인 건 아니에요 ({1, 3} 과 {2, 2}). 그래서 합 뒤에 MLP 를 붙여요."]},{"kind":"check","q":"다음 중 '단사 이웃 집계' 에 가장 가까운 것은? (특징 1 인 봉투 {1, 1} 과 {1} 기준)","choices":["평균: 1 과 1","최대: 1 과 1","합: 2 와 1"],"a":2,"why":"서로 다른 봉투를 다른 결과로 바꾼 건 합뿐이에요. 평균과 최대는 이웃 수 정보를 잃어요."}],"pass4":[{"kind":"code","head":"2주차 노트북의 세 가지 집계","file":"PracticeCode_2_번역.ipynb 셀 49","code":"def generate_messages(neighbor_features):\n    '''In the basic model the message is the neighbor representation itself.'''\n    return neighbor_features\n\n\ndef aggregate(messages, method=\"mean\"):\n    if method == \"sum\":\n        return messages.sum(dim=0)\n    if method == \"mean\":\n        return messages.mean(dim=0)\n    if method == \"max\":\n        return messages.max(dim=0).values\n    raise ValueError(f\"Unknown aggregation method: {method}\")\n\n\ndef update(self_features, aggregated, W_self, W_neigh):\n    '''Combine the node state with the aggregated neighborhood, then apply ReLU.'''\n    return torch.relu(self_features @ W_self + aggregated @ W_neigh)\n\n\nneighbor_ids = list(G.neighbors(0))\nneighbor_x = data.x[neighbor_ids]\nmessages = generate_messages(neighbor_x)\n\nprint(\"Target node: 0\")\nprint(\"Neighbors of node 0:\", neighbor_ids)\nfor method in [\"sum\", \"mean\", \"max\"]:\n    agg = aggregate(messages, method=method)\n    print(f\"{method:4s} aggregation:\", [round(v, 4) for v in agg[:8].tolist()])\n\nfeat_dim = data.x.size(1)\ntorch.manual_seed(0)\nW_self = torch.randn(feat_dim, 8) * 0.1\nW_neigh = torch.randn(feat_dim, 8) * 0.1\nh0 = update(data.x[0], aggregate(messages, \"mean\"), W_self, W_neigh)\nprint(\"Updated representation of node 0:\", [round(v, 4) for v in h0.tolist()])","lines":[{"from":1,"to":4,"say":"generate_messages: 기본 모델에서는 이웃 특징 그대로가 메시지라서, 받은 것을 그대로 돌려줘요."},{"from":6,"to":6,"say":"messages 는 이웃 특징을 행으로 쌓은 텐서(이웃 수 × 칸 수)예요. method 의 기본값은 \"mean\"."},{"from":7,"to":8,"say":"합: `.sum(dim=0)` 은 0번 방향(행 방향, 이웃 방향)으로 더해요. 칸마다 더한다는 뜻이에요."},{"from":9,"to":10,"say":"평균: `.mean(dim=0)` 은 칸마다 이웃 수로 나눈 평균."},{"from":11,"to":12,"say":"최대: `.max(dim=0)` 은 (최댓값, 위치) 두 가지를 주므로 `.values` 로 값만 꺼내요."},{"from":13,"to":13,"say":"셋 다 아니면 `raise` 로 오류를 내요."},{"from":15,"to":19,"say":"update: 내 특징과 모은 이웃 정보에 각자 가중치 행렬을 곱해(@) 더하고 ReLU 를 씌워요."},{"from":20,"to":23,"say":"노드 0 의 이웃 번호를 리스트로 받고, 그 이웃들의 특징 줄을 뽑아 메시지로 써요."},{"from":24,"to":29,"say":"세 가지 방법으로 모은 결과의 앞 8칸을 소수 넷째 자리까지 출력해요."},{"from":30,"to":36,"say":"특징 칸 수를 재고, 난수 시드를 고정해 작은 가중치 두 개를 만든 뒤, 평균으로 모은 노드 0 의 새 표현을 출력해요."}],"link":"합, 평균, 최대 중 봉투 {1, 1} 과 {1} 을 가르는 건 sum 뿐이에요 (p.27 표)."},{"kind":"pyterm","name":"텐서의 dim=0","say":["텐서는 파이토치의 숫자 표(행렬)예요. `torch.tensor([[...], [...]])` 로 만들어요.","`dim=0` 은 '행들을 위아래로 합쳐 칸마다 하나씩' 계산하라는 뜻이에요."],"example":"import torch\nx = torch.tensor([[1., 2.], [1., 2.]])\nprint(x.sum(dim=0), x.mean(dim=0))","out":"tensor([2., 4.]) tensor([1., 2.])"}]},{"p":28,"title":"핵심 관찰: 표현력은 집계가 정해요","terms":["Expressive power","Neighbor aggregation","Injective","Aggregation"],"pass1":[{"kind":"say","lines":["지금까지 알아낸 걸 한 문장으로 정리해요.","GNN 전체가 얼마나 잘 구별하는지, 즉 **표현력(Expressive power)** 은 **이웃 집계(Neighbor aggregation)** 방법이 정해요.","모으는 방법이 좋을수록 GNN 도 좋아지고, 정보를 하나도 잃지 않는 단사 집계면 가장 좋아요.","그래서 앞으로는 모으는 방법 하나만 자세히 뜯어보면 돼요."]},{"kind":"analogy","head":"좁은 병 입구","scene":"큰 물통의 물을 작은 병에 옮겨 담아요. 물통이 아무리 커도, 병 입구가 좁으면 병에 들어가는 물의 양은 입구가 정해요. 입구에서 흘러넘친 물은 병 안에서 되찾을 수 없어요. GNN 에서 이 좁은 입구가 바로 이웃 정보를 모으는 단계예요.","map":[["병 입구","**이웃 집계(Neighbor aggregation)**"],["흘러넘친 물","모으면서 잃어버린 정보"],["병 안","모은 뒤에 이어지는 계산"]]}],"pass2":[{"kind":"look","head":"글자만 있는 슬라이드","boxes":[{"x":0.03,"y":0.14,"w":0.74,"h":0.06,"say":"핵심 관찰: GNN 의 표현력은 그 GNN 이 쓰는 이웃 집계 함수의 표현력으로 결정돼요."},{"x":0.07,"y":0.26,"w":0.5,"h":0.06,"say":"집계 함수의 표현력이 클수록 GNN 의 표현력도 커져요."},{"x":0.07,"y":0.32,"w":0.48,"h":0.06,"say":"초록 글씨: 단사 집계 함수를 쓰면 가장 표현력 있는 GNN 이 돼요."},{"x":0.03,"y":0.39,"w":0.44,"h":0.12,"say":"다음: 집계 함수의 표현력을 이론적으로 분석해요. p.30 부터 평균, 최대를 따져요."}]},{"kind":"formula","head":"왜 집계가 병목일까","tex":"h_v^{(k)} = \\sigma\\left( W^{(k)} \\cdot \\underbrace{\\text{AGG}\\left( \\{\\!\\{ h_u^{(k-1)} : u \\in N(v) \\}\\!\\} \\right)}_{m_v^{(k)}} \\right)","parts":[{"sym":"\\{\\!\\{ h_u^{(k-1)} \\}\\!\\}","say":"이웃이 보낸 원본 쪽지 봉투"},{"sym":"\\text{AGG}","say":"**집계(Aggregation)**: 봉투를 요약본 하나로"},{"sym":"m_v^{(k)}","say":"요약본. 뒤 단계는 이것만 받아요"},{"sym":"W^{(k)}","say":"요약본을 읽는 가중치 (학습됨)"},{"sym":"\\sigma","say":"활성화 함수"}],"whole":"봉투 → AGG → 요약본 → W → σ. W 와 σ 는 원본 봉투를 절대 못 봐요."},{"kind":"compare","head":"봉투 A = {2, 2}, B = {2}, W = 3, ReLU","cols":["집계","A 의 m","B 의 m","ReLU(W m)","구별?"],"rows":[["평균","2","2","6 / 6","안 된다"],["합","4","2","12 / 6","된다"],["최대","2","2","6 / 6","안 된다"]]},{"kind":"steps","head":"W 를 바꿔도 소용없을까?","steps":["평균 쪽: W = -5 면 둘 다 ReLU(-10) = 0.","평균 쪽: W = 100 이면 둘 다 200.","W 를 무엇으로 학습하든 평균 쪽 두 봉투는 영원히 같은 값이에요.","합 쪽도 W = 0 이면 둘 다 0 이지만, 그건 학습으로 고칠 수 있어요."],"answer":"평균이 버린 정보는 학습으로도 못 되찾아요. 이게 '병목은 집계' 라는 뜻이에요."},{"kind":"prof","when":"3주차 화요일 수업","lines":["모델마다 집계와 업데이트 방법이 달라서 표현력이 달라진다고 했어요.","그래서 어떤 집계 함수를 쓰느냐가 핵심이에요."]}],"pass3":[{"kind":"english","head":"서술형 뼈대 문장","en":"The expressive power of a GNN is characterized by its neighbor aggregation function; an injective aggregation function leads to the most expressive GNN.","ko":"GNN 의 표현력은 이웃 집계 함수가 정하고, 단사 집계 함수를 쓰면 가장 표현력 있는 GNN 이 돼요.","tip":"뒤에 'The update step only sees the aggregated result' 를 붙이면 이유까지 완성이에요."},{"kind":"check","q":"평균 집계를 쓴 GNN 에서 {2, 2} 와 {2} 를 구별하려면?","choices":["W 를 더 크게","층을 더 쌓기","집계 함수를 합 같은 단사 집계로 바꾸기","학습을 더 오래"],"a":2,"why":"AGG 에서 이미 같은 요약본이 되면 뒤의 W, 층, 학습으로는 되살릴 수 없어요."},{"kind":"warn","head":"주의","items":["'층을 더 쌓거나 W 를 키우면 해결된다' 는 틀린 생각이에요.","'가장 표현력 있는' 은 메시지 패싱 GNN 틀 안에서의 최고라는 뜻이에요. 틀 자체의 한계는 1-WL 부분에서 나와요."]}],"pass4":[{"kind":"code","head":"업데이트는 요약본만 받아요","file":"PracticeCode_2_번역.ipynb 셀 49","code":"def generate_messages(neighbor_features):\n    '''In the basic model the message is the neighbor representation itself.'''\n    return neighbor_features\n\n\ndef aggregate(messages, method=\"mean\"):\n    if method == \"sum\":\n        return messages.sum(dim=0)\n    if method == \"mean\":\n        return messages.mean(dim=0)\n    if method == \"max\":\n        return messages.max(dim=0).values\n    raise ValueError(f\"Unknown aggregation method: {method}\")\n\n\ndef update(self_features, aggregated, W_self, W_neigh):\n    '''Combine the node state with the aggregated neighborhood, then apply ReLU.'''\n    return torch.relu(self_features @ W_self + aggregated @ W_neigh)\n\n\nneighbor_ids = list(G.neighbors(0))\nneighbor_x = data.x[neighbor_ids]\nmessages = generate_messages(neighbor_x)\n\nprint(\"Target node: 0\")\nprint(\"Neighbors of node 0:\", neighbor_ids)\nfor method in [\"sum\", \"mean\", \"max\"]:\n    agg = aggregate(messages, method=method)\n    print(f\"{method:4s} aggregation:\", [round(v, 4) for v in agg[:8].tolist()])\n\nfeat_dim = data.x.size(1)\ntorch.manual_seed(0)\nW_self = torch.randn(feat_dim, 8) * 0.1\nW_neigh = torch.randn(feat_dim, 8) * 0.1\nh0 = update(data.x[0], aggregate(messages, \"mean\"), W_self, W_neigh)\nprint(\"Updated representation of node 0:\", [round(v, 4) for v in h0.tolist()])","lines":[{"from":1,"to":4,"say":"generate_messages: 기본 모델에서는 이웃 특징 그대로가 메시지라서, 받은 것을 그대로 돌려줘요."},{"from":5,"to":14,"say":"aggregate: method 가 'sum' 이면 합, 'mean' 이면 평균, 'max' 면 최댓값으로 모아요. dim=0 은 이웃 방향으로 칸마다 계산하라는 뜻이에요."},{"from":16,"to":17,"say":"재료는 자기 특징, 집계 결과 aggregated, 가중치 두 개예요. 원본 이웃 봉투(messages)는 재료에 없어요."},{"from":18,"to":18,"say":"`@` 는 행렬 곱이에요. 자기 특징과 요약본에 각각 가중치를 곱해 더하고 `torch.relu` 로 음수를 0 으로."},{"from":20,"to":23,"say":"노드 0 의 이웃 번호를 리스트로 받고, 그 이웃들의 특징 줄을 뽑아 메시지로 써요."},{"from":24,"to":29,"say":"세 가지 방법으로 모은 결과의 앞 8칸을 소수 넷째 자리까지 출력해요."},{"from":30,"to":36,"say":"특징 칸 수를 재고, 난수 시드를 고정해 작은 가중치 두 개를 만든 뒤, 평균으로 모은 노드 0 의 새 표현을 출력해요."}],"link":"슬라이드 식의 $\\sigma(W \\cdot m_v)$ 와 짝이에요. W 와 σ 는 요약본 $m_v$ 만 봐요."},{"kind":"pyterm","name":"행렬 곱 @","say":["`A @ B` 는 행렬 곱이에요. 파이썬의 `*` 는 칸끼리 곱하기라서 달라요.","숫자 하나짜리로 보면 W = 3 을 요약본 2 에 곱한 것과 같아요."],"example":"import torch\nm = torch.tensor([2.])\nW = torch.tensor([[3.]])\nprint(torch.relu(m @ W))","out":"tensor([6.])"}]},{"p":29,"title":"이웃 집계 = 멀티셋 위의 함수","terms":["Multi-set","Neighbor aggregation","Permutation invariance","Injective"],"pass1":[{"kind":"say","lines":["**이웃 집계(Neighbor aggregation)** 에 들어가는 입력은 이웃들의 정보를 담은 봉투예요.","봉투에는 같은 쪽지가 여러 장 들어갈 수 있고, 넣은 순서는 따지지 않아요. 대신 몇 장인지는 세요.","이렇게 순서는 무시하고 개수는 세는 모음을 **멀티셋(Multi-set)** 이라고 해요."]},{"kind":"look","head":"봉투 그림","boxes":[{"x":0.615,"y":0.34,"w":0.15,"h":0.36,"say":"오른쪽 두 봉투의 예예요. 노랑 1개와 파랑 1개, 노랑 2개와 파랑 1개는 서로 다른 멀티셋이에요."},{"x":0.62,"y":0.695,"w":0.14,"h":0.06,"say":"같은 색은 같은 특징, 곧 똑같은 쪽지라는 뜻이에요."}]},{"kind":"analogy","head":"맛이 섞인 사탕 봉투","scene":"편의점에서 사탕 봉투를 샀어요. 봉투 안에는 딸기 맛 2개, 포도 맛 1개가 들어 있어요. 사탕을 어떤 순서로 넣었는지는 아무도 신경 쓰지 않지만, 딸기 맛이 2개인지 1개인지는 중요하죠. 멀티셋도 순서는 무시하고, 무엇이 몇 개인지는 기억하는 봉투예요.","map":[["사탕 봉투","**멀티셋(Multi-set)**"],["사탕 한 개","이웃 한 명의 특징"],["같은 맛 여러 개","특징이 같은 이웃 여러 명"]]}],"pass2":[{"kind":"look","head":"그림 세 부분","boxes":[{"x":0.03,"y":0.14,"w":0.74,"h":0.06,"say":"관찰: 이웃 집계는 멀티셋(원소 중복을 허용하는 집합) 위의 함수로 추상화할 수 있어요."},{"x":0.235,"y":0.36,"w":0.11,"h":0.33,"say":"Neighbor aggregation: 노랑 이웃 둘이 초록 막대로 올라가 위 노드 결과를 만들어요."},{"x":0.34,"y":0.39,"w":0.1,"h":0.14,"say":"Equivalent(같은 것): 왼쪽과 오른쪽은 같은 일을 다르게 그린 거예요."},{"x":0.46,"y":0.4,"w":0.145,"h":0.26,"say":"Multi-set function: 네모 속 노랑 둘이 봉투. 빨간 중괄호 = 통째로 함수에 넣어요."},{"x":0.615,"y":0.34,"w":0.15,"h":0.36,"say":"멀티셋의 예: 노랑 1 + 파랑 1, 노랑 2 + 파랑 1. 둘은 다른 멀티셋이에요."},{"x":0.62,"y":0.695,"w":0.14,"h":0.06,"say":"Same color indicates the same features: 같은 색 = 같은 특징 = 똑같은 쪽지."}]},{"kind":"formula","head":"멀티셋 적는 법","tex":"S = \\{\\!\\{ a, a, b \\}\\!\\}, \\qquad m_S(a) = 2, \\qquad m_S(b) = 1","parts":[{"sym":"\\{\\!\\{ \\cdots \\}\\!\\}","say":"이중 중괄호 = 멀티셋 표시 (집합은 한 겹)"},{"sym":"a, a, b","say":"봉투 속 원소. $a$ 가 두 번"},{"sym":"m_S(a)","say":"$S$ 안에 $a$ 가 몇 번 들었나 (중복도)"}],"whole":"{{a, a, b}} = {{b, a, a}} 이지만 {{a, a, b}} ≠ {{a, b}} 예요. 순서는 무시, 장수는 기억."},{"kind":"figure","head":"리스트, 멀티셋, 집합","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\"><text x=\"10\" y=\"45\" font-size=\"15\" text-anchor=\"start\" class=\"tb b1\">리스트<\/text><rect x=\"100\" y=\"20\" width=\"120\" height=\"40\" rx=\"8\" class=\"box b1\"/><circle cx=\"124\" cy=\"40\" r=\"16\" class=\"n2 b1\"/><circle cx=\"160\" cy=\"40\" r=\"16\" class=\"n2 b1\"/><circle cx=\"196\" cy=\"40\" r=\"16\" class=\"n3 b1\"/><rect x=\"280\" y=\"20\" width=\"120\" height=\"40\" rx=\"8\" class=\"box b1\"/><circle cx=\"304\" cy=\"40\" r=\"16\" class=\"n3 b1\"/><circle cx=\"340\" cy=\"40\" r=\"16\" class=\"n2 b1\"/><circle cx=\"376\" cy=\"40\" r=\"16\" class=\"n2 b1\"/><text x=\"250\" y=\"46\" font-size=\"20\" text-anchor=\"middle\" class=\"tb b1\">≠<\/text><text x=\"100\" y=\"82\" font-size=\"14\" text-anchor=\"start\" class=\"tm b1\">순서도, 개수도 봐요. 번호를 바꾸면 입력이 바뀌어요.<\/text><text x=\"10\" y=\"133\" font-size=\"15\" text-anchor=\"start\" class=\"tb b2\">멀티셋<\/text><rect x=\"100\" y=\"108\" width=\"120\" height=\"40\" rx=\"8\" class=\"box b2\"/><circle cx=\"124\" cy=\"128\" r=\"16\" class=\"n2 b2\"/><circle cx=\"160\" cy=\"128\" r=\"16\" class=\"n2 b2\"/><circle cx=\"196\" cy=\"128\" r=\"16\" class=\"n3 b2\"/><rect x=\"280\" y=\"108\" width=\"120\" height=\"40\" rx=\"8\" class=\"box b2\"/><circle cx=\"304\" cy=\"128\" r=\"16\" class=\"n3 b2\"/><circle cx=\"340\" cy=\"128\" r=\"16\" class=\"n2 b2\"/><circle cx=\"376\" cy=\"128\" r=\"16\" class=\"n2 b2\"/><text x=\"250\" y=\"134\" font-size=\"20\" text-anchor=\"middle\" class=\"tb b2\">=<\/text><text x=\"100\" y=\"170\" font-size=\"14\" text-anchor=\"start\" class=\"tm b2\">순서는 무시, 개수는 세요.<\/text><text x=\"10\" y=\"221\" font-size=\"15\" text-anchor=\"start\" class=\"tb b3\">집합<\/text><rect x=\"100\" y=\"196\" width=\"120\" height=\"40\" rx=\"8\" class=\"box b3\"/><circle cx=\"124\" cy=\"216\" r=\"16\" class=\"n2 b3\"/><circle cx=\"160\" cy=\"216\" r=\"16\" class=\"n2 b3\"/><circle cx=\"196\" cy=\"216\" r=\"16\" class=\"n3 b3\"/><rect x=\"280\" y=\"196\" width=\"84\" height=\"40\" rx=\"8\" class=\"box b3\"/><circle cx=\"304\" cy=\"216\" r=\"16\" class=\"n2 b3\"/><circle cx=\"340\" cy=\"216\" r=\"16\" class=\"n3 b3\"/><text x=\"250\" y=\"222\" font-size=\"20\" text-anchor=\"middle\" class=\"tb b3\">=<\/text><text x=\"100\" y=\"258\" font-size=\"14\" text-anchor=\"start\" class=\"tm b3\">개수까지 무시. 두 개였는지 사라져요.<\/text><\/svg>","caption":"그래서 이웃 묶음은 리스트도 집합도 아닌 **멀티셋(Multi-set)** 이어야 해요.","builds":3},{"kind":"compare","head":"색칠한 그래프로 확인 (노드 1, 2, 3 노랑 / 4, 5 파랑)","cols":["노드","이웃","멀티셋","집합"],"rows":[["1","2, 5","{{노랑, 파랑}}","{노랑, 파랑}"],["3","4","{{파랑}}","{파랑}"],["4","3, 5","{{노랑, 파랑}}","{노랑, 파랑}"],["5","1, 2, 4","{{노랑, 노랑, 파랑}}","{노랑, 파랑} (노드 1 과 같아짐)"]]},{"kind":"prof","when":"3주차 화요일 수업","lines":["집계 함수는 **멀티셋(Multi-set)** 위의 함수이고 선택지가 몇 가지 있대요.","GCN 은 평균, GraphSAGE 는 최대, 그리고 지난주 말한 대로 합이 더 낫대요."]},{"kind":"mining","src":"마이닝 9강 WL 동형 테스트","lines":["2단계: Compute multiset of the neighboring nodes' compressed labels.","{1, 1, 1} 과 {1, 1} 을 집합으로 바꾸면 둘 다 {1} 이 되어 이웃 수를 못 갈라요."]}],"pass3":[{"kind":"check","q":"**멀티셋(Multi-set)** 에 대한 설명으로 맞는 것은?","choices":["순서와 개수를 모두 무시한다","순서는 무시하고 개수는 센다","순서는 보고 개수는 무시한다","리스트와 같다"],"a":1,"why":"{{노랑, 노랑, 파랑}} 과 {{노랑, 파랑}} 은 다른 멀티셋이에요. 집합과 헷갈리지 마세요."},{"kind":"warn","head":"주의","items":["멀티셋을 '집합과 같은 것' 으로 외우면 틀려요. 개수를 세요.","'같은 색 = 같은 특징' 약속이 중요해요. 이름이 다른 두 이웃도 특징이 같으면 봉투 속 같은 쪽지 두 장이에요."]}],"pass4":[{"kind":"code","head":"노트북은 멀티셋을 정렬한 튜플로 표현해요 (1/3)","file":"Sample_Code_3_번역.ipynb 셀 19 (원본 셀 14) (1/3)","code":"def aggregate(G, colors):\n    \"\"\"Step 2: aggregated color of every node = (own color, sorted tuple of neighbor colors).\"\"\"\n    return {v: (colors[v], tuple(sorted(colors[u] for u in G[v]))) for v in G}\n\n\ndef wl_refine(graphs, num_iterations=3):\n    \"\"\"\n    Color refinement run jointly on a list of graphs with one shared HASH table.\n\n    Returns `rounds`, where rounds[l] is a dict:\n        'colors' : [{node: color} per graph]             colors after round l\n        'agg'    : [{node: aggregated color} per graph]  what was hashed in round l\n        'table'  : {aggregated color: new color}         the HASH table of round l\n    rounds[0] is the initial coloring: every node gets color 1.\n    \"\"\"\n    rounds = [{'colors': [{v: 1 for v in G} for G in graphs], 'agg': None, 'table': {}}]\n    next_color = 2\n    for _ in range(num_iterations):\n        agg = [aggregate(G, c) for G, c in zip(graphs, rounds[-1]['colors'])]\n        # Step 3: 단사 해시. 처음 보는 집계된 색마다 아직 안 쓴 다음 번호를 준다.\n        # (매 라운드의 입력은 새 색들이므로 라운드마다 자기 표 하나만 있으면 된다.)\n        table = {}\n        for a in agg:\n            for sig in a.values():\n                if sig not in table:\n                    table[sig] = next_color\n                    next_color += 1\n        colors = [{v: table[sig] for v, sig in a.items()} for a in agg]\n        rounds.append({'colors': colors, 'agg': agg, 'table': table})\n    return rounds\n","lines":[{"from":1,"to":2,"say":"그래프 G 와 노드별 색 colors 를 받아요. 설명문: 집계된 색 = (자기 색, 이웃 색을 정렬한 튜플)."},{"from":3,"to":3,"say":"`sorted(...)` 로 이웃 색을 정렬해 순서를 없애고, 튜플에 전부 넣어 개수는 남겨요. 그게 멀티셋이에요."},{"from":5,"to":15,"say":"wl_refine 함수의 이름과 설명이에요. 여러 그래프가 HASH 표를 같이 쓰며 색 정제를 하고 rounds 목록을 돌려준대요."},{"from":16,"to":17,"say":"0라운드: 모든 노드를 색 1 로 칠해 rounds 에 넣어요. 새 번호는 2 부터 줘요."},{"from":18,"to":19,"say":"라운드 수만큼 반복하며, 지난 라운드 색으로 모든 노드의 집계 색을 만들어요."},{"from":20,"to":27,"say":"주석 두 줄 뒤, 빈 사전 table 에 처음 보는 집계 색마다 다음 번호를 적어요. 같은 조합은 같은 번호예요."},{"from":28,"to":31,"say":"표에서 새 번호를 찾아 노드를 다시 칠하고, 이번 라운드 결과를 rounds 끝에 붙여요. 다 돌면 rounds 를 돌려줘요."}],"link":"정렬 = 순서 무시, 중복 그대로 = 개수 셈. 슬라이드의 멀티셋 정의와 딱 맞아요."},{"kind":"code","head":"노트북은 멀티셋을 정렬한 튜플로 표현해요 (2/3)","file":"Sample_Code_3_번역.ipynb 셀 19 (원본 셀 14) (2/3)","code":"\ndef color_histogram(colors):\n    \"\"\"How many nodes carry each color: the graph-level fingerprint.\"\"\"\n    return dict(sorted(Counter(colors.values()).items()))\n\n\ndef wl_report(rounds, names):\n    \"\"\"The WL test: compare the two graphs' color histograms round by round.\"\"\"\n    differ = False\n    for l, r in enumerate(rounds):\n        h1, h2 = (color_histogram(c) for c in r['colors'])\n        differ = differ or h1 != h2\n        print(f\"round {l}:  {names[0]} {str(h1):<34s} {'==' if h1 == h2 else '!='}  {names[1]} {h2}\")\n    print('\\n→ NON-ISOMORPHIC (the histograms differ)' if differ else\n          '\\n→ INCONCLUSIVE (the histograms are always equal)')\n\n\n# ---- 그리기 -------------------------------------------------------------------------\ndef fmt_agg(sig):\n    \"\"\"(3, (3, 4)) -> '3,{3,4}'\"\"\"\n    own, nbrs = sig\n    return f\"{own},{{{','.join(map(str, nbrs))}}}\"\n\n\ndef draw_aggregated(G, pos, ax, colors, agg, title=None):\n    \"\"\"Each node is a box showing its aggregated color, filled with its current color.\"\"\"\n    nx.draw_networkx_edges(G, pos, ax=ax, edge_color=C_EDGE, width=2.0)\n    for v in G:\n        f = color_of(colors[v])\n        ax.text(*pos[v], fmt_agg(agg[v]), ha='center', va='center', fontsize=10, color=ink(f),\n                bbox=dict(boxstyle='round,pad=0.35', fc=f, ec=C_DARK, lw=1.2))\n    xs, ys = zip(*pos.values())\n    ax.set_xlim(min(xs) - 0.5, max(xs) + 0.5)\n    ax.set_ylim(min(ys) - 0.4, max(ys) + 0.4)\n    if title:\n        ax.set_title(title)\n    ax.set_axis_off()\n","lines":[{"from":1,"to":5,"say":"color_histogram 함수: Counter 로 색마다 노드가 몇 개인지 세서 번호 순으로 정리해요."},{"from":6,"to":16,"say":"wl_report 함수: 라운드마다 두 그래프의 색 개수표를 비교해 == 또는 != 를 출력하고, 마지막에 판정을 알려 줘요."},{"from":17,"to":23,"say":"그리기 부분 시작이에요. fmt_agg 는 (3, (3, 4)) 같은 집계 색을 '3,{3,4}' 글자로 바꿔요."},{"from":24,"to":38,"say":"draw_aggregated 함수: 노드마다 집계 색 글자를 지금 색으로 칠한 상자에 적어 그려요."}]},{"kind":"code","head":"노트북은 멀티셋을 정렬한 튜플로 표현해요 (3/3)","file":"Sample_Code_3_번역.ipynb 셀 19 (원본 셀 14) (3/3)","code":"\ndef draw_hash_table(ax, table, title):\n    tab = ax.table(cellText=[[fmt_agg(sig), c] for sig, c in table.items()],\n                   colLabels=['aggregated color', 'new color'], loc='center', cellLoc='center')\n    tab.auto_set_font_size(False); tab.set_fontsize(11); tab.scale(1, 1.7)\n    for j in range(2):                                   # 머리글 행\n        tab[0, j].set_facecolor(C_DARK)\n        tab[0, j].get_text().set(color='white', fontweight='bold')\n    for i, c in enumerate(table.values(), start=1):      # 새 색마다 칸을 그 색으로 칠한다\n        tab[i, 1].set_facecolor(color_of(c))\n        tab[i, 1].get_text().set(color=ink(color_of(c)), fontweight='bold')\n    ax.set_title(title)\n    ax.set_axis_off()\n\n\ndef show_initial(graphs, names, positions, rounds):\n    fig, axes = plt.subplots(1, len(graphs), figsize=(11, 3))\n    for ax, G, name, pos, c in zip(axes, graphs, names, positions, rounds[0]['colors']):\n        draw_graph(G, pos, ax, colors=c, labels='color', title=name)\n    fig.suptitle('Step 1 - Assign initial colors: every node gets color 1',\n                 fontsize=13, fontweight='bold')\n    plt.tight_layout(); plt.show()\n\n\ndef show_round(graphs, names, positions, rounds, l):\n    \"\"\"One round, left to right: aggregated colors -> HASH table -> new colors.\"\"\"\n    r, prev = rounds[l], rounds[l - 1]['colors']\n    fig = plt.figure(figsize=(15, 5.6))\n    gs = fig.add_gridspec(2, 3, width_ratios=[1, 0.75, 1])\n    for i, (G, name, pos) in enumerate(zip(graphs, names, positions)):\n        draw_aggregated(G, pos, fig.add_subplot(gs[i, 0]), prev[i], r['agg'][i],\n                        title=f'{name}: aggregated colors')\n        draw_graph(G, pos, fig.add_subplot(gs[i, 2]), colors=r['colors'][i], labels='color',\n                   title=f'{name}: new colors')\n    draw_hash_table(fig.add_subplot(gs[:, 1]), r['table'], title=f'HASH table (round {l})')\n    fig.suptitle(f'Round {l}:   Step 2 - aggregate neighboring colors   →   '\n                 f'Step 3 - injectively hash   →   new colors', fontsize=13, fontweight='bold')\n    plt.tight_layout(); plt.show()","lines":[{"from":1,"to":14,"say":"draw_hash_table 함수: HASH 표를 '집계 색, 새 색' 두 열짜리 표 그림으로 그리고 새 색 칸을 그 색으로 칠해요."},{"from":15,"to":23,"say":"show_initial 함수: 모든 노드가 색 1 인 시작 그림을 그래프마다 그려요."},{"from":24,"to":38,"say":"show_round 함수: 한 라운드를 왼쪽 집계 색, 가운데 HASH 표, 오른쪽 새 색 순서로 한 장에 그려요."}]},{"kind":"pyterm","name":"Counter (예시 코드)","say":["노트북 셀 6 에서 불러오는 `Counter` 는 값마다 몇 번 나왔는지 세어 줘요.","멀티셋의 중복도 $m_S$ 를 그대로 보여 주는 도구예요."],"example":"from collections import Counter\nprint(Counter(['노랑', '노랑', '파랑']))","out":"Counter({'노랑': 2, '파랑': 1})"}]},{"p":30,"title":"이웃 집계: GCN 은 평균, GraphSAGE 는 최대","terms":["GCN","GraphSAGE","Mean-pool","Max-pool","Element-wise"],"pass1":[{"kind":"say","lines":["이제 실제 모델 두 개를 시험대에 올려요.","**GCN** 은 이웃 특징 봉투를 평균으로 요약해요. 이걸 **평균 풀링(Mean-pool)** 이라고 해요.","**GraphSAGE** 는 가장 큰 값만 뽑아 요약해요. 이걸 **최대 풀링(Max-pool)** 이라고 해요.","같은 봉투를 받아도 요약하는 방법이 달라서 남는 정보가 달라져요."]},{"kind":"analogy","head":"반 점수를 한 줄로 알리기","scene":"우리 반 시험 점수를 부모님께 한 줄로 알려야 해요. 한 친구는 '반 평균 80점' 이라고 적고, 다른 친구는 '1등 점수 100점' 이라고 적어요. 같은 점수표를 보고 적었는데도 한 줄 요약에 남는 정보가 서로 달라요. GCN 과 GraphSAGE 도 같은 이웃 봉투를 서로 다르게 요약해요.","map":[["반 점수표","이웃 특징 봉투"],["반 평균","**평균 풀링(Mean-pool)**, GCN 의 방법"],["1등 점수","**최대 풀링(Max-pool)**, GraphSAGE 의 방법"]]}],"pass2":[{"kind":"look","head":"두 모델, 두 식","boxes":[{"x":0.03,"y":0.16,"w":0.44,"h":0.06,"say":"GCN (평균 풀링) [Kipf & Welling, ICLR 2017]. 대괄호는 논문 출처예요."},{"x":0.07,"y":0.25,"w":0.5,"h":0.14,"say":"이웃 노드 특징에 원소별 평균 풀링. 식 Mean({x_u}, u ∈ N(v))."},{"x":0.03,"y":0.41,"w":0.53,"h":0.06,"say":"GraphSAGE (최대 풀링) [Hamilton et al. NeurIPS 2017]. et al. 은 '외 여러 명'."},{"x":0.07,"y":0.51,"w":0.5,"h":0.14,"say":"이웃 노드 특징에 원소별 최대 풀링. 식 Max({x_u}, u ∈ N(v))."}]},{"kind":"formula","head":"평균 풀링 (GCN)","tex":"\\text{Mean}\\left(\\{x_u\\}_{u \\in N(v)}\\right) = \\frac{1}{\\lvert N(v) \\rvert} \\sum_{u \\in N(v)} x_u","parts":[{"sym":"x_u","say":"이웃 $u$ 의 특징 벡터 (쪽지)"},{"sym":"\\{x_u\\}_{u \\in N(v)}","say":"모든 이웃 특징의 멀티셋 (봉투)"},{"sym":"\\lvert N(v) \\rvert","say":"이웃 수 (차수)"},{"sym":"\\sum","say":"전부 더하기"}],"whole":"이웃 특징을 전부 더한 뒤 이웃 수로 나눠요."},{"kind":"formula","head":"최대 풀링 (GraphSAGE)","tex":"\\left[\\text{Max}\\left(\\{x_u\\}_{u \\in N(v)}\\right)\\right]_i = \\max_{u \\in N(v)} x_{u,i}","parts":[{"sym":"x_{u,i}","say":"$x_u$ 의 $i$ 번째 칸"},{"sym":"[\\ \\cdot\\ ]_i","say":"결과 벡터의 $i$ 번째 칸"},{"sym":"\\max","say":"가장 큰 값 고르기"}],"whole":"결과의 $i$ 번째 칸은 이웃들의 $i$ 번째 칸 중 1등이에요. 칸마다 따로 뽑아요."},{"kind":"compare","head":"**원소별(Element-wise)** 계산: 이웃 (1, 3), (3, 1), (2, 2)","cols":["칸","값","평균 (GCN)","최대 (GraphSAGE)"],"rows":[["첫째 칸","1, 3, 2","2","3"],["둘째 칸","3, 1, 2","2","3"],["결과","","(2, 2)","(3, 3)"]]},{"kind":"points","head":"눈여겨볼 점","items":["최대 결과 (3, 3) 은 어느 이웃의 특징과도 같지 않아요. 칸마다 1등을 따로 뽑았으니까요.","평균은 칸마다 해도 전체 벡터 평균과 같아요.","시험식 예: 노드 A 0.4, 이웃 0.3, 0.2, 0.1 → 평균 0.2, 최대 0.3, 합 0.6."]},{"kind":"prof","when":"3주차 화요일 수업","lines":["GCN 은 평균, GraphSAGE 는 최대 풀링이에요.","지난주 말한 대로 합이 더 낫고, 이유는 간단한 계산만 해 봐도 안대요."]}],"pass3":[{"kind":"exam","src":"2024 가을 기말 2번 (GraphSAGE, MAX 집계, 10점)","q":"GraphSAGE with MAX: $h_{N(i)}^{(k)} = \\text{MAX}(\\{h_u^{(k-1)}, \\forall u \\in N(i)\\})$, $h_i^{(k)} = \\text{ReLU}(h_i^{(k-1)} \\Vert h_{N(i)}^{(k)})$. (a) Calculate the feature of each node at $k = 1$. (b) How does GraphSAGE address the scalability problem?","qko":"MAX 집계 GraphSAGE 로 각 노드의 $k=1$ 특징을 구하고, GraphSAGE 가 확장성 문제를 어떻게 푸는지 서술하세요. $\\Vert$ 는 이어 붙이기예요.","solve":["해설에서 읽은 값: A 0.1, B 0.2, C 0.4, D 0.3. 이웃은 A: B, C, D / B: A, C / C: A, B / D: A.","A: MAX(0.2, 0.4, 0.3) = 0.4 → ReLU([0.1, 0.4]) = [0.1, 0.4]","B: MAX(0.1, 0.4) = 0.4 → [0.2, 0.4]","C: MAX(0.1, 0.2) = 0.2 → [0.4, 0.2]","D: MAX(0.1) = 0.1 → [0.3, 0.1]","(b) 이웃을 정해진 수만큼 샘플링, 귀납적(inductive) 학습."],"answer":"(a) A [0.1, 0.4], B [0.2, 0.4], C [0.4, 0.2], D [0.3, 0.1]. (b) GraphSAGE samples a fixed number of neighbors for each node instead of using all neighbors, and learns inductive representations, so it can embed unseen nodes without retraining."},{"kind":"exam","src":"2025 가을 중간 4번 (GraphSAGE, MEAN 집계, 10점)","q":"GraphSAGE with MEAN aggregation and concatenation. (a) What is the main idea of GraphSAGE and how does it differ from GCN? (b) Calculate the feature of each node at $k = 1$. (c) Compute a graph-level embedding $h_G$ with mean global pooling.","qko":"(a) 4점 핵심 아이디어와 GCN 과의 차이, (b) 3점 $k=1$ 계산, (c) 3점 평균 전역 풀링으로 그래프 임베딩.","solve":["해설에서 읽은 값: A 0.4, B 0.1, C 0.3, D 0.2, E 0.1. 이웃은 A: C, D, E / B: C, E / C: A, B / D: A, E / E: A, B, D.","A: MEAN(0.3, 0.2, 0.1) = 0.2 → [0.4, 0.2].  B: MEAN(0.3, 0.1) = 0.2 → [0.1, 0.2]","C: MEAN(0.4, 0.1) = 0.25 → [0.3, 0.25].  D: MEAN(0.4, 0.1) = 0.25 → [0.2, 0.25]","E: MEAN(0.4, 0.1, 0.2) = 0.7/3 ≈ 0.233 → [0.1, 0.233]","(c) 칸마다 평균: (0.4+0.1+0.3+0.2+0.1)/5 = 0.22, (0.2+0.2+0.25+0.25+0.233)/5 ≈ 0.227"],"answer":"(a) GraphSAGE learns node embeddings by sampling and aggregating features from a node's neighbors, enabling inductive learning for unseen nodes, unlike GCNs that require the entire graph during training. (b) A [0.4, 0.2], B [0.1, 0.2], C [0.3, 0.25], D [0.2, 0.25], E [0.1, 0.233]. (c) h_G ≈ [0.22, 0.227]."},{"kind":"warn","head":"시험 주의","items":["GraphSAGE 문제는 MEAN 으로도, MAX 로도 나와요. 문제에 적힌 집계를 그대로 따르세요.","2025 중간 4번 해설의 h_G 첫 칸 0.022 는 오타예요. 계산하면 0.22 예요.","실제 GCN 은 차수로 정규화한 인접행렬, 실제 GraphSAGE max-pool 은 최대 전에 MLP 를 거쳐요. 이 덱은 핵심만 단순화했어요."]}],"pass4":[{"kind":"pyterm","name":"예시 코드: 원소별 평균과 최대","say":["p.27 에서 본 노트북 aggregate 함수의 `.mean(dim=0)`, `.max(dim=0).values` 를 슬라이드 숫자로 돌려 본 예시예요.","텐서 값 뒤의 점(2.)은 실수라는 표시예요. 평균은 실수 텐서에서만 돼요."],"example":"import torch\nx = torch.tensor([[1., 3.], [3., 1.], [2., 2.]])\nprint(x.mean(dim=0), x.max(dim=0).values)","out":"tensor([2., 2.]) tensor([3., 3.])"},{"kind":"say","lines":["2주차 노트북 셀 88 설명: PyG 의 MessagePassing 층은 `super().__init__(aggr=\"add\")` 로 집계를 정해요.","\"add\" 는 합, \"mean\" 은 평균(GCN 식), \"max\" 는 최대(GraphSAGE 식)예요.","코드 한 단어가 p.31 부터 따질 표현력 차이를 정해요."]}]},{"p":31,"title":"사례 연구: GCN 평균 집계의 실패","terms":["GCN","Mean-pool","Multi-set","Injective","Element-wise"],"pass1":[{"kind":"say","lines":["**GCN** 의 **평균 풀링(Mean-pool)** 은 색 비율이 같은 두 봉투를 구별하지 못해요.","노랑 1개와 파랑 1개가 든 봉투, 노랑 2개와 파랑 2개가 든 봉투를 생각해 봐요.","둘 다 평균을 내면 '노랑 절반, 파랑 절반' 으로 똑같아져요.","서로 다른 봉투가 같은 결과를 받으니, 평균 풀링은 단사가 아니에요."]},{"kind":"look","head":"아래의 두 봉투","boxes":[{"x":0.25,"y":0.7,"w":0.14,"h":0.19,"say":"왼쪽 봉투에는 노랑 1개, 파랑 1개가 들어 있어요."},{"x":0.49,"y":0.7,"w":0.245,"h":0.19,"say":"오른쪽 봉투에는 노랑 2개, 파랑 2개가 들어 있어요. 개수는 다르지만 비율은 같아요."}]},{"kind":"analogy","head":"성비만 적어 둔 모둠 명단","scene":"1모둠은 남학생 1명, 여학생 1명이에요. 2모둠은 남학생 2명, 여학생 2명이에요. 담임 선생님이 성비만 적어 두면 두 모둠 모두 '남녀 반반' 이 되어서, 나중에 봐도 몇 명짜리 모둠이었는지 알 수 없어요. 인원수를 그대로 적어 두었다면 두 모둠을 바로 구별했겠죠.","map":[["모둠","이웃 특징 봉투(멀티셋)"],["성비만 적기","평균 (비율만 남음)"],["인원수를 그대로 적기","합 (개수가 남음)"]]}],"pass2":[{"kind":"look","head":"정리와 실패 사례","boxes":[{"x":0.03,"y":0.16,"w":0.44,"h":0.06,"say":"GCN (평균 풀링) [Kipf & Welling, ICLR 2017]."},{"x":0.07,"y":0.25,"w":0.56,"h":0.12,"say":"원소별 평균을 구한 뒤 선형 함수와 ReLU 활성화. ReLU = max(0, x). 순서가 중요해요."},{"x":0.07,"y":0.4,"w":0.27,"h":0.06,"say":"정리(Theorem) [Xu et al. ICLR 2019]: 수학적으로 증명된 사실이에요."},{"x":0.1,"y":0.49,"w":0.64,"h":0.06,"say":"GCN 의 집계 함수는 색 비율이 같은 서로 다른 멀티셋을 구별하지 못해요."},{"x":0.25,"y":0.7,"w":0.14,"h":0.19,"say":"왼쪽 봉투: 노랑 1, 파랑 1 (2개)."},{"x":0.49,"y":0.7,"w":0.245,"h":0.19,"say":"오른쪽 봉투: 노랑 2, 파랑 2 (4개). 개수는 다르지만 비율은 같아요."}]},{"kind":"formula","head":"GCN 한 층 (단순화)","tex":"h_v = \\text{ReLU}\\left( W \\cdot \\text{Mean}\\left(\\{x_u\\}_{u \\in N(v)}\\right) \\right)","parts":[{"sym":"\\text{Mean}(\\cdots)","say":"**원소별(Element-wise)** 평균: 봉투 속 비율 요약"},{"sym":"W \\cdot","say":"가중치 행렬 곱 (선형 함수)"},{"sym":"\\text{ReLU}","say":"음수는 0, 나머지는 그대로"}],"whole":"칸마다 평균 → 가중치 곱 → 음수 지우기. 평균이 같으면 뒤 계산도 같아요."},{"kind":"figure","head":"개수 대 비율 (노랑 = (1, 0), 파랑 = (0, 1) 로 적었을 때)","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\"><rect x=\"20\" y=\"30\" width=\"84\" height=\"40\" rx=\"8\" class=\"box\"/><circle cx=\"44\" cy=\"50\" r=\"16\" class=\"n2\"/><circle cx=\"80\" cy=\"50\" r=\"16\" class=\"n3\"/><rect x=\"240\" y=\"30\" width=\"156\" height=\"40\" rx=\"8\" class=\"box\"/><circle cx=\"264\" cy=\"50\" r=\"16\" class=\"n2\"/><circle cx=\"300\" cy=\"50\" r=\"16\" class=\"n2\"/><circle cx=\"336\" cy=\"50\" r=\"16\" class=\"n3\"/><circle cx=\"372\" cy=\"50\" r=\"16\" class=\"n3\"/><text x=\"62\" y=\"30\" font-size=\"14\" text-anchor=\"middle\" class=\"tm\">봉투 1 (2개)<\/text><text x=\"318\" y=\"22\" font-size=\"14\" text-anchor=\"middle\" class=\"tm\">봉투 2 (4개)<\/text><text x=\"62\" y=\"120\" font-size=\"16\" text-anchor=\"middle\" class=\"t b1\">(1, 1)<\/text><text x=\"180\" y=\"120\" font-size=\"16\" text-anchor=\"middle\" class=\"tb b1\">합: 다름<\/text><text x=\"318\" y=\"120\" font-size=\"16\" text-anchor=\"middle\" class=\"t b1\">(2, 2)<\/text><text x=\"62\" y=\"175\" font-size=\"16\" text-anchor=\"middle\" class=\"t b2\">(0.5, 0.5)<\/text><text x=\"180\" y=\"175\" font-size=\"16\" text-anchor=\"middle\" class=\"tb b2\">평균: 같음<\/text><text x=\"318\" y=\"175\" font-size=\"16\" text-anchor=\"middle\" class=\"t b2\">(0.5, 0.5)<\/text><text x=\"240\" y=\"235\" font-size=\"16\" text-anchor=\"middle\" class=\"tb b3\">평균은 비율만 보고 개수를 못 봐요<\/text><\/svg>","caption":"합은 (1, 1) 과 (2, 2) 로 가르고, 평균은 둘 다 (0.5, 0.5) 예요.","builds":3},{"kind":"compare","head":"노랑 = 1, 파랑 = 0 으로 임시로 적으면","cols":["요약","{1, 0}","{1, 1, 0, 0}","구별?"],"rows":[["평균","0.5","0.5","안 된다"],["평균 → W = 2 → ReLU","1","1","안 된다"],["평균 → W = -3 → ReLU","0","0","안 된다"],["합","1","2","된다"]]},{"kind":"points","head":"평균이 아무것도 못 보는 건 아니에요","items":["{노랑, 노랑, 파랑} 과 노랑 4 + 파랑 2 는 둘 다 2/3 이라 못 갈라요 (이웃 3명 대 6명).","하지만 {노랑, 파랑} 1/2 과 {노랑, 노랑, 파랑} 2/3 은 갈라요.","정확히는 '비율은 보고 개수는 못 본다' 예요."]},{"kind":"prof","when":"3주차 화요일 수업","lines":["평균 풀링은 이웃 구성이 달라도 집계 결과가 같아질 수 있다고 했어요."]}],"pass3":[{"kind":"exam","src":"2024 가을 기말 1번 (GCN, 10점)","q":"Six-node undirected graph (A to F) with initial features. GCN layer: $H^{(k)} = \\sigma(A H^{(k-1)})$, $\\sigma$ = ReLU, A = adjacency matrix. (a) Calculate the output at $k = 1$. (b) What are the limitations of GCN compared to GraphSAGE?","qko":"인접행렬 A 로 GCN 한 층 출력을 계산하고, GraphSAGE 와 비교한 GCN 의 한계를 서술하세요.","solve":["그림(그래프와 특징 값)은 텍스트 기출에 없어서 방법으로 정리해요.","$AH$ 의 $i$ 행 = 노드 $i$ 의 이웃 특징 행을 전부 더한 것. 정규화가 없으니 평균이 아니라 합이에요.","연습: 노드 1 의 이웃 2, 3 / 노드 2, 3 의 이웃 1, $H = (1, 2, 3)$ 이면 $AH = (5, 1, 1)$.","ReLU 로 음수만 0 으로 바꿔요.","(b) 확장성(전체 인접행렬, 특징 행렬 필요)과 전이적 학습(고정 그래프 가정)."],"answer":"(a) 행마다 이웃 특징 합을 구하고 ReLU. (b) Scalability: GCNs require the entire graph adjacency matrix and feature matrix during training. Transductive learning: GCNs assume a static, fixed graph structure, so adding nodes or edges requires retraining."},{"kind":"exam","src":"2025 가을 중간 3번 (GCN, 10점)","q":"(a) (3p) Explain how information is propagated in a GCN layer. (b) (7p) Given adjacency matrix $A$ and $H^{(0)}$, calculate $H^{(1)} = \\sigma(A \\cdot H^{(0)})$ with ReLU.","qko":"(a) GCN 층에서 정보가 어떻게 전파되는지 설명하고, (b) 5×5 인접행렬과 5×2 특징 행렬로 $H^{(1)}$ 을 계산하세요.","solve":["(a) 이웃 특징을 모아 평균(정규화 인접행렬)을 내고 선형 변환과 활성화를 해요.","(b) 크기 확인: 5×5 곱하기 5×2 = 5×2.","각 칸 = 그 노드 이웃들의 같은 칸 값의 합.","특징과 A 에 음수가 없어 ReLU 뒤에도 값이 그대로예요."],"answer":"(a) Each node aggregates and averages features from its neighbors (using the normalized adjacency matrix), then applies a linear transformation and activation. (b) $H^{(1)} = \text{ReLU}(A H^{(0)})$, 행마다 이웃 합."},{"kind":"english","head":"표현력 한계를 덧붙이는 문장","en":"Mean aggregation in GCN cannot distinguish different multisets with the same proportion of features, so it is not injective.","ko":"GCN 의 평균 집계는 특징 비율이 같은 서로 다른 멀티셋을 구별하지 못해서 단사가 아니에요."},{"kind":"warn","head":"주의","items":["실패 원인은 W 나 ReLU 가 아니라 맨 앞의 평균이에요.","시험식 $\\sigma(AH)$ 는 정규화가 없어 실제 계산은 합인데, 서술 해설은 '평균(정규화 인접행렬)' 이라고 써요. 계산은 주어진 식대로.","$D^{-1}AH$ 처럼 이웃 수로 나누면 평균이 돼요. 연습 예에서 노드 1 은 5/2 = 2.5."]},{"kind":"check","q":"**평균 풀링(Mean-pool)** 이 구별하지 못하는 봉투 쌍은?","choices":["{노랑} 과 {파랑}","{노랑, 파랑} 과 {노랑, 노랑, 파랑}","{노랑, 파랑} 과 {노랑, 노랑, 파랑, 파랑}"],"a":2,"why":"셋째 쌍은 비율이 둘 다 반반이라 평균이 (0.5, 0.5) 로 같아요. 둘째 쌍은 1/2 대 2/3 이라 구별돼요."}],"pass4":[{"kind":"code","head":"2주차 노트북의 평균 집계 층","file":"PracticeCode_2_번역.ipynb 셀 71","code":"class MeanAggregationLayer(nn.Module):\n    '''Average neighbor messages, then combine with a linear map + ReLU.'''\n\n    def __init__(self, in_dim, out_dim):\n        super().__init__()\n        self.W_self = nn.Linear(in_dim, out_dim, bias=False)\n        self.W_neigh = nn.Linear(in_dim, out_dim, bias=False)\n\n    def forward(self, x, adj):\n        degree = adj.sum(dim=1, keepdim=True).clamp(min=1.0)\n        aggregated = (adj @ x) / degree\n        return torch.relu(self.W_self(x) + self.W_neigh(aggregated))\n\n\nclass BasicGNN(nn.Module):\n    '''Two-layer mean-aggregation GNN for node classification.'''\n\n    def __init__(self, in_dim, hidden_dim, num_classes):\n        super().__init__()\n        self.layer1 = MeanAggregationLayer(in_dim, hidden_dim)\n        self.layer2 = MeanAggregationLayer(hidden_dim, hidden_dim)\n        self.classifier = nn.Linear(hidden_dim, num_classes)\n\n    def forward(self, x, adj, return_embeddings=False):\n        h = self.layer1(x, adj)\n        h = self.layer2(h, adj)\n        if return_embeddings:\n            return h\n        return self.classifier(h)\n\n\nadj = to_dense_adj(data.edge_index, max_num_nodes=data.num_nodes)[0]\nprint(\"Mean-aggregation adjacency shape:\", tuple(adj.shape))","lines":[{"from":1,"to":2,"say":"`class` 는 부품 설계도예요. `nn.Module` 을 물려받아 파이토치 신경망 층이 돼요."},{"from":4,"to":7,"say":"`__init__` 은 만들 때 한 번 실행. `nn.Linear` 는 '입력 × 가중치' 층이고 가중치는 학습돼요."},{"from":9,"to":10,"say":"`forward` 가 실제 계산. `adj.sum(dim=1)` 은 인접행렬 행 합 = 차수. 0 으로 나누지 않게 최소 1."},{"from":11,"to":11,"say":"`adj @ x` 는 이웃 특징 합, 차수로 나누면 평균. 슬라이드의 Mean 이에요."},{"from":12,"to":12,"say":"선형 변환 후 `torch.relu`. 평균 → 선형 함수 → ReLU, 슬라이드 순서 그대로예요."},{"from":14,"to":17,"say":"BasicGNN 클래스: 평균 집계 층 두 개로 만든 노드 분류용 GNN 이에요."},{"from":18,"to":23,"say":"__init__: 층 두 개와 마지막 분류용 선형 층을 만들어요."},{"from":24,"to":30,"say":"forward: 두 층을 차례로 지나고, return_embeddings 가 참이면 임베딩을, 아니면 분류 점수를 돌려줘요."},{"from":31,"to":33,"say":"edge_index 를 꽉 찬 인접행렬로 바꾸고 그 모양을 출력해요."}],"link":"aggregated 가 같아지면 W_neigh 와 ReLU 를 거쳐도 이웃 쪽 기여는 같아요 (p.31 실패 원인)."},{"kind":"pyterm","name":"예시 코드: 반반 봉투 두 개","say":["노랑 (1, 0), 파랑 (0, 1) 을 행으로 쌓아 평균과 합을 비교한 예시예요."],"example":"a = torch.tensor([[1., 0.], [0., 1.]])\nb = torch.tensor([[1., 0.], [1., 0.], [0., 1.], [0., 1.]])\nprint(a.mean(dim=0), b.mean(dim=0))\nprint(a.sum(dim=0), b.sum(dim=0))","out":"tensor([0.5000, 0.5000]) tensor([0.5000, 0.5000])\ntensor([1., 1.]) tensor([2., 2.])"}]},{"p":32,"title":"사례 연구: 색을 원-핫 벡터로","terms":["One-hot encoding","Node feature","GCN","Mean-pool","Injective"],"pass1":[{"kind":"say","lines":["컴퓨터는 '노랑' 같은 색 이름으로는 계산할 수 없어서 숫자로 바꿔야 해요.","색마다 칸을 하나씩 만들고, 그 색에 해당하는 칸에만 1 을, 나머지 칸에는 0 을 적어요.","이렇게 바꾸는 방법을 **원-핫 인코딩(One-hot encoding)** 이라고 해요. 딱 한 칸만 켜진다는 뜻이에요.","이 단순한 설정만으로도 **GCN** 이 실패하는 걸 보여 줄 수 있어요."]},{"kind":"look","head":"노랑과 파랑의 숫자 표","boxes":[{"x":0.305,"y":0.33,"w":0.15,"h":0.16,"say":"노랑은 위 칸 '노랑인가?' 에만 1 을 적고 아래 칸은 0 이에요."},{"x":0.515,"y":0.33,"w":0.15,"h":0.16,"say":"파랑은 아래 칸 '파랑인가?' 에만 1 을 적고 위 칸은 0 이에요."}]},{"kind":"analogy","head":"한 칸에만 동그라미 치는 설문지","scene":"설문지에 '좋아하는 색' 을 묻는 칸이 노랑, 파랑 두 개 있어요. 노랑을 좋아하면 노랑 칸에만 동그라미를 치고 파랑 칸은 비워 둬요. 파랑을 좋아하면 반대로 파랑 칸에만 동그라미를 쳐요. 이렇게 한 칸에만 표시하는 방법이 원-핫 인코딩이에요.","map":[["설문지의 색 칸","벡터의 칸 (색마다 하나)"],["동그라미","1"],["빈칸","0"]]}],"pass2":[{"kind":"look","head":"슬라이드 세 줄","boxes":[{"x":0.03,"y":0.16,"w":0.6,"h":0.06,"say":"단순화를 위해 노드 특징(색)을 원-핫 인코딩으로 나타낸다고 가정해요. 설명용 설정이에요."},{"x":0.07,"y":0.24,"w":0.3,"h":0.06,"say":"예: 서로 다른 색이 두 가지라면."},{"x":0.305,"y":0.33,"w":0.15,"h":0.16,"say":"노랑 = 세로 벡터 (1, 0). 위 칸 '노랑인가?' 에 1."},{"x":0.515,"y":0.33,"w":0.15,"h":0.16,"say":"하늘색(파랑) = (0, 1). 아래 칸 '파랑인가?' 에 1."},{"x":0.07,"y":0.51,"w":0.54,"h":0.06,"say":"이 가정만으로도 GCN 이 실패하는 방식을 보이기에 충분해요."}]},{"kind":"formula","head":"원-핫 벡터 읽기","tex":"\\text{노랑} = \\begin{bmatrix} 1 \\\\ 0 \\end{bmatrix}, \\qquad \\text{파랑} = \\begin{bmatrix} 0 \\\\ 1 \\end{bmatrix}","parts":[{"sym":"\\begin{bmatrix} 1 \\\\ 0 \\end{bmatrix}","say":"칸 두 개짜리 세로 벡터. 위 칸 1, 아래 칸 0"},{"sym":"\\text{위 칸}","say":"노랑인가? 맞으면 1"},{"sym":"\\text{아래 칸}","say":"파랑인가? 맞으면 1"}],"whole":"색이 세 가지면 칸도 세 개: (1, 0, 0), (0, 1, 0), (0, 0, 1). 원-핫 = 딱 한 칸만 켜짐."},{"kind":"figure","head":"원-핫과 봉투의 합","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\"><text x=\"90\" y=\"22\" font-size=\"15\" text-anchor=\"middle\" class=\"tb\">원-핫 약속<\/text><circle cx=\"35\" cy=\"67\" r=\"16\" class=\"n2\"/><text x=\"62\" y=\"72\" font-size=\"18\" text-anchor=\"middle\" class=\"tb\">=<\/text><rect x=\"78\" y=\"42\" width=\"30\" height=\"26\" rx=\"3\" class=\"box\"/><text x=\"93\" y=\"61\" font-size=\"15\" text-anchor=\"middle\" class=\"t\">1<\/text><rect x=\"78\" y=\"68\" width=\"30\" height=\"26\" rx=\"3\" class=\"box\"/><text x=\"93\" y=\"87\" font-size=\"15\" text-anchor=\"middle\" class=\"t\">0<\/text><circle cx=\"35\" cy=\"142\" r=\"16\" class=\"n3\"/><text x=\"62\" y=\"147\" font-size=\"18\" text-anchor=\"middle\" class=\"tb\">=<\/text><rect x=\"78\" y=\"117\" width=\"30\" height=\"26\" rx=\"3\" class=\"box\"/><text x=\"93\" y=\"136\" font-size=\"15\" text-anchor=\"middle\" class=\"t\">0<\/text><rect x=\"78\" y=\"143\" width=\"30\" height=\"26\" rx=\"3\" class=\"box\"/><text x=\"93\" y=\"162\" font-size=\"15\" text-anchor=\"middle\" class=\"t\">1<\/text><text x=\"355\" y=\"22\" font-size=\"15\" text-anchor=\"middle\" class=\"tb b1\">봉투 {노랑, 파랑, 파랑} 의 합<\/text><circle cx=\"235\" cy=\"55\" r=\"16\" class=\"n2 b1\"/><circle cx=\"295\" cy=\"55\" r=\"16\" class=\"n3 b1\"/><circle cx=\"355\" cy=\"55\" r=\"16\" class=\"n3 b1\"/><rect x=\"220\" y=\"80\" width=\"30\" height=\"26\" rx=\"3\" class=\"box b1\"/><text x=\"235\" y=\"99\" font-size=\"15\" text-anchor=\"middle\" class=\"t b1\">1<\/text><rect x=\"220\" y=\"106\" width=\"30\" height=\"26\" rx=\"3\" class=\"box b1\"/><text x=\"235\" y=\"125\" font-size=\"15\" text-anchor=\"middle\" class=\"t b1\">0<\/text><text x=\"265\" y=\"116\" font-size=\"18\" text-anchor=\"middle\" class=\"tb b1\">+<\/text><rect x=\"280\" y=\"80\" width=\"30\" height=\"26\" rx=\"3\" class=\"box b1\"/><text x=\"295\" y=\"99\" font-size=\"15\" text-anchor=\"middle\" class=\"t b1\">0<\/text><rect x=\"280\" y=\"106\" width=\"30\" height=\"26\" rx=\"3\" class=\"box b1\"/><text x=\"295\" y=\"125\" font-size=\"15\" text-anchor=\"middle\" class=\"t b1\">1<\/text><text x=\"325\" y=\"116\" font-size=\"18\" text-anchor=\"middle\" class=\"tb b1\">+<\/text><rect x=\"340\" y=\"80\" width=\"30\" height=\"26\" rx=\"3\" class=\"box b1\"/><text x=\"355\" y=\"99\" font-size=\"15\" text-anchor=\"middle\" class=\"t b1\">0<\/text><rect x=\"340\" y=\"106\" width=\"30\" height=\"26\" rx=\"3\" class=\"box b1\"/><text x=\"355\" y=\"125\" font-size=\"15\" text-anchor=\"middle\" class=\"t b1\">1<\/text><text x=\"385\" y=\"116\" font-size=\"18\" text-anchor=\"middle\" class=\"tb b1\">=<\/text><rect x=\"400\" y=\"80\" width=\"30\" height=\"26\" rx=\"3\" class=\"box2 b2\"/><text x=\"415\" y=\"99\" font-size=\"15\" text-anchor=\"middle\" class=\"t b2\">1<\/text><rect x=\"400\" y=\"106\" width=\"30\" height=\"26\" rx=\"3\" class=\"box2 b2\"/><text x=\"415\" y=\"125\" font-size=\"15\" text-anchor=\"middle\" class=\"t b2\">2<\/text><text x=\"440\" y=\"99\" font-size=\"14\" text-anchor=\"start\" class=\"t b2\">노랑 1<\/text><text x=\"440\" y=\"125\" font-size=\"14\" text-anchor=\"start\" class=\"t b2\">파랑 2<\/text><rect x=\"10\" y=\"175\" width=\"460\" height=\"85\" rx=\"8\" class=\"box b3\"/><text x=\"240\" y=\"203\" font-size=\"15\" text-anchor=\"middle\" class=\"t b3\">숫자 하나로 (노랑 1, 파랑 2): {노랑, 노랑} = 2, {파랑} = 2<\/text><text x=\"240\" y=\"238\" font-size=\"15\" text-anchor=\"middle\" class=\"tb b3\">원-핫으로: (2, 0) 과 (0, 1) 로 달라요<\/text><\/svg>","caption":"칸마다 더하면 색별 개수표가 나와요. 숫자 하나로 적으면 서로 다른 봉투가 부딪혀요.","builds":3},{"kind":"compare","head":"세 가지 요약 미리 보기 (p.33 부터 확인)","cols":["봉투","평균 (비율)","최대 (있나 없나)","합 (개수)"],"rows":[["{노랑, 파랑}","(0.5, 0.5)","(1, 1)","(1, 1)"],["{노랑, 노랑, 파랑, 파랑}","(0.5, 0.5)","(1, 1)","(2, 2)"],["{노랑, 노랑, 파랑}","(2/3, 1/3)","(1, 1)","(2, 1)"]]},{"kind":"points","head":"왜 '충분' 할까","items":["단사가 아니라는 걸 보이려면 반례 하나면 돼요 (p.23 확인법).","가장 단순한 원-핫 설정에서 반례를 찾으면, GCN 의 평균은 단사라고 말할 수 없어요."]},{"kind":"prof","when":"3주차 화요일 수업","lines":["노드 특징 벡터가 $(1, 0)$ 과 $(0, 1)$ 두 가지인 상황을 가정하고 보자고 했어요."]},{"kind":"mining","src":"마이닝 9강 WL 테스트","lines":["WL 라벨 1, 2, 3 은 크기가 아니라 이름이었어요. 라벨 3 이 라벨 2 보다 크다는 뜻이 아니었죠.","원-핫은 이런 이름을 칸으로 나눠 '3 = 1 + 2' 같은 엉뚱한 산수를 막아요."]}],"pass3":[{"kind":"english","head":"반례를 영어로 쓰기","en":"Let yellow = (1, 0) and blue = (0, 1). The multisets {yellow, blue} and {yellow, yellow, blue, blue} both have mean (0.5, 0.5), so mean aggregation is not injective.","ko":"노랑 (1, 0), 파랑 (0, 1) 로 두면 두 멀티셋의 평균이 모두 (0.5, 0.5) 라서 평균 집계는 단사가 아니에요.","tip":"One counterexample is enough 를 덧붙이면 논리가 완성돼요."},{"kind":"check","q":"**원-핫 인코딩(One-hot encoding)** 으로 색 세 가지(빨, 노, 파)를 적을 때 파랑은?","choices":["(3)","(0, 0, 1)","(1, 1, 1)","(0, 1)"],"a":1,"why":"색마다 칸 하나, 해당 칸만 1. 세 번째 색이면 (0, 0, 1) 이에요."},{"kind":"warn","head":"주의","items":["원-핫은 반례를 쉽게 보이려는 설정이에요. 실제 데이터 특징이 원-핫이라는 뜻은 아니에요.","원-핫에서 평균의 칸 = 비율, 합의 칸 = 개수, 최대의 칸 = 있다/없다. 세 읽는 법을 섞지 마세요."]}],"pass4":[{"kind":"pyterm","name":"torch.eye: 원-핫을 한꺼번에","say":["`torch.eye(n)` 은 대각선만 1 인 n×n 행렬이에요. 행 하나하나가 원-핫 벡터예요.","2주차 노트북 셀 58 은 `X0 = torch.eye(num_nodes)` 로 노드마다 원-핫 특징을 줘요."],"example":"import torch\nprint(torch.eye(2))","out":"tensor([[1., 0.],\n        [0., 1.]])"},{"kind":"code","head":"원-핫 특징에 합, 평균, 최대 적용","file":"PracticeCode_2_번역.ipynb 셀 49","code":"def generate_messages(neighbor_features):\n    '''In the basic model the message is the neighbor representation itself.'''\n    return neighbor_features\n\n\ndef aggregate(messages, method=\"mean\"):\n    if method == \"sum\":\n        return messages.sum(dim=0)\n    if method == \"mean\":\n        return messages.mean(dim=0)\n    if method == \"max\":\n        return messages.max(dim=0).values\n    raise ValueError(f\"Unknown aggregation method: {method}\")\n\n\ndef update(self_features, aggregated, W_self, W_neigh):\n    '''Combine the node state with the aggregated neighborhood, then apply ReLU.'''\n    return torch.relu(self_features @ W_self + aggregated @ W_neigh)\n\n\nneighbor_ids = list(G.neighbors(0))\nneighbor_x = data.x[neighbor_ids]\nmessages = generate_messages(neighbor_x)\n\nprint(\"Target node: 0\")\nprint(\"Neighbors of node 0:\", neighbor_ids)\nfor method in [\"sum\", \"mean\", \"max\"]:\n    agg = aggregate(messages, method=method)\n    print(f\"{method:4s} aggregation:\", [round(v, 4) for v in agg[:8].tolist()])\n\nfeat_dim = data.x.size(1)\ntorch.manual_seed(0)\nW_self = torch.randn(feat_dim, 8) * 0.1\nW_neigh = torch.randn(feat_dim, 8) * 0.1\nh0 = update(data.x[0], aggregate(messages, \"mean\"), W_self, W_neigh)\nprint(\"Updated representation of node 0:\", [round(v, 4) for v in h0.tolist()])","lines":[{"from":1,"to":4,"say":"generate_messages: 기본 모델에서는 이웃 특징 그대로가 메시지라서, 받은 것을 그대로 돌려줘요."},{"from":5,"to":14,"say":"aggregate: method 가 'sum' 이면 합, 'mean' 이면 평균, 'max' 면 최댓값으로 모아요. dim=0 은 이웃 방향으로 칸마다 계산하라는 뜻이에요."},{"from":15,"to":19,"say":"update: 내 특징과 모은 이웃 정보에 각자 가중치 행렬을 곱해(@) 더하고 ReLU 를 씌워요."},{"from":21,"to":23,"say":"가라테 클럽의 노드 0 이웃 16명을 `list` 로 모으고, `data.x[...]` 로 그 이웃들의 원-핫 특징 행을 뽑아요."},{"from":25,"to":26,"say":"노드 0 과 이웃 번호를 출력해요."},{"from":27,"to":29,"say":"p.27 의 aggregate 를 세 방식으로 불러 앞 8칸을 반올림해 출력해요."},{"from":30,"to":36,"say":"특징 칸 수를 재고, 난수 시드를 고정해 작은 가중치 두 개를 만든 뒤, 평균으로 모은 노드 0 의 새 표현을 출력해요."}],"link":"출력: sum [0.0, 1.0, 1.0, ...], mean [0.0, 0.0625, ...], max [0.0, 1.0, ...]. 원-핫이라 합은 개수, 평균은 1/16 비율이에요."},{"kind":"warn","head":"출력 읽기","items":["0번 칸이 0 인 이유: 노드 0 자신은 이웃이 아니라서 봉투에 없어요.","합과 최대가 여기선 같아 보여요. 이웃마다 색(칸)이 달라 개수가 전부 1 이기 때문이에요. 같은 색이 겹치면 달라져요."]}]},{"p":33,"title":"평균은 개수를 지운다 (GCN)","terms":["GCN","Mean pooling","Multiset","One-hot encoding","Expressive power"],"pass1":[{"kind":"say","lines":["**GCN** 은 이웃들이 보낸 쪽지를 **평균 풀링(Mean pooling)**, 곧 평균으로 모아요.","노랑 1장과 파랑 1장이 든 봉투, 노랑 2장과 파랑 2장이 든 봉투를 넣어 볼게요.","둘 다 평균은 '노랑 절반, 파랑 절반' 이라서, 그 뒤 계산을 거쳐도 끝까지 같은 결과가 나와요."]},{"kind":"look","head":"그림은 아래에서 위로 읽어요","boxes":[{"x":0.3,"y":0.6,"w":0.13,"h":0.25,"say":"왼쪽 아래 봉투예요. 노랑 쪽지 1장, 파랑 쪽지 1장이 들어 있어요."},{"x":0.54,"y":0.37,"w":0.24,"h":0.47,"say":"오른쪽 봉투는 노랑 2장, 파랑 2장이에요. 장수는 두 배지만 비율은 같아요."},{"x":0.44,"y":0.32,"w":0.16,"h":0.14,"say":"두 봉투가 결국 '같은 출력' 이 되었다는 표시예요."}]},{"kind":"analogy","head":"비율만 적어 둔 메모","scene":"도서부장이 친구들의 봉투를 열어 보고 메모를 남겨요. 첫 봉투엔 노랑 쪽지 1장과 파랑 쪽지 1장, 둘째 봉투엔 노랑 2장과 파랑 2장이 있었어요. 그런데 메모에는 둘 다 '노랑 반, 파랑 반' 이라고만 적었어요. 메모만 받은 사람은 봉투에 2장이 있었는지 4장이 있었는지 영영 알 수 없어요.","map":[["쪽지 봉투","**멀티셋(Multiset)**, 순서 없이 개수를 세는 모음"],["비율만 적은 메모","**평균 풀링(Mean pooling)**"],["메모만 읽는 다음 사람","평균 뒤에 이어지는 계산"]]}],"pass2":[{"kind":"look","head":"슬라이드 그림은 아래에서 위로 읽어요","boxes":[{"x":0.03,"y":0.15,"w":0.45,"h":0.08,"say":"**GCN** 은 이웃을 **평균 풀링(Mean pooling)** 으로 모아요. 출처는 Kipf & Welling, ICLR 2017."},{"x":0.3,"y":0.6,"w":0.13,"h":0.25,"say":"왼쪽 봉투: 노랑 $(1,0)$, 파랑 $(0,1)$. **원-핫 인코딩(One-hot encoding)** 이에요."},{"x":0.17,"y":0.5,"w":0.23,"h":0.12,"say":"초록 글씨는 원소별 평균. 칸끼리 평균을 내면 $(0.5, 0.5)$ 예요."},{"x":0.3,"y":0.37,"w":0.13,"h":0.13,"say":"평균에 $W$ 를 곱하고 ReLU 를 씌운 결과가 짙은 동그라미예요."},{"x":0.54,"y":0.37,"w":0.24,"h":0.47,"say":"오른쪽 봉투는 노랑 2, 파랑 2. 평균은 역시 $(0.5, 0.5)$ 예요."},{"x":0.44,"y":0.32,"w":0.16,"h":0.14,"say":"그래서 두 결과가 '같은 출력!'이에요."}]},{"kind":"formula","head":"GCN 한 층을 식으로","tex":"h_v = \\mathrm{ReLU}\\left(W \\cdot \\mathrm{Mean}\\left(\\{\\{x_u\\}\\}_{u\\in N(v)}\\right)\\right)","parts":[{"sym":"x_u","say":"이웃 $u$ 의 특징. 여기서는 원-핫 쪽지"},{"sym":"\\{\\{x_u\\}\\}_{u\\in N(v)}","say":"쪽지들을 모은 봉투, **멀티셋(Multiset)**"},{"sym":"\\mathrm{Mean}","say":"칸별 평균. 봉투 속 비율만 남겨요"},{"sym":"W","say":"학습되는 가중치 행렬 (요약본을 읽는 뇌)"},{"sym":"\\mathrm{ReLU}","say":"음수는 0, 0 이상은 그대로"}],"whole":"쪽지 봉투를 평균으로 요약하고, W 로 읽고, 음수를 지워 새 임베딩을 만든다. W 는 요약본만 받아 봐요."},{"kind":"steps","head":"숫자로 직접 해 보기","steps":["1단계. 왼쪽 합 $(1, 1)$ 을 쪽지 2장으로 나누면 $(0.5, 0.5)$","2단계. 오른쪽 합 $(2, 2)$ 를 쪽지 4장으로 나누면 $(0.5, 0.5)$","3단계. $W$ 곱: $(1\\times0.5 + 2\\times0.5,\\ 3\\times0.5 - 4\\times0.5) = (1.5, -0.5)$","4단계. ReLU 로 $-0.5$ 는 0. 결과 $(1.5, 0)$. 오른쪽도 입력이 같으니 $(1.5, 0)$","비교. 합이었다면 왼쪽 $(3, 0)$, 오른쪽 $(6, 0)$ 으로 달라요."],"answer":"평균: 두 봉투 모두 (1.5, 0). 합: (3, 0) 과 (6, 0)","given":"노랑 $(1,0)$, 파랑 $(0,1)$, $W = \\begin{bmatrix} 1 & 2 \\\\ 3 & -4 \\end{bmatrix}$"},{"kind":"figure","head":"평균 단계에서 이미 같아져요","svg":"<svg viewBox=\"0 0 480 270\" xmlns=\"http://www.w3.org/2000/svg\">\n<text class=\"tb b3\" x=\"240\" y=\"28\" font-size=\"18\" text-anchor=\"middle\">같은 출력!<\/text>\n<text class=\"t b3\" x=\"120\" y=\"60\" font-size=\"16\" text-anchor=\"middle\">(1.5, 0)<\/text>\n<text class=\"t b3\" x=\"360\" y=\"60\" font-size=\"16\" text-anchor=\"middle\">(1.5, 0)<\/text>\n<line class=\"hl b3\" x1=\"170\" y1=\"55\" x2=\"310\" y2=\"55\"/>\n<text class=\"tm b3\" x=\"240\" y=\"84\" font-size=\"14\" text-anchor=\"middle\">W 곱 + ReLU<\/text>\n<line class=\"e b2\" x1=\"120\" y1=\"168\" x2=\"120\" y2=\"136\"/>\n<line class=\"e b2\" x1=\"360\" y1=\"168\" x2=\"360\" y2=\"136\"/>\n<rect class=\"box2 b2\" x=\"70\" y=\"100\" width=\"100\" height=\"34\" rx=\"8\"/>\n<text class=\"t b2\" x=\"120\" y=\"123\" font-size=\"16\" text-anchor=\"middle\">(0.5, 0.5)<\/text>\n<rect class=\"box2 b2\" x=\"310\" y=\"100\" width=\"100\" height=\"34\" rx=\"8\"/>\n<text class=\"t b2\" x=\"360\" y=\"123\" font-size=\"16\" text-anchor=\"middle\">(0.5, 0.5)<\/text>\n<text class=\"tm b2\" x=\"240\" y=\"123\" font-size=\"14\" text-anchor=\"middle\">평균<\/text>\n<rect class=\"box\" x=\"50\" y=\"170\" width=\"140\" height=\"44\" rx=\"10\"/>\n<circle class=\"n2\" cx=\"90\" cy=\"192\" r=\"16\"/>\n<circle class=\"n3\" cx=\"150\" cy=\"192\" r=\"16\"/>\n<rect class=\"box\" x=\"270\" y=\"170\" width=\"180\" height=\"44\" rx=\"10\"/>\n<circle class=\"n2\" cx=\"295\" cy=\"192\" r=\"16\"/>\n<circle class=\"n2\" cx=\"335\" cy=\"192\" r=\"16\"/>\n<circle class=\"n3\" cx=\"385\" cy=\"192\" r=\"16\"/>\n<circle class=\"n3\" cx=\"425\" cy=\"192\" r=\"16\"/>\n<text class=\"t b1\" x=\"120\" y=\"242\" font-size=\"14\" text-anchor=\"middle\">노랑 1, 파랑 1<\/text>\n<text class=\"t b1\" x=\"360\" y=\"242\" font-size=\"14\" text-anchor=\"middle\">노랑 2, 파랑 2<\/text>\n<\/svg>","caption":"진한 공은 노랑, 다른 색 공은 파랑. 나누기 순간 '몇 장'이 지워져요.","builds":3},{"kind":"prof","when":"3주차 화요일 수업","lines":["왼쪽과 오른쪽은 이웃 구성이 분명히 달라요.","평균을 하면 같아지지만, 합을 하면 $(1, 1)$ 과 $(2, 2)$ 로 달라진대요."]}],"pass3":[{"kind":"warn","head":"헷갈리기 쉬운 점","items":["실패의 범인은 $W$ 나 ReLU 가 아니라 맨 앞의 **평균 풀링(Mean pooling)** 이에요.","실제 **GCN** 은 $\\tilde{D}^{-1/2}\\tilde{A}\\tilde{D}^{-1/2}$ 로 정규화해서 딱 평균은 아니에요. 여기선 단순화했어요.","짙은 동그라미는 새 색이 아니라 최종 임베딩을 그린 거예요."]},{"kind":"english","head":"서술형: 왜 평균 집계는 단사가 아닌가","en":"Mean pooling cannot distinguish multisets with the same proportion of features, e.g., {a, b} and {a, a, b, b} both give (0.5, 0.5).","ko":"평균 풀링은 특징 비율이 같은 멀티셋을 구별하지 못한다. {a, b} 와 {a, a, b, b} 는 둘 다 (0.5, 0.5) 가 된다.","tip":"proportion(비율) 한 단어가 핵심이에요."}],"pass4":[{"kind":"pyterm","name":"텐서(tensor)와 mean(dim=0), sum(dim=0)","say":["**예시 코드**예요. 3주차 노트북에는 GCN 집계 코드가 없어서 짧게 만들었어요.","`import torch` 로 파이토치를 먼저 불러왔다고 가정해요. `torch.tensor` 는 숫자 표를 만들어요.","한 줄이 쪽지 한 장. `mean(dim=0)` 은 세로(칸)별 평균, `sum(dim=0)` 은 칸별 합이에요."],"example":"x = torch.tensor([[1., 0.], [0., 1.]])\ny = torch.tensor([[1., 0.], [1., 0.], [0., 1.], [0., 1.]])\nprint(x.mean(dim=0), y.mean(dim=0), x.sum(dim=0), y.sum(dim=0))","out":"tensor([0.5000, 0.5000]) tensor([0.5000, 0.5000]) tensor([1., 1.]) tensor([2., 2.])"}]},{"p":34,"title":"최댓값은 종류만 본다 (GraphSAGE)","terms":["GraphSAGE","Max pooling","MLP","Multiset","Injective","Degree"],"pass1":[{"kind":"say","lines":["**GraphSAGE** 는 쪽지를 한 장씩 작은 신경망인 **MLP** 에 넣어 다듬어요.","그다음 **최대 풀링(Max pooling)**, 곧 가장 큰 값만 뽑는 방법으로 모아요.","그런데 가장 큰 값만 보면, 봉투에 어떤 색이 '있는지' 만 알 수 있어요.","그래서 색 종류만 같으면 개수가 달라도 같은 봉투로 봐 버려요."]},{"kind":"look","head":"아래 봉투 세 개","boxes":[{"x":0.2,"y":0.56,"w":0.6,"h":0.26,"say":"봉투마다 노랑과 파랑의 개수는 달라요. 하지만 셋 다 노랑과 파랑이 둘 다 들어 있어요."}]},{"kind":"analogy","head":"출석표에 체크만 하는 선생님","scene":"체육 선생님이 반별 출석표에 체크만 해요. 노랑 반 학생이 1명 왔든 2명 왔든 '노랑 반 왔음' 칸에 체크 하나만 남겨요. 그래서 출석표만 보고는 몇 명이 왔는지 알 수 없어요. 최대 풀링도 어떤 색이 있었는지만 남기고 몇 개였는지는 지워요.","map":[["출석표에 체크하기","**최대 풀링(Max pooling)**"],["왔는지 안 왔는지만 남음","색 종류만 남음"],["몇 명 왔는지","사라지는 개수 정보"]]}],"pass2":[{"kind":"look","head":"슬라이드 글자 짚기","boxes":[{"x":0.03,"y":0.15,"w":0.54,"h":0.08,"say":"**GraphSAGE** 는 **최대 풀링(Max pooling)** 모델. Hamilton 외, NeurIPS 2017."},{"x":0.07,"y":0.24,"w":0.4,"h":0.07,"say":"순서가 중요해요. 쪽지 한 장씩 따로 **MLP** 에 넣고, 칸별 최댓값을 뽑아요."},{"x":0.07,"y":0.33,"w":0.83,"h":0.15,"say":"Xu 외 ICLR 2019 정리: 색 종류가 같은 서로 다른 **멀티셋(Multiset)** 은 구별 못 해요."},{"x":0.2,"y":0.56,"w":0.6,"h":0.26,"say":"실패 사례 봉투 셋: 노랑1 파랑1, 노랑2 파랑2, 노랑2 파랑1. 집합으로는 셋 다 {노랑, 파랑}."}]},{"kind":"points","head":"정리를 쉬운 말로","items":["**MLP** 는 쪽지를 한 장씩 따로 가공해요. 같은 노랑 두 장은 같은 결과 두 장이에요.","같은 값을 두 번 넣어도 최댓값은 그대로예요. $\\max(3, 3) = 3$","'same set of distinct colors' 는 '색 종류 집합이 같다'는 뜻이에요.","그래서 **GraphSAGE** 의 집계는 **단사(Injective)** 가 아니에요."]},{"kind":"compare","head":"세 봉투를 세 가지로 요약 (노랑 (1,0), 파랑 (0,1))","cols":["봉투","합","평균","최댓값"],"rows":[["① 노랑 1, 파랑 1","(1, 1)","(0.5, 0.5)","(1, 1)"],["② 노랑 2, 파랑 2","(2, 2)","(0.5, 0.5)","(1, 1)"],["③ 노랑 2, 파랑 1","(2, 1)","(0.67, 0.33)","(1, 1)"]]},{"kind":"say","lines":["세로로 읽어요. 합은 셋 다 달라요.","평균은 ①, ② 가 같고 ③ 만 달라요. 최댓값은 셋 다 같아요.","③ 은 평균은 구별하고 최댓값은 못 하는 봉투라서, 최댓값이 더 약하다는 걸 보여 줘요."]},{"kind":"prof","when":"3주차 화요일 수업","lines":["GraphSAGE 는 최대 풀링을 쓰는데,","최대 풀링은 평균 풀링보다도 표현력이 좋지 않다고 했어요."]},{"kind":"mining","src":"마이닝 9강 Graph Kernels","lines":["동형 불변량으로 노드 수, 엣지 수, 차수 구성을 배웠어요.","**차수(Degree)** 는 친구 수예요.","최댓값 집계는 봉투 크기를 못 보니 가장 기본 불변량인 차수조차 놓쳐요."]}],"pass3":[{"kind":"check","q":"**최대 풀링(Max pooling)** 이 구별하지 못하는 봉투 쌍은?","choices":["{노랑} 과 {파랑}","{노랑, 파랑} 과 {노랑, 노랑, 파랑}","{노랑, 노랑} 과 {노랑, 파랑}"],"a":1,"why":"둘 다 색 종류 집합이 {노랑, 파랑} 이라서 칸별 최댓값이 (1, 1) 로 같아요."},{"kind":"warn","head":"흔한 실수","items":["**MLP** 를 앞에 붙여도 해결 안 돼요. 한 장씩 가공할 뿐 같은 쪽지가 몇 장인지는 세지 않아요.","'set of distinct colors' 는 색 개수가 아니라 색 종류 집합이에요."]}],"pass4":[]},{"p":35,"title":"최대 풀링 계산: 셋 다 (1, 1)","terms":["GraphSAGE","Max pooling","MLP","Injective","One-hot encoding","Sum aggregation"],"pass1":[{"kind":"say","lines":["앞 쪽의 봉투 세 개를 실제로 최대 풀링에 넣어 보는 쪽이에요.","셋 다 노랑과 파랑이 적어도 하나씩 들어 있어서, 가장 큰 값을 뽑은 결과가 세 봉투 모두 똑같아요.","서로 다른 봉투가 같은 결과를 받았으니 **최대 풀링(Max pooling)** 은 **단사(Injective)** 가 아니에요.","단사는 '다른 입력에는 반드시 다른 결과' 라는 뜻이었죠."]},{"kind":"look","head":"그림을 아래에서 위로","boxes":[{"x":0.29,"y":0.8,"w":0.55,"h":0.1,"say":"맨 아래가 원래 봉투 세 개예요."},{"x":0.15,"y":0.4,"w":0.64,"h":0.13,"say":"가장 큰 값을 뽑은 결과예요. 세 봉투의 결과가 모두 같아요."},{"x":0.46,"y":0.34,"w":0.23,"h":0.06,"say":"그래서 빨간 글씨로 '같은 출력!' 이라고 적혀 있어요."}]}],"pass2":[{"kind":"look","head":"그림을 아래에서 위로","boxes":[{"x":0.29,"y":0.8,"w":0.55,"h":0.1,"say":"맨 아래가 원래 봉투 셋: {노랑, 파랑}, {노랑, 노랑, 파랑, 파랑}, {노랑, 노랑, 파랑}."},{"x":0.25,"y":0.72,"w":0.59,"h":0.09,"say":"초록 화살표가 공마다 하나씩. 쪽지 한 장마다 따로 **MLP** 를 쓴다는 뜻이에요."},{"x":0.15,"y":0.54,"w":0.69,"h":0.21,"say":"노랑은 분홍, 파랑은 연두로 가공됐어요. 단순화를 위해 결과를 **원-핫 인코딩(One-hot encoding)** 이라 가정해요."},{"x":0.15,"y":0.4,"w":0.64,"h":0.13,"say":"원소별 **최대 풀링(Max pooling)** 결과는 세 봉투 모두 $(1, 1)$."},{"x":0.46,"y":0.34,"w":0.23,"h":0.06,"say":"그래서 빨간 글씨 '같은 출력!'이에요."}]},{"kind":"formula","head":"원소별 최댓값 식","tex":"\\mathrm{Max}\\left(\\begin{bmatrix} a_1 \\\\ a_2 \\end{bmatrix}, \\begin{bmatrix} b_1 \\\\ b_2 \\end{bmatrix}, \\dots\\right) = \\begin{bmatrix} \\max(a_1, b_1, \\dots) \\\\ \\max(a_2, b_2, \\dots) \\end{bmatrix}","parts":[{"sym":"a_1, b_1","say":"각 쪽지 벡터의 첫째 칸 (분홍 칸)"},{"sym":"a_2, b_2","say":"각 쪽지 벡터의 둘째 칸 (연두 칸)"},{"sym":"\\max(a_1, b_1, \\dots)","say":"첫째 칸들 중 가장 큰 값"}],"whole":"칸마다 따로 줄 세워 가장 큰 값만 뽑는다. 원-핫이면 '적어도 하나 있다'는 뜻일 뿐이에요."},{"kind":"steps","head":"봉투 셋 손계산","steps":["봉투 ①: 첫째 칸 $\\max(1, 0) = 1$, 둘째 칸 $\\max(0, 1) = 1$. 결과 $(1, 1)$","봉투 ②: $\\max(1, 1, 0, 0) = 1$, $\\max(0, 0, 1, 1) = 1$. 결과 $(1, 1)$","봉투 ③: $\\max(1, 1, 0) = 1$, $\\max(0, 0, 1) = 1$. 결과 $(1, 1)$","**MLP** 가 노랑을 $(3, 1)$, 파랑을 $(0, 2)$ 로 바꿔도 셋 다 $(3, 2)$ 예요.","**합 집계(Sum aggregation)** 로 모으면 ① $(1, 1)$, ② $(2, 2)$, ③ $(2, 1)$ 로 전부 달라요."],"answer":"최댓값은 셋 다 같고, 합은 셋 다 달라요."},{"kind":"prof","when":"3주차 화요일 수업","lines":["$(1, 0)$ 과 $(0, 1)$ 에 최대 풀링을 하면 $(1, 1)$,","다른 경우들도 모두 $(1, 1)$ 이 된다고 했어요. 평균보다도 못해요."]}],"pass3":[{"kind":"warn","head":"헷갈리기 쉬운 점","items":["분홍, 연두는 새 이웃이 아니라 노랑, 파랑이 **MLP** 를 지난 모습이에요.","원소별 최댓값은 '가장 큰 벡터 하나 고르기'가 아니에요. 칸마다 따로 골라요.","2023 가을 기말 5번의 Max 전역 풀링은 그래프 전체를 모으는 **리드아웃(Readout)** 자리예요. 계산법과 약점은 같고, 숫자는 p.43 에서 풀어요."]},{"kind":"english","head":"서술형 한 줄","en":"Max pooling (GraphSAGE) fails on multisets with the same set of distinct elements.","ko":"최대 풀링(GraphSAGE)은 원소 종류가 같은 멀티셋에서 실패한다."}],"pass4":[{"kind":"pyterm","name":"max(dim=0).values","say":["**예시 코드**예요. 노트북에는 GraphSAGE 코드가 없어요. 텐서 x, y 는 p.33 과 같아요.","`max(dim=0)` 은 칸별 최댓값과 그 위치를 함께 돌려줘요.","`.values` 로 최댓값만 꺼내요. 슬라이드의 원소별 **최대 풀링(Max pooling)** 과 짝이에요."],"example":"x = torch.tensor([[1., 0.], [0., 1.]])\ny = torch.tensor([[1., 0.], [1., 0.], [0., 1.], [0., 1.]])\nprint(x.max(dim=0).values, y.max(dim=0).values)","out":"tensor([1., 1.]) tensor([1., 1.])"}]},{"p":36,"title":"지금까지 정리: 표현력은 집계가 정한다","terms":["Expressive power","Neighbor aggregation","Multiset","Injective","GCN","GraphSAGE","Message passing"],"pass1":[{"kind":"say","lines":["여기서 지금까지 한 이야기를 한 번 정리해요."]},{"kind":"points","head":"네 줄 정리","items":["GNN 의 구별하는 힘, **표현력(Expressive power)** 은 모으는 방법인 **이웃 집계(Neighbor aggregation)** 가 정해요.","모으는 방법에 들어가는 입력은 순서 없이 개수를 세는 봉투, **멀티셋(Multiset)** 이에요.","평균으로 모으는 **GCN** 과 최댓값으로 모으는 **GraphSAGE** 는 아주 단순한 봉투도 헷갈려요.","그래서 둘 다 구별을 가장 잘하는 GNN 은 아니에요."]}],"pass2":[{"kind":"look","head":"핵심 정리 네 줄","boxes":[{"x":0.03,"y":0.15,"w":0.28,"h":0.07,"say":"우리는 **GNN 의 표현력(Expressive power)** 을 분석했어요."},{"x":0.07,"y":0.33,"w":0.52,"h":0.07,"say":"첫째: 표현력은 **이웃 집계(Neighbor aggregation)** 함수가 정해요."},{"x":0.07,"y":0.49,"w":0.52,"h":0.06,"say":"둘째: 집계는 **멀티셋(Multiset)**, 즉 중복을 허용하는 집합 위의 함수예요."},{"x":0.07,"y":0.58,"w":0.83,"h":0.06,"say":"셋째: **GCN**, **GraphSAGE** 집계는 기본 멀티셋도 구별 못 하니 **단사(Injective)** 가 아니에요."},{"x":0.07,"y":0.73,"w":0.56,"h":0.06,"say":"넷째: 그래서 둘은 최대로 강력한 GNN 이 아니에요."}]},{"kind":"points","head":"네 줄은 하나의 논리 사슬","items":["고치기 단계는 요약본만 받아요. 그래서 병목은 **이웃 집계(Neighbor aggregation)** 예요.","집계 입력은 **멀티셋(Multiset)**. 순서는 무시하고 개수는 세요.","평균과 최댓값은 반례가 있으니 **단사(Injective)** 가 아니에요. 반례 하나면 충분해요.","그러니 **GCN**, **GraphSAGE** 는 최대로 강력한(maximally powerful) GNN 이 아니에요."]},{"kind":"say","lines":["지금까지 봉투를 A = {노랑, 파랑}, B = {노랑, 노랑, 파랑, 파랑},","C = {노랑, 노랑, 파랑} 이라고 하고 같은 값끼리 무리를 지어 볼게요.","무리 수가 많을수록 더 잘 구별하는 거예요."]},{"kind":"compare","head":"요약 방법별 같은 값 무리","cols":["요약 방법","같은 값 무리","무리 수"],"rows":[["합","{A}, {B}, {C}","3"],["평균","{A, B}, {C}","2"],["최댓값","{A, B, C}","1"]]},{"kind":"prof","when":"3주차 화요일 수업","lines":["표현력 순서: 최대가 가장 나쁘고, 그다음 평균, 그나마 합이 가장 낫대요.","단, 합이 모든 함수 중 최고라는 뜻은 아니래요.","계산이 거의 없는 단순한 함수들끼리 비교하면 합이 낫다는 뜻이에요."]}],"pass3":[{"kind":"check","q":"'**단사(Injective)**' 의 뜻으로 맞는 것은?","choices":["서로 다른 입력은 절대 같은 출력으로 보내지 않는다","모든 출력값이 한 번씩은 나온다","입력 순서를 바꾸면 출력도 바뀐다"],"a":0,"why":"단사는 '다른 입력, 같은 출력'이 없다는 뜻이에요. 반례 하나만 있어도 단사가 아니에요."},{"kind":"english","head":"서술형 뼈대: 왜 GCN, GraphSAGE 는 최강이 아닌가","en":"The expressive power of a GNN is determined by its neighbor aggregation function, which is a function over multisets. Since mean and max pooling are not injective, GCN and GraphSAGE are not maximally powerful.","ko":"GNN 의 표현력은 멀티셋 위의 함수인 이웃 집계가 정한다. 평균과 최대 풀링은 단사가 아니므로 GCN, GraphSAGE 는 최대로 강력하지 않다."},{"kind":"warn","head":"주의","items":["'최대로 강력하지 않다'는 '쓸모없다'가 아니에요. 구별 못 하는 경우가 존재한다는 뜻이에요.","이 비교는 **메시지 패싱(Message passing)** GNN 부류 안에서의 이야기예요."]}],"pass4":[]},{"p":37,"title":"단사 멀티셋 함수의 모양: Φ(Σ f(x))","terms":["Injective","Multiset","Sum aggregation","Non-linear function"],"pass1":[{"kind":"say","lines":["그럼 정보를 하나도 잃지 않는, 즉 **단사(Injective)** 인 모으기는 어떻게 생겼을까요?","수학자들이 답을 찾아 증명했어요. 세 단계로 된 모양이에요."]},{"kind":"points","head":"단사인 모으기의 세 단계","items":["첫째, 봉투 속 쪽지를 한 장씩 같은 방법으로 바꿔 적어요.","둘째, 바꿔 적은 것을 전부 더해요. 평균도 최댓값도 아닌 **합 집계(Sum aggregation)** 예요.","셋째, 더한 결과를 마지막으로 한 번 더 정리해요.","가운데가 합이라는 점이 가장 중요해요. 합은 몇 장이었는지를 지우지 않거든요."]},{"kind":"analogy","head":"번역해서 공책에 모두 옮겨 적기","scene":"외국 친구들에게서 편지가 여러 통 왔어요. 먼저 편지를 한 통씩 같은 번역기로 우리말로 바꿔요. 그다음 번역한 내용을 공책 한 쪽에 빠짐없이 모두 옮겨 적고, 마지막으로 그 쪽을 보고 깔끔하게 정리해요. 옮겨 적을 때 한 통도 빼먹지 않으니 몇 통이 왔는지도 그대로 남아요.","map":[["같은 번역기로 한 통씩 바꾸기","첫째 단계, 쪽지마다 같은 변환"],["공책에 빠짐없이 모두 옮겨 적기","**합 집계(Sum aggregation)**"],["마지막 정리","셋째 단계, 합을 한 번 더 변환"]]}],"pass2":[{"kind":"look","head":"정리와 식 주변 화살표","boxes":[{"x":0.03,"y":0.15,"w":0.47,"h":0.14,"say":"Xu 외 ICLR 2019 정리: 모든 **단사(Injective)** 멀티셋 함수는 아래 꼴로 쓸 수 있어요."},{"x":0.09,"y":0.44,"w":0.36,"h":0.1,"say":"왼쪽 화살표: 바깥 $\\Phi$ 는 어떤 **비선형 함수(Non-linear function)** 예요."},{"x":0.5,"y":0.3,"w":0.33,"h":0.25,"say":"오른쪽 위 화살표: 안쪽 $f$ 도 어떤 **비선형 함수(Non-linear function)** 예요."},{"x":0.45,"y":0.43,"w":0.29,"h":0.3,"say":"주황 상자와 빨간 '합': **멀티셋(Multiset)** 위의 합이 제일 중요해요."},{"x":0.32,"y":0.74,"w":0.41,"h":0.14,"say":"예시: 노랑 1, 파랑 2 봉투는 $\\Phi(f(노랑) + f(파랑) + f(파랑))$. 파랑이 두 번 더해져요."}]},{"kind":"formula","head":"정리 식 기호 하나씩","tex":"\\Phi\\left(\\sum_{x\\in S} f(x)\\right)","parts":[{"sym":"S","say":"**멀티셋(Multiset)**. 이웃 특징 봉투"},{"sym":"x\\in S","say":"봉투 속 쪽지 한 장. 같은 쪽지 두 장이면 두 번"},{"sym":"f(x)","say":"쪽지 한 장을 가공한 벡터"},{"sym":"\\sum_{x\\in S}","say":"봉투 속 모든 쪽지를 더하기"},{"sym":"\\Phi","say":"합을 한 번 더 가공하는 함수 (대문자 파이)"}],"whole":"봉투 속 쪽지를 한 장씩 f 로 번역하고, 모두 더하고, 그 합을 Φ 로 정리한다. 괄호 안쪽부터 계산해요."},{"kind":"figure","head":"f, 합, Φ 순서","svg":"<svg viewBox=\"0 0 480 270\" xmlns=\"http://www.w3.org/2000/svg\">\n<circle class=\"n2\" cx=\"50\" cy=\"60\" r=\"18\"/>\n<circle class=\"n3\" cx=\"50\" cy=\"135\" r=\"18\"/>\n<circle class=\"n3\" cx=\"50\" cy=\"210\" r=\"18\"/>\n<line class=\"e b1\" x1=\"70\" y1=\"60\" x2=\"110\" y2=\"60\"/>\n<line class=\"e b1\" x1=\"70\" y1=\"135\" x2=\"110\" y2=\"135\"/>\n<line class=\"e b1\" x1=\"70\" y1=\"210\" x2=\"110\" y2=\"210\"/>\n<rect class=\"box b1\" x=\"112\" y=\"44\" width=\"40\" height=\"32\" rx=\"6\"/>\n<rect class=\"box b1\" x=\"112\" y=\"119\" width=\"40\" height=\"32\" rx=\"6\"/>\n<rect class=\"box b1\" x=\"112\" y=\"194\" width=\"40\" height=\"32\" rx=\"6\"/>\n<text class=\"tb b1\" x=\"132\" y=\"66\" font-size=\"18\" text-anchor=\"middle\">f<\/text>\n<text class=\"tb b1\" x=\"132\" y=\"141\" font-size=\"18\" text-anchor=\"middle\">f<\/text>\n<text class=\"tb b1\" x=\"132\" y=\"216\" font-size=\"18\" text-anchor=\"middle\">f<\/text>\n<text class=\"t b1\" x=\"198\" y=\"66\" font-size=\"15\" text-anchor=\"middle\">(1, 0)<\/text>\n<text class=\"t b1\" x=\"198\" y=\"141\" font-size=\"15\" text-anchor=\"middle\">(0, 1)<\/text>\n<text class=\"t b1\" x=\"198\" y=\"216\" font-size=\"15\" text-anchor=\"middle\">(0, 1)<\/text>\n<line class=\"e2 b2\" x1=\"235\" y1=\"62\" x2=\"290\" y2=\"125\"/>\n<line class=\"e2 b2\" x1=\"235\" y1=\"135\" x2=\"290\" y2=\"135\"/>\n<line class=\"e2 b2\" x1=\"235\" y1=\"208\" x2=\"290\" y2=\"145\"/>\n<rect class=\"box2 b2\" x=\"292\" y=\"115\" width=\"40\" height=\"40\" rx=\"8\"/>\n<text class=\"tb b2\" x=\"312\" y=\"142\" font-size=\"20\" text-anchor=\"middle\">Σ<\/text>\n<text class=\"t b2\" x=\"312\" y=\"180\" font-size=\"15\" text-anchor=\"middle\">(1, 2)<\/text>\n<line class=\"e b3\" x1=\"334\" y1=\"135\" x2=\"370\" y2=\"135\"/>\n<polygon class=\"arrow b3\" points=\"370,129 380,135 370,141\"/>\n<rect class=\"box b3\" x=\"382\" y=\"117\" width=\"40\" height=\"36\" rx=\"6\"/>\n<text class=\"tb b3\" x=\"402\" y=\"142\" font-size=\"18\" text-anchor=\"middle\">Φ<\/text>\n<text class=\"tm b3\" x=\"240\" y=\"258\" font-size=\"14\" text-anchor=\"middle\">f 는 한 장씩, 합은 모두 함께, Φ 는 마지막 한 번<\/text>\n<\/svg>","caption":"진한 공 노랑 1개, 다른 색 공 파랑 2개. 합 (1, 2) 에 개수가 그대로 남아요.","builds":3},{"kind":"steps","head":"왜 f 가 필요할까?","steps":["그냥 합 ($f(x)=x$): $1+3=4$, $2+2=4$. 같아서 구별 못 해요.","$f(x)=x^2$ 후 합: $1+9=10$, $4+4=8$. 구별해요.","$f(x)=10^x$ 후 합: $1010$ 과 $200$. 자릿수로 원래 봉투를 되살릴 수 있어요.","되살릴 수 있으면 서로 다른 봉투가 같은 합이 될 수 없어요. 즉 **단사(Injective)**.","$\\Phi(z) = 2z + 1$ 이면 $2021$ 과 $401$ 로 여전히 달라요."],"answer":"알맞은 f 를 고르면 합이 봉투 정보를 지켜요.","given":"쪽지가 숫자 하나. $S_1 = \\{\\{1, 3\\}\\}$, $S_2 = \\{\\{2, 2\\}\\}$"},{"kind":"prof","when":"2주차 화요일 수업","lines":["교수님은 표현력이 가장 좋은 방법은 합(summation)이라고 딱 잘라 말했어요.","이 정리가 그 말의 이론 버전이에요. 단사 집계는 모두 합을 가운데에 둬요."]}],"pass3":[{"kind":"check","q":"$\\Phi\\left(\\sum_{x\\in S} f(x)\\right)$ 에서 가운데 연산은?","choices":["평균","최댓값","합"],"a":2,"why":"가운데가 **합 집계(Sum aggregation)** 라서 순서는 무시하고 개수는 살아남아요."},{"kind":"warn","head":"주의","items":["아무 $f$, $\\Phi$ 나 넣으면 단사라는 뜻이 아니에요. $f(x)=x$ 는 실패했죠.","원 논문에는 '특징 값이 셀 수 있는(countable) 범위, 봉투 크기 상한' 조건이 붙어요. p.44 의 'X 가 가산일 때'예요."]}],"pass4":[]},{"p":38,"title":"목표: 가장 표현력 있는 GNN 설계","terms":["Message passing","Injective","Neighbor aggregation","Multiset","Expressive power"],"pass1":[{"kind":"say","lines":["목표는 이웃에게 정보를 받아 모으는 GNN, 곧 **메시지 패싱(Message passing)** GNN 중에서 가장 잘 구별하는 모델이에요.","방법은 앞 쪽에서 본 **단사(Injective)** 모으기를 신경망으로 만드는 거예요.","첫째 단계와 셋째 단계의 정확한 모양은 모르니까, 학습하는 신경망에게 맡겨요."]},{"kind":"analogy","head":"레시피 없이 찌개 맛 따라 하기","scene":"엄마표 김치찌개 맛을 따라 하고 싶은데 레시피가 없어요. 그래서 조금 만들어 맛보고, 엄마 찌개와 비교해 간을 고치는 일을 계속 반복해요. 반복하다 보면 레시피를 몰라도 거의 같은 맛을 내게 돼요. 신경망도 정답 모양을 모를 때 이렇게 연습으로 흉내 내요.","map":[["레시피를 모르는 찌개","정확한 모양을 모르는 첫째, 셋째 단계"],["맛보고 고치기를 반복","신경망의 학습"]]}],"pass2":[{"kind":"look","head":"세 줄 방향 전환","boxes":[{"x":0.03,"y":0.15,"w":0.62,"h":0.07,"say":"목표: **메시지 패싱(Message passing)** GNN 부류 안에서 최대로 강력한 GNN."},{"x":0.03,"y":0.25,"w":0.57,"h":0.07,"say":"방법: **멀티셋(Multiset)** 위의 **단사(Injective)** **이웃 집계(Neighbor aggregation)** 함수를 설계."},{"x":0.03,"y":0.4,"w":0.58,"h":0.07,"say":"p.37 의 $f$, $\\Phi$ 모양을 모르니 학습하는 신경망으로 흉내 내요(모델링)."}]},{"kind":"compare","head":"세 집계 채점표","cols":["집계","대표 모델","단사?","목표 통과?"],"rows":[["평균","GCN","아님","탈락"],["최댓값","GraphSAGE","아님","탈락"],["f 후 합 후 Φ","다음에 나올 GIN","가능","합격"]]},{"kind":"figure","head":"지금까지의 논리 사슬","svg":"<svg viewBox=\"0 0 480 270\" xmlns=\"http://www.w3.org/2000/svg\">\n<rect class=\"box\" x=\"70\" y=\"10\" width=\"300\" height=\"44\" rx=\"8\"/>\n<text class=\"t\" x=\"220\" y=\"38\" font-size=\"15\" text-anchor=\"middle\">목표: 메시지 패싱 GNN 중 최강<\/text>\n<line class=\"e b1\" x1=\"220\" y1=\"54\" x2=\"220\" y2=\"72\"/>\n<rect class=\"box2 b1\" x=\"70\" y=\"72\" width=\"300\" height=\"44\" rx=\"8\"/>\n<text class=\"t b1\" x=\"220\" y=\"100\" font-size=\"15\" text-anchor=\"middle\">집계를 멀티셋 위 단사 함수로<\/text>\n<text class=\"tm b1\" x=\"385\" y=\"100\" font-size=\"14\">왜?<\/text>\n<line class=\"e b2\" x1=\"220\" y1=\"116\" x2=\"220\" y2=\"134\"/>\n<rect class=\"box b2\" x=\"70\" y=\"134\" width=\"300\" height=\"44\" rx=\"8\"/>\n<text class=\"t b2\" x=\"220\" y=\"162\" font-size=\"15\" text-anchor=\"middle\">단사 함수는 Φ(Σ f(x)) 꼴<\/text>\n<text class=\"tm b2\" x=\"385\" y=\"162\" font-size=\"14\">어떻게?<\/text>\n<line class=\"e b3\" x1=\"220\" y1=\"178\" x2=\"220\" y2=\"196\"/>\n<rect class=\"box2 b3\" x=\"70\" y=\"196\" width=\"300\" height=\"44\" rx=\"8\"/>\n<text class=\"t b3\" x=\"220\" y=\"224\" font-size=\"15\" text-anchor=\"middle\">f 와 Φ 를 MLP 로 (p.40, p.41)<\/text>\n<text class=\"tm b3\" x=\"385\" y=\"224\" font-size=\"14\">구현<\/text>\n<\/svg>","caption":"목표에서 출발해 'MLP 로 f 와 Φ 만들기'까지 내려가요.","builds":3}],"pass3":[{"kind":"warn","head":"주의","items":["'최대로 강력한'은 메시지 패싱 방식 안에서 최고라는 뜻이에요. 모든 그래프를 구별한다는 뜻은 아니에요.","층을 많이 쌓거나 $W$ 를 키워도, 집계가 단사가 아니면 **표현력(Expressive power)** 최강이 되지 않아요."]}],"pass4":[]},{"p":39,"title":"증명 직관: 원-핫을 더하면 개수표","terms":["One-hot encoding","Injective","Histogram","Multiset","WL graph kernel"],"pass1":[{"kind":"say","lines":["왜 합이 정보를 지키는지 쉬운 경우로 볼게요.","쪽지를 **원-핫 인코딩(One-hot encoding)**, 곧 '자기 색 칸에만 1, 나머지 칸은 0' 으로 적었다고 해 봐요.","이걸 전부 더하면 칸마다 그 색이 몇 장인지 적힌 개수표가 돼요. 이 개수표를 **히스토그램(Histogram)** 이라고 해요.","개수표만 보면 봉투 속을 그대로 되살릴 수 있으니, 합은 정보를 잃지 않아요."]},{"kind":"look","head":"아래 두 줄","boxes":[{"x":0.34,"y":0.69,"w":0.27,"h":0.13,"say":"윗줄은 노랑 1장, 파랑 2장이 든 봉투를 쪽지 한 장씩 적은 모습이에요."},{"x":0.33,"y":0.81,"w":0.33,"h":0.1,"say":"아랫줄은 그걸 모두 더한 결과예요. 노랑 칸에는 노랑 장수, 파랑 칸에는 파랑 장수가 남아요."}]},{"kind":"analogy","head":"칠판 스티커 투표","scene":"반 친구들이 좋아하는 과일에 스티커를 붙여요. 칠판에 사과 칸과 귤 칸이 있고, 한 사람은 자기가 고른 칸에만 스티커 한 장을 붙여요. 다 붙이고 나면 칸마다 스티커 수가 곧 그 과일을 고른 사람 수예요. 칠판만 봐도 과일마다 몇 명이 골랐는지 정확히 알 수 있죠.","map":[["한 칸에만 붙이는 스티커 한 장","원-핫으로 적은 쪽지 한 장"],["칸마다 쌓인 스티커 수","합한 결과, **히스토그램(Histogram)**"],["칠판만 보고도 알 수 있음","합은 봉투 정보를 잃지 않음"]]}],"pass2":[{"kind":"look","head":"증명 직관 읽기","boxes":[{"x":0.03,"y":0.15,"w":0.8,"h":0.15,"say":"$f$ 는 색의 **원-핫 인코딩(One-hot encoding)** 을 만들고, 합하면 **멀티셋(Multiset)** 정보가 모두 보존돼요."},{"x":0.4,"y":0.39,"w":0.19,"h":0.22,"say":"식은 p.37 과 같은 $\\Phi\\left(\\sum_{x\\in S} f(x)\\right)$ 예요."},{"x":0.34,"y":0.69,"w":0.27,"h":0.13,"say":"윗줄: 노랑 1, 파랑 2 봉투. 빨간 중괄호가 각 $f$ 를 아랫줄 벡터와 짝지어요."},{"x":0.33,"y":0.81,"w":0.33,"h":0.1,"say":"아랫줄: $(1,0) + (0,1) + (0,1) = (1,2)$. 노랑 1개, 파랑 2개예요."}]},{"kind":"steps","head":"개수표 만들기","steps":["노랑 쪽지는 $(1, 0)$, 파랑 쪽지 두 장은 $(0, 1)$, $(0, 1)$ 이에요.","첫째 칸: $1 + 0 + 0 = 1$ 은 노랑 개수예요.","둘째 칸: $0 + 1 + 1 = 2$ 는 파랑 개수예요.","원-핫은 자기 색 칸에만 1 이라, 더할 때마다 그 칸이 1씩 올라가요."],"answer":"합 (1, 2) = 노랑 1개, 파랑 2개. 이게 **히스토그램(Histogram)**","given":"봉투: 노랑 1, 파랑 2. 노랑 $(1,0)$, 파랑 $(0,1)$"},{"kind":"compare","head":"작은 봉투 전부 비교","cols":["봉투","합","평균","최댓값"],"rows":[["{노랑}","(1, 0)","(1, 0)","(1, 0)"],["{노랑, 노랑}","(2, 0)","(1, 0)","(1, 0)"],["{노랑, 파랑}","(1, 1)","(0.5, 0.5)","(1, 1)"],["{파랑}","(0, 1)","(0, 1)","(0, 1)"],["{파랑, 파랑}","(0, 2)","(0, 1)","(0, 1)"]]},{"kind":"say","lines":["합 열은 다섯 값이 전부 달라요.","평균과 최댓값은 {노랑} 과 {노랑, 노랑} 이 같아졌어요.","합 (2, 0) 만 받아도 원래 봉투가 {노랑, 노랑} 이라고 확실히 알아요."]},{"kind":"mining","src":"마이닝 9강 Graph Kernels","lines":["**WL 그래프 커널(WL graph kernel)** 은 색칠 후 색마다 노드가 몇 개인지 셌어요.","그 색별 개수 세기가 원-핫을 더한 개수표와 같은 일이에요."]}],"pass3":[{"kind":"check","q":"원-핫 $(1,0)$, $(1,0)$, $(0,1)$ 을 모두 합하면?","choices":["(1, 1)","(2, 1)","(0.67, 0.33)"],"a":1,"why":"첫째 칸 1+1+0 = 2, 둘째 칸 0+0+1 = 1. 노랑 2개, 파랑 1개라는 개수표예요."},{"kind":"english","head":"서술형 한 줄","en":"Summing one-hot vectors gives the count of each color, from which the original multiset can be recovered.","ko":"원-핫 벡터를 더하면 색별 개수가 나오고, 그것으로 원래 멀티셋을 되살릴 수 있다."},{"kind":"warn","head":"주의","items":["원-핫은 '이런 $f$ 가 존재한다'를 보여 주는 예시예요. 실제로는 $f$ 를 학습시켜요(p.40, p.41).","$\\Phi$ 도 서로 다른 개수표를 뭉개지 않아야 전체가 단사로 유지돼요."]}],"pass4":[{"kind":"pyterm","name":"딕셔너리(dict)","say":["`{키: 값}` 모양의 이름표 사전이에요. **예시 코드**로 먼저 볼게요.","노트북의 `colors` 는 {노드 번호: 색 번호} 사전이에요.","`.values()` 는 값들만, `.items()` 는 (키, 값) 쌍을 꺼내요."],"example":"colors = {0: 1, 1: 1, 2: 2}\nprint(list(colors.values()))","out":"[1, 1, 2]"},{"kind":"pyterm","name":"Counter (개수 세기)","say":["노트북 셀 5 에서 `from collections import Counter` 로 불러와요.","`import` 는 파이썬 도구 상자에서 도구를 꺼내 오는 줄이에요.","`Counter` 는 같은 것이 몇 번 나오는지 세요. 원-핫을 더한 **히스토그램(Histogram)** 과 같은 일이에요."],"example":"from collections import Counter\nprint(Counter(['yellow', 'blue', 'blue']))","out":"Counter({'blue': 2, 'yellow': 1})"},{"kind":"code","head":"색 히스토그램 함수 (1/3)","file":"Sample_Code_3.ipynb 셀 14 (1/3)","code":"def aggregate(G, colors):\n    \"\"\"Step 2: aggregated color of every node = (own color, sorted tuple of neighbor colors).\"\"\"\n    return {v: (colors[v], tuple(sorted(colors[u] for u in G[v]))) for v in G}\n\n\ndef wl_refine(graphs, num_iterations=3):\n    \"\"\"\n    Color refinement run jointly on a list of graphs with one shared HASH table.\n\n    Returns `rounds`, where rounds[l] is a dict:\n        'colors' : [{node: color} per graph]             colors after round l\n        'agg'    : [{node: aggregated color} per graph]  what was hashed in round l\n        'table'  : {aggregated color: new color}         the HASH table of round l\n    rounds[0] is the initial coloring: every node gets color 1.\n    \"\"\"\n    rounds = [{'colors': [{v: 1 for v in G} for G in graphs], 'agg': None, 'table': {}}]\n    next_color = 2\n    for _ in range(num_iterations):\n        agg = [aggregate(G, c) for G, c in zip(graphs, rounds[-1]['colors'])]\n        # Step 3: injective hash. Every unseen aggregated color gets the next unused number.\n        # (Each round's inputs use fresh colors, so each round needs only its own table.)\n        table = {}\n        for a in agg:\n            for sig in a.values():\n                if sig not in table:\n                    table[sig] = next_color\n                    next_color += 1\n        colors = [{v: table[sig] for v, sig in a.items()} for a in agg]\n        rounds.append({'colors': colors, 'agg': agg, 'table': table})\n    return rounds\n","lines":[{"from":1,"to":4,"say":"aggregate 함수: 노드마다 (내 색, 이웃 색을 정렬해 묶은 튜플)을 만들어 사전으로 돌려줘요."},{"from":5,"to":15,"say":"wl_refine 함수의 이름과 설명이에요. 여러 그래프가 HASH 표를 같이 쓰며 색 정제를 하고 rounds 목록을 돌려준대요."},{"from":16,"to":17,"say":"0라운드: 모든 노드를 색 1 로 칠해 rounds 에 넣어요. 새 번호는 2 부터 줘요."},{"from":18,"to":19,"say":"라운드 수만큼 반복하며, 지난 라운드 색으로 모든 노드의 집계 색을 만들어요."},{"from":20,"to":27,"say":"주석 두 줄 뒤, 빈 사전 table 에 처음 보는 집계 색마다 다음 번호를 적어요. 같은 조합은 같은 번호예요."},{"from":28,"to":31,"say":"표에서 새 번호를 찾아 노드를 다시 칠하고, 이번 라운드 결과를 rounds 끝에 붙여요. 다 돌면 rounds 를 돌려줘요."}]},{"kind":"code","head":"색 히스토그램 함수 (2/3)","file":"Sample_Code_3.ipynb 셀 14 (2/3)","code":"\ndef color_histogram(colors):\n    \"\"\"How many nodes carry each color: the graph-level fingerprint.\"\"\"\n    return dict(sorted(Counter(colors.values()).items()))\n\n\ndef wl_report(rounds, names):\n    \"\"\"The WL test: compare the two graphs' color histograms round by round.\"\"\"\n    differ = False\n    for l, r in enumerate(rounds):\n        h1, h2 = (color_histogram(c) for c in r['colors'])\n        differ = differ or h1 != h2\n        print(f\"round {l}:  {names[0]} {str(h1):<34s} {'==' if h1 == h2 else '!='}  {names[1]} {h2}\")\n    print('\\n→ NON-ISOMORPHIC (the histograms differ)' if differ else\n          '\\n→ INCONCLUSIVE (the histograms are always equal)')\n\n\n# ---- drawing -------------------------------------------------------------------------\ndef fmt_agg(sig):\n    \"\"\"(3, (3, 4)) -> '3,{3,4}'\"\"\"\n    own, nbrs = sig\n    return f\"{own},{{{','.join(map(str, nbrs))}}}\"\n\n\ndef draw_aggregated(G, pos, ax, colors, agg, title=None):\n    \"\"\"Each node is a box showing its aggregated color, filled with its current color.\"\"\"\n    nx.draw_networkx_edges(G, pos, ax=ax, edge_color=C_EDGE, width=2.0)\n    for v in G:\n        f = color_of(colors[v])\n        ax.text(*pos[v], fmt_agg(agg[v]), ha='center', va='center', fontsize=10, color=ink(f),\n                bbox=dict(boxstyle='round,pad=0.35', fc=f, ec=C_DARK, lw=1.2))\n    xs, ys = zip(*pos.values())\n    ax.set_xlim(min(xs) - 0.5, max(xs) + 0.5)\n    ax.set_ylim(min(ys) - 0.4, max(ys) + 0.4)\n    if title:\n        ax.set_title(title)\n    ax.set_axis_off()\n","lines":[{"from":2,"to":2,"say":"`def` 는 함수를 만드는 말이에요. 이름은 color_histogram, 입력은 colors 사전이에요."},{"from":3,"to":3,"say":"세 따옴표 줄은 설명문(docstring)이에요. 실행에는 영향이 없어요."},{"from":4,"to":4,"say":"`colors.values()` 로 색만 꺼내 `Counter` 로 세고, `sorted` 로 색 번호 순 정렬, `dict` 로 사전을 만들어 돌려줘요(`return`)."},{"from":6,"to":16,"say":"wl_report 함수: 라운드마다 두 그래프의 색 개수표를 비교해 == 또는 != 를 출력하고, 마지막에 판정을 알려 줘요."},{"from":17,"to":23,"say":"그리기 부분 시작이에요. fmt_agg 는 (3, (3, 4)) 같은 집계 색을 '3,{3,4}' 글자로 바꿔요."},{"from":24,"to":38,"say":"draw_aggregated 함수: 노드마다 집계 색 글자를 지금 색으로 칠한 상자에 적어 그려요."}],"link":"슬라이드의 원-핫 합 $(1, 2)$ 처럼, 그래프 전체 노드 색의 개수표를 만들어요."},{"kind":"code","head":"색 히스토그램 함수 (3/3)","file":"Sample_Code_3.ipynb 셀 14 (3/3)","code":"\ndef draw_hash_table(ax, table, title):\n    tab = ax.table(cellText=[[fmt_agg(sig), c] for sig, c in table.items()],\n                   colLabels=['aggregated color', 'new color'], loc='center', cellLoc='center')\n    tab.auto_set_font_size(False); tab.set_fontsize(11); tab.scale(1, 1.7)\n    for j in range(2):                                   # header row\n        tab[0, j].set_facecolor(C_DARK)\n        tab[0, j].get_text().set(color='white', fontweight='bold')\n    for i, c in enumerate(table.values(), start=1):      # paint each new color\n        tab[i, 1].set_facecolor(color_of(c))\n        tab[i, 1].get_text().set(color=ink(color_of(c)), fontweight='bold')\n    ax.set_title(title)\n    ax.set_axis_off()\n\n\ndef show_initial(graphs, names, positions, rounds):\n    fig, axes = plt.subplots(1, len(graphs), figsize=(11, 3))\n    for ax, G, name, pos, c in zip(axes, graphs, names, positions, rounds[0]['colors']):\n        draw_graph(G, pos, ax, colors=c, labels='color', title=name)\n    fig.suptitle('Step 1 - Assign initial colors: every node gets color 1',\n                 fontsize=13, fontweight='bold')\n    plt.tight_layout(); plt.show()\n\n\ndef show_round(graphs, names, positions, rounds, l):\n    \"\"\"One round, left to right: aggregated colors -> HASH table -> new colors.\"\"\"\n    r, prev = rounds[l], rounds[l - 1]['colors']\n    fig = plt.figure(figsize=(15, 5.6))\n    gs = fig.add_gridspec(2, 3, width_ratios=[1, 0.75, 1])\n    for i, (G, name, pos) in enumerate(zip(graphs, names, positions)):\n        draw_aggregated(G, pos, fig.add_subplot(gs[i, 0]), prev[i], r['agg'][i],\n                        title=f'{name}: aggregated colors')\n        draw_graph(G, pos, fig.add_subplot(gs[i, 2]), colors=r['colors'][i], labels='color',\n                   title=f'{name}: new colors')\n    draw_hash_table(fig.add_subplot(gs[:, 1]), r['table'], title=f'HASH table (round {l})')\n    fig.suptitle(f'Round {l}:   Step 2 - aggregate neighboring colors   →   '\n                 f'Step 3 - injectively hash   →   new colors', fontsize=13, fontweight='bold')\n    plt.tight_layout(); plt.show()","lines":[{"from":1,"to":14,"say":"draw_hash_table 함수: HASH 표를 '집계 색, 새 색' 두 열짜리 표 그림으로 그리고 새 색 칸을 그 색으로 칠해요."},{"from":15,"to":23,"say":"show_initial 함수: 모든 노드가 색 1 인 시작 그림을 그래프마다 그려요."},{"from":24,"to":38,"say":"show_round 함수: 한 라운드를 왼쪽 집계 색, 가운데 HASH 표, 오른쪽 새 색 순서로 한 장에 그려요."}]}]},{"p":40,"title":"보편 근사 정리: f 와 Φ 는 MLP 로","terms":["MLP","Universal Approximation Theorem","Non-linear function"],"pass1":[{"kind":"say","lines":["첫째 단계와 셋째 단계의 정확한 모양은 모르니, 작은 신경망인 **MLP** 로 두고 학습시켜요.","**MLP** 는 숫자를 곱하고, 한 번 구부리고, 다시 곱하는 계산을 겹쳐 쌓은 신경망이에요.","근거는 **보편 근사 정리(Universal Approximation Theorem)** 예요.","가운데 칸이 충분히 많으면, 가운데 층 하나짜리 MLP 로도 매끄러운 함수는 거의 다 흉내 낼 수 있다는 정리예요."]},{"kind":"look","head":"아래 MLP 그림","boxes":[{"x":0.29,"y":0.67,"w":0.44,"h":0.25,"say":"왼쪽에서 들어온 숫자가 넓은 가운데 층을 지나 오른쪽으로 나가요. 가운데가 넓다는 건 가운데 칸이 많다는 뜻이에요."}]},{"kind":"analogy","head":"빨대로 곡선 따라 만들기","scene":"미술 시간에 곡선 그림을 빨대로 따라 만든다고 해 봐요. 곧은 빨대 하나로는 곡선을 못 만들지만, 빨대를 여러 개 이어 마디마다 살짝 꺾으면 곡선과 거의 같은 모양이 돼요. 빨대를 많이 쓸수록 더 매끄럽게 따라 할 수 있어요. MLP 도 가운데 칸이 많을수록 원하는 함수를 더 똑같이 흉내 내요.","map":[["곧은 빨대","숫자를 곱하는 곧은 계산"],["마디에서 꺾기","구부리는 계산, **비선형 함수(Non-linear function)**"],["빨대 개수","MLP 가운데 칸의 수"]]}],"pass2":[{"kind":"look","head":"질문, 답, 정리, 그림","boxes":[{"x":0.03,"y":0.17,"w":0.43,"h":0.06,"say":"질문: p.37 식의 $\\Phi$ 와 $f$ 를 어떻게 모델링할까?"},{"x":0.03,"y":0.26,"w":0.29,"h":0.06,"say":"답: **다층 퍼셉트론(MLP)** 을 쓴다."},{"x":0.03,"y":0.35,"w":0.4,"h":0.06,"say":"근거: **보편 근사 정리(Universal Approximation Theorem)**, Hornik 외 1989."},{"x":0.06,"y":0.43,"w":0.63,"h":0.19,"say":"은닉 차원이 충분히 크고 적절한 **비선형 함수(Non-linear function)** 를 가진 은닉층 1개 MLP 는 어떤 연속 함수든 근사해요."},{"x":0.29,"y":0.67,"w":0.44,"h":0.25,"say":"그림: Input, $W_1$, 넓은 은닉층 $\\sigma$, $W_2$, Output. 가운데가 넓다 = 은닉 칸이 많다."}]},{"kind":"formula","head":"은닉층 1개 MLP 식","tex":"\\mathrm{MLP}(x) = W_2\\,\\sigma\\left(W_1 x\\right)","parts":[{"sym":"x","say":"입력 벡터 (들어오는 쪽지)"},{"sym":"W_1","say":"입력 칸 수를 은닉 칸 수로 바꾸는 행렬"},{"sym":"\\sigma","say":"칸마다 쓰는 **비선형 함수(Non-linear function)**. 합 기호 Σ 와 다른 소문자"},{"sym":"W_2","say":"은닉 칸 수를 출력 칸 수로 바꾸는 행렬"}],"whole":"W_1 로 나눠 읽고, σ 로 구부리고, W_2 로 다시 합친다. (편향 b 는 생략했어요)"},{"kind":"steps","head":"|x| 를 MLP 로 정확히 만들기","steps":["$x = 3$: $W_1 x = (3, -3)$, ReLU 후 $(3, 0)$, 두 칸 더해 $3$","$x = -2$: $W_1 x = (-2, 2)$, ReLU 후 $(0, 2)$, 더해 $2$","$x = 0$: 모두 $0$","곧은 선만으로는 V자를 못 만들지만 ReLU 로 한 번 꺾으니 만들어졌어요."],"answer":"MLP 출력이 정확히 |x|","given":"은닉 2칸, $\\sigma$ = ReLU, $W_1 = \\begin{bmatrix} 1 \\\\ -1 \\end{bmatrix}$, $W_2 = \\begin{bmatrix} 1 & 1 \\end{bmatrix}$"},{"kind":"figure","head":"은닉층 1개로 |x|","svg":"<svg viewBox=\"0 0 480 270\" xmlns=\"http://www.w3.org/2000/svg\">\n<line class=\"e b1\" x1=\"68\" y1=\"112\" x2=\"152\" y2=\"66\"/>\n<line class=\"e b1\" x1=\"68\" y1=\"128\" x2=\"152\" y2=\"174\"/>\n<text class=\"t b1\" x=\"96\" y=\"78\" font-size=\"14\" text-anchor=\"middle\">×1<\/text>\n<text class=\"t b1\" x=\"96\" y=\"172\" font-size=\"14\" text-anchor=\"middle\">×(-1)<\/text>\n<text class=\"tm b1\" x=\"170\" y=\"30\" font-size=\"14\" text-anchor=\"middle\">ReLU(x)<\/text>\n<text class=\"tm b1\" x=\"170\" y=\"222\" font-size=\"14\" text-anchor=\"middle\">ReLU(-x)<\/text>\n<line class=\"e b2\" x1=\"188\" y1=\"66\" x2=\"272\" y2=\"112\"/>\n<line class=\"e b2\" x1=\"188\" y1=\"174\" x2=\"272\" y2=\"128\"/>\n<text class=\"t b2\" x=\"244\" y=\"78\" font-size=\"14\" text-anchor=\"middle\">×1<\/text>\n<text class=\"t b2\" x=\"244\" y=\"172\" font-size=\"14\" text-anchor=\"middle\">×1<\/text>\n<circle class=\"n\" cx=\"50\" cy=\"120\" r=\"18\"/>\n<text class=\"tl\" x=\"50\" y=\"126\" font-size=\"16\" text-anchor=\"middle\">x<\/text>\n<circle class=\"n2 b1\" cx=\"170\" cy=\"60\" r=\"18\"/>\n<text class=\"tl b1\" x=\"170\" y=\"66\" font-size=\"16\" text-anchor=\"middle\">σ<\/text>\n<circle class=\"n2 b1\" cx=\"170\" cy=\"180\" r=\"18\"/>\n<text class=\"tl b1\" x=\"170\" y=\"186\" font-size=\"16\" text-anchor=\"middle\">σ<\/text>\n<circle class=\"n3 b2\" cx=\"290\" cy=\"120\" r=\"18\"/>\n<text class=\"tl b2\" x=\"290\" y=\"126\" font-size=\"16\" text-anchor=\"middle\">y<\/text>\n<line class=\"e b2\" x1=\"330\" y1=\"200\" x2=\"470\" y2=\"200\"/>\n<line class=\"e b2\" x1=\"400\" y1=\"70\" x2=\"400\" y2=\"210\"/>\n<polyline class=\"hl b2\" fill=\"none\" points=\"340,140 400,200 460,140\"/>\n<text class=\"t b2\" x=\"465\" y=\"130\" font-size=\"14\" text-anchor=\"end\">y = |x|<\/text>\n<text class=\"tm b2\" x=\"400\" y=\"250\" font-size=\"14\" text-anchor=\"middle\">0 에서 한 번 꺾임<\/text>\n<\/svg>","caption":"왼쪽은 신경망, 오른쪽은 결과 그래프. 은닉 칸을 늘리면 꺾는 점이 늘어요.","builds":2},{"kind":"prof","when":"3주차 화요일 수업","lines":["업데이트 선택지: 선형 변환과 활성화, 선형 변환만, 또는 MLP.","MLP 는 은닉 차원이 충분하면 어떤 연속 함수든 근사할 수 있어요.","그게 수학적으로 증명되어 있어서, 연산은 많아도 표현력은 MLP 가 낫대요."]}],"pass3":[{"kind":"check","q":"**보편 근사 정리(Universal Approximation Theorem)** 가 말하는 것은?","choices":["은닉층 1개 MLP 도 칸이 충분하면 어떤 연속 함수든 근사한다","MLP 는 층이 많을수록 항상 정확하다","ReLU 없이도 V자 함수를 만들 수 있다"],"a":0,"why":"정리는 '충분히 넓은 은닉층 1개 + 비선형 함수'면 된다고 말해요. 층 수 이야기가 아니에요."},{"kind":"english","head":"서술형: 왜 f 와 Φ 에 MLP 를 쓰나","en":"By the universal approximation theorem, a 1-hidden-layer MLP with enough hidden units can approximate any continuous function, so MLPs can learn the functions f and Φ needed for an injective multiset function.","ko":"보편 근사 정리에 따라 은닉 칸이 충분한 MLP 는 어떤 연속 함수든 근사하므로, 단사 멀티셋 함수에 필요한 f 와 Φ 를 학습할 수 있다."},{"kind":"warn","head":"주의","items":["'그런 MLP 가 존재한다'는 말이지, 학습하면 반드시 찾아진다는 말은 아니에요.","소문자 $\\sigma$ (활성화 함수)와 대문자 $\\Sigma$ (합)를 헷갈리지 마세요.","그림 위쪽 빈 네모 선은 원본 그림 흔적이라 뜻이 없어요."]}],"pass4":[{"kind":"pyterm","name":"nn.Linear 와 nn.Sequential","say":["**예시 코드**예요. 3주차 노트북에는 **MLP** 코드가 없어요.","`nn.Linear(2, 16)` 은 $W_1$ (2칸을 16칸으로), `nn.ReLU()` 는 $\\sigma$, `nn.Linear(16, 2)` 는 $W_2$ 예요.","`nn.Sequential` 은 부품을 순서대로 이어 MLP 하나로 만들어요. `.shape` 는 결과 모양이에요."],"example":"import torch.nn as nn\nmlp = nn.Sequential(nn.Linear(2, 16), nn.ReLU(), nn.Linear(16, 2))\nprint(mlp(torch.tensor([1., 0.])).shape)","out":"torch.Size([2])"}]},{"p":41,"title":"신경망으로 완성: MLP_Φ(Σ MLP_f(x))","terms":["MLP","Injective","Multiset","Sum aggregation","GIN","1-WL"],"pass1":[{"kind":"say","lines":["세 단계 모양에서 첫째 단계와 셋째 단계 자리에 **MLP** 를 하나씩 넣었어요. 가운데 합은 그대로예요.","그러면 정보를 잃지 않는 **단사(Injective)** 모으기라면 무엇이든 흉내 낼 수 있는 신경망이 돼요.","실제로는 MLP 가운데 칸이 100개에서 500개 정도면 충분하다고 해요. 실험으로 얻은 경험이에요."]},{"kind":"compare","head":"세 단계에 무엇을 넣었나","cols":["단계","하는 일","넣은 것"],"rows":[["첫째","쪽지를 한 장씩 바꿔 적기","MLP 하나"],["가운데","바꾼 쪽지를 전부 더하기","합 그대로"],["셋째","합을 마지막으로 정리하기","또 다른 MLP 하나"]]}],"pass2":[{"kind":"look","head":"도착한 신경망","boxes":[{"x":0.03,"y":0.16,"w":0.54,"h":0.06,"say":"어떤 **단사(Injective)** **멀티셋(Multiset)** 함수든 모델링할 수 있는 신경망에 도달했어요."},{"x":0.36,"y":0.29,"w":0.21,"h":0.16,"say":"p.37 과 비교하면 $\\Phi$ 가 $\\mathrm{MLP}_\\Phi$, $f$ 가 $\\mathrm{MLP}_f$ 로. 가운데 합은 그대로."},{"x":0.03,"y":0.47,"w":0.45,"h":0.06,"say":"실제로는 **MLP** 은닉 차원 100~500 이면 충분해요. 실험에서 얻은 규칙이에요."}]},{"kind":"formula","head":"완성된 식","tex":"\\mathrm{MLP}_{\\Phi}\\left(\\sum_{x\\in S}\\mathrm{MLP}_{f}(x)\\right)","parts":[{"sym":"\\mathrm{MLP}_{f}(x)","say":"쪽지 한 장을 가공하는 MLP. 모든 쪽지가 같은 것 하나를 공유"},{"sym":"\\sum_{x\\in S}","say":"가공된 벡터를 모두 더하기. **합 집계(Sum aggregation)** 그대로"},{"sym":"\\mathrm{MLP}_{\\Phi}","say":"합을 최종 결과로 바꾸는 MLP"},{"sym":"_{f},\\ _{\\Phi}","say":"아래첨자는 곱하기가 아니라 역할 이름표. 두 MLP 는 가중치가 달라요"}],"whole":"같은 번역기 MLP_f 로 한 장씩 가공하고, 모두 더하고, 정리기 MLP_Φ 에 넣는다."},{"kind":"steps","head":"잘 학습된 MLP_f 로 네 봉투","steps":["{노랑, 파랑}: $(3,1)+(1,2) = (4, 3)$","{노랑, 노랑, 파랑, 파랑}: $(8, 6)$","{노랑, 노랑, 파랑}: $(7, 4)$, {노랑, 파랑, 파랑}: $(5, 5)$","거꾸로: $3a + b = 5$, $a + 2b = 5$ 이면 $a = 1$, $b = 2$. 봉투가 되살아나요.","$\\mathrm{MLP}_\\Phi(z_1, z_2) = (z_1 + z_2, z_1 - z_2)$ 면 $(7,1), (14,2), (11,3), (10,0)$ 로 여전히 달라요."],"answer":"네 봉투 모두 서로 다른 결과. 전체가 단사로 유지돼요.","given":"$\\mathrm{MLP}_f$: 노랑을 $(3, 1)$, 파랑을 $(1, 2)$ 로 바꾼다고 해요."},{"kind":"say","lines":["반대로 $\\mathrm{MLP}_f$ 가 노랑 $(1, 1)$, 파랑 $(2, 2)$ 로 잘못 학습되면,","{노랑, 노랑} 과 {파랑} 의 합이 둘 다 $(2, 2)$ 로 충돌해요.","그래서 $\\mathrm{MLP}_f$ 를 학습시켜 좋은 모양을 찾게 해요."]},{"kind":"prof","when":"3주차 화요일 수업","lines":["은닉 차원은 100 에서 500 정도는 줘야 충분하다고 했어요.","이건 실험으로 검증된 부분이래요."]}],"pass3":[{"kind":"english","head":"2024 가을 기말 5번 (b) 해설 문장","en":"The combination of the sum operator with an injective MLP ensures that GIN can distinguish graphs as powerful as the 1-WL testing.","ko":"합 연산과 단사 MLP 의 조합이 GIN 을 1-WL 테스트만큼 그래프를 구별하게 해 준다.","tip":"'sum' 과 'injective MLP' 두 단어가 답안에 꼭 들어가야 해요."},{"kind":"warn","head":"주의","items":["합 자리를 평균이나 최댓값으로 바꾸면 p.33, p.35 의 실패가 돌아와요.","$\\mathrm{MLP}_f$ 는 쪽지마다 따로 만드는 게 아니라 하나를 공유해요.","'100~500 이면 충분'은 이론이 아니라 실험에서 얻은 경험 규칙이에요."]}],"pass4":[]},{"p":42,"title":"GIN: 가장 표현력 있는 GNN","terms":["GIN","Injective","Message passing","Sum aggregation","GCN","GraphSAGE","1-WL","HASH"],"pass1":[{"kind":"say","lines":["쪽지를 MLP 로 바꾸고, 전부 더하고, 다시 MLP 로 정리하는 방식으로 이웃을 모으는 GNN,","이걸 **그래프 동형 네트워크(GIN)** 라고 해요.","**GIN** 의 모으기는 **단사(Injective)** 라서, 평균이나 최댓값처럼 헷갈리는 봉투가 없어요.","그래서 이웃에게 받아 모으는 **메시지 패싱(Message passing)** GNN 중에서 가장 잘 구별해요."]},{"kind":"compare","head":"세 모델의 차이는 가운데 모으기 하나","cols":["모델","모으는 방법","봉투에서 남는 정보"],"rows":[["GCN","평균","색 종류와 비율"],["GraphSAGE","최댓값","색 종류만"],["GIN","합","색 종류와 개수"]]}],"pass2":[{"kind":"look","head":"GIN 선언","boxes":[{"x":0.03,"y":0.16,"w":0.47,"h":0.06,"say":"**그래프 동형 네트워크(GIN)**, Xu 외 ICLR 2019. 이름의 '동형'은 WL 만큼 구별하도록 설계해서예요."},{"x":0.07,"y":0.24,"w":0.52,"h":0.22,"say":"계산 순서: **MLP** 적용, 원소별 합, 또 MLP. 식은 p.41 과 같아요."},{"x":0.03,"y":0.49,"w":0.35,"h":0.15,"say":"정리: **GIN** 의 이웃 집계 함수는 **단사(Injective)** 예요."},{"x":0.03,"y":0.67,"w":0.17,"h":0.06,"say":"실패 사례 없음! p.33, p.35 같은 반례가 GIN 집계에는 없어요."},{"x":0.03,"y":0.75,"w":0.73,"h":0.07,"say":"**GIN** 은 **메시지 패싱(Message passing)** GNN 부류에서 단연(THE) 가장 표현력 있는 GNN 이에요."}]},{"kind":"formula","head":"노드 v 에 대해 다시 쓰기","tex":"\\mathrm{AGG}(v) = \\mathrm{MLP}_{\\Phi}\\left(\\sum_{u\\in N(v)}\\mathrm{MLP}_{f}(x_u)\\right)","parts":[{"sym":"N(v),\\ x_u","say":"$v$ 의 이웃, 이웃 $u$ 의 특징. 세 모델 모두 같음"},{"sym":"\\mathrm{MLP}_{f}(x_u)","say":"이웃 특징 가공. GraphSAGE 도 있고 GCN 은 없음"},{"sym":"\\sum","say":"원소별 합. GCN 은 Mean, GraphSAGE 는 Max"},{"sym":"\\mathrm{MLP}_{\\Phi}","say":"합 뒤 가공. GCN 은 $W$ 한 번과 ReLU"}],"whole":"이웃 특징을 한 장씩 가공해서 더하고, 다시 가공한다. 세 모델 차이는 가운데 모으기 하나예요."},{"kind":"steps","head":"실패 봉투 셋을 GIN 에 넣기","steps":["A {노랑, 파랑}: 합 $(1, 1)$, $W$ 곱 $(3, -1)$, ReLU $(3, 0)$","B {노랑, 노랑, 파랑, 파랑}: 합 $(2, 2)$, $W$ 곱 $(6, -2)$, ReLU $(6, 0)$","C {노랑, 노랑, 파랑}: 합 $(2, 1)$, $W$ 곱 $(4, 2)$, ReLU $(4, 2)$","같은 뒤 가공이면 GCN 은 A, B 가 둘 다 $(1.5, 0)$, GraphSAGE 는 셋 다 $(3, 0)$ 이에요."],"answer":"GIN: (3, 0), (6, 0), (4, 2) 로 세 쌍 모두 구별","given":"원-핫 그대로, 뒤 가공은 $W = \\begin{bmatrix} 1 & 2 \\\\ 3 & -4 \\end{bmatrix}$ 와 ReLU 로 통일"},{"kind":"figure","head":"세 모델 구별 성적표","svg":"<svg viewBox=\"0 0 480 270\" xmlns=\"http://www.w3.org/2000/svg\">\n<text class=\"t\" x=\"250\" y=\"30\" font-size=\"14\" text-anchor=\"middle\">A 와 B<\/text>\n<text class=\"t\" x=\"340\" y=\"30\" font-size=\"14\" text-anchor=\"middle\">A 와 C<\/text>\n<text class=\"t\" x=\"430\" y=\"30\" font-size=\"14\" text-anchor=\"middle\">B 와 C<\/text>\n<line class=\"e\" x1=\"20\" y1=\"45\" x2=\"470\" y2=\"45\"/>\n<text class=\"t\" x=\"20\" y=\"86\" font-size=\"15\">GCN (평균)<\/text>\n<text class=\"t\" x=\"20\" y=\"146\" font-size=\"15\">GraphSAGE (최대)<\/text>\n<circle class=\"n4 b1\" cx=\"250\" cy=\"80\" r=\"16\"/>\n<text class=\"tl b1\" x=\"250\" y=\"86\" font-size=\"16\" text-anchor=\"middle\">X<\/text>\n<circle class=\"n3 b1\" cx=\"340\" cy=\"80\" r=\"16\"/>\n<text class=\"tl b1\" x=\"340\" y=\"86\" font-size=\"16\" text-anchor=\"middle\">O<\/text>\n<circle class=\"n3 b1\" cx=\"430\" cy=\"80\" r=\"16\"/>\n<text class=\"tl b1\" x=\"430\" y=\"86\" font-size=\"16\" text-anchor=\"middle\">O<\/text>\n<circle class=\"n4 b2\" cx=\"250\" cy=\"140\" r=\"16\"/>\n<text class=\"tl b2\" x=\"250\" y=\"146\" font-size=\"16\" text-anchor=\"middle\">X<\/text>\n<circle class=\"n4 b2\" cx=\"340\" cy=\"140\" r=\"16\"/>\n<text class=\"tl b2\" x=\"340\" y=\"146\" font-size=\"16\" text-anchor=\"middle\">X<\/text>\n<circle class=\"n4 b2\" cx=\"430\" cy=\"140\" r=\"16\"/>\n<text class=\"tl b2\" x=\"430\" y=\"146\" font-size=\"16\" text-anchor=\"middle\">X<\/text>\n<rect class=\"box2 b3\" x=\"10\" y=\"175\" width=\"460\" height=\"50\" rx=\"10\"/>\n<text class=\"tb\" x=\"20\" y=\"206\" font-size=\"15\">GIN (합)<\/text>\n<circle class=\"n3 b3\" cx=\"250\" cy=\"200\" r=\"16\"/>\n<text class=\"tl b3\" x=\"250\" y=\"206\" font-size=\"16\" text-anchor=\"middle\">O<\/text>\n<circle class=\"n3 b3\" cx=\"340\" cy=\"200\" r=\"16\"/>\n<text class=\"tl b3\" x=\"340\" y=\"206\" font-size=\"16\" text-anchor=\"middle\">O<\/text>\n<circle class=\"n3 b3\" cx=\"430\" cy=\"200\" r=\"16\"/>\n<text class=\"tl b3\" x=\"430\" y=\"206\" font-size=\"16\" text-anchor=\"middle\">O<\/text>\n<text class=\"tm\" x=\"240\" y=\"258\" font-size=\"14\" text-anchor=\"middle\">O 는 구별함, X 는 구별 못 함<\/text>\n<\/svg>","caption":"GIN 만 세 쌍을 모두 구별해요. 이게 '실패 사례 없음'이에요.","builds":3},{"kind":"prof","when":"3주차 화요일 수업","lines":["GCN, GraphSAGE 다음에 나온 모델이 **GIN** 이래요.","풀링은 합으로, 업데이트는 MLP 로 해요. WL 처럼 단사가 되도록요."]}],"pass3":[{"kind":"exam","src":"2024 가을 기말 5번 (b) (GIN, 10점)","q":"What are the reasons why GIN model achieves 1-d Weisfeiler-Lehman?","qko":"GIN 모델이 1차원 Weisfeiler-Lehman(1-WL) 만큼 강력한 이유는 무엇인가?","solve":["**GIN** 은 이웃을 **합 집계(Sum aggregation)** 로 모은다.","평균이나 최대 풀링과 달리 합은 멀티셋 위에서 **단사(Injective)** 다.","합 뒤의 MLP 도 단사면, 서로 다른 이웃 봉투는 서로 다른 임베딩이 된다.","이는 **1-WL** 의 단사 **HASH** 와 같은 역할이라 구별력이 1-WL 과 같다."],"answer":"GIN uses a sum aggregation function. Unlike mean or max-pooling used in other GNNs, the sum operation ensures that the aggregation function is injective. The combination of the sum operator with an injective MLP ensures that GIN can distinguish graphs as powerful as the 1-WL testing."},{"kind":"check","q":"**GIN** 이 이웃을 모을 때 가운데에 쓰는 연산은?","choices":["평균","합","최댓값","곱"],"a":1,"why":"GIN 은 MLP, 합, MLP. 합이라서 개수까지 남고 단사가 돼요."},{"kind":"warn","head":"주의","items":["'실패 사례 없음'은 집계 한 번이 봉투를 뭉개지 않는다는 뜻이에요. 모든 그래프를 구별한다는 뜻은 아니에요.","위 숫자 예의 ReLU 는 경우에 따라 충돌을 만들 수 있어요. 실제 $\\mathrm{MLP}_\\Phi$ 는 학습으로 맞춰진다고 봐요."]}],"pass4":[{"kind":"say","lines":["3주차 노트북에는 **GIN** 코드가 없어요.","대신 p.47, p.48 의 색 정제 코드가 있어요.","여기서는 PyTorch Geometric 의 GIN 층을 예시로만 짧게 봐요."]},{"kind":"pyterm","name":"GINConv","say":["**예시 코드**예요. `GINConv` 는 PyTorch Geometric 라이브러리의 **GIN** 층이에요.","안에 넣는 `mlp` 가 합 뒤의 MLP 자리이고, `eps` 는 p.45 기출 식의 $\\epsilon$ 이에요.","이웃을 합으로 모으는 부분은 `GINConv` 가 알아서 해요."],"example":"from torch_geometric.nn import GINConv\nmlp = nn.Sequential(nn.Linear(2, 16), nn.ReLU(), nn.Linear(16, 16))\nconv = GINConv(mlp, eps=0.5)"}]},{"p":43,"title":"풀링의 힘: 합 > 평균 > 최대","terms":["Discriminative power","Mean pooling","Max pooling","Sum aggregation","Multiset","Readout","GIN"],"pass1":[{"kind":"say","lines":["이번엔 실제 그래프 모양으로, 평균과 최댓값이 헷갈리는 경우를 다시 봐요.","합은 '무엇이 몇 개', 평균은 '어떤 비율', 최댓값은 '무엇이 있나' 만 기억해요.","그래서 구별하는 힘, 곧 **구별력(Discriminative power)** 은 합이 가장 크고, 그다음 평균, 마지막이 최댓값이에요."]},{"kind":"look","head":"위쪽 그래프 세 쌍","boxes":[{"x":0.11,"y":0.23,"w":0.21,"h":0.28,"say":"왼쪽 쌍은 이웃이 파랑 2명인 노드와 파랑 3명인 노드예요. 평균도 최댓값도 둘을 못 갈라요."},{"x":0.4,"y":0.23,"w":0.2,"h":0.28,"say":"가운데 쌍은 이웃 색 비율이 달라서 평균은 가르지만, 최댓값은 못 갈라요."},{"x":0.67,"y":0.23,"w":0.21,"h":0.28,"say":"오른쪽 쌍은 비율도 종류도 같아서 평균도 최댓값도 못 갈라요."}]}],"pass2":[{"kind":"look","head":"세 그래프 쌍과 순위 그림","boxes":[{"x":0.11,"y":0.23,"w":0.21,"h":0.28,"say":"(a) $v$ 는 파랑 이웃 2명, $v'$ 는 3명. **평균 풀링(Mean pooling)** 도 **최대 풀링(Max pooling)** 도 실패."},{"x":0.4,"y":0.23,"w":0.2,"h":0.28,"say":"(b) 초록1 빨강1 대 초록1 빨강2. 비율은 달라서 평균은 구별, 최대만 실패."},{"x":0.67,"y":0.23,"w":0.21,"h":0.28,"say":"(c) 초록1 빨강1 대 초록2 빨강2. 비율도 종류도 같아서 둘 다 실패."},{"x":0.11,"y":0.6,"w":0.19,"h":0.29,"say":"순위 그림의 Input: 파랑 4, 빨강 2 봉투."},{"x":0.32,"y":0.6,"w":0.52,"h":0.29,"say":"sum 은 **멀티셋(Multiset)** 그대로, mean 은 분포(2:1), max 는 집합(종류 둘)만 남아요."}]},{"kind":"compare","head":"세 그래프 쌍 결과","cols":["그림","이웃 봉투 v / v'","합","평균","최대"],"rows":[["(a)","파랑 2 / 파랑 3","구별","실패","실패"],["(b)","초록1 빨강1 / 초록1 빨강2","구별","구별","실패"],["(c)","초록1 빨강1 / 초록2 빨강2","구별","실패","실패"]]},{"kind":"steps","head":"(b) 를 숫자로","steps":["$v$: 합 $(0, 1, 1)$, 평균 $(0, 0.5, 0.5)$, 최대 $(0, 1, 1)$","$v'$: 합 $(0, 1, 2)$, 평균 $(0, 0.33, 0.67)$, 최대 $(0, 1, 1)$","합과 평균은 달라지고, 최대만 같아요. 그래서 '(b) Max fails'."],"answer":"(b) 에서는 최대 풀링만 실패","given":"파랑 $(1,0,0)$, 초록 $(0,1,0)$, 빨강 $(0,0,1)$"},{"kind":"figure","head":"같은 봉투, 세 가지 요약","svg":"<svg viewBox=\"0 0 480 270\" xmlns=\"http://www.w3.org/2000/svg\">\n<text class=\"tb\" x=\"60\" y=\"28\" font-size=\"14\" text-anchor=\"middle\">입력<\/text>\n<text class=\"tb b1\" x=\"180\" y=\"28\" font-size=\"14\" text-anchor=\"middle\">합 = 멀티셋<\/text>\n<text class=\"tb b2\" x=\"300\" y=\"28\" font-size=\"14\" text-anchor=\"middle\">평균 = 분포<\/text>\n<text class=\"tb b3\" x=\"420\" y=\"28\" font-size=\"14\" text-anchor=\"middle\">최대 = 집합<\/text>\n<rect class=\"box\" x=\"10\" y=\"40\" width=\"100\" height=\"150\" rx=\"10\"/>\n<circle class=\"n3\" cx=\"40\" cy=\"70\" r=\"16\"/>\n<circle class=\"n3\" cx=\"80\" cy=\"70\" r=\"16\"/>\n<circle class=\"n4\" cx=\"40\" cy=\"115\" r=\"16\"/>\n<circle class=\"n4\" cx=\"80\" cy=\"115\" r=\"16\"/>\n<circle class=\"n3\" cx=\"40\" cy=\"160\" r=\"16\"/>\n<circle class=\"n3\" cx=\"80\" cy=\"160\" r=\"16\"/>\n<text class=\"t\" x=\"60\" y=\"215\" font-size=\"14\" text-anchor=\"middle\">파랑 4, 빨강 2<\/text>\n<rect class=\"box2 b1\" x=\"130\" y=\"40\" width=\"100\" height=\"150\" rx=\"10\"/>\n<circle class=\"n3 b1\" cx=\"160\" cy=\"70\" r=\"16\"/>\n<circle class=\"n3 b1\" cx=\"200\" cy=\"70\" r=\"16\"/>\n<circle class=\"n4 b1\" cx=\"160\" cy=\"115\" r=\"16\"/>\n<circle class=\"n4 b1\" cx=\"200\" cy=\"115\" r=\"16\"/>\n<circle class=\"n3 b1\" cx=\"160\" cy=\"160\" r=\"16\"/>\n<circle class=\"n3 b1\" cx=\"200\" cy=\"160\" r=\"16\"/>\n<text class=\"t b1\" x=\"180\" y=\"215\" font-size=\"14\" text-anchor=\"middle\">(4, 2)<\/text>\n<text class=\"tm b1\" x=\"180\" y=\"240\" font-size=\"14\" text-anchor=\"middle\">종류 + 개수<\/text>\n<text class=\"tm b2\" x=\"240\" y=\"122\" font-size=\"18\" text-anchor=\"middle\">&gt;<\/text>\n<rect class=\"box b2\" x=\"250\" y=\"40\" width=\"100\" height=\"150\" rx=\"10\"/>\n<circle class=\"n3 b2\" cx=\"280\" cy=\"85\" r=\"16\"/>\n<circle class=\"n3 b2\" cx=\"320\" cy=\"85\" r=\"16\"/>\n<circle class=\"n4 b2\" cx=\"300\" cy=\"145\" r=\"16\"/>\n<text class=\"t b2\" x=\"300\" y=\"215\" font-size=\"14\" text-anchor=\"middle\">(2/3, 1/3)<\/text>\n<text class=\"tm b2\" x=\"300\" y=\"240\" font-size=\"14\" text-anchor=\"middle\">종류 + 비율<\/text>\n<text class=\"tm b3\" x=\"360\" y=\"122\" font-size=\"18\" text-anchor=\"middle\">&gt;<\/text>\n<rect class=\"box b3\" x=\"370\" y=\"40\" width=\"100\" height=\"150\" rx=\"10\"/>\n<circle class=\"n3 b3\" cx=\"420\" cy=\"85\" r=\"16\"/>\n<circle class=\"n4 b3\" cx=\"420\" cy=\"145\" r=\"16\"/>\n<text class=\"t b3\" x=\"420\" y=\"215\" font-size=\"14\" text-anchor=\"middle\">(1, 1)<\/text>\n<text class=\"tm b3\" x=\"420\" y=\"240\" font-size=\"14\" text-anchor=\"middle\">종류만<\/text>\n<\/svg>","caption":"한 색 공은 파랑, 다른 색 공은 빨강. 오른쪽으로 갈수록 남는 정보가 줄어요.","builds":3},{"kind":"prof","when":"3주차 화요일 수업","lines":["이 쪽은 짧게 넘어갔지만 기억할 건 하나래요.","표현력은 최대가 가장 안 좋고, 그다음 평균, 가장 나은 건 합이에요."]}],"pass3":[{"kind":"exam","src":"2023 가을 기말 5번 (GIN, 10점)","q":"GIN with fixed $\\epsilon = 0.5$: $h_i^{(k)} = (1+\\epsilon)\\,h_i^{(k-1)} + \\sum_{j\\in N(i)} h_j^{(k-1)}$. a) Calculate the feature of each node at k = 1. b) Calculate a graph-level embedding $h_G$ by using a 'Max' global pooling when k = 1.","qko":"ε = 0.5 인 GIN 식으로 (a) k = 1 노드 특징, (b) 'Max' 전역 풀링 그래프 임베딩 $h_G$ 를 구하라. 해설 기준 초기값 A 0.5, B 0.2, C 0.2, D 0.3, 이웃 A: B, C / B: A, C / C: A, B, D / D: C.","solve":["A: $1.5 \\times 0.5 + (0.2 + 0.2) = 0.75 + 0.4 = 1.15$","B: $1.5 \\times 0.2 + (0.5 + 0.2) = 0.3 + 0.7 = 1.0$","C: $1.5 \\times 0.2 + (0.5 + 0.2 + 0.3) = 0.3 + 1.0 = 1.3$","D: $1.5 \\times 0.3 + 0.2 = 0.45 + 0.2 = 0.65$","(b) $h_G = \\max(1.15, 1.0, 1.3, 0.65) = 1.3$"],"answer":"(a) A 1.15, B 1.0, C 1.3, D 0.65. (b) $h_G = 1.3$"},{"kind":"english","head":"Max 풀링 서술 한 줄","en":"Max pooling only keeps the largest value, so it ignores how many nodes and what other values exist.","ko":"최대 풀링은 가장 큰 값만 남겨서 노드가 몇 개인지, 다른 값이 무엇인지를 무시한다."},{"kind":"check","q":"(c) 에서 **평균 풀링(Mean pooling)** 이 실패하는 이유는?","choices":["색 종류가 달라서","초록과 빨강 비율이 둘 다 절반씩이라서","v 와 v' 의 색이 달라서"],"a":1,"why":"초록1 빨강1 과 초록2 빨강2 는 비율이 같아 평균이 $(0, 0.5, 0.5)$ 로 같아요."},{"kind":"warn","head":"주의","items":["평균이 구별 못 하는 봉투는 최대도 구별 못 해요. 반대로 (b) 처럼 평균만 구별하는 경우는 있어요.","기출의 Max 전역 풀링은 그래프 전체를 모으는 **리드아웃(Readout)** 자리, 슬라이드는 이웃 집계 자리예요. 약점은 같아요."]}],"pass4":[]},{"p":44,"title":"왜 합 ≻ 평균 ≻ 최대인가","terms":["Multiset","Injective","Degree","1-WL","Inductive bias","Expressive power"],"pass1":[{"kind":"say","lines":["합은 봉투 전체를, 평균은 비율을, 최댓값은 어떤 종류가 있는지만 담아요.","그래서 구별하는 힘인 **구별력(Discriminative power)** 도 최댓값보다 평균이, 평균보다 합이 더 커요.","합으로 모으는 GNN 은 뒤에서 배울 색칠 시험인 **1-WL** 과 딱 같은 만큼 구별해요.","다만 구별을 잘한다고 해서 처음 보는 데이터에서도 늘 더 잘 맞히는 건 아니에요."]},{"kind":"analogy","head":"과일 바구니를 적는 세 가지 방법","scene":"과일 바구니 두 개를 기록하는 방법이 세 가지 있어요. 첫째는 '사과 4개, 귤 2개' 처럼 개수를 다 적고, 둘째는 '사과가 귤의 두 배' 처럼 비율만 적고, 셋째는 '사과, 귤 있음' 처럼 종류만 적어요. 개수를 다 적은 기록끼리 비교하면 두 바구니의 차이를 가장 많이 찾아낼 수 있어요. 적는 정보가 줄수록 찾을 수 있는 차이도 줄어요.","map":[["개수를 다 적은 기록","합"],["비율만 적은 기록","평균"],["종류만 적은 기록","최댓값"]]}],"pass2":[{"kind":"look","head":"세 상자, 긴 식, 기울임 문장","boxes":[{"x":0.04,"y":0.2,"w":0.3,"h":0.48,"say":"합: 멀티셋 전체를 담아요. X 가 가산일 때 **단사(Injective)**. 두 식 모두 $\\neq$."},{"x":0.35,"y":0.2,"w":0.3,"h":0.48,"say":"평균: 분포만 담아 중복 횟수를 못 봐요. 비율이 같으면 $=$, **차수(Degree)** 를 못 봐요."},{"x":0.65,"y":0.2,"w":0.3,"h":0.48,"say":"최대: 바탕 집합만 담아 개수를 전혀 못 봐요. 두 식 모두 $=$. 집합 함수예요."},{"x":0.04,"y":0.7,"w":0.92,"h":0.13,"say":"구별 가능한 쌍의 포함 관계. 합 GNN 은 **1-WL** 과 정확히 같아요."},{"x":0.04,"y":0.83,"w":0.76,"h":0.05,"say":"차수가 달라지면 평균, 최대가 더 잘 일반화하기도 해요. **귀납적 편향(Inductive bias)** 이야기예요."}]},{"kind":"formula","head":"포함 관계 식","tex":"Sep(\\text{MAX-GNN}) \\subsetneq Sep(\\text{MEAN-GNN}) \\subsetneq Sep(\\text{SUM-GNN}) = Sep(\\text{1-WL})","parts":[{"sym":"Sep(\\cdot)","say":"그 방법이 구별(separate)해 내는 그래프 쌍 전체의 모음"},{"sym":"\\text{MAX-GNN}","say":"최댓값으로 모으는 GNN (GraphSAGE 식)"},{"sym":"\\text{MEAN-GNN}","say":"평균으로 모으는 GNN (GCN 식)"},{"sym":"\\text{SUM-GNN}","say":"합으로 모으는 GNN (GIN 식)"},{"sym":"\\subsetneq","say":"왼쪽이 오른쪽에 다 들어 있고, 오른쪽에만 있는 것도 있음"},{"sym":"\\text{1-WL}","say":"**1-WL** 색 정제 테스트"}],"whole":"최대 GNN 이 구별하는 쌍은 평균 GNN 도 다 구별하고, 합 GNN 은 더 구별하며, 그 범위가 1-WL 과 같다."},{"kind":"compare","head":"a = 1, b = 3 으로 상자 속 등호 확인","cols":["멀티셋","합","평균","최대"],"rows":[["{{1, 3}}","4","2","3"],["{{1, 1, 3, 3}}","8","2","3"],["{{1, 3, 3}}","7","2.33","3"]]},{"kind":"figure","head":"구별 가능한 쌍의 포함 관계","svg":"<svg viewBox=\"0 0 480 270\" xmlns=\"http://www.w3.org/2000/svg\">\n<rect class=\"box2 b3\" x=\"10\" y=\"10\" width=\"460\" height=\"250\" rx=\"16\"/>\n<text class=\"tb b3\" x=\"240\" y=\"36\" font-size=\"16\" text-anchor=\"middle\">Sep(SUM) = Sep(1-WL)<\/text>\n<text class=\"tm b3\" x=\"240\" y=\"58\" font-size=\"14\" text-anchor=\"middle\">+ 개수만 다른 쌍. 예: (a), (c)<\/text>\n<rect class=\"box b2\" x=\"40\" y=\"70\" width=\"400\" height=\"178\" rx=\"14\"/>\n<text class=\"tb b2\" x=\"240\" y=\"94\" font-size=\"16\" text-anchor=\"middle\">Sep(MEAN)<\/text>\n<text class=\"tm b2\" x=\"240\" y=\"116\" font-size=\"14\" text-anchor=\"middle\">+ 비율만 다른 쌍. 예: (b)<\/text>\n<rect class=\"box2 b1\" x=\"90\" y=\"130\" width=\"300\" height=\"100\" rx=\"12\"/>\n<text class=\"tb b1\" x=\"240\" y=\"172\" font-size=\"16\" text-anchor=\"middle\">Sep(MAX)<\/text>\n<text class=\"tm b1\" x=\"240\" y=\"198\" font-size=\"14\" text-anchor=\"middle\">종류가 다른 쌍<\/text>\n<\/svg>","caption":"안쪽일수록 약한 풀링이에요. 바깥 상자가 1-WL 과 같은 범위예요.","builds":3},{"kind":"compare","head":"차수가 달라질 때 (이웃 특징 모두 1)","cols":["풀링","학습 (이웃 5명)","시험 (이웃 50명)"],"rows":[["합","5","50"],["평균","1","1"],["최대","1","1"]]},{"kind":"points","head":"기울임 문장 풀이","items":["일반화(generalize): 처음 보는 데이터에서도 잘 맞히는 것.","합은 학습 때 못 본 큰 값 50 이 들어와 헷갈릴 수 있어요.","**귀납적 편향(Inductive bias)**: 모델이 미리 가진 '이렇게 보자'는 성향.","구별을 잘하는 것과 처음 보는 크기에 강한 것은 다른 문제예요."]},{"kind":"prof","when":"3주차 화요일 수업","lines":["합이 모든 함수 중 가장 좋다는 뜻은 아니라고 짚었어요.","계산이 거의 없는 단순한 함수끼리 비교할 때 합이 제일 낫다는 뜻이에요.","합도 완벽하진 않지만 평균, 최대보다는 낫대요."]},{"kind":"mining","src":"마이닝 9강 Graph Kernels","lines":["**1-WL** 은 마이닝의 WL 동형 테스트예요.","이웃 라벨을 **멀티셋(Multiset)** 으로 모아 새 라벨로 압축하는 일을 반복했죠.","개수를 지키니 합 GNN 과 힘이 같아요."]}],"pass3":[{"kind":"english","head":"비교 서술 1","en":"Sum captures the full multiset and is injective; mean captures only the distribution and cannot see degree; max captures only the underlying set.","ko":"합은 멀티셋 전체를 담아 단사이고, 평균은 분포만 담아 차수를 못 보며, 최대는 바탕 집합만 담는다."},{"kind":"english","head":"비교 서술 2","en":"However, mean and max may generalize better when node degrees differ between training and test graphs.","ko":"다만 학습과 테스트 그래프의 차수가 다르면 평균과 최대가 더 잘 일반화할 수 있다."},{"kind":"check","q":"'**Inductive bias**' 의 뜻으로 맞는 것은?","choices":["모델이 미리 가진 '이렇게 보자'는 성향","학습 데이터에 섞인 잘못된 레이블","구별할 수 있는 그래프 쌍의 모음"],"a":0,"why":"**귀납적 편향(Inductive bias)** 은 모델의 기본 성향이에요. 표현력 최대가 곧 좋은 편향은 아니에요."},{"kind":"warn","head":"주의","items":["$Sep$ 은 구별 가능한 '쌍들의 모음'이에요. 안쪽일수록 약한 방법. 포함 방향을 거꾸로 외우기 쉬워요.","'X 가 가산일 때'는 조건이에요. 아무 실수를 그냥 더하면 단사라는 뜻이 아니에요(p.37 의 {1,3}, {2,2}).","합 GNN 이 1-WL 과 같다는 건 1-WL 보다 강하지는 않다는 뜻도 돼요."]}],"pass4":[]},{"p":45,"title":"GIN 전체 모델 예고: WL 커널의 신경망 버전","terms":["GIN","WL graph kernel","HASH","MLP","Neighbor aggregation","Color refinement","1-WL"],"pass1":[{"kind":"say","lines":["지금까지는 **GIN** 에서 '이웃을 모으는 부분' 만 봤어요.","이제 GIN 전체를 예전부터 쓰던 방법인 **WL 그래프 커널(WL graph kernel)** 과 나란히 놓고 봐요.","WL 그래프 커널은 노드에 색을 칠하고 고쳐 칠하는 규칙으로 그래프를 숫자로 요약하는 옛 방법이에요.","결론부터 말하면, GIN 은 WL 그래프 커널을 신경망으로 바꾼 버전이에요."]},{"kind":"analogy","head":"번호표 기계 자리에 선 로봇","scene":"은행 번호표 기계는 정해진 규칙대로만 번호를 줘요. 규칙은 바뀌지 않고, 스스로 나아지지도 않아요. 그런데 이 기계 자리에 연습하면서 점점 똑똑해지는 로봇을 세웠다고 해 봐요. 하는 일의 틀은 같지만, 로봇은 쓸수록 더 쓸모 있는 번호를 줄 수 있어요.","map":[["정해진 규칙의 번호표 기계","**HASH**, WL 이 새 색을 붙이는 고정 규칙"],["연습하며 나아지는 로봇","**MLP**, GIN 이 쓰는 학습하는 신경망"],["새로 받은 번호","새 색, 또는 새 임베딩(노드를 설명하는 숫자 목록)"]]}],"pass2":[{"kind":"look","head":"예고편 세 줄","boxes":[{"x":0.03,"y":0.16,"w":0.41,"h":0.06,"say":"지금까지: **GIN** 의 **이웃 집계(Neighbor aggregation)** 부분을 설명했어요."},{"x":0.03,"y":0.25,"w":0.83,"h":0.06,"say":"이제 **WL 그래프 커널(WL graph kernel)**, 그래프 수준 특징을 얻는 전통적 방법과 연결해요."},{"x":0.07,"y":0.4,"w":0.49,"h":0.06,"say":"GIN 이 WL 그래프 커널의 '신경망' 버전임을 보게 돼요."}]},{"kind":"points","head":"낯선 단어 풀기","items":["WL: 바이스파일러(Weisfeiler)와 레만(Lehman), 두 사람 이름이에요.","커널(kernel): 두 대상이 얼마나 닮았는지 숫자로 재는 방법.","그래프 수준 특징: 노드 하나가 아니라 그래프 전체를 설명하는 숫자 목록.","전통적 방법: 신경망 이전, 사람이 정한 규칙으로 특징을 뽑던 방법."]},{"kind":"figure","head":"WL 과 GIN 은 같은 틀","svg":"<svg viewBox=\"0 0 480 270\" xmlns=\"http://www.w3.org/2000/svg\">\n<text class=\"tb\" x=\"20\" y=\"32\" font-size=\"15\">WL 커널<\/text>\n<rect class=\"box\" x=\"20\" y=\"45\" width=\"140\" height=\"50\" rx=\"8\"/>\n<text class=\"t\" x=\"90\" y=\"66\" font-size=\"14\" text-anchor=\"middle\">내 색 +<\/text>\n<text class=\"t\" x=\"90\" y=\"86\" font-size=\"14\" text-anchor=\"middle\">이웃 색 봉투<\/text>\n<line class=\"e\" x1=\"160\" y1=\"70\" x2=\"190\" y2=\"70\"/>\n<polygon class=\"arrow\" points=\"190,64 200,70 190,76\"/>\n<rect class=\"box2\" x=\"202\" y=\"45\" width=\"120\" height=\"50\" rx=\"8\"/>\n<text class=\"tb\" x=\"262\" y=\"68\" font-size=\"15\" text-anchor=\"middle\">HASH<\/text>\n<text class=\"tm\" x=\"262\" y=\"88\" font-size=\"14\" text-anchor=\"middle\">정해진 번호표<\/text>\n<line class=\"e\" x1=\"322\" y1=\"70\" x2=\"350\" y2=\"70\"/>\n<polygon class=\"arrow\" points=\"350,64 360,70 350,76\"/>\n<rect class=\"box\" x=\"362\" y=\"45\" width=\"100\" height=\"50\" rx=\"8\"/>\n<text class=\"t\" x=\"412\" y=\"76\" font-size=\"14\" text-anchor=\"middle\">새 색 번호<\/text>\n<text class=\"tb b1\" x=\"20\" y=\"152\" font-size=\"15\">GIN<\/text>\n<rect class=\"box b1\" x=\"20\" y=\"165\" width=\"140\" height=\"50\" rx=\"8\"/>\n<text class=\"t b1\" x=\"90\" y=\"186\" font-size=\"14\" text-anchor=\"middle\">내 벡터 +<\/text>\n<text class=\"t b1\" x=\"90\" y=\"206\" font-size=\"14\" text-anchor=\"middle\">이웃 벡터 봉투<\/text>\n<line class=\"e b1\" x1=\"160\" y1=\"190\" x2=\"190\" y2=\"190\"/>\n<polygon class=\"arrow b1\" points=\"190,184 200,190 190,196\"/>\n<rect class=\"box2 b1\" x=\"202\" y=\"165\" width=\"120\" height=\"50\" rx=\"8\"/>\n<text class=\"tb b1\" x=\"262\" y=\"188\" font-size=\"15\" text-anchor=\"middle\">합 + MLP<\/text>\n<text class=\"tm b1\" x=\"262\" y=\"208\" font-size=\"14\" text-anchor=\"middle\">학습함<\/text>\n<line class=\"e b1\" x1=\"322\" y1=\"190\" x2=\"350\" y2=\"190\"/>\n<polygon class=\"arrow b1\" points=\"350,184 360,190 350,196\"/>\n<rect class=\"box b1\" x=\"362\" y=\"165\" width=\"100\" height=\"50\" rx=\"8\"/>\n<text class=\"t b1\" x=\"412\" y=\"196\" font-size=\"14\" text-anchor=\"middle\">새 임베딩<\/text>\n<line class=\"e2 b2\" x1=\"262\" y1=\"97\" x2=\"262\" y2=\"163\"/>\n<text class=\"tm b2\" x=\"380\" y=\"135\" font-size=\"14\" text-anchor=\"middle\">같은 틀, 기계만 다름<\/text>\n<\/svg>","caption":"번호표 기계 HASH 자리에 학습하는 MLP 가 들어갔어요.","builds":2},{"kind":"formula","head":"기출에 나온 GIN 식 (MLP 생략)","tex":"h_i^{(k)} = (1+\\epsilon)\\, h_i^{(k-1)} + \\sum_{j\\in N(i)} h_j^{(k-1)}","parts":[{"sym":"h_i^{(k)}","say":"노드 $i$ 의 $k$ 층 특징. 위첨자 괄호는 층 번호, 제곱 아님"},{"sym":"(1+\\epsilon)","say":"내 특징에 곱하는 무게. $\\epsilon$ 은 숫자 하나"},{"sym":"\\sum_{j\\in N(i)} h_j^{(k-1)}","say":"이웃들의 이전 층 특징을 합"}],"whole":"다음 층 내 값 = 이전 내 값에 (1+ε) 를 곱한 것 + 이웃 이전 값들의 합."},{"kind":"steps","head":"왜 (1+ε) 을 곱할까?","steps":["$\\epsilon = 0$ 이면 나와 이웃을 한 봉투에 섞어 더하는 셈이에요.","나 0.2, 이웃 {0.3} 이면 $0.2 + 0.3 = 0.5$","나 0.3, 이웃 {0.2} 여도 $0.5$. 구별이 안 돼요.","$1.5$ 를 곱하면 $0.3 + 0.3 = 0.6$ 과 $0.45 + 0.2 = 0.65$ 로 갈라져요."],"answer":"(1+ε) 은 '나'와 '이웃'을 구별하게 해 줘요."},{"kind":"prof","when":"3주차 화요일 수업","lines":["WL 재라벨링, PageRank 같은 전파 알고리즘은 본질적으로 GNN 과 같은 방식이래요.","다른 건 전파하는 게 이름이냐, 스칼라냐, 고차원 벡터냐 정도예요.","그러면 GNN 은 최소한 **1-WL** 만큼은 구별해야 하는데 실제로는 왜 못 할까?","이 의문에서 GIN 이 출발했대요."]},{"kind":"mining","src":"마이닝 9강 Graph Kernels","lines":["커널은 두 대상을 특징 공간으로 옮겨 닮은 정도를 재는 유사도 척도였어요.","**WL 그래프 커널(WL graph kernel)** 은 리라벨링 라벨 개수를 세어 그래프를 벡터로 만들었죠."]}],"pass3":[{"kind":"exam","src":"2024 가을 기말 5번 (a) (GIN, 10점)","q":"According to GIN model, the parameter is a fixed scalar $\\epsilon = 0.5$: $h_i^{(k)} = (1+\\epsilon)\\,h_i^{(k-1)} + \\sum_{j\\in N(i)} h_j^{(k-1)}$. a) Calculate the feature of each node at k = 1.","qko":"ε = 0.5 인 GIN 식으로 k = 1 에서 각 노드 특징을 구하라. 해설 기준 초기값 A 0.2, B 0.3, C 0.2, D 0.1, 이웃 A: B, C, D / B: A, C / C: A, B, D / D: A, C.","solve":["A: $1.5 \\times 0.2 + (0.3 + 0.2 + 0.1) = 0.3 + 0.6 = 0.9$","B: $1.5 \\times 0.3 + (0.2 + 0.2) = 0.45 + 0.4 = 0.85$","C: $1.5 \\times 0.2 + (0.2 + 0.3 + 0.1) = 0.3 + 0.6 = 0.9$","D: $1.5 \\times 0.1 + (0.2 + 0.2) = 0.15 + 0.4 = 0.55$","A 와 C 는 자기 값과 이웃 구성이 같은 대칭 자리라 같은 값이 맞아요."],"answer":"$h_A^{(1)} = 0.9$, $h_B^{(1)} = 0.85$, $h_C^{(1)} = 0.9$, $h_D^{(1)} = 0.55$"},{"kind":"warn","head":"계산 실수 주의","items":["$(1+\\epsilon)$ 을 이웃 쪽에 곱하지 마세요. 나에게만 곱해요.","이웃 합에 자기 자신을 또 넣지 마세요. 그림에서 이웃 명단도 꼼꼼히.","표를 '나 × 1.5 / 이웃 합 / 더하기' 세 칸으로 그리면 실수가 줄어요."]},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["WL 그래프 커널과 **1-WL** 테스트는 같은 **색 정제(Color refinement)** 를 써요. 커널은 개수로 닮음을 재고, 테스트는 같은지만 봐요.","기출 식에는 MLP 가 없지만 슬라이드의 GIN 전체 모델에는 있어요. 문제에 주어진 식 그대로 계산하세요."]}],"pass4":[{"kind":"pyterm","name":"사전 컴프리헨션과 sum","say":["**예시 코드**예요. 2024 기출 (a) 계산을 파이썬 세 줄로 확인해요.","`h` 는 {노드: 특징}, `nbr` 는 {노드: 이웃 리스트} 딕셔너리예요.","`{v: ... for v in h}` 는 노드마다 식을 계산해 새 사전을 만들어요. `sum(...)` 이 이웃 합이에요."],"example":"h = {'A': 0.2, 'B': 0.3, 'C': 0.2, 'D': 0.1}\nnbr = {'A': ['B', 'C', 'D'], 'B': ['A', 'C'], 'C': ['A', 'B', 'D'], 'D': ['A', 'C']}\nprint({v: 1.5 * h[v] + sum(h[u] for u in nbr[v]) for v in h})","out":"{'A': 0.9, 'B': 0.85, 'C': 0.9, 'D': 0.55}"}]},{"p":46,"title":"복습: 그래프 동형 문제","terms":["Graph isomorphism","Expressive power","Degree","Color refinement"],"pass1":[{"kind":"say","lines":["GNN 이 얼마나 잘 구별하는지 재는 오래된 시험 문제가 있어요.","두 그래프가 이름표만 바꾸면 똑같아지는지, 즉 모양이 같은 그래프인지 묻는 **그래프 동형(Graph isomorphism)** 문제예요.","아직 빠르게 푸는 방법이 알려지지 않은 어려운 문제예요."]},{"kind":"look","head":"오른쪽 그래프의 세로선","boxes":[{"x":0.52,"y":0.27,"w":0.2,"h":0.23,"say":"오른쪽 그래프는 2 와 4 를 잇는 세로선이 하나 더 있어요. 그래서 왼쪽과 모양이 달라요."}]},{"kind":"analogy","head":"이름을 가린 친구 관계도 두 장","scene":"반 친구 관계도 두 장이 있어요. 한 장엔 우리 반 이름이, 다른 장엔 옆 반 이름이 적혀 있어요. 이름을 모두 가린 뒤, 선으로 이어진 모양이 똑같은지 비교해요. 이름표만 바꿔서 딱 겹치면 같은 모양이고, 선 하나라도 남거나 모자라면 다른 모양이에요.","map":[["학생 이름표","노드 번호"],["친구 관계선","엣지"],["이름표만 바꾸면 딱 겹치는 관계도","**그래프 동형(Graph isomorphism)**"]]}],"pass2":[{"kind":"look","head":"복습 슬라이드 짚기","boxes":[{"x":0.03,"y":0.15,"w":0.4,"h":0.06,"say":"**표현력(Expressive power)** 의 고전적 시험대는 **그래프 동형(Graph isomorphism)** 이에요."},{"x":0.07,"y":0.22,"w":0.45,"h":0.05,"say":"두 그래프가 주어질 때 동형인지 판별할 수 있을까?"},{"x":0.2,"y":0.27,"w":0.2,"h":0.23,"say":"왼쪽 선: 1-2, 1-5, 2-5, 5-4, 4-3. 모두 5개."},{"x":0.52,"y":0.27,"w":0.2,"h":0.23,"say":"오른쪽은 2 와 4 를 잇는 세로선이 하나 더 있어 6개. 그래서 동형이 아니에요."},{"x":0.07,"y":0.6,"w":0.77,"h":0.07,"say":"미해결 문제: 다항 시간 알고리즘은 아직 알려지지 않았고, NP-완전인지도 증명되지 않았어요."}]},{"kind":"compare","head":"차수로 먼저 걸러 보기","cols":["노드","왼쪽 차수","오른쪽 차수"],"rows":[["1","2","2"],["2","2","3"],["3","1","1"],["4","2","3"],["5","3","3"],["합","10 (선 5개)","12 (선 6개)"]]},{"kind":"say","lines":["**차수(Degree)** 구성이 (3,2,2,2,1) 과 (3,3,3,2,1) 로 달라요.","차수 구성이 다르면 확실히 동형이 아니에요.","하지만 차수 구성이 같다고 동형인 건 아니에요."]},{"kind":"compare","head":"하나하나 다 맞춰 보면?","cols":["노드 수","이름표 바꾸는 방법 수"],"rows":[["5","$5! = 120$"],["10","$10! = 3{,}628{,}800$"],["20","약 $2.4 \\times 10^{18}$"]]},{"kind":"mining","src":"마이닝 9강 Graph Kernels","lines":["일대일 대응이 있어 이웃 관계가 빠짐없이 옮겨지면 동형이라고 정의했어요.","노드 수, 엣지 수, 차수 구성은 동형이면 반드시 같은 불변량이에요.","동형은 다항 시간 알고리즘도, NP-hard 여부도 알려지지 않았다고 배웠어요."]}],"pass3":[{"kind":"check","q":"'**그래프 동형(Graph isomorphism)**' 의 뜻은?","choices":["노드 수가 같은 두 그래프","이름표만 바꾸면 연결이 똑같아지는 두 그래프","차수 구성이 같은 두 그래프"],"a":1,"why":"노드 수나 차수 구성이 같은 건 필요조건일 뿐이에요. 연결이 통째로 같아져야 동형이에요."},{"kind":"english","head":"서술형 예시","en":"Two graphs are isomorphic if there is a node relabeling that makes their edges identical. A more expressive GNN should map non-isomorphic graphs to different embeddings.","ko":"노드 이름을 바꿔 엣지가 똑같아지면 두 그래프는 동형이다. 표현력이 좋은 GNN 은 동형이 아닌 그래프를 서로 다른 임베딩으로 보내야 한다."},{"kind":"warn","head":"슬라이드 오류와 주의","items":["영어 원본의 'does not exist' 는 틀린 표현이에요. '아직 알려지지 않았다'가 맞고, 한글 슬라이드는 고쳐 옮겼어요.","그림 속 번호는 설명용 이름표예요. 동형을 볼 때는 연결 모양만 봐요.","차수 구성이 같으면 더 강한 검사, **색 정제(Color refinement)** 가 필요해요."]}],"pass4":[{"kind":"pyterm","name":"리스트와 for 반복문","say":["`[a, b, c]` 는 순서 있는 목록, 리스트예요. **예시 코드**로 먼저 볼게요.","`for x in 리스트:` 는 하나씩 꺼내 아래 들여쓴 줄을 반복해요.","들여쓰기(빈칸 4개)가 어디까지 반복하는지를 정해요."],"example":"for d in [2, 2, 1]:\n    print(d * 10)","out":"20\n20\n10"},{"kind":"code","head":"차수는 같은데 동형이 아닌 두 그래프","file":"Sample_Code_3.ipynb 셀 7","code":"C6    = nx.cycle_graph(6)\nTwoC3 = nx.disjoint_union(nx.cycle_graph(3), nx.cycle_graph(3))\n\nfor name, G in [('C6', C6), ('2 x C3', TwoC3)]:\n    print(f'{name:7s} | nodes {G.number_of_nodes()} | edges {G.number_of_edges()} '\n          f'| components {nx.number_connected_components(G)} '\n          f'| degrees {sorted(d for _, d in G.degree())} '\n          f'| triangles {sum(nx.triangles(G).values()) // 3}')\nprint(f'Isomorphic? {nx.is_isomorphic(C6, TwoC3)}')\n\n# Fixed layouts reused by later figures: a hexagon, and two triangles side by side\nPOS_C6  = nx.circular_layout(C6)\nPOS_2C3 = {}\nfor nodes, cx, start in [([0, 1, 2], -1.0, np.pi), ([3, 4, 5], 1.0, 0.0)]:\n    for i, n in enumerate(nodes):\n        a = start + 2 * np.pi * i / 3\n        POS_2C3[n] = np.array([cx + 0.55 * np.cos(a), 0.55 * np.sin(a)])\n\nfig, axes = plt.subplots(1, 2, figsize=(10, 3.8))\ndraw_graph(C6, POS_C6, axes[0], title='$C_6$  (one 6-cycle)')\ndraw_graph(TwoC3, POS_2C3, axes[1], title='$2 \\\\times C_3$  (two triangles)')\nfig.suptitle('Two non-isomorphic graphs - every node has degree 2', fontsize=13, fontweight='bold')\nplt.tight_layout(); plt.show()","lines":[{"from":1,"to":2,"say":"`nx` 는 그래프 도구 NetworkX 의 별명이에요. 6각형 고리 C6 과, 삼각형 둘을 떨어뜨려 붙인 TwoC3 을 만들어요."},{"from":4,"to":4,"say":"리스트 속 (이름, 그래프) 쌍을 하나씩 꺼내 반복해요."},{"from":5,"to":8,"say":"노드 수, 엣지 수, 덩어리 수, 정렬한 **차수(Degree)** 목록, 삼각형 수를 출력해요. `f'...{}'` 는 값을 글자에 끼워 넣는 f-문자열이에요."},{"from":9,"to":9,"say":"`nx.is_isomorphic` 으로 진짜 **그래프 동형(Graph isomorphism)** 검사를 해요. 결과는 동형 아님이에요."},{"from":10,"to":17,"say":"뒤 그림에서 계속 쓸 좌표를 정해요. 육각형은 원 모양으로, 삼각형 두 개는 왼쪽과 오른쪽에 나란히 놓아요."},{"from":18,"to":23,"say":"그림판 두 칸을 만들어 두 그래프를 나란히 그리고 화면에 보여 줘요."}],"link":"슬라이드처럼 차수만 세면 못 가르는 쌍이에요. 두 그래프 모두 모든 노드 차수가 2 예요."}]},{"p":47,"title":"WL 커널의 색 정제 알고리즘","terms":["Color refinement","HASH","K-hop neighborhood","Multiset","Injective","WL graph kernel"],"pass1":[{"kind":"say","lines":["모든 노드에 같은 색을 칠하고, 노드마다 '내 색과 이웃들 색 묶음' 을 보고 새 색을 받는 일을 반복해요.","이 방법을 **색 정제(Color refinement)** 라고 해요. 색을 점점 잘게 나눈다는 뜻이에요.","새 색을 붙여 주는 규칙을 **HASH** 라고 불러요. 다른 묶음에는 반드시 다른 색을 줘요.","여러 번 반복할수록 색에 더 먼 이웃, 곧 **K홉 이웃(K-hop neighborhood)** 의 모양까지 담겨요. K홉은 K 걸음이에요."]},{"kind":"analogy","head":"라운드마다 스티커 바꾸기","scene":"반 친구 모두가 똑같은 별 스티커를 받고 시작해요. 한 라운드마다 각자 '내 스티커와 친구들 스티커 묶음' 을 적어 스티커 기계에 넣고 새 스티커를 받아요. 친구가 많은 사람과 적은 사람은 적은 내용이 달라서 서로 다른 스티커를 받아요. 라운드를 반복할수록 친구의 친구 정보까지 스티커에 담겨요.","map":[["지금 내 스티커","지금 내 색"],["친구들 스티커 묶음","이웃 색 **멀티셋(Multiset)**"],["스티커 기계","**HASH**, 다른 묶음엔 다른 색을 주는 규칙"]]}],"pass2":[{"kind":"look","head":"색 정제 알고리즘 읽기","boxes":[{"x":0.03,"y":0.16,"w":0.25,"h":0.05,"say":"**WL 그래프 커널(WL graph kernel)** 의 **색 정제(Color refinement)** 알고리즘이에요."},{"x":0.03,"y":0.25,"w":0.4,"h":0.15,"say":"주어진 것: 노드 집합 $V$ 인 그래프 $G$. 각 노드에 초기 색 $c^{(0)}(v)$ 를 줘요."},{"x":0.09,"y":0.43,"w":0.59,"h":0.18,"say":"주황 상자 식으로 색을 반복해서 정제해요. 정제 = 더 잘게 나누기."},{"x":0.1,"y":0.63,"w":0.5,"h":0.06,"say":"**HASH** 는 서로 다른 입력을 서로 다른 색으로 보내요. 즉 **단사(Injective)**."},{"x":0.09,"y":0.72,"w":0.73,"h":0.13,"say":"$K$ 단계 뒤 $c^{(K)}(v)$ 는 **K홉 이웃(K-hop neighborhood)** 구조를 요약해요. 1홉은 이웃, 2홉은 이웃의 이웃."}]},{"kind":"formula","head":"색 정제 식 (이웃 색은 두 겹 중괄호로 고쳐 적음)","tex":"c^{(k+1)}(v) = \\mathrm{HASH}\\left(c^{(k)}(v),\\ \\{\\{c^{(k)}(u)\\}\\}_{u\\in N(v)}\\right)","parts":[{"sym":"c^{(k)}(v)","say":"라운드 $k$ 에서 $v$ 의 색 (지금 내 스티커)"},{"sym":"c^{(k+1)}(v)","say":"다음 라운드에 받을 새 색"},{"sym":"\\{\\{c^{(k)}(u)\\}\\}_{u\\in N(v)}","say":"이웃들 지금 색을 모은 봉투, **멀티셋(Multiset)**"},{"sym":"\\mathrm{HASH}","say":"(내 색, 봉투) 를 새 색 번호로. 단사"},{"sym":"K","say":"전체 반복 횟수"}],"whole":"다음 라운드 내 색은, 지금 내 색과 이웃 색 봉투를 번호표 기계에 넣어 받는다."},{"kind":"steps","head":"선 그래프 가-나-다 로 두 라운드","steps":["라운드 1 입력: 가 (1, {{1}}), 나 (1, {{1, 1}}), 다 (1, {{1}})","HASH 표: (1, {{1}}) → 2, (1, {{1, 1}}) → 3. 새 색 가 2, 나 3, 다 2","라운드 2 입력: 가 (2, {{3}}), 나 (3, {{2, 2}}), 다 (2, {{3}})","HASH 표: (2, {{3}}) → 4, (3, {{2, 2}}) → 5. 새 색 가 4, 나 5, 다 4","무리 {가, 다}, {나} 가 그대로라 더 돌려도 안 갈라져요. '안정됐다'고 해요."],"answer":"가와 다는 좌우 대칭이라 끝까지 같은 색","given":"처음엔 모두 색 1"},{"kind":"figure","head":"라운드마다 새 색","svg":"<svg viewBox=\"0 0 480 270\" xmlns=\"http://www.w3.org/2000/svg\">\n<text class=\"tm\" x=\"20\" y=\"50\" font-size=\"14\">라운드 0<\/text>\n<line class=\"e\" x1=\"130\" y1=\"45\" x2=\"290\" y2=\"45\"/>\n<circle class=\"n\" cx=\"130\" cy=\"45\" r=\"18\"/>\n<circle class=\"n\" cx=\"210\" cy=\"45\" r=\"18\"/>\n<circle class=\"n\" cx=\"290\" cy=\"45\" r=\"18\"/>\n<text class=\"tl\" x=\"130\" y=\"51\" font-size=\"16\" text-anchor=\"middle\">1<\/text>\n<text class=\"tl\" x=\"210\" y=\"51\" font-size=\"16\" text-anchor=\"middle\">1<\/text>\n<text class=\"tl\" x=\"290\" y=\"51\" font-size=\"16\" text-anchor=\"middle\">1<\/text>\n<text class=\"tm\" x=\"130\" y=\"84\" font-size=\"14\" text-anchor=\"middle\">가<\/text>\n<text class=\"tm\" x=\"210\" y=\"84\" font-size=\"14\" text-anchor=\"middle\">나<\/text>\n<text class=\"tm\" x=\"290\" y=\"84\" font-size=\"14\" text-anchor=\"middle\">다<\/text>\n<text class=\"t\" x=\"330\" y=\"50\" font-size=\"14\">모두 색 1<\/text>\n<text class=\"tm b1\" x=\"20\" y=\"135\" font-size=\"14\">라운드 1<\/text>\n<line class=\"e b1\" x1=\"130\" y1=\"130\" x2=\"290\" y2=\"130\"/>\n<circle class=\"n2 b1\" cx=\"130\" cy=\"130\" r=\"18\"/>\n<circle class=\"n3 b1\" cx=\"210\" cy=\"130\" r=\"18\"/>\n<circle class=\"n2 b1\" cx=\"290\" cy=\"130\" r=\"18\"/>\n<text class=\"tl b1\" x=\"130\" y=\"136\" font-size=\"16\" text-anchor=\"middle\">2<\/text>\n<text class=\"tl b1\" x=\"210\" y=\"136\" font-size=\"16\" text-anchor=\"middle\">3<\/text>\n<text class=\"tl b1\" x=\"290\" y=\"136\" font-size=\"16\" text-anchor=\"middle\">2<\/text>\n<text class=\"t b1\" x=\"330\" y=\"122\" font-size=\"14\">(1, {{1}}) → 2<\/text>\n<text class=\"t b1\" x=\"330\" y=\"146\" font-size=\"14\">(1, {{1,1}}) → 3<\/text>\n<text class=\"tm b2\" x=\"20\" y=\"220\" font-size=\"14\">라운드 2<\/text>\n<line class=\"e b2\" x1=\"130\" y1=\"215\" x2=\"290\" y2=\"215\"/>\n<circle class=\"n4 b2\" cx=\"130\" cy=\"215\" r=\"18\"/>\n<circle class=\"n b2\" cx=\"210\" cy=\"215\" r=\"18\"/>\n<circle class=\"n4 b2\" cx=\"290\" cy=\"215\" r=\"18\"/>\n<text class=\"tl b2\" x=\"130\" y=\"221\" font-size=\"16\" text-anchor=\"middle\">4<\/text>\n<text class=\"tl b2\" x=\"210\" y=\"221\" font-size=\"16\" text-anchor=\"middle\">5<\/text>\n<text class=\"tl b2\" x=\"290\" y=\"221\" font-size=\"16\" text-anchor=\"middle\">4<\/text>\n<text class=\"t b2\" x=\"330\" y=\"207\" font-size=\"14\">(2, {{3}}) → 4<\/text>\n<text class=\"t b2\" x=\"330\" y=\"231\" font-size=\"14\">(3, {{2,2}}) → 5<\/text>\n<text class=\"tm b2\" x=\"240\" y=\"262\" font-size=\"14\" text-anchor=\"middle\">가와 다는 대칭이라 계속 같은 색<\/text>\n<\/svg>","caption":"색 번호 크기에는 뜻이 없어요. 다른 이름표일 뿐이에요.","builds":2},{"kind":"prof","when":"3주차 화요일 수업","lines":["WL 은 친구 이름과 내 이름을 모아 사전에서 찾고, 없으면 새 이름을 줘요.","사전처럼, 즉 해시 함수처럼 작동하니 **단사(Injective)** 래요.","지난 학기 WL 을 안 들었다면 한 번 다시 보고 오라고 했어요."]},{"kind":"mining","src":"마이닝 9강 Graph Kernels","lines":["WL 동형 테스트: 라벨 1 로 시작, 이웃 라벨 멀티셋 만들기, 새 라벨로 압축, 반복.","라벨 무리가 더 이상 안 바뀌면 멈췄어요. 이 슬라이드와 같은 과정이에요."]}],"pass3":[{"kind":"check","q":"**HASH** 가 꼭 가져야 하는 성질은?","choices":["같은 입력에 매번 다른 번호를 준다","서로 다른 입력에 서로 다른 번호를 준다","번호가 클수록 중요한 노드다"],"a":1,"why":"HASH 는 **단사(Injective)** 여야 해요. 같은 입력은 같은 번호, 다른 입력은 다른 번호."},{"kind":"english","head":"서술형 한 줄","en":"In color refinement, each node's new color is obtained by injectively hashing its own color together with the multiset of its neighbors' colors.","ko":"색 정제에서 각 노드의 새 색은 자기 색과 이웃 색 멀티셋을 함께 단사 해시해서 얻는다."},{"kind":"warn","head":"슬라이드 표기 오류와 주의","items":["식의 이웃 색 묶음이 한 겹 중괄호(집합)로 적혀 있어요. 개수를 세야 하니 두 겹(멀티셋)이 맞아요.","색 번호 크기에는 뜻이 없어요. 5 가 3 보다 '크다'가 아니라 다른 이름표예요.","HASH 표는 비교하는 두 그래프가 함께 쓰는 표 하나여야 해요."]}],"pass4":[{"kind":"say","lines":["이제 3주차 노트북 4절과 짝을 맞춰요.","노트북 4절이 바로 이 슬라이드의 **색 정제(Color refinement)** 예요."]},{"kind":"pyterm","name":"튜플(tuple)과 sorted","say":["`(1, (1, 1))` 처럼 둥근 괄호 묶음이 튜플이에요. 한 번 만들면 못 바꿔요. **예시 코드**로 볼게요.","`sorted(...)` 는 작은 것부터 줄 세워요. 이웃 색 순서를 통일해 멀티셋처럼 쓰는 요령이에요.","튜플은 사전의 키가 될 수 있어서 HASH 표의 입력으로 써요."],"example":"print(tuple(sorted([3, 1, 1])))","out":"(1, 1, 3)"},{"kind":"code","head":"aggregate: 내 색 + 이웃 색 봉투 (1/3)","file":"Sample_Code_3.ipynb 셀 14 (1/3)","code":"def aggregate(G, colors):\n    \"\"\"Step 2: aggregated color of every node = (own color, sorted tuple of neighbor colors).\"\"\"\n    return {v: (colors[v], tuple(sorted(colors[u] for u in G[v]))) for v in G}\n\n\ndef wl_refine(graphs, num_iterations=3):\n    \"\"\"\n    Color refinement run jointly on a list of graphs with one shared HASH table.\n\n    Returns `rounds`, where rounds[l] is a dict:\n        'colors' : [{node: color} per graph]             colors after round l\n        'agg'    : [{node: aggregated color} per graph]  what was hashed in round l\n        'table'  : {aggregated color: new color}         the HASH table of round l\n    rounds[0] is the initial coloring: every node gets color 1.\n    \"\"\"\n    rounds = [{'colors': [{v: 1 for v in G} for G in graphs], 'agg': None, 'table': {}}]\n    next_color = 2\n    for _ in range(num_iterations):\n        agg = [aggregate(G, c) for G, c in zip(graphs, rounds[-1]['colors'])]\n        # Step 3: injective hash. Every unseen aggregated color gets the next unused number.\n        # (Each round's inputs use fresh colors, so each round needs only its own table.)\n        table = {}\n        for a in agg:\n            for sig in a.values():\n                if sig not in table:\n                    table[sig] = next_color\n                    next_color += 1\n        colors = [{v: table[sig] for v, sig in a.items()} for a in agg]\n        rounds.append({'colors': colors, 'agg': agg, 'table': table})\n    return rounds\n","lines":[{"from":1,"to":1,"say":"그래프 G 와 지금 색 사전 colors 를 받는 함수예요."},{"from":2,"to":2,"say":"설명문: 집계된 색 = (내 색, 이웃 색을 정렬한 튜플)."},{"from":3,"to":3,"say":"`for v in G` 로 노드마다, `G[v]` 는 v 의 이웃들. `colors[v]` 가 내 색, `tuple(sorted(...))` 가 이웃 색 봉투예요."},{"from":5,"to":15,"say":"wl_refine 함수의 이름과 설명이에요. 여러 그래프가 HASH 표를 같이 쓰며 색 정제를 하고 rounds 목록을 돌려준대요."},{"from":16,"to":17,"say":"0라운드: 모든 노드를 색 1 로 칠해 rounds 에 넣어요. 새 번호는 2 부터 줘요."},{"from":18,"to":19,"say":"라운드 수만큼 반복하며, 지난 라운드 색으로 모든 노드의 집계 색을 만들어요."},{"from":20,"to":27,"say":"주석 두 줄 뒤, 빈 사전 table 에 처음 보는 집계 색마다 다음 번호를 적어요. 같은 조합은 같은 번호예요."},{"from":28,"to":31,"say":"표에서 새 번호를 찾아 노드를 다시 칠하고, 이번 라운드 결과를 rounds 끝에 붙여요. 다 돌면 rounds 를 돌려줘요."}],"link":"식의 $\\left(c^{(k)}(v), \\{\\{c^{(k)}(u)\\}\\}_{u\\in N(v)}\\right)$ 부분과 짝이에요."},{"kind":"code","head":"aggregate: 내 색 + 이웃 색 봉투 (2/3)","file":"Sample_Code_3.ipynb 셀 14 (2/3)","code":"\ndef color_histogram(colors):\n    \"\"\"How many nodes carry each color: the graph-level fingerprint.\"\"\"\n    return dict(sorted(Counter(colors.values()).items()))\n\n\ndef wl_report(rounds, names):\n    \"\"\"The WL test: compare the two graphs' color histograms round by round.\"\"\"\n    differ = False\n    for l, r in enumerate(rounds):\n        h1, h2 = (color_histogram(c) for c in r['colors'])\n        differ = differ or h1 != h2\n        print(f\"round {l}:  {names[0]} {str(h1):<34s} {'==' if h1 == h2 else '!='}  {names[1]} {h2}\")\n    print('\\n→ NON-ISOMORPHIC (the histograms differ)' if differ else\n          '\\n→ INCONCLUSIVE (the histograms are always equal)')\n\n\n# ---- drawing -------------------------------------------------------------------------\ndef fmt_agg(sig):\n    \"\"\"(3, (3, 4)) -> '3,{3,4}'\"\"\"\n    own, nbrs = sig\n    return f\"{own},{{{','.join(map(str, nbrs))}}}\"\n\n\ndef draw_aggregated(G, pos, ax, colors, agg, title=None):\n    \"\"\"Each node is a box showing its aggregated color, filled with its current color.\"\"\"\n    nx.draw_networkx_edges(G, pos, ax=ax, edge_color=C_EDGE, width=2.0)\n    for v in G:\n        f = color_of(colors[v])\n        ax.text(*pos[v], fmt_agg(agg[v]), ha='center', va='center', fontsize=10, color=ink(f),\n                bbox=dict(boxstyle='round,pad=0.35', fc=f, ec=C_DARK, lw=1.2))\n    xs, ys = zip(*pos.values())\n    ax.set_xlim(min(xs) - 0.5, max(xs) + 0.5)\n    ax.set_ylim(min(ys) - 0.4, max(ys) + 0.4)\n    if title:\n        ax.set_title(title)\n    ax.set_axis_off()\n","lines":[{"from":1,"to":5,"say":"color_histogram 함수: Counter 로 색마다 노드가 몇 개인지 세서 번호 순으로 정리해요."},{"from":6,"to":16,"say":"wl_report 함수: 라운드마다 두 그래프의 색 개수표를 비교해 == 또는 != 를 출력하고, 마지막에 판정을 알려 줘요."},{"from":17,"to":23,"say":"그리기 부분 시작이에요. fmt_agg 는 (3, (3, 4)) 같은 집계 색을 '3,{3,4}' 글자로 바꿔요."},{"from":24,"to":38,"say":"draw_aggregated 함수: 노드마다 집계 색 글자를 지금 색으로 칠한 상자에 적어 그려요."}]},{"kind":"code","head":"aggregate: 내 색 + 이웃 색 봉투 (3/3)","file":"Sample_Code_3.ipynb 셀 14 (3/3)","code":"\ndef draw_hash_table(ax, table, title):\n    tab = ax.table(cellText=[[fmt_agg(sig), c] for sig, c in table.items()],\n                   colLabels=['aggregated color', 'new color'], loc='center', cellLoc='center')\n    tab.auto_set_font_size(False); tab.set_fontsize(11); tab.scale(1, 1.7)\n    for j in range(2):                                   # header row\n        tab[0, j].set_facecolor(C_DARK)\n        tab[0, j].get_text().set(color='white', fontweight='bold')\n    for i, c in enumerate(table.values(), start=1):      # paint each new color\n        tab[i, 1].set_facecolor(color_of(c))\n        tab[i, 1].get_text().set(color=ink(color_of(c)), fontweight='bold')\n    ax.set_title(title)\n    ax.set_axis_off()\n\n\ndef show_initial(graphs, names, positions, rounds):\n    fig, axes = plt.subplots(1, len(graphs), figsize=(11, 3))\n    for ax, G, name, pos, c in zip(axes, graphs, names, positions, rounds[0]['colors']):\n        draw_graph(G, pos, ax, colors=c, labels='color', title=name)\n    fig.suptitle('Step 1 - Assign initial colors: every node gets color 1',\n                 fontsize=13, fontweight='bold')\n    plt.tight_layout(); plt.show()\n\n\ndef show_round(graphs, names, positions, rounds, l):\n    \"\"\"One round, left to right: aggregated colors -> HASH table -> new colors.\"\"\"\n    r, prev = rounds[l], rounds[l - 1]['colors']\n    fig = plt.figure(figsize=(15, 5.6))\n    gs = fig.add_gridspec(2, 3, width_ratios=[1, 0.75, 1])\n    for i, (G, name, pos) in enumerate(zip(graphs, names, positions)):\n        draw_aggregated(G, pos, fig.add_subplot(gs[i, 0]), prev[i], r['agg'][i],\n                        title=f'{name}: aggregated colors')\n        draw_graph(G, pos, fig.add_subplot(gs[i, 2]), colors=r['colors'][i], labels='color',\n                   title=f'{name}: new colors')\n    draw_hash_table(fig.add_subplot(gs[:, 1]), r['table'], title=f'HASH table (round {l})')\n    fig.suptitle(f'Round {l}:   Step 2 - aggregate neighboring colors   →   '\n                 f'Step 3 - injectively hash   →   new colors', fontsize=13, fontweight='bold')\n    plt.tight_layout(); plt.show()","lines":[{"from":1,"to":14,"say":"draw_hash_table 함수: HASH 표를 '집계 색, 새 색' 두 열짜리 표 그림으로 그리고 새 색 칸을 그 색으로 칠해요."},{"from":15,"to":23,"say":"show_initial 함수: 모든 노드가 색 1 인 시작 그림을 그래프마다 그려요."},{"from":24,"to":38,"say":"show_round 함수: 한 라운드를 왼쪽 집계 색, 가운데 HASH 표, 오른쪽 새 색 순서로 한 장에 그려요."}]},{"kind":"code","head":"wl_refine: HASH 표로 새 색 주기 (1/3)","file":"Sample_Code_3.ipynb 셀 14 (1/3)","code":"def aggregate(G, colors):\n    \"\"\"Step 2: aggregated color of every node = (own color, sorted tuple of neighbor colors).\"\"\"\n    return {v: (colors[v], tuple(sorted(colors[u] for u in G[v]))) for v in G}\n\n\ndef wl_refine(graphs, num_iterations=3):\n    \"\"\"\n    Color refinement run jointly on a list of graphs with one shared HASH table.\n\n    Returns `rounds`, where rounds[l] is a dict:\n        'colors' : [{node: color} per graph]             colors after round l\n        'agg'    : [{node: aggregated color} per graph]  what was hashed in round l\n        'table'  : {aggregated color: new color}         the HASH table of round l\n    rounds[0] is the initial coloring: every node gets color 1.\n    \"\"\"\n    rounds = [{'colors': [{v: 1 for v in G} for G in graphs], 'agg': None, 'table': {}}]\n    next_color = 2\n    for _ in range(num_iterations):\n        agg = [aggregate(G, c) for G, c in zip(graphs, rounds[-1]['colors'])]\n        # Step 3: injective hash. Every unseen aggregated color gets the next unused number.\n        # (Each round's inputs use fresh colors, so each round needs only its own table.)\n        table = {}\n        for a in agg:\n            for sig in a.values():\n                if sig not in table:\n                    table[sig] = next_color\n                    next_color += 1\n        colors = [{v: table[sig] for v, sig in a.items()} for a in agg]\n        rounds.append({'colors': colors, 'agg': agg, 'table': table})\n    return rounds\n","lines":[{"from":1,"to":4,"say":"aggregate 함수: 노드마다 (내 색, 이웃 색을 정렬해 묶은 튜플)을 만들어 사전으로 돌려줘요."},{"from":6,"to":15,"say":"함수 이름과 설명문. 여러 그래프에 **HASH** 표 하나를 함께 쓴다고 적혀 있어요."},{"from":16,"to":17,"say":"라운드 0: 모든 노드 색 1, 즉 $c^{(0)}(v) = 1$. 새 색 번호는 2 부터 줘요."},{"from":18,"to":19,"say":"`range(num_iterations)` 번 반복. 그래프마다 aggregate 로 (내 색, 이웃 색 봉투)를 만들어요. `zip` 은 그래프와 그 색을 짝지어요."},{"from":20,"to":27,"say":"처음 보는 집계 색이면 아직 안 쓴 번호를 줘요. 같은 입력은 같은 번호, 다른 입력은 다른 번호. 이게 단사 HASH 예요."},{"from":28,"to":29,"say":"HASH 표로 모든 노드의 새 색을 정하고, 이번 라운드 기록을 `append` 로 리스트에 붙여요."},{"from":30,"to":30,"say":"라운드별 기록 리스트를 돌려줘요."}],"link":"식 $c^{(k+1)}(v) = \\mathrm{HASH}(\\dots)$ 를 $K$ = num_iterations 번 반복하는 코드예요."},{"kind":"code","head":"wl_refine: HASH 표로 새 색 주기 (2/3)","file":"Sample_Code_3.ipynb 셀 14 (2/3)","code":"\ndef color_histogram(colors):\n    \"\"\"How many nodes carry each color: the graph-level fingerprint.\"\"\"\n    return dict(sorted(Counter(colors.values()).items()))\n\n\ndef wl_report(rounds, names):\n    \"\"\"The WL test: compare the two graphs' color histograms round by round.\"\"\"\n    differ = False\n    for l, r in enumerate(rounds):\n        h1, h2 = (color_histogram(c) for c in r['colors'])\n        differ = differ or h1 != h2\n        print(f\"round {l}:  {names[0]} {str(h1):<34s} {'==' if h1 == h2 else '!='}  {names[1]} {h2}\")\n    print('\\n→ NON-ISOMORPHIC (the histograms differ)' if differ else\n          '\\n→ INCONCLUSIVE (the histograms are always equal)')\n\n\n# ---- drawing -------------------------------------------------------------------------\ndef fmt_agg(sig):\n    \"\"\"(3, (3, 4)) -> '3,{3,4}'\"\"\"\n    own, nbrs = sig\n    return f\"{own},{{{','.join(map(str, nbrs))}}}\"\n\n\ndef draw_aggregated(G, pos, ax, colors, agg, title=None):\n    \"\"\"Each node is a box showing its aggregated color, filled with its current color.\"\"\"\n    nx.draw_networkx_edges(G, pos, ax=ax, edge_color=C_EDGE, width=2.0)\n    for v in G:\n        f = color_of(colors[v])\n        ax.text(*pos[v], fmt_agg(agg[v]), ha='center', va='center', fontsize=10, color=ink(f),\n                bbox=dict(boxstyle='round,pad=0.35', fc=f, ec=C_DARK, lw=1.2))\n    xs, ys = zip(*pos.values())\n    ax.set_xlim(min(xs) - 0.5, max(xs) + 0.5)\n    ax.set_ylim(min(ys) - 0.4, max(ys) + 0.4)\n    if title:\n        ax.set_title(title)\n    ax.set_axis_off()\n","lines":[{"from":1,"to":5,"say":"color_histogram 함수: Counter 로 색마다 노드가 몇 개인지 세서 번호 순으로 정리해요."},{"from":6,"to":16,"say":"wl_report 함수: 라운드마다 두 그래프의 색 개수표를 비교해 == 또는 != 를 출력하고, 마지막에 판정을 알려 줘요."},{"from":17,"to":23,"say":"그리기 부분 시작이에요. fmt_agg 는 (3, (3, 4)) 같은 집계 색을 '3,{3,4}' 글자로 바꿔요."},{"from":24,"to":38,"say":"draw_aggregated 함수: 노드마다 집계 색 글자를 지금 색으로 칠한 상자에 적어 그려요."}]},{"kind":"code","head":"wl_refine: HASH 표로 새 색 주기 (3/3)","file":"Sample_Code_3.ipynb 셀 14 (3/3)","code":"\ndef draw_hash_table(ax, table, title):\n    tab = ax.table(cellText=[[fmt_agg(sig), c] for sig, c in table.items()],\n                   colLabels=['aggregated color', 'new color'], loc='center', cellLoc='center')\n    tab.auto_set_font_size(False); tab.set_fontsize(11); tab.scale(1, 1.7)\n    for j in range(2):                                   # header row\n        tab[0, j].set_facecolor(C_DARK)\n        tab[0, j].get_text().set(color='white', fontweight='bold')\n    for i, c in enumerate(table.values(), start=1):      # paint each new color\n        tab[i, 1].set_facecolor(color_of(c))\n        tab[i, 1].get_text().set(color=ink(color_of(c)), fontweight='bold')\n    ax.set_title(title)\n    ax.set_axis_off()\n\n\ndef show_initial(graphs, names, positions, rounds):\n    fig, axes = plt.subplots(1, len(graphs), figsize=(11, 3))\n    for ax, G, name, pos, c in zip(axes, graphs, names, positions, rounds[0]['colors']):\n        draw_graph(G, pos, ax, colors=c, labels='color', title=name)\n    fig.suptitle('Step 1 - Assign initial colors: every node gets color 1',\n                 fontsize=13, fontweight='bold')\n    plt.tight_layout(); plt.show()\n\n\ndef show_round(graphs, names, positions, rounds, l):\n    \"\"\"One round, left to right: aggregated colors -> HASH table -> new colors.\"\"\"\n    r, prev = rounds[l], rounds[l - 1]['colors']\n    fig = plt.figure(figsize=(15, 5.6))\n    gs = fig.add_gridspec(2, 3, width_ratios=[1, 0.75, 1])\n    for i, (G, name, pos) in enumerate(zip(graphs, names, positions)):\n        draw_aggregated(G, pos, fig.add_subplot(gs[i, 0]), prev[i], r['agg'][i],\n                        title=f'{name}: aggregated colors')\n        draw_graph(G, pos, fig.add_subplot(gs[i, 2]), colors=r['colors'][i], labels='color',\n                   title=f'{name}: new colors')\n    draw_hash_table(fig.add_subplot(gs[:, 1]), r['table'], title=f'HASH table (round {l})')\n    fig.suptitle(f'Round {l}:   Step 2 - aggregate neighboring colors   →   '\n                 f'Step 3 - injectively hash   →   new colors', fontsize=13, fontweight='bold')\n    plt.tight_layout(); plt.show()","lines":[{"from":1,"to":14,"say":"draw_hash_table 함수: HASH 표를 '집계 색, 새 색' 두 열짜리 표 그림으로 그리고 새 색 칸을 그 색으로 칠해요."},{"from":15,"to":23,"say":"show_initial 함수: 모든 노드가 색 1 인 시작 그림을 그래프마다 그려요."},{"from":24,"to":38,"say":"show_round 함수: 한 라운드를 왼쪽 집계 색, 가운데 HASH 표, 오른쪽 새 색 순서로 한 장에 그려요."}]}]},{"p":48,"title":"색 정제 (1): 초기 색과 이웃 색 집계","terms":["Color refinement","Degree","Multiset","HASH","Graph isomorphism","1-WL"],"pass1":[{"kind":"say","lines":["두 그래프에 **색 정제(Color refinement)** 를 함께 돌려 보는 예예요.","처음엔 모든 노드를 같은 색으로 칠해요. 슬라이드에서는 이 색을 1 번 색이라고 불러요.","그다음 노드마다 '내 색과 이웃들 색' 을 적어요.","첫 라운드에 적는 내용은 사실상 이웃이 몇 명인지, 곧 **차수(Degree)** 라서 두 그래프가 아직 똑같아 보여요."]},{"kind":"look","head":"색칠하고 적기","boxes":[{"x":0.07,"y":0.25,"w":0.67,"h":0.27,"say":"위쪽은 두 그래프를 모두 1 번 색으로 칠한 시작 모습이에요."},{"x":0.16,"y":0.61,"w":0.32,"h":0.28,"say":"아래 왼쪽은 노드마다 '내 색, 이웃 색들' 을 적은 결과예요. 쉼표 뒤 1 의 개수가 이웃 수예요."},{"x":0.52,"y":0.61,"w":0.31,"h":0.28,"say":"아래 오른쪽 그래프도 적힌 내용의 종류와 개수가 왼쪽과 똑같아요."}]}],"pass2":[{"kind":"look","head":"초기 색 부여와 이웃 색 집계","boxes":[{"x":0.03,"y":0.16,"w":0.24,"h":0.05,"say":"두 그래프에 대한 **색 정제(Color refinement)** 예. 같은 **HASH** 표를 함께 써요."},{"x":0.07,"y":0.25,"w":0.67,"h":0.27,"say":"초기 색 부여: 두 그래프 모두 노드 6개, 선 7개, 전부 색 1 에서 출발."},{"x":0.16,"y":0.61,"w":0.32,"h":0.28,"say":"왼쪽 집계: '1,111' 은 내 색 1 과 이웃 색 **멀티셋(Multiset)** {{1, 1, 1}}."},{"x":0.52,"y":0.61,"w":0.31,"h":0.28,"say":"오른쪽 집계도 글자 종류와 개수가 왼쪽과 똑같아요."},{"x":0.24,"y":0.81,"w":0.17,"h":0.08,"say":"왼쪽 아래 '1,1' 두 개는 둘 다 같은 노드(가운데 왼쪽)에 붙어 있어요. 차이는 여기서 나와요."}]},{"kind":"points","head":"'1,111' 읽는 법","items":["쉼표 앞 1: 내 색 $c^{(0)}(v)$","쉼표 뒤 111: 이웃 색 멀티셋 {{1, 1, 1}}","뒤쪽 1 의 개수 = 이웃 수 = **차수(Degree)**","이웃 색은 순서가 없으니 작은 번호부터 적기로 약속해요."]},{"kind":"say","lines":["위치로 이름을 붙여요. 위 왼쪽 A, 위 오른쪽 B,","가운데 왼쪽 C, 가운데 오른쪽 D, 아래 왼쪽 E, 아래 오른쪽 F."]},{"kind":"compare","head":"왼쪽 그래프 집계","cols":["노드","이웃","집계 글자"],"rows":[["A","B, C, D","1,111"],["B","A, D","1,11"],["C","A, D, E, F","1,1111"],["D","A, B, C","1,111"],["E","C","1,1"],["F","C","1,1"]]},{"kind":"compare","head":"오른쪽 그래프 집계","cols":["노드","이웃","집계 글자"],"rows":[["A","B, C","1,11"],["B","A, C, D","1,111"],["C","A, B, D, E","1,1111"],["D","B, C, F","1,111"],["E","C","1,1"],["F","D","1,1"]]},{"kind":"compare","head":"글자별 개수","cols":["집계 글자","왼쪽","오른쪽"],"rows":[["1,1","2","2"],["1,11","1","1"],["1,111","2","2"],["1,1111","1","1"]]},{"kind":"say","lines":["완전히 같아요. 차수 구성이 둘 다 (4, 3, 3, 2, 1, 1) 이거든요.","차이는 E, F 가 붙은 곳이에요. 왼쪽은 둘 다 C, 오른쪽은 C 와 D.","이 차이는 이웃의 이웃을 보는 2라운드에서 잡혀요."]},{"kind":"prof","when":"3주차 화요일 수업","lines":["1-WL 은 노드마다 이름을 두고, 이웃에 따라 이름을 업데이트해요.","'나는 1 인데 1, 2 를 친구로 가진 1 이야' 식이에요.","정확히는 노드가 아니라 노드의 구조에 이름을 준다고 했어요."]},{"kind":"mining","src":"마이닝 9강 Graph Kernels","lines":["마이닝 WL 테스트 예제도 모든 라벨을 1 로 두고 {1,1,1}, {1,1} 같은 멀티셋을 만들었어요.","'1,111' 은 그 멀티셋 앞에 내 라벨을 붙여 한 줄로 적은 것뿐이에요."]}],"pass3":[{"kind":"exam","src":"그래프 마이닝 2026 봄 기말 3번 (a) (WL 커널, 5점)","q":"Perform one iteration (color refinement) of the 1-WL test for the given graph. Initialize all nodes with the color '1'. Show the multi-set of neighborhood colors for each node, the aggregated string, and assign new hashed colors.","qko":"주어진 그래프에 1-WL 색 정제를 한 번 하라. 모든 노드를 색 1 로 두고, 노드마다 이웃 색 멀티셋, 합친 문자열, 새 해시 색을 보여라.","solve":["모든 노드에 색 1 을 준다.","노드마다 이웃 색 멀티셋을 적는다. 이웃 3명이면 {{1, 1, 1}}.","내 색을 앞에 붙여 집계 문자열을 쓴다. 예: '1,111'.","처음 보는 문자열마다 새 번호를 준다(단사 **HASH**). 여러 그래프면 표 하나를 함께 쓴다."],"answer":"노드 / 내 색 / 이웃 색 멀티셋 / 집계 문자열 / 새 색, 다섯 칸 표로 답해요. 첫 반복의 새 색은 차수만 반영해요."},{"kind":"check","q":"1라운드 집계 글자 '1,11' 이 뜻하는 것은?","choices":["내 색 1, 이웃 2명(색 1, 1)","색 번호 111","내 색 11, 이웃 1명"],"a":0,"why":"쉼표 앞이 내 색, 뒤의 1 개수가 이웃 수예요. 숫자 십일이 아니에요."},{"kind":"english","head":"서술형 한 줄","en":"In the first iteration, the aggregated colors only reflect node degrees.","ko":"첫 반복에서 집계된 색은 노드 차수만 반영한다."},{"kind":"warn","head":"주의","items":["'1,111' 은 숫자 천백십일이 아니에요. 내 색 1 과 이웃 색 1, 1, 1 을 붙인 기호예요.","1라운드 결과가 같다고 **그래프 동형(Graph isomorphism)** 이라 결론 내리면 안 돼요. 다음 라운드까지 봐야 해요.","선 개수, 차수 구성이 같아서 차수만으로는 못 가르는 쌍이에요. 그래서 **1-WL** 의 좋은 예제예요."]}],"pass4":[{"kind":"code","head":"두 그래프 만들고 초기 색 칠하기","file":"Sample_Code_3.ipynb 셀 16","code":"G1 = nx.Graph([(0, 1), (1, 2), (2, 0), (2, 3), (3, 4), (4, 5)])     # triangle + tail\nG2 = nx.Graph([(0, 1), (1, 2), (2, 3), (3, 0), (3, 4), (4, 5)])     # square + tail\nPOS_G1 = {0: (0, 0.6), 1: (0, -0.6), 2: (1, 0), 3: (2, 0), 4: (3, 0), 5: (4, 0)}\nPOS_G2 = {0: (0.7, 0.7), 1: (0, 0), 2: (0.7, -0.7), 3: (1.4, 0), 4: (2.4, 0), 5: (3.4, 0)}\n\nPAIR = dict(graphs=[G1, G2], names=['$G_1$', '$G_2$'], positions=[POS_G1, POS_G2])\nrounds = wl_refine(PAIR['graphs'], num_iterations=2)\n\nshow_initial(**PAIR, rounds=rounds)","lines":[{"from":1,"to":2,"say":"`nx.Graph([...])` 는 (노드, 노드) 쌍 리스트로 그래프를 만들어요. G1 은 삼각형 + 꼬리, G2 는 사각형 + 꼬리."},{"from":3,"to":4,"say":"그림 그릴 좌표 사전이에요. 계산에는 쓰이지 않아요."},{"from":6,"to":6,"say":"두 그래프 정보를 사전 하나에 묶어요. `dict(graphs=...)` 는 {'graphs': ...} 와 같아요."},{"from":7,"to":7,"say":"두 그래프를 HASH 표 하나로 2라운드 정제해요. p.47 의 wl_refine 이에요."},{"from":9,"to":9,"say":"`**PAIR` 는 사전을 이름 붙은 인자로 펼쳐 넘겨요. 모든 노드 색 1 인 초기 그림을 그려요."}],"link":"슬라이드의 '초기 색 부여'예요. 노트북 그래프는 슬라이드와 다르지만 절차는 같아요."},{"kind":"steps","head":"노트북 결과 읽기 (셀 17, 23)","steps":["라운드 1 HASH 표: (1, (1, 1)) → 2, (1, (1, 1, 1)) → 3, (1, (1,)) → 4","색 2, 3, 4 는 차수 2, 3, 1 의 변장이에요. 두 그래프 모두 {2: 4, 3: 1, 4: 1}.","라운드 2: G1 {5: 3, 6: 1, 7: 1, 8: 1}, G2 {5: 2, 6: 1, 8: 1, 9: 1, 10: 1}.","색 9 = 2,{2,2} 는 G2 에만, 색 7 = 2,{2,4} 는 G1 에만 있어요."],"answer":"색 개수표(히스토그램)가 달라져서 G1, G2 는 동형이 아니에요."},{"kind":"code","head":"두 그래프 비교 보고서","file":"Sample_Code_3.ipynb 셀 22","code":"wl_report(rounds, ['G1', 'G2'])","lines":[{"from":1,"to":1,"say":"라운드마다 두 그래프의 색 **히스토그램(Histogram)** 을 비교해 == 또는 != 를 출력해요. p.39 의 개수표와 같은 생각이에요."}],"link":"색 구성이 한 번이라도 다르면 **1-WL** 판정은 '동형 아님'이에요."}]},{"p":49,"title":"색 정제 (2): 모은 색을 새 번호로","terms":["Color refinement","HASH","Injective","Color histogram"],"pass1":[{"kind":"say","lines":["첫 라운드의 뒷부분이에요. 노드마다 모은 '내 색과 이웃 색' 조합에 짧은 새 번호를 붙여요.","번호를 붙여 주는 규칙을 **해시(HASH)** 라고 불러요.","조합이 다르면 반드시 다른 번호를, 같으면 같은 번호를 줘요. 다른 입력에 다른 결과, 이게 **단사(Injective)** 예요."]},{"kind":"look","head":"번호표 규칙과 결과","boxes":[{"x":0.61,"y":0.6,"w":0.24,"h":0.27,"say":"오른쪽 표가 번호표 규칙이에요. 적힌 조합마다 새 번호가 하나씩 정해져 있어요."},{"x":0.16,"y":0.61,"w":0.43,"h":0.27,"say":"왼쪽은 새 번호를 노드에 적은 결과예요. 두 그래프가 같은 규칙표 하나를 함께 써요."}]},{"kind":"analogy","head":"용무마다 줄이 다른 번호표 기계","scene":"은행 번호표 기계가 용무마다 다른 줄의 번호표를 준다고 생각해요. 예금하러 온 사람은 모두 같은 줄 번호를, 대출 상담하러 온 사람은 모두 다른 줄 번호를 받아요. 용무가 다른데 같은 줄로 보내는 일은 절대 없어요. 그래서 번호표만 봐도 어떤 용무로 왔는지 알 수 있어요.","map":[["용무 종류","노드가 모은 '내 색과 이웃 색' 조합"],["번호표","새 색 번호"],["용무가 다르면 번호도 다름","**단사(Injective)**"]]}],"pass2":[{"kind":"look","head":"슬라이드를 차례로 짚어 볼게요","boxes":[{"x":0.25,"y":0.29,"w":0.49,"h":0.21,"say":"위 그림은 p.48 에서 모은 결과예요. '1,111' 은 내 색 1, 친구 셋 모두 색 1 이에요."},{"x":0.09,"y":0.51,"w":0.27,"h":0.06,"say":"주황 글씨 '단사적으로' 가 핵심이에요. **단사(Injective)** 는 다른 조합에 다른 번호예요."},{"x":0.61,"y":0.6,"w":0.24,"h":0.27,"say":"**해시(HASH)** 표예요. 1,1 은 2, 1,11 은 3, 1,111 은 4, 1,1111 은 5 로 가요."},{"x":0.16,"y":0.61,"w":0.43,"h":0.27,"say":"새 번호를 노드에 적은 결과예요. 두 그래프가 표 하나를 같이 써요."}]},{"kind":"points","head":"'1,111' 읽는 법","items":["쉼표 **앞**의 1 은 '내 색' 이에요.","쉼표 **뒤** 1 의 개수가 친구 수예요. 111 이면 친구 3명.","새 번호가 2 부터인 건 1 을 처음 색으로 이미 썼기 때문이에요.","그래서 1라운드 색은 사실상 '친구 수' 의 다른 이름이에요."]},{"kind":"figure","head":"HASH 표가 하는 일","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\"><text x=\"240\" y=\"28\" font-size=\"18\" text-anchor=\"middle\" class=\"tb\">HASH 표 (두 그래프가 함께 씀)<\/text><rect x=\"110\" y=\"44\" width=\"260\" height=\"176\" rx=\"12\" class=\"box\"/><text x=\"200\" y=\"76\" font-size=\"17\" text-anchor=\"end\" class=\"t b1\">1,1<\/text><line x1=\"215\" y1=\"70\" x2=\"271\" y2=\"70\" class=\"e b1\"/><polygon points=\"280,70 271,75 271,65\" class=\"arrow b1\"/><circle cx=\"310\" cy=\"70\" r=\"17\" class=\"n3 b1\"/><text x=\"310\" y=\"75\" font-size=\"16\" text-anchor=\"middle\" class=\"tl b1\">2<\/text><text x=\"200\" y=\"118\" font-size=\"17\" text-anchor=\"end\" class=\"t b1\">1,11<\/text><line x1=\"215\" y1=\"112\" x2=\"271\" y2=\"112\" class=\"e b1\"/><polygon points=\"280,112 271,117 271,107\" class=\"arrow b1\"/><circle cx=\"310\" cy=\"112\" r=\"17\" class=\"n3 b1\"/><text x=\"310\" y=\"117\" font-size=\"16\" text-anchor=\"middle\" class=\"tl b1\">3<\/text><text x=\"200\" y=\"160\" font-size=\"17\" text-anchor=\"end\" class=\"t b2\">1,111<\/text><line x1=\"215\" y1=\"154\" x2=\"271\" y2=\"154\" class=\"e b2\"/><polygon points=\"280,154 271,159 271,149\" class=\"arrow b2\"/><circle cx=\"310\" cy=\"154\" r=\"17\" class=\"n3 b2\"/><text x=\"310\" y=\"159\" font-size=\"16\" text-anchor=\"middle\" class=\"tl b2\">4<\/text><text x=\"200\" y=\"202\" font-size=\"17\" text-anchor=\"end\" class=\"t b2\">1,1111<\/text><line x1=\"215\" y1=\"196\" x2=\"271\" y2=\"196\" class=\"e b2\"/><polygon points=\"280,196 271,201 271,191\" class=\"arrow b2\"/><circle cx=\"310\" cy=\"196\" r=\"17\" class=\"n3 b2\"/><text x=\"310\" y=\"201\" font-size=\"16\" text-anchor=\"middle\" class=\"tl b2\">5<\/text><text x=\"240\" y=\"250\" font-size=\"15\" text-anchor=\"middle\" class=\"tm b3\">새 색 2, 3, 4, 5 = 친구 1, 2, 3, 4명<\/text><\/svg>","caption":"서로 다른 조합은 서로 다른 번호로 가요. 겹치는 번호가 없으니 **단사(Injective)** 예요.","builds":3},{"kind":"steps","head":"왼쪽 그래프를 손으로 계산해요","steps":["A 친구 B, C, D: 집계 1,111 이라서 새 색 4","B 친구 A, D: 집계 1,11 이라서 새 색 3","C 친구 A, D, E, F: 집계 1,1111 이라서 새 색 5","D 친구 A, B, C: 집계 1,111 이라서 새 색 4","E, F 는 친구가 C 하나: 집계 1,1 이라서 새 색 2","색마다 개수를 세면 **색 히스토그램(Color histogram)** 이 돼요."],"answer":"'색:개수' 로 적으면 왼쪽 {2:2, 3:1, 4:2, 5:1}, 오른쪽도 {2:2, 3:1, 4:2, 5:1}. 색 2 가 2개, 색 3 이 1개라는 뜻이에요. 아직 구별이 안 돼요.","given":"이름: 위 왼쪽 A, 위 오른쪽 B, 가운데 왼쪽 C, 가운데 오른쪽 D, 아래 E, F. 엣지 A-B, A-C, A-D, B-D, C-D, C-E, C-F"},{"kind":"prof","when":"3주차 화요일 수업","lines":["업데이트한 설명을 사전에서 찾아 새 이름을 줘요.","설명이 같으면 같은 이름, 다르면 다른 이름이어야 한대요."]},{"kind":"mining","src":"마이닝 9강 Graph Kernels","lines":["WL 동형 테스트를 같은 순서로 배웠어요. 모두 라벨 1, 이웃 라벨 모으기, 압축 라벨, 반복.","해시 함수는 긴 입력을 작은 정수로 바꾸는 함수라고 정의했어요.","여기서 꼭 필요한 성질은 '다른 조합이면 다른 번호', 곧 **단사(Injective)** 예요."]}],"pass3":[{"kind":"exam","src":"그래프 마이닝 2026 봄 기말 3번 (a) (5점)","q":"Perform one iteration (color refinement) of the 1-WL test for the given graph. Initialize all nodes with color 1. Show the multi-set of neighborhood colors, the aggregated string, and the new hashed colors.","qko":"주어진 그래프에 **1-WL 테스트(1-WL)** 를 한 번 돌려라. 모두 색 1 로 시작하고, 이웃 색 멀티셋, 집계 문자열, 새 해시 색을 보여라. (이 슬라이드 왼쪽 그래프와 같은 그래프)","solve":["이웃 목록: N(A)={B,C,D}, N(B)={A,D}, N(C)={A,D,E,F}, N(D)={A,B,C}, N(E)={C}, N(F)={C}","이웃 색 멀티셋: A {1,1,1}, B {1,1}, C {1,1,1,1}, D {1,1,1}, E {1}, F {1}","집계 문자열: A (1,{1,1,1}), B (1,{1,1}), C (1,{1,1,1,1}), D (1,{1,1,1}), E, F (1,{1})","단사 해시 표: (1,{1}) 2, (1,{1,1}) 3, (1,{1,1,1}) 4, (1,{1,1,1,1}) 5"],"answer":"A 4, B 3, C 5, D 4, E 2, F 2"},{"kind":"english","head":"해시 과정을 영어로","en":"The aggregated string (1, {1,1,1}) is injectively hashed to the new color 4.","ko":"집계 문자열 (1, {1,1,1}) 은 단사적으로 새 색 4 로 해시된다.","tip":"injectively hashed 를 한 덩어리로 외워요."},{"kind":"check","q":"'1,111' 은 무슨 뜻일까요?","choices":["숫자 천백십일","내 색 1, 친구 셋 모두 색 1","친구가 111명","색 1 이 네 번 바뀜"],"a":1,"why":"쉼표 앞은 내 색, 뒤 1 의 개수가 친구 수예요. 숫자가 아니라 기호예요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["HASH 표는 두 그래프가 **하나를 같이** 써요. 따로 번호를 매기면 비교할 수 없어요.","새 번호가 2 인지 7 인지는 중요하지 않아요. 같은 조합은 같은 번호, 다른 조합은 다른 번호면 돼요.","시험 답에는 이웃 목록, 멀티셋, 집계 문자열, 해시 표를 차례로 모두 적어요."]}],"pass4":[{"kind":"say","lines":["이제 3주차 실습 노트북 Sample_Code_3_번역.ipynb 에서 같은 일을 하는 코드를 봐요.","셀 번호는 노트북 맨 위 셀을 0 으로 세었어요.","파이썬이 처음이어도 괜찮아요. 한 줄씩 뜻을 붙일게요."]},{"kind":"pyterm","name":"딕셔너리(dict, 사전)","say":["이름표(키)로 값을 찾는 사전이에요. {키: 값} 으로 써요.","색 정제에서는 '노드 이름: 색 번호' 를 담는 데 써요."],"example":"colors = {'A': 1, 'B': 1}\nprint(colors['A'])","out":"1"},{"kind":"pyterm","name":"튜플(tuple)","say":["괄호로 묶은 값 모음이에요. 한 번 만들면 바꿀 수 없어요.","(내 색, 친구 색 묶음) 처럼 칸 순서가 정해진 묶음을 만들 때 써요."],"example":"sig = (1, (1, 1, 1))\nprint(sig[0], sig[1])","out":"1 (1, 1, 1)"},{"kind":"code","head":"집계: 내 색과 친구 색 봉투 만들기 (1/3)","file":"Sample_Code_3_번역.ipynb 셀 19 (1/3)","code":"def aggregate(G, colors):\n    \"\"\"Step 2: aggregated color of every node = (own color, sorted tuple of neighbor colors).\"\"\"\n    return {v: (colors[v], tuple(sorted(colors[u] for u in G[v]))) for v in G}\n\n\ndef wl_refine(graphs, num_iterations=3):\n    \"\"\"\n    Color refinement run jointly on a list of graphs with one shared HASH table.\n\n    Returns `rounds`, where rounds[l] is a dict:\n        'colors' : [{node: color} per graph]             colors after round l\n        'agg'    : [{node: aggregated color} per graph]  what was hashed in round l\n        'table'  : {aggregated color: new color}         the HASH table of round l\n    rounds[0] is the initial coloring: every node gets color 1.\n    \"\"\"\n    rounds = [{'colors': [{v: 1 for v in G} for G in graphs], 'agg': None, 'table': {}}]\n    next_color = 2\n    for _ in range(num_iterations):\n        agg = [aggregate(G, c) for G, c in zip(graphs, rounds[-1]['colors'])]\n        # Step 3: 단사 해시. 처음 보는 집계된 색마다 아직 안 쓴 다음 번호를 준다.\n        # (매 라운드의 입력은 새 색들이므로 라운드마다 자기 표 하나만 있으면 된다.)\n        table = {}\n        for a in agg:\n            for sig in a.values():\n                if sig not in table:\n                    table[sig] = next_color\n                    next_color += 1\n        colors = [{v: table[sig] for v, sig in a.items()} for a in agg]\n        rounds.append({'colors': colors, 'agg': agg, 'table': table})\n    return rounds\n","lines":[{"from":1,"to":1,"say":"def 는 함수를 만드는 말이에요. 이름은 aggregate, 재료는 그래프 G 와 색 사전 colors 예요."},{"from":2,"to":2,"say":"세 따옴표로 감싼 줄은 설명문이에요. 실행 결과에는 영향이 없어요."},{"from":3,"to":3,"say":"sorted 로 정렬해서 친구 순서가 달라도 같은 멀티셋이면 같은 튜플이 돼요."},{"from":3,"to":3,"say":"노드 v 마다 (내 색, 친구 색을 정렬한 튜플) 을 만들어 사전으로 돌려줘요. G[v] 는 v 의 친구들이에요."},{"from":5,"to":15,"say":"wl_refine 함수의 이름과 설명이에요. 여러 그래프가 HASH 표를 같이 쓰며 색 정제를 하고 rounds 목록을 돌려준대요."},{"from":16,"to":17,"say":"0라운드: 모든 노드를 색 1 로 칠해 rounds 에 넣어요. 새 번호는 2 부터 줘요."},{"from":18,"to":19,"say":"라운드 수만큼 반복하며, 지난 라운드 색으로 모든 노드의 집계 색을 만들어요."},{"from":20,"to":27,"say":"주석 두 줄 뒤, 빈 사전 table 에 처음 보는 집계 색마다 다음 번호를 적어요. 같은 조합은 같은 번호예요."},{"from":28,"to":31,"say":"표에서 새 번호를 찾아 노드를 다시 칠하고, 이번 라운드 결과를 rounds 끝에 붙여요. 다 돌면 rounds 를 돌려줘요."}],"link":"슬라이드의 '1,111' 한 칸 = 파이썬 튜플 (1, (1, 1, 1)) 이에요."},{"kind":"code","head":"집계: 내 색과 친구 색 봉투 만들기 (2/3)","file":"Sample_Code_3_번역.ipynb 셀 19 (2/3)","code":"\ndef color_histogram(colors):\n    \"\"\"How many nodes carry each color: the graph-level fingerprint.\"\"\"\n    return dict(sorted(Counter(colors.values()).items()))\n\n\ndef wl_report(rounds, names):\n    \"\"\"The WL test: compare the two graphs' color histograms round by round.\"\"\"\n    differ = False\n    for l, r in enumerate(rounds):\n        h1, h2 = (color_histogram(c) for c in r['colors'])\n        differ = differ or h1 != h2\n        print(f\"round {l}:  {names[0]} {str(h1):<34s} {'==' if h1 == h2 else '!='}  {names[1]} {h2}\")\n    print('\\n→ NON-ISOMORPHIC (the histograms differ)' if differ else\n          '\\n→ INCONCLUSIVE (the histograms are always equal)')\n\n\n# ---- 그리기 -------------------------------------------------------------------------\ndef fmt_agg(sig):\n    \"\"\"(3, (3, 4)) -> '3,{3,4}'\"\"\"\n    own, nbrs = sig\n    return f\"{own},{{{','.join(map(str, nbrs))}}}\"\n\n\ndef draw_aggregated(G, pos, ax, colors, agg, title=None):\n    \"\"\"Each node is a box showing its aggregated color, filled with its current color.\"\"\"\n    nx.draw_networkx_edges(G, pos, ax=ax, edge_color=C_EDGE, width=2.0)\n    for v in G:\n        f = color_of(colors[v])\n        ax.text(*pos[v], fmt_agg(agg[v]), ha='center', va='center', fontsize=10, color=ink(f),\n                bbox=dict(boxstyle='round,pad=0.35', fc=f, ec=C_DARK, lw=1.2))\n    xs, ys = zip(*pos.values())\n    ax.set_xlim(min(xs) - 0.5, max(xs) + 0.5)\n    ax.set_ylim(min(ys) - 0.4, max(ys) + 0.4)\n    if title:\n        ax.set_title(title)\n    ax.set_axis_off()\n","lines":[{"from":1,"to":5,"say":"color_histogram 함수: Counter 로 색마다 노드가 몇 개인지 세서 번호 순으로 정리해요."},{"from":6,"to":16,"say":"wl_report 함수: 라운드마다 두 그래프의 색 개수표를 비교해 == 또는 != 를 출력하고, 마지막에 판정을 알려 줘요."},{"from":17,"to":23,"say":"그리기 부분 시작이에요. fmt_agg 는 (3, (3, 4)) 같은 집계 색을 '3,{3,4}' 글자로 바꿔요."},{"from":24,"to":38,"say":"draw_aggregated 함수: 노드마다 집계 색 글자를 지금 색으로 칠한 상자에 적어 그려요."}]},{"kind":"code","head":"집계: 내 색과 친구 색 봉투 만들기 (3/3)","file":"Sample_Code_3_번역.ipynb 셀 19 (3/3)","code":"\ndef draw_hash_table(ax, table, title):\n    tab = ax.table(cellText=[[fmt_agg(sig), c] for sig, c in table.items()],\n                   colLabels=['aggregated color', 'new color'], loc='center', cellLoc='center')\n    tab.auto_set_font_size(False); tab.set_fontsize(11); tab.scale(1, 1.7)\n    for j in range(2):                                   # 머리글 행\n        tab[0, j].set_facecolor(C_DARK)\n        tab[0, j].get_text().set(color='white', fontweight='bold')\n    for i, c in enumerate(table.values(), start=1):      # 새 색마다 칸을 그 색으로 칠한다\n        tab[i, 1].set_facecolor(color_of(c))\n        tab[i, 1].get_text().set(color=ink(color_of(c)), fontweight='bold')\n    ax.set_title(title)\n    ax.set_axis_off()\n\n\ndef show_initial(graphs, names, positions, rounds):\n    fig, axes = plt.subplots(1, len(graphs), figsize=(11, 3))\n    for ax, G, name, pos, c in zip(axes, graphs, names, positions, rounds[0]['colors']):\n        draw_graph(G, pos, ax, colors=c, labels='color', title=name)\n    fig.suptitle('Step 1 - Assign initial colors: every node gets color 1',\n                 fontsize=13, fontweight='bold')\n    plt.tight_layout(); plt.show()\n\n\ndef show_round(graphs, names, positions, rounds, l):\n    \"\"\"One round, left to right: aggregated colors -> HASH table -> new colors.\"\"\"\n    r, prev = rounds[l], rounds[l - 1]['colors']\n    fig = plt.figure(figsize=(15, 5.6))\n    gs = fig.add_gridspec(2, 3, width_ratios=[1, 0.75, 1])\n    for i, (G, name, pos) in enumerate(zip(graphs, names, positions)):\n        draw_aggregated(G, pos, fig.add_subplot(gs[i, 0]), prev[i], r['agg'][i],\n                        title=f'{name}: aggregated colors')\n        draw_graph(G, pos, fig.add_subplot(gs[i, 2]), colors=r['colors'][i], labels='color',\n                   title=f'{name}: new colors')\n    draw_hash_table(fig.add_subplot(gs[:, 1]), r['table'], title=f'HASH table (round {l})')\n    fig.suptitle(f'Round {l}:   Step 2 - aggregate neighboring colors   →   '\n                 f'Step 3 - injectively hash   →   new colors', fontsize=13, fontweight='bold')\n    plt.tight_layout(); plt.show()","lines":[{"from":1,"to":14,"say":"draw_hash_table 함수: HASH 표를 '집계 색, 새 색' 두 열짜리 표 그림으로 그리고 새 색 칸을 그 색으로 칠해요."},{"from":15,"to":23,"say":"show_initial 함수: 모든 노드가 색 1 인 시작 그림을 그래프마다 그려요."},{"from":24,"to":38,"say":"show_round 함수: 한 라운드를 왼쪽 집계 색, 가운데 HASH 표, 오른쪽 새 색 순서로 한 장에 그려요."}]},{"kind":"code","head":"단사 해시: HASH 표 채우기 (1/3)","file":"Sample_Code_3_번역.ipynb 셀 19 (1/3)","code":"def aggregate(G, colors):\n    \"\"\"Step 2: aggregated color of every node = (own color, sorted tuple of neighbor colors).\"\"\"\n    return {v: (colors[v], tuple(sorted(colors[u] for u in G[v]))) for v in G}\n\n\ndef wl_refine(graphs, num_iterations=3):\n    \"\"\"\n    Color refinement run jointly on a list of graphs with one shared HASH table.\n\n    Returns `rounds`, where rounds[l] is a dict:\n        'colors' : [{node: color} per graph]             colors after round l\n        'agg'    : [{node: aggregated color} per graph]  what was hashed in round l\n        'table'  : {aggregated color: new color}         the HASH table of round l\n    rounds[0] is the initial coloring: every node gets color 1.\n    \"\"\"\n    rounds = [{'colors': [{v: 1 for v in G} for G in graphs], 'agg': None, 'table': {}}]\n    next_color = 2\n    for _ in range(num_iterations):\n        agg = [aggregate(G, c) for G, c in zip(graphs, rounds[-1]['colors'])]\n        # Step 3: 단사 해시. 처음 보는 집계된 색마다 아직 안 쓴 다음 번호를 준다.\n        # (매 라운드의 입력은 새 색들이므로 라운드마다 자기 표 하나만 있으면 된다.)\n        table = {}\n        for a in agg:\n            for sig in a.values():\n                if sig not in table:\n                    table[sig] = next_color\n                    next_color += 1\n        colors = [{v: table[sig] for v, sig in a.items()} for a in agg]\n        rounds.append({'colors': colors, 'agg': agg, 'table': table})\n    return rounds\n","lines":[{"from":1,"to":4,"say":"aggregate 함수: 노드마다 (내 색, 이웃 색을 정렬해 묶은 튜플)을 만들어 사전으로 돌려줘요."},{"from":5,"to":15,"say":"wl_refine 함수의 이름과 설명이에요. 여러 그래프가 HASH 표를 같이 쓰며 색 정제를 하고 rounds 목록을 돌려준대요."},{"from":16,"to":17,"say":"0라운드: 모든 노드를 색 1 로 칠해 rounds 에 넣어요. 새 번호는 2 부터 줘요."},{"from":18,"to":19,"say":"라운드 수만큼 반복하며, 지난 라운드 색으로 모든 노드의 집계 색을 만들어요."},{"from":20,"to":21,"say":"주석 두 줄 뒤, 빈 사전 table 에 처음 보는 집계 색마다 다음 번호를 적어요. 같은 조합은 같은 번호예요."},{"from":22,"to":22,"say":"빈 사전 table 이 **해시(HASH)** 표예요. 키는 집계된 색, 값은 새 색 번호예요."},{"from":23,"to":24,"say":"for 는 반복이에요. 그래프마다(agg), 노드마다 집계된 색 sig 를 하나씩 꺼내요."},{"from":25,"to":27,"say":"표에 없는 새 조합이면 다음 번호를 주고 번호를 1 올려요. 그래서 다른 조합은 다른 번호, **단사(Injective)** 예요."},{"from":28,"to":28,"say":"모든 노드를 표에서 찾은 새 번호로 다시 칠해요."},{"from":29,"to":31,"say":"표에서 새 번호를 찾아 노드를 다시 칠하고, 이번 라운드 결과를 rounds 끝에 붙여요. 다 돌면 rounds 를 돌려줘요."}],"link":"슬라이드 'HASH table: Injective!' 상자 = 파이썬 사전 table"},{"kind":"code","head":"단사 해시: HASH 표 채우기 (2/3)","file":"Sample_Code_3_번역.ipynb 셀 19 (2/3)","code":"\ndef color_histogram(colors):\n    \"\"\"How many nodes carry each color: the graph-level fingerprint.\"\"\"\n    return dict(sorted(Counter(colors.values()).items()))\n\n\ndef wl_report(rounds, names):\n    \"\"\"The WL test: compare the two graphs' color histograms round by round.\"\"\"\n    differ = False\n    for l, r in enumerate(rounds):\n        h1, h2 = (color_histogram(c) for c in r['colors'])\n        differ = differ or h1 != h2\n        print(f\"round {l}:  {names[0]} {str(h1):<34s} {'==' if h1 == h2 else '!='}  {names[1]} {h2}\")\n    print('\\n→ NON-ISOMORPHIC (the histograms differ)' if differ else\n          '\\n→ INCONCLUSIVE (the histograms are always equal)')\n\n\n# ---- 그리기 -------------------------------------------------------------------------\ndef fmt_agg(sig):\n    \"\"\"(3, (3, 4)) -> '3,{3,4}'\"\"\"\n    own, nbrs = sig\n    return f\"{own},{{{','.join(map(str, nbrs))}}}\"\n\n\ndef draw_aggregated(G, pos, ax, colors, agg, title=None):\n    \"\"\"Each node is a box showing its aggregated color, filled with its current color.\"\"\"\n    nx.draw_networkx_edges(G, pos, ax=ax, edge_color=C_EDGE, width=2.0)\n    for v in G:\n        f = color_of(colors[v])\n        ax.text(*pos[v], fmt_agg(agg[v]), ha='center', va='center', fontsize=10, color=ink(f),\n                bbox=dict(boxstyle='round,pad=0.35', fc=f, ec=C_DARK, lw=1.2))\n    xs, ys = zip(*pos.values())\n    ax.set_xlim(min(xs) - 0.5, max(xs) + 0.5)\n    ax.set_ylim(min(ys) - 0.4, max(ys) + 0.4)\n    if title:\n        ax.set_title(title)\n    ax.set_axis_off()\n","lines":[{"from":1,"to":5,"say":"color_histogram 함수: Counter 로 색마다 노드가 몇 개인지 세서 번호 순으로 정리해요."},{"from":6,"to":16,"say":"wl_report 함수: 라운드마다 두 그래프의 색 개수표를 비교해 == 또는 != 를 출력하고, 마지막에 판정을 알려 줘요."},{"from":17,"to":23,"say":"그리기 부분 시작이에요. fmt_agg 는 (3, (3, 4)) 같은 집계 색을 '3,{3,4}' 글자로 바꿔요."},{"from":24,"to":38,"say":"draw_aggregated 함수: 노드마다 집계 색 글자를 지금 색으로 칠한 상자에 적어 그려요."}]},{"kind":"code","head":"단사 해시: HASH 표 채우기 (3/3)","file":"Sample_Code_3_번역.ipynb 셀 19 (3/3)","code":"\ndef draw_hash_table(ax, table, title):\n    tab = ax.table(cellText=[[fmt_agg(sig), c] for sig, c in table.items()],\n                   colLabels=['aggregated color', 'new color'], loc='center', cellLoc='center')\n    tab.auto_set_font_size(False); tab.set_fontsize(11); tab.scale(1, 1.7)\n    for j in range(2):                                   # 머리글 행\n        tab[0, j].set_facecolor(C_DARK)\n        tab[0, j].get_text().set(color='white', fontweight='bold')\n    for i, c in enumerate(table.values(), start=1):      # 새 색마다 칸을 그 색으로 칠한다\n        tab[i, 1].set_facecolor(color_of(c))\n        tab[i, 1].get_text().set(color=ink(color_of(c)), fontweight='bold')\n    ax.set_title(title)\n    ax.set_axis_off()\n\n\ndef show_initial(graphs, names, positions, rounds):\n    fig, axes = plt.subplots(1, len(graphs), figsize=(11, 3))\n    for ax, G, name, pos, c in zip(axes, graphs, names, positions, rounds[0]['colors']):\n        draw_graph(G, pos, ax, colors=c, labels='color', title=name)\n    fig.suptitle('Step 1 - Assign initial colors: every node gets color 1',\n                 fontsize=13, fontweight='bold')\n    plt.tight_layout(); plt.show()\n\n\ndef show_round(graphs, names, positions, rounds, l):\n    \"\"\"One round, left to right: aggregated colors -> HASH table -> new colors.\"\"\"\n    r, prev = rounds[l], rounds[l - 1]['colors']\n    fig = plt.figure(figsize=(15, 5.6))\n    gs = fig.add_gridspec(2, 3, width_ratios=[1, 0.75, 1])\n    for i, (G, name, pos) in enumerate(zip(graphs, names, positions)):\n        draw_aggregated(G, pos, fig.add_subplot(gs[i, 0]), prev[i], r['agg'][i],\n                        title=f'{name}: aggregated colors')\n        draw_graph(G, pos, fig.add_subplot(gs[i, 2]), colors=r['colors'][i], labels='color',\n                   title=f'{name}: new colors')\n    draw_hash_table(fig.add_subplot(gs[:, 1]), r['table'], title=f'HASH table (round {l})')\n    fig.suptitle(f'Round {l}:   Step 2 - aggregate neighboring colors   →   '\n                 f'Step 3 - injectively hash   →   new colors', fontsize=13, fontweight='bold')\n    plt.tight_layout(); plt.show()","lines":[{"from":1,"to":14,"say":"draw_hash_table 함수: HASH 표를 '집계 색, 새 색' 두 열짜리 표 그림으로 그리고 새 색 칸을 그 색으로 칠해요."},{"from":15,"to":23,"say":"show_initial 함수: 모든 노드가 색 1 인 시작 그림을 그래프마다 그려요."},{"from":24,"to":38,"say":"show_round 함수: 한 라운드를 왼쪽 집계 색, 가운데 HASH 표, 오른쪽 새 색 순서로 한 장에 그려요."}]}]},{"p":50,"title":"색 정제 (3): 한 라운드 더 돌려 갈라지기","terms":["Color refinement","Color histogram","Stable coloring","Isomorphic","1-WL"],"pass1":[{"kind":"say","lines":["같은 규칙을 한 라운드 더 돌렸더니 두 그래프의 색이 달라졌어요.","그래프마다 색별로 노드가 몇 개인지 센 표를 **색 히스토그램(Color histogram)** 이라고 해요.","이 표가 한 번이라도 다르면, 두 그래프는 확실히 다른 모양이에요.","반대로 끝까지 같으면 '같다' 가 아니라 '구별하지 못했다' 는 뜻이에요."]},{"kind":"look","head":"둘째 라운드 결과","boxes":[{"x":0.07,"y":0.24,"w":0.36,"h":0.07,"say":"색이 더 이상 쪼개지지 않을 때까지 반복한다는 줄이에요."},{"x":0.18,"y":0.52,"w":0.23,"h":0.25,"say":"왼쪽 그래프의 둘째 라운드 색이에요."},{"x":0.59,"y":0.52,"w":0.23,"h":0.25,"say":"오른쪽 그래프의 둘째 라운드 색이에요. 왼쪽과 나온 번호들이 달라요."}]},{"kind":"analogy","head":"체육복 색별로 인원 세기","scene":"두 반이 똑같이 생긴 반인지 알아보려고 체육복 색별로 학생 수를 세요. 1반은 빨강 3명, 파랑 3명이고 2반은 빨강 2명, 파랑 4명이면 두 반은 확실히 달라요. 그런데 색별 인원이 똑같다고 해서 두 반이 같다고 장담할 수는 없어요. 체육복 말고 다른 점이 다를 수도 있으니까요.","map":[["색별 학생 수 표","**색 히스토그램(Color histogram)**"],["인원이 다름","확실히 다른 그래프"],["인원이 같음","구별하지 못함 (같다는 보장은 아님)"]]}],"pass2":[{"kind":"look","head":"슬라이드를 차례로 짚어 볼게요","boxes":[{"x":0.07,"y":0.24,"w":0.36,"h":0.07,"say":"더 쪼개지지 않을 때까지 반복해요. 그 상태가 **안정된 색칠(Stable coloring)** 이에요."},{"x":0.07,"y":0.33,"w":0.56,"h":0.07,"say":"색 구성이 같으면 **동형(Isomorphic)** 으로 '간주' 한대요. 이 문장은 조금 부정확해서 뒤에서 고쳐요."},{"x":0.18,"y":0.52,"w":0.23,"h":0.25,"say":"왼쪽 그래프 2라운드 색: 위 11, 8, 가운데 12, 11, 아래 7, 7."},{"x":0.59,"y":0.52,"w":0.23,"h":0.25,"say":"오른쪽: 위 9, 11, 가운데 13, 10, 아래 7, 6. 6부터 13 은 2라운드 새 번호예요."}]},{"kind":"points","head":"**동형(Isomorphic)** 과 **안정된 색칠(Stable coloring)**","items":["동형: 노드 이름만 바꿔 붙이면 두 그래프가 완전히 같아지는 관계예요.","안정된 색칠: 번호 이름은 바뀌어도 같은 색 무리 나누기가 그대로인 상태예요.","안정되면 라운드를 더 돌려도 새로 알게 되는 게 없어서 멈춰요."]},{"kind":"steps","head":"2라운드를 직접 계산해요","steps":["왼쪽 집계: A 4,{3,4,5}, B 3,{4,4}, C 5,{2,2,4,4}, D 4,{3,4,5}, E 2,{5}, F 2,{5}","오른쪽 집계: A 3,{4,5}, B 4,{3,4,5}, C 5,{2,3,4,4}, D 4,{2,4,5}, E 2,{5}, F 2,{4}","공용 표 앞쪽: 2,{4} 6, 2,{5} 7, 3,{4,4} 8, 3,{4,5} 9","공용 표 뒤쪽: 4,{2,4,5} 10, 4,{3,4,5} 11, 5,{2,2,4,4} 12, 5,{2,3,4,4} 13","왼쪽 {7:2, 8:1, 11:2, 12:1}, 오른쪽 {6:1, 7:1, 9:1, 10:1, 11:1, 13:1}"],"answer":"**색 히스토그램(Color histogram)** 이 달라요. 그래서 두 그래프는 동형이 아니에요.","given":"1라운드 색: 왼쪽 A4 B3 C5 D4 E2 F2, 오른쪽 A3 B4 C5 D4 E2 F2"},{"kind":"figure","head":"차이는 끝 노드가 붙은 자리","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\"><line x1=\"60\" y1=\"60\" x2=\"150\" y2=\"60\" class=\"e\"/><line x1=\"60\" y1=\"60\" x2=\"40\" y2=\"135\" class=\"e\"/><line x1=\"60\" y1=\"60\" x2=\"175\" y2=\"135\" class=\"e\"/><line x1=\"150\" y1=\"60\" x2=\"175\" y2=\"135\" class=\"e\"/><line x1=\"40\" y1=\"135\" x2=\"175\" y2=\"135\" class=\"e\"/><line x1=\"40\" y1=\"135\" x2=\"55\" y2=\"205\" class=\"e\"/><line x1=\"40\" y1=\"135\" x2=\"140\" y2=\"205\" class=\"e\"/><line x1=\"330\" y1=\"60\" x2=\"420\" y2=\"60\" class=\"e\"/><line x1=\"330\" y1=\"60\" x2=\"310\" y2=\"135\" class=\"e\"/><line x1=\"420\" y1=\"60\" x2=\"310\" y2=\"135\" class=\"e\"/><line x1=\"420\" y1=\"60\" x2=\"445\" y2=\"135\" class=\"e\"/><line x1=\"310\" y1=\"135\" x2=\"445\" y2=\"135\" class=\"e\"/><line x1=\"310\" y1=\"135\" x2=\"325\" y2=\"205\" class=\"e\"/><line x1=\"445\" y1=\"135\" x2=\"410\" y2=\"205\" class=\"e\"/><circle cx=\"60\" cy=\"60\" r=\"17\" class=\"n\"/><text x=\"60\" y=\"65\" font-size=\"14\" text-anchor=\"middle\" class=\"tl\">11<\/text><circle cx=\"150\" cy=\"60\" r=\"17\" class=\"n\"/><text x=\"150\" y=\"65\" font-size=\"14\" text-anchor=\"middle\" class=\"tl\">8<\/text><circle cx=\"40\" cy=\"135\" r=\"17\" class=\"n\"/><text x=\"40\" y=\"140\" font-size=\"14\" text-anchor=\"middle\" class=\"tl\">12<\/text><circle cx=\"175\" cy=\"135\" r=\"17\" class=\"n\"/><text x=\"175\" y=\"140\" font-size=\"14\" text-anchor=\"middle\" class=\"tl\">11<\/text><circle cx=\"55\" cy=\"205\" r=\"17\" class=\"n2\"/><text x=\"55\" y=\"210\" font-size=\"14\" text-anchor=\"middle\" class=\"tl\">7<\/text><circle cx=\"140\" cy=\"205\" r=\"17\" class=\"n2\"/><text x=\"140\" y=\"210\" font-size=\"14\" text-anchor=\"middle\" class=\"tl\">7<\/text><circle cx=\"330\" cy=\"60\" r=\"17\" class=\"n\"/><text x=\"330\" y=\"65\" font-size=\"14\" text-anchor=\"middle\" class=\"tl\">9<\/text><circle cx=\"420\" cy=\"60\" r=\"17\" class=\"n\"/><text x=\"420\" y=\"65\" font-size=\"14\" text-anchor=\"middle\" class=\"tl\">11<\/text><circle cx=\"310\" cy=\"135\" r=\"17\" class=\"n\"/><text x=\"310\" y=\"140\" font-size=\"14\" text-anchor=\"middle\" class=\"tl\">13<\/text><circle cx=\"445\" cy=\"135\" r=\"17\" class=\"n\"/><text x=\"445\" y=\"140\" font-size=\"14\" text-anchor=\"middle\" class=\"tl\">10<\/text><circle cx=\"325\" cy=\"205\" r=\"17\" class=\"n2\"/><text x=\"325\" y=\"210\" font-size=\"14\" text-anchor=\"middle\" class=\"tl\">7<\/text><circle cx=\"410\" cy=\"205\" r=\"17\" class=\"n3\"/><text x=\"410\" y=\"210\" font-size=\"14\" text-anchor=\"middle\" class=\"tl\">6<\/text><text x=\"240\" y=\"145\" font-size=\"20\" text-anchor=\"middle\" class=\"tb b1\">≠<\/text><text x=\"105\" y=\"250\" font-size=\"15\" text-anchor=\"middle\" class=\"t b2\">끝 노드 둘 다 C 에 붙음<\/text><text x=\"375\" y=\"250\" font-size=\"15\" text-anchor=\"middle\" class=\"t b2\">끝 노드가 C, D 에 하나씩<\/text><\/svg>","caption":"1라운드는 친구 수만 봐서 못 봤고, 2라운드는 친구의 친구 수까지 봐서 잡아냈어요.","builds":2},{"kind":"compare","head":"1라운드 대 2라운드","cols":["","1라운드","2라운드"],"rows":[["색에 담기는 것","친구 수","친구들의 친구 수"],["보는 범위","1홉","2홉"],["두 그래프 히스토그램","같음","다름"]]},{"kind":"prof","when":"3주차 화요일 수업","lines":["이 과정을 더 이상 구별 결과가 바뀌지 않을 때까지 반복한다고 했어요."]},{"kind":"mining","src":"마이닝 9강 Graph Kernels","lines":["동형 판단 전에 노드 수, 엣지 수, 차수 같은 불변량을 먼저 확인했어요.","이 두 그래프는 노드 6, 엣지 7, 차수 (4,3,3,2,1,1) 이 모두 같아요.","그래서 불변량으로는 못 가르고 **색 정제(Color refinement)** 2라운드에서 갈라졌어요."]}],"pass3":[{"kind":"warn","head":"슬라이드 둘째 불릿 고치기","items":["집합(set)이 아니라 색마다 개수까지 센 멀티셋, 곧 히스토그램이 같아야 해요.","히스토그램이 같다고 **동형(Isomorphic)** 이 확정되지 않아요. '구별 못 했다' 일 뿐이에요.","확실한 방향은 하나예요. 히스토그램이 다르면 동형이 아니에요."]},{"kind":"english","head":"판정 문장 (다를 때)","en":"At round 2, the color histograms of the two graphs differ, so the graphs are non-isomorphic.","ko":"2라운드에서 두 그래프의 색 히스토그램이 달라서 두 그래프는 동형이 아니다."},{"kind":"english","head":"판정 문장 (끝까지 같을 때)","en":"1-WL cannot distinguish them (they may or may not be isomorphic).","ko":"1-WL 은 구별하지 못한다. 동형일 수도 아닐 수도 있다.","tip":"may or may not 을 꼭 붙여야 안전해요."},{"kind":"check","q":"모든 라운드에서 두 그래프의 색 히스토그램이 같았어요. 옳은 결론은?","choices":["두 그래프는 동형이다","두 그래프는 동형이 아니다","**1-WL 테스트(1-WL)** 로는 판정할 수 없다"],"a":2,"why":"같은 히스토그램은 '구별 못 함' 이에요. 육각형 하나와 삼각형 두 개처럼 다른데도 같은 경우가 있어요(p.60)."}],"pass4":[{"kind":"pyterm","name":"Counter (개수 세기)","say":["리스트 안에 같은 값이 몇 번 나오는지 세어 주는 도구예요.","색 히스토그램을 만드는 데 딱 맞아요."],"example":"from collections import Counter\nprint(Counter([7, 7, 8]))","out":"Counter({7: 2, 8: 1})"},{"kind":"code","head":"히스토그램 만들고 라운드마다 비교하기 (1/3)","file":"Sample_Code_3_번역.ipynb 셀 19 (1/3)","code":"def aggregate(G, colors):\n    \"\"\"Step 2: aggregated color of every node = (own color, sorted tuple of neighbor colors).\"\"\"\n    return {v: (colors[v], tuple(sorted(colors[u] for u in G[v]))) for v in G}\n\n\ndef wl_refine(graphs, num_iterations=3):\n    \"\"\"\n    Color refinement run jointly on a list of graphs with one shared HASH table.\n\n    Returns `rounds`, where rounds[l] is a dict:\n        'colors' : [{node: color} per graph]             colors after round l\n        'agg'    : [{node: aggregated color} per graph]  what was hashed in round l\n        'table'  : {aggregated color: new color}         the HASH table of round l\n    rounds[0] is the initial coloring: every node gets color 1.\n    \"\"\"\n    rounds = [{'colors': [{v: 1 for v in G} for G in graphs], 'agg': None, 'table': {}}]\n    next_color = 2\n    for _ in range(num_iterations):\n        agg = [aggregate(G, c) for G, c in zip(graphs, rounds[-1]['colors'])]\n        # Step 3: 단사 해시. 처음 보는 집계된 색마다 아직 안 쓴 다음 번호를 준다.\n        # (매 라운드의 입력은 새 색들이므로 라운드마다 자기 표 하나만 있으면 된다.)\n        table = {}\n        for a in agg:\n            for sig in a.values():\n                if sig not in table:\n                    table[sig] = next_color\n                    next_color += 1\n        colors = [{v: table[sig] for v, sig in a.items()} for a in agg]\n        rounds.append({'colors': colors, 'agg': agg, 'table': table})\n    return rounds\n","lines":[{"from":1,"to":4,"say":"aggregate 함수: 노드마다 (내 색, 이웃 색을 정렬해 묶은 튜플)을 만들어 사전으로 돌려줘요."},{"from":5,"to":15,"say":"wl_refine 함수의 이름과 설명이에요. 여러 그래프가 HASH 표를 같이 쓰며 색 정제를 하고 rounds 목록을 돌려준대요."},{"from":16,"to":17,"say":"0라운드: 모든 노드를 색 1 로 칠해 rounds 에 넣어요. 새 번호는 2 부터 줘요."},{"from":18,"to":19,"say":"라운드 수만큼 반복하며, 지난 라운드 색으로 모든 노드의 집계 색을 만들어요."},{"from":20,"to":27,"say":"주석 두 줄 뒤, 빈 사전 table 에 처음 보는 집계 색마다 다음 번호를 적어요. 같은 조합은 같은 번호예요."},{"from":28,"to":31,"say":"표에서 새 번호를 찾아 노드를 다시 칠하고, 이번 라운드 결과를 rounds 끝에 붙여요. 다 돌면 rounds 를 돌려줘요."}]},{"kind":"code","head":"히스토그램 만들고 라운드마다 비교하기 (2/3)","file":"Sample_Code_3_번역.ipynb 셀 19 (2/3)","code":"\ndef color_histogram(colors):\n    \"\"\"How many nodes carry each color: the graph-level fingerprint.\"\"\"\n    return dict(sorted(Counter(colors.values()).items()))\n\n\ndef wl_report(rounds, names):\n    \"\"\"The WL test: compare the two graphs' color histograms round by round.\"\"\"\n    differ = False\n    for l, r in enumerate(rounds):\n        h1, h2 = (color_histogram(c) for c in r['colors'])\n        differ = differ or h1 != h2\n        print(f\"round {l}:  {names[0]} {str(h1):<34s} {'==' if h1 == h2 else '!='}  {names[1]} {h2}\")\n    print('\\n→ NON-ISOMORPHIC (the histograms differ)' if differ else\n          '\\n→ INCONCLUSIVE (the histograms are always equal)')\n\n\n# ---- 그리기 -------------------------------------------------------------------------\ndef fmt_agg(sig):\n    \"\"\"(3, (3, 4)) -> '3,{3,4}'\"\"\"\n    own, nbrs = sig\n    return f\"{own},{{{','.join(map(str, nbrs))}}}\"\n\n\ndef draw_aggregated(G, pos, ax, colors, agg, title=None):\n    \"\"\"Each node is a box showing its aggregated color, filled with its current color.\"\"\"\n    nx.draw_networkx_edges(G, pos, ax=ax, edge_color=C_EDGE, width=2.0)\n    for v in G:\n        f = color_of(colors[v])\n        ax.text(*pos[v], fmt_agg(agg[v]), ha='center', va='center', fontsize=10, color=ink(f),\n                bbox=dict(boxstyle='round,pad=0.35', fc=f, ec=C_DARK, lw=1.2))\n    xs, ys = zip(*pos.values())\n    ax.set_xlim(min(xs) - 0.5, max(xs) + 0.5)\n    ax.set_ylim(min(ys) - 0.4, max(ys) + 0.4)\n    if title:\n        ax.set_title(title)\n    ax.set_axis_off()\n","lines":[{"from":2,"to":4,"say":"색만 꺼내(colors.values()) Counter 로 세고 색 번호 순서로 정렬해 사전으로 만들어요. 이게 **색 히스토그램(Color histogram)** 이에요."},{"from":7,"to":9,"say":"differ 는 '한 번이라도 달랐나' 를 기억하는 참/거짓 변수예요. 처음엔 False."},{"from":10,"to":11,"say":"enumerate 는 라운드 번호 l 과 그 라운드 기록 r 을 함께 줘요. 두 그래프의 히스토그램 h1, h2 를 만들어요."},{"from":12,"to":13,"say":"!= 는 '다르다' 비교예요. or 라서 한 번 True 가 되면 끝까지 True. 라운드마다 == 또는 != 를 출력해요."},{"from":14,"to":15,"say":"한 번이라도 달랐으면 NON-ISOMORPHIC, 끝까지 같으면 INCONCLUSIVE(판정 불가) 를 출력해요."},{"from":17,"to":23,"say":"그리기 부분 시작이에요. fmt_agg 는 (3, (3, 4)) 같은 집계 색을 '3,{3,4}' 글자로 바꿔요."},{"from":24,"to":38,"say":"draw_aggregated 함수: 노드마다 집계 색 글자를 지금 색으로 칠한 상자에 적어 그려요."}],"link":"슬라이드 판정 규칙 '다르면 동형 아님, 같으면 모름' 이 마지막 두 줄이에요."},{"kind":"code","head":"히스토그램 만들고 라운드마다 비교하기 (3/3)","file":"Sample_Code_3_번역.ipynb 셀 19 (3/3)","code":"\ndef draw_hash_table(ax, table, title):\n    tab = ax.table(cellText=[[fmt_agg(sig), c] for sig, c in table.items()],\n                   colLabels=['aggregated color', 'new color'], loc='center', cellLoc='center')\n    tab.auto_set_font_size(False); tab.set_fontsize(11); tab.scale(1, 1.7)\n    for j in range(2):                                   # 머리글 행\n        tab[0, j].set_facecolor(C_DARK)\n        tab[0, j].get_text().set(color='white', fontweight='bold')\n    for i, c in enumerate(table.values(), start=1):      # 새 색마다 칸을 그 색으로 칠한다\n        tab[i, 1].set_facecolor(color_of(c))\n        tab[i, 1].get_text().set(color=ink(color_of(c)), fontweight='bold')\n    ax.set_title(title)\n    ax.set_axis_off()\n\n\ndef show_initial(graphs, names, positions, rounds):\n    fig, axes = plt.subplots(1, len(graphs), figsize=(11, 3))\n    for ax, G, name, pos, c in zip(axes, graphs, names, positions, rounds[0]['colors']):\n        draw_graph(G, pos, ax, colors=c, labels='color', title=name)\n    fig.suptitle('Step 1 - Assign initial colors: every node gets color 1',\n                 fontsize=13, fontweight='bold')\n    plt.tight_layout(); plt.show()\n\n\ndef show_round(graphs, names, positions, rounds, l):\n    \"\"\"One round, left to right: aggregated colors -> HASH table -> new colors.\"\"\"\n    r, prev = rounds[l], rounds[l - 1]['colors']\n    fig = plt.figure(figsize=(15, 5.6))\n    gs = fig.add_gridspec(2, 3, width_ratios=[1, 0.75, 1])\n    for i, (G, name, pos) in enumerate(zip(graphs, names, positions)):\n        draw_aggregated(G, pos, fig.add_subplot(gs[i, 0]), prev[i], r['agg'][i],\n                        title=f'{name}: aggregated colors')\n        draw_graph(G, pos, fig.add_subplot(gs[i, 2]), colors=r['colors'][i], labels='color',\n                   title=f'{name}: new colors')\n    draw_hash_table(fig.add_subplot(gs[:, 1]), r['table'], title=f'HASH table (round {l})')\n    fig.suptitle(f'Round {l}:   Step 2 - aggregate neighboring colors   →   '\n                 f'Step 3 - injectively hash   →   new colors', fontsize=13, fontweight='bold')\n    plt.tight_layout(); plt.show()","lines":[{"from":1,"to":14,"say":"draw_hash_table 함수: HASH 표를 '집계 색, 새 색' 두 열짜리 표 그림으로 그리고 새 색 칸을 그 색으로 칠해요."},{"from":15,"to":23,"say":"show_initial 함수: 모든 노드가 색 1 인 시작 그림을 그래프마다 그려요."},{"from":24,"to":38,"say":"show_round 함수: 한 라운드를 왼쪽 집계 색, 가운데 HASH 표, 오른쪽 새 색 순서로 한 장에 그려요."}]}]},{"p":51,"title":"또 다른 예: 친구 수까지 같은 두 그래프","terms":["Color refinement","Degree sequence","Multi-set","HASH","Color histogram"],"pass1":[{"kind":"say","lines":["이번 두 그래프는 노드 수도, 선 수도, 노드마다 친구 수 구성까지 똑같아요.","왼쪽은 삼각형에 꼬리가 3칸 달렸고, 오른쪽은 사각형에 꼬리가 2칸 달렸어요.","친구 수만 보는 첫 라운드로는 두 그래프를 절대 가를 수 없어요."]},{"kind":"look","head":"두 그래프와 첫 라운드 색","boxes":[{"x":0.19,"y":0.12,"w":0.61,"h":0.31,"say":"위쪽이 두 그래프예요. 왼쪽은 삼각형과 긴 꼬리, 오른쪽은 사각형과 짧은 꼬리예요."},{"x":0.61,"y":0.5,"w":0.19,"h":0.39,"say":"첫 라운드 새 색으로 칠한 결과예요. 두 그래프 모두 같은 색이 같은 개수만큼 나왔어요."}]},{"kind":"analogy","head":"친구 수 명단이 똑같은 두 모둠","scene":"두 모둠이 있어요. 두 모둠 모두 친구가 3명인 학생 1명, 2명인 학생 4명, 1명인 학생 1명으로 구성이 똑같아요. 그런데 한 모둠은 세 명이 삼각형으로 뭉쳐 있고, 다른 모둠은 네 명이 사각형으로 둘러앉아 있어요. 친구 수만 적은 명단으로는 이 차이를 알 수 없어요.","map":[["친구 수만 적은 명단","첫 라운드 색"],["삼각형으로 뭉친 모양, 사각형으로 둘러앉은 모양","두 그래프의 구조 차이"]]}],"pass2":[{"kind":"look","head":"슬라이드를 차례로 짚어 볼게요","boxes":[{"x":0.19,"y":0.12,"w":0.61,"h":0.31,"say":"Step 1: 모든 노드가 색 1 에서 출발해요. 왼쪽 G1, 오른쪽 G2 예요."},{"x":0.18,"y":0.5,"w":0.23,"h":0.39,"say":"집계 결과예요. '1,{1,1}' 은 내 색 1, 친구 색 1 과 1 이에요."},{"x":0.41,"y":0.65,"w":0.18,"h":0.12,"say":"**해시(HASH)** 표 1라운드: 1,{1,1} 은 2, 1,{1,1,1} 은 3, 1,{1} 은 4."},{"x":0.61,"y":0.5,"w":0.19,"h":0.39,"say":"새 색으로 칠한 결과예요. 두 그래프 모두 주황 4, 초록 1, 분홍 1 이에요."}]},{"kind":"points","head":"중괄호 표기 읽기","items":["중괄호는 친구 색 봉투, 곧 **멀티셋(Multi-set)** 이에요. 순서는 없고 개수는 세요.","'1,{1,1}' 은 p.48 의 '1,11' 과 같은 뜻이에요.","이 표는 처음 나온 순서로 번호를 줘서 친구 1명이 4번이에요. 번호 크기는 뜻이 없어요."]},{"kind":"compare","head":"두 그래프 기본 정보","cols":["","G1","G2"],"rows":[["노드 수","6","6"],["엣지 수","6","6"],["**차수 수열(Degree sequence)**","(3,2,2,2,2,1)","(3,2,2,2,2,1)"],["모양","삼각형 + 꼬리 3","사각형 + 꼬리 2"]]},{"kind":"steps","head":"1라운드를 직접 계산해요","steps":["G1 a, b: 친구 2명이라 1,{1,1} 은 2","G1 c: 친구 a, b, d 셋이라 1,{1,1,1} 은 3","G1 d, e: 친구 2명이라 2, 끝 f: 친구 1명이라 1,{1} 은 4","G2 p, q, r, t: 친구 2명이라 2, s: 친구 3명이라 3, 끝 w: 4"],"answer":"둘 다 {2:4, 3:1, 4:1}. **색 히스토그램(Color histogram)** 이 같아요.","given":"G1 엣지 a-b, a-c, b-c, c-d, d-e, e-f. G2 엣지 p-q, q-r, p-s, r-s, s-t, t-w"},{"kind":"figure","head":"1라운드 색까지는 쌍둥이","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\"><text x=\"120\" y=\"30\" font-size=\"15\" text-anchor=\"middle\" class=\"tb\">G1 (삼각형 + 꼬리 3)<\/text><text x=\"345\" y=\"30\" font-size=\"15\" text-anchor=\"middle\" class=\"tb\">G2 (사각형 + 꼬리 2)<\/text><line x1=\"30\" y1=\"70\" x2=\"30\" y2=\"160\" class=\"e\"/><line x1=\"30\" y1=\"70\" x2=\"80\" y2=\"115\" class=\"e\"/><line x1=\"30\" y1=\"160\" x2=\"80\" y2=\"115\" class=\"e\"/><line x1=\"80\" y1=\"115\" x2=\"125\" y2=\"115\" class=\"e\"/><line x1=\"125\" y1=\"115\" x2=\"170\" y2=\"115\" class=\"e\"/><line x1=\"170\" y1=\"115\" x2=\"215\" y2=\"115\" class=\"e\"/><line x1=\"295\" y1=\"70\" x2=\"255\" y2=\"115\" class=\"e\"/><line x1=\"255\" y1=\"115\" x2=\"295\" y2=\"160\" class=\"e\"/><line x1=\"295\" y1=\"70\" x2=\"335\" y2=\"115\" class=\"e\"/><line x1=\"295\" y1=\"160\" x2=\"335\" y2=\"115\" class=\"e\"/><line x1=\"335\" y1=\"115\" x2=\"385\" y2=\"115\" class=\"e\"/><line x1=\"385\" y1=\"115\" x2=\"435\" y2=\"115\" class=\"e\"/><circle cx=\"30\" cy=\"70\" r=\"16\" class=\"n\"/><text x=\"30\" y=\"75\" font-size=\"14\" text-anchor=\"middle\" class=\"tl\">2<\/text><circle cx=\"30\" cy=\"160\" r=\"16\" class=\"n\"/><text x=\"30\" y=\"165\" font-size=\"14\" text-anchor=\"middle\" class=\"tl\">2<\/text><circle cx=\"80\" cy=\"115\" r=\"16\" class=\"n2\"/><text x=\"80\" y=\"120\" font-size=\"14\" text-anchor=\"middle\" class=\"tl\">3<\/text><circle cx=\"125\" cy=\"115\" r=\"16\" class=\"n\"/><text x=\"125\" y=\"120\" font-size=\"14\" text-anchor=\"middle\" class=\"tl\">2<\/text><circle cx=\"170\" cy=\"115\" r=\"16\" class=\"n\"/><text x=\"170\" y=\"120\" font-size=\"14\" text-anchor=\"middle\" class=\"tl\">2<\/text><circle cx=\"215\" cy=\"115\" r=\"16\" class=\"n3\"/><text x=\"215\" y=\"120\" font-size=\"14\" text-anchor=\"middle\" class=\"tl\">4<\/text><circle cx=\"295\" cy=\"70\" r=\"16\" class=\"n\"/><text x=\"295\" y=\"75\" font-size=\"14\" text-anchor=\"middle\" class=\"tl\">2<\/text><circle cx=\"255\" cy=\"115\" r=\"16\" class=\"n\"/><text x=\"255\" y=\"120\" font-size=\"14\" text-anchor=\"middle\" class=\"tl\">2<\/text><circle cx=\"295\" cy=\"160\" r=\"16\" class=\"n\"/><text x=\"295\" y=\"165\" font-size=\"14\" text-anchor=\"middle\" class=\"tl\">2<\/text><circle cx=\"335\" cy=\"115\" r=\"16\" class=\"n2\"/><text x=\"335\" y=\"120\" font-size=\"14\" text-anchor=\"middle\" class=\"tl\">3<\/text><circle cx=\"385\" cy=\"115\" r=\"16\" class=\"n\"/><text x=\"385\" y=\"120\" font-size=\"14\" text-anchor=\"middle\" class=\"tl\">2<\/text><circle cx=\"435\" cy=\"115\" r=\"16\" class=\"n3\"/><text x=\"435\" y=\"120\" font-size=\"14\" text-anchor=\"middle\" class=\"tl\">4<\/text><text x=\"240\" y=\"215\" font-size=\"15\" text-anchor=\"middle\" class=\"t b1\">차수 수열 둘 다 (3, 2, 2, 2, 2, 1)<\/text><text x=\"240\" y=\"245\" font-size=\"15\" text-anchor=\"middle\" class=\"t b1\">1라운드 히스토그램 둘 다 {2:4, 3:1, 4:1}<\/text><\/svg>","caption":"처음에 모두 색 1 이라 봉투 속은 1 뿐이에요. 다른 점은 1 의 개수, 곧 친구 수뿐이에요.","builds":1},{"kind":"prof","when":"1주차 목요일 수업","lines":["구조를 비교하는 전통적 방법으로 차수 분포를 먼저 소개하셨어요.","차수는 1홉 범위 구조를 정확히 묘사해서 생각보다 정확하다고요.","이 예는 그 방법의 한계예요. 차수 분포가 같아서 2라운드가 필요해요."]},{"kind":"mining","src":"마이닝 9강 Graph Kernels","lines":["동형 예제에서는 '차수 1 노드가 한쪽에만 있다' 로 바로 판정했어요.","이번 쌍은 **차수 수열(Degree sequence)** 이 같아서 그런 지름길이 없어요.","WL 은 차수 검사를 라운드마다 넓혀 가는 업그레이드 버전이에요."]}],"pass3":[{"kind":"exam","src":"그래프 마이닝 2024 봄 중간 11번 (10점)","q":"Conduct the Weisfeiler-Lehman (WL) relabeling process with the maximum degree 3. Make feature vectors based on the frequency of WL subgraphs, then calculate the cosine similarity of G1 and G2.","qko":"두 그래프에 최대 3단계 WL 재라벨링을 하고, 라벨별 개수로 특징 벡터를 만든 뒤 코사인 유사도를 구하라.","solve":["해설 G1 특징 벡터: 라벨 1 부터 9 까지 개수 (7, 3, 4, 2, 1, 4, 2, 1, 4)","해설 G2 특징 벡터도 (7, 3, 4, 2, 1, 4, 2, 1, 4) 로 같아요.","검산: 라벨 1 이 7개 = 노드 7개. 라벨 2, 3 합 7, 4, 5, 6 합 7, 7, 8, 9 합 7.","내적 = 49+9+16+4+1+16+4+1+16 = 116. 두 길이 제곱도 116.","코사인 = 116 / (116) = 1"],"answer":"코사인 유사도 1. 하지만 이것이 **동형(Isomorphic)** 을 보장하지는 않아요."},{"kind":"check","q":"**차수 수열(Degree sequence)** 이 같은 두 그래프에 1라운드만 돌리면?","choices":["반드시 갈라진다","1라운드 히스토그램이 같다","동형이 확정된다"],"a":1,"why":"1라운드 색은 친구 수의 다른 이름이라서, 차수 수열이 같으면 히스토그램도 같아요."},{"kind":"warn","head":"시험 요령","items":["먼저 노드 수, 엣지 수, 차수 목록을 적어요. 여기서 다르면 WL 없이 '동형 아님' 이에요.","전부 같을 때만 2라운드 이후로 넘어가요.","특징 벡터를 쓰면 라운드마다 개수 합이 노드 수인지 검산해요."]}],"pass4":[{"kind":"pyterm","name":"nx.Graph(엣지 리스트)","say":["networkx(nx) 는 그래프를 다루는 라이브러리예요.","(0, 1) 같은 쌍의 리스트를 주면 그 엣지들로 그래프를 만들어요."],"example":"import networkx as nx\nG = nx.Graph([(0, 1), (1, 2)])\nprint(G.number_of_edges())","out":"2"},{"kind":"code","head":"슬라이드의 G1, G2 만들고 색 정제 돌리기","file":"Sample_Code_3_번역.ipynb 셀 22","code":"G1 = nx.Graph([(0, 1), (1, 2), (2, 0), (2, 3), (3, 4), (4, 5)])     # 삼각형 + 꼬리\nG2 = nx.Graph([(0, 1), (1, 2), (2, 3), (3, 0), (3, 4), (4, 5)])     # 사각형 + 꼬리\nPOS_G1 = {0: (0, 0.6), 1: (0, -0.6), 2: (1, 0), 3: (2, 0), 4: (3, 0), 5: (4, 0)}\nPOS_G2 = {0: (0.7, 0.7), 1: (0, 0), 2: (0.7, -0.7), 3: (1.4, 0), 4: (2.4, 0), 5: (3.4, 0)}\n\nPAIR = dict(graphs=[G1, G2], names=['$G_1$', '$G_2$'], positions=[POS_G1, POS_G2])\nrounds = wl_refine(PAIR['graphs'], num_iterations=2)\n\nshow_initial(**PAIR, rounds=rounds)","lines":[{"from":1,"to":1,"say":"G1: 0-1-2 가 삼각형, 2-3-4-5 가 꼬리예요. # 뒤는 설명 주석이에요."},{"from":2,"to":2,"say":"G2: 0-1-2-3 이 사각형, 3-4-5 가 꼬리예요."},{"from":3,"to":4,"say":"그림 그릴 좌표 사전이에요. 색 계산에는 안 쓰여요."},{"from":6,"to":6,"say":"두 그래프 정보를 사전 하나(PAIR)로 묶어 둬요."},{"from":7,"to":7,"say":"p.49 에서 본 wl_refine 으로 2라운드 **색 정제(Color refinement)** 를 미리 계산해요."},{"from":9,"to":9,"say":"모든 노드가 색 1 인 첫 그림을 그려요. PAIR 앞 별 두 개는 사전을 인자들로 펼치는 문법이에요."}],"link":"슬라이드 윗줄 Step 1 그림이 이 셀의 출력이고, 가운데 줄은 셀 25 show_round(..., l=1) 의 출력이에요."}]},{"p":52,"title":"또 다른 예: 2라운드에서 갈라지다","terms":["Color refinement","Color histogram","Multi-set","Isomorphic","WL graph kernel"],"pass1":[{"kind":"say","lines":["둘째 라운드에서는 '친구의 친구' 정보까지 색에 들어가요.","그러자 두 그래프의 색 구성이 달라져서 갈라졌어요.","결론은 두 그래프가 모양이 같은 그래프가 아니다, 즉 **동형(Isomorphic)** 이 아니라는 거예요."]},{"kind":"look","head":"둘째 라운드와 결론","boxes":[{"x":0.61,"y":0.15,"w":0.19,"h":0.39,"say":"둘째 라운드 새 색으로 칠한 결과예요. 두 그래프에 나온 색이 서로 달라요."},{"x":0.05,"y":0.83,"w":0.41,"h":0.06,"say":"맨 아래 결론: 두 그래프는 동형이 아니에요."}]},{"kind":"analogy","head":"친구의 친구까지 물어보기","scene":"앞 쪽의 두 모둠에게 이번엔 '네 친구들은 각자 친구가 몇 명이야?' 라고 한 번 더 물어요. 그러자 사각형 모둠에서만 '나는 친구가 2명인데, 두 친구도 모두 친구가 2명이야' 라는 대답이 나와요. 친구 수 명단은 같았지만, 친구의 친구까지 물어보니 두 모둠이 다르다는 게 드러났어요.","map":[["친구의 친구까지 물어보기","둘째 라운드"],["한쪽 모둠에서만 나온 대답","한쪽 그래프에만 있는 새 색"],["두 모둠이 다름","**동형(Isomorphic)** 이 아님"]]}],"pass2":[{"kind":"look","head":"슬라이드를 차례로 짚어 볼게요","boxes":[{"x":0.18,"y":0.15,"w":0.23,"h":0.39,"say":"왼쪽 집계 상자의 칠은 1라운드 색이에요. 주황 2, 초록 3, 분홍 4."},{"x":0.41,"y":0.27,"w":0.18,"h":0.18,"say":"HASH 표 2라운드: 새 조합 여섯 개에 5 부터 10 번을 줘요."},{"x":0.61,"y":0.15,"w":0.19,"h":0.39,"say":"새 색: G1 은 5, 5, 6, 5, 7, 8. G2 는 5, 9, 5, 6, 10, 8."},{"x":0.2,"y":0.58,"w":0.6,"h":0.19,"say":"라운드별 **색 히스토그램(Color histogram)**. {2: 4} 는 색 2 가 4개라는 뜻이에요."},{"x":0.2,"y":0.72,"w":0.6,"h":0.05,"say":"빨간 2라운드 줄은 숫자가 틀렸어요. 개수를 더하면 6 이 안 나와요."},{"x":0.05,"y":0.83,"w":0.41,"h":0.06,"say":"결과: 동형 아님. 라운드 2 에서 히스토그램이 달라져요."}]},{"kind":"steps","head":"2라운드를 직접 계산해요","steps":["G1 a, b, d: 2,{2,3} 이라 5. c: 3,{2,2,2} 라 6","G1 e: 2,{2,4} 라 7. f: 4,{2} 라 8","G2 p, r: 2,{2,3} 이라 5. q: 2,{2,2} 라 9. s: 3,{2,2,2} 라 6","G2 t: 2,{3,4} 라 10. w: 4,{2} 라 8","G1 {5:3, 6:1, 7:1, 8:1}, 합 6","G2 {5:2, 6:1, 8:1, 9:1, 10:1}, 합 6"],"answer":"2라운드 히스토그램이 달라요. 그래서 동형이 아니에요.","given":"p.51 이름표 그대로. 1라운드 색은 친구 2명 2, 3명 3, 1명 4"},{"kind":"figure","head":"올바른 2라운드 히스토그램","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\"><text x=\"240\" y=\"26\" font-size=\"15\" text-anchor=\"middle\" class=\"tb\">2라운드 색 히스토그램 (막대 높이 = 노드 수)<\/text><line x1=\"40\" y1=\"220\" x2=\"450\" y2=\"220\" class=\"e\"/><rect x=\"50\" y=\"85\" width=\"18\" height=\"135\" rx=\"2\" class=\"box2 b1\"/><rect x=\"72\" y=\"130\" width=\"18\" height=\"90\" rx=\"2\" class=\"box b2\"/><text x=\"70\" y=\"242\" font-size=\"15\" text-anchor=\"middle\" class=\"t\">5<\/text><rect x=\"118\" y=\"175\" width=\"18\" height=\"45\" rx=\"2\" class=\"box2 b1\"/><rect x=\"140\" y=\"175\" width=\"18\" height=\"45\" rx=\"2\" class=\"box b2\"/><text x=\"138\" y=\"242\" font-size=\"15\" text-anchor=\"middle\" class=\"t\">6<\/text><rect x=\"186\" y=\"175\" width=\"18\" height=\"45\" rx=\"2\" class=\"box2 b1\"/><text x=\"206\" y=\"242\" font-size=\"15\" text-anchor=\"middle\" class=\"t\">7<\/text><rect x=\"254\" y=\"175\" width=\"18\" height=\"45\" rx=\"2\" class=\"box2 b1\"/><rect x=\"276\" y=\"175\" width=\"18\" height=\"45\" rx=\"2\" class=\"box b2\"/><text x=\"274\" y=\"242\" font-size=\"15\" text-anchor=\"middle\" class=\"t\">8<\/text><rect x=\"344\" y=\"175\" width=\"18\" height=\"45\" rx=\"2\" class=\"box b2\"/><text x=\"342\" y=\"242\" font-size=\"15\" text-anchor=\"middle\" class=\"t\">9<\/text><rect x=\"412\" y=\"175\" width=\"18\" height=\"45\" rx=\"2\" class=\"box b2\"/><text x=\"410\" y=\"242\" font-size=\"15\" text-anchor=\"middle\" class=\"t\">10<\/text><rect x=\"330\" y=\"40\" width=\"14\" height=\"14\" rx=\"2\" class=\"box2 b1\"/><text x=\"350\" y=\"52\" font-size=\"14\" text-anchor=\"start\" class=\"t b1\">G1 합 6<\/text><rect x=\"400\" y=\"40\" width=\"14\" height=\"14\" rx=\"2\" class=\"box b2\"/><text x=\"420\" y=\"52\" font-size=\"14\" text-anchor=\"start\" class=\"t b2\">G2 합 6<\/text><text x=\"240\" y=\"265\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b2\">색 7 은 G1 에만, 색 9 와 10 은 G2 에만<\/text><\/svg>","caption":"막대가 다른 칸이 여러 개예요. 개수 합은 둘 다 노드 수 6 이에요.","builds":2},{"kind":"points","head":"2라운드 번호를 사람 말로","items":["5: 친구 2명, 그중 한 명이 갈림길(친구 3명)","6: 갈림길 자신. 8: 꼬리 끝 노드","7: 친구 2명, 한 명이 끝 노드 (꼬리가 긴 G1 의 e)","9: 친구 둘 다 친구 2명 (사각형 반대편 G2 의 q). 10: 갈림길과 끝 사이 (G2 의 t)"]},{"kind":"formula","head":"WL 특징 벡터의 코사인 유사도","tex":"\\cos = \\frac{\\phi(G_1)\\cdot\\phi(G_2)}{\\lVert\\phi(G_1)\\rVert\\,\\lVert\\phi(G_2)\\rVert}","parts":[{"sym":"\\phi(G_1)","say":"G1 의 0~2라운드 색 1~10 개수를 한 줄로 이은 특징 벡터"},{"sym":"\\cdot","say":"같은 칸끼리 곱해서 모두 더하기(내적)"},{"sym":"\\lVert\\phi\\rVert","say":"벡터의 길이. 칸마다 제곱해 더한 뒤 루트"},{"sym":"\\cos","say":"1 이면 방향이 똑같고, 작을수록 덜 비슷해요"}],"whole":"두 그래프의 색 개수 벡터가 얼마나 같은 방향인지 재는 점수예요. **WL 그래프 커널(WL graph kernel)** 의 기본 계산이에요."},{"kind":"steps","head":"코사인 유사도 손계산","steps":["$\\phi(G_1) = (6,4,1,1,3,1,1,1,0,0)$","$\\phi(G_2) = (6,4,1,1,2,1,0,1,1,1)$","내적: 36+16+1+1+6+1+0+1+0+0 = 62","길이 제곱: G1 은 66, G2 는 62","$\\cos = 62/(\\sqrt{66}\\sqrt{62}) = \\sqrt{62/66}$"],"answer":"약 0.969. 1 보다 작으니 '비슷하지만 같지는 않다' 예요."}],"pass3":[{"kind":"warn","head":"슬라이드 표 2라운드 줄이 틀렸어요","items":["슬라이드: G1 {2:5, 3:1, 7:1, 8:1}, G2 {2:5, 3:1, 8:1, 9:1, 10:1}. 합이 8 과 9 예요.","노드는 6개이고, 2라운드 표에는 색 2, 3 이 아예 없어요.","올바른 값: G1 {5:3, 6:1, 7:1, 8:1}, G2 {5:2, 6:1, 8:1, 9:1, 10:1}. 결론 '동형 아님' 은 맞아요."]},{"kind":"english","head":"왜 2라운드에서 갈라지나","en":"Round 1 only reflects node degrees, which are identical in both graphs. Round 2 reflects the neighbors' degrees, so the histograms differ and the graphs are non-isomorphic.","ko":"1라운드는 차수만 반영하는데 두 그래프의 차수가 같다. 2라운드는 이웃의 차수를 반영해서 히스토그램이 달라지고 동형이 아니다."},{"kind":"check","q":"히스토그램을 적은 뒤 가장 먼저 할 검산은?","choices":["개수 합이 노드 수와 같은지","번호가 10 을 넘지 않는지","색 번호가 짝수인지"],"a":0,"why":"모든 노드는 색을 딱 하나 받으니 개수 합은 늘 노드 수예요. 슬라이드 표 오류도 여기서 걸려요."},{"kind":"check","q":"**멀티셋(Multi-set)** {2, 2, 3} 과 {2, 3} 은?","choices":["같다","다르다","순서에 따라 다르다"],"a":1,"why":"멀티셋은 순서는 무시하지만 개수는 세요. 2 가 두 개인 것과 한 개인 것은 달라요."}],"pass4":[{"kind":"code","head":"노트북으로 판정 보고서 출력","file":"Sample_Code_3_번역.ipynb 셀 31","code":"wl_report(rounds, ['G1', 'G2'])","lines":[{"from":1,"to":1,"say":"p.50 의 wl_report 를 p.51 에서 계산한 rounds 로 불러요. ['G1', 'G2'] 는 이름 두 개짜리 리스트예요."}],"link":"출력 마지막 줄이 NON-ISOMORPHIC 이에요. 슬라이드 '결과: 동형 아님' 과 짝이에요."},{"kind":"say","lines":["셀 30 설명에 따르면 2라운드 출력은 G1 {5: 3, 6: 1, 7: 1, 8: 1}, G2 {5: 2, 6: 1, 8: 1, 9: 1, 10: 1} 이에요.","코드 출력이 올바른 값이라서 슬라이드 표 오류를 확인할 수 있어요."]},{"kind":"code","head":"networkx 내장 WL 해시로 한 번 더 확인","file":"Sample_Code_3_번역.ipynb 셀 38","code":"def nx_wl_equal(A, B):\n    return nx.weisfeiler_lehman_graph_hash(A, iterations=4) == nx.weisfeiler_lehman_graph_hash(B, iterations=4)\n\nprint(f'networkx WL hash equal?  C6 vs 2xC3: {nx_wl_equal(C6, TwoC3)}   |   G1 vs G2: {nx_wl_equal(G1, G2)}')","lines":[{"from":1,"to":2,"say":"networkx 가 가진 WL 해시로 두 그래프의 지문 문자열을 만들고 == 로 같은지 비교해요. 결과는 True 또는 False 예요."},{"from":4,"to":4,"say":"따옴표 앞 f 는 중괄호 안 값을 글자에 끼워 넣는 f-문자열이에요. G1 vs G2 는 False(구별됨) 가 나와요."}],"link":"C6 vs 2xC3 는 True(구별 못 함). 이 쌍은 p.60 에서 다시 만나요."}]},{"p":53,"title":"완전한 GIN 모델 (1): HASH 를 신경망으로","terms":["GIN","HASH","Injective","Tuple","Multi-set"],"pass1":[{"kind":"say","lines":["이제 이야기를 다시 GNN 으로 가져와요.","색 정제에서 번호를 붙여 주던 규칙, 즉 해시를 신경망으로 바꾼 모델이 **그래프 동형 네트워크(GIN)** 예요.","이 신경망의 입력은 칸이 두 개로 나뉜 묶음이에요. 첫 칸은 내 색, 둘째 칸은 이웃 색 봉투예요.","이렇게 칸의 순서가 정해진 묶음을 **튜플(Tuple)** 이라고 해요."]},{"kind":"look","head":"식 속의 두 칸","boxes":[{"x":0.39,"y":0.43,"w":0.07,"h":0.07,"say":"주황 칸은 지금 새 색을 받을 주인공 노드의 색이에요."},{"x":0.46,"y":0.43,"w":0.14,"h":0.07,"say":"초록 칸은 이웃들 색을 모은 봉투예요."}]},{"kind":"analogy","head":"칸이 나뉜 급식 식판","scene":"급식 식판에는 밥 칸과 반찬 칸이 따로 있어요. 칸이 나뉘어 있으니 무엇이 밥이고 무엇이 반찬인지 한눈에 알아요. 그런데 칸을 없애고 한 그릇에 다 섞어 버리면, 밥이 얼마였고 반찬이 얼마였는지 구별할 수 없어요. 그래서 내 색과 이웃 색도 칸을 나눠서 넣어요.","map":[["밥 칸","내 색 (주인공 노드의 특징)"],["반찬 칸","이웃 색 봉투 (멀티셋)"],["칸이 나뉜 식판","**튜플(Tuple)**"]]}],"pass2":[{"kind":"look","head":"슬라이드를 차례로 짚어 볼게요","boxes":[{"x":0.03,"y":0.16,"w":0.71,"h":0.15,"say":"**그래프 동형 네트워크(GIN)** 는 단사 HASH 를 신경망으로 만든대요. 아래 식은 색 정제 규칙이에요."},{"x":0.39,"y":0.43,"w":0.07,"h":0.07,"say":"주황 칸: 루트 노드 특징. 지금 새 색을 받을 주인공 v 의 색이에요."},{"x":0.46,"y":0.43,"w":0.14,"h":0.07,"say":"초록 칸: 이웃 노드 색. 친구 u 전원의 색을 모은 **멀티셋(Multi-set)** 이에요."},{"x":0.25,"y":0.5,"w":0.45,"h":0.18,"say":"화살표 이름표 두 개가 두 칸을 가리켜요. 이 두 칸 묶음이 **튜플(Tuple)** 이에요."}]},{"kind":"formula","head":"색 정제 규칙을 식으로","tex":"c^{(k+1)}(v) = \\text{HASH}\\left(c^{(k)}(v),\\ \\{c^{(k)}(u)\\}_{u \\in N(v)}\\right)","parts":[{"sym":"c^{(k)}(v)","say":"k 라운드 후 v 의 색. 위첨자 (k) 는 제곱이 아니라 라운드 번호"},{"sym":"c^{(k+1)}(v)","say":"한 라운드 뒤 v 의 새 색"},{"sym":"N(v)","say":"v 의 이웃(친구) 목록"},{"sym":"\\{c^{(k)}(u)\\}_{u \\in N(v)}","say":"친구 전원의 색을 모은 봉투. 순서 없음, 개수는 셈"},{"sym":"(\\ \\cdot\\ ,\\ \\cdot\\ )","say":"튜플. 첫째 칸 내 색, 둘째 칸 친구 봉투"}],"whole":"다음 내 색은 (지금 내 색, 친구 색 봉투) 두 칸 묶음을 **단사(Injective)** 기계에 넣은 값이에요."},{"kind":"steps","head":"칸을 섞으면 무슨 일이?","steps":["X: 내 색 2, 친구 {2, 3}. 튜플 (2, {2, 3})","Y: 내 색 3, 친구 {2, 2}. 튜플 (3, {2, 2})","튜플로 보면 첫째 칸이 2 대 3 이라 달라요.","한 봉투에 섞으면 X 는 {2, 2, 3}, Y 도 {2, 2, 3}"],"answer":"섞으면 다른 노드가 같아져요. 그래서 칸을 나눈 **튜플(Tuple)** 이 필요해요."},{"kind":"figure","head":"튜플 대 한 봉투","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\"><text x=\"120\" y=\"28\" font-size=\"16\" text-anchor=\"middle\" class=\"tb\">칸을 나누면 (튜플)<\/text><text x=\"360\" y=\"28\" font-size=\"16\" text-anchor=\"middle\" class=\"tb b2\">한 봉투에 섞으면<\/text><line x1=\"240\" y1=\"40\" x2=\"240\" y2=\"250\" class=\"hl b2\"/><text x=\"20\" y=\"90\" font-size=\"16\" text-anchor=\"start\" class=\"tb\">X<\/text><rect x=\"40\" y=\"60\" width=\"70\" height=\"46\" rx=\"8\" class=\"box2 b1\"/><text x=\"75\" y=\"89\" font-size=\"14\" text-anchor=\"middle\" class=\"t b1\">내 색 2<\/text><rect x=\"118\" y=\"60\" width=\"110\" height=\"46\" rx=\"8\" class=\"box b1\"/><text x=\"173\" y=\"89\" font-size=\"14\" text-anchor=\"middle\" class=\"t b1\">친구 {2, 3}<\/text><rect x=\"280\" y=\"60\" width=\"160\" height=\"46\" rx=\"8\" class=\"box b2\"/><text x=\"360\" y=\"89\" font-size=\"15\" text-anchor=\"middle\" class=\"t b2\">X: {2, 2, 3}<\/text><text x=\"20\" y=\"170\" font-size=\"16\" text-anchor=\"start\" class=\"tb\">Y<\/text><rect x=\"40\" y=\"140\" width=\"70\" height=\"46\" rx=\"8\" class=\"box2 b1\"/><text x=\"75\" y=\"169\" font-size=\"14\" text-anchor=\"middle\" class=\"t b1\">내 색 3<\/text><rect x=\"118\" y=\"140\" width=\"110\" height=\"46\" rx=\"8\" class=\"box b1\"/><text x=\"173\" y=\"169\" font-size=\"14\" text-anchor=\"middle\" class=\"t b1\">친구 {2, 2}<\/text><rect x=\"280\" y=\"140\" width=\"160\" height=\"46\" rx=\"8\" class=\"box b2\"/><text x=\"360\" y=\"169\" font-size=\"15\" text-anchor=\"middle\" class=\"t b2\">Y: {2, 2, 3}<\/text><text x=\"120\" y=\"245\" font-size=\"14\" text-anchor=\"middle\" class=\"t b1\">첫째 칸이 달라 구별돼요<\/text><text x=\"360\" y=\"245\" font-size=\"14\" text-anchor=\"middle\" class=\"tb b2\">똑같아져서 단사 실패<\/text><\/svg>","caption":"칸을 나눈 채로 단사 함수에 넣어야 다른 노드가 다른 번호를 받아요.","builds":2},{"kind":"points","head":"HASH 표와 신경망","items":["HASH 표는 메뉴판이에요. 조합마다 번호를 적어 둬요.","신경망은 요리사예요. 조합을 보고 숫자 벡터를 계산해요.","요리사가 '다른 조합이면 다른 요리' 만 지키면 메뉴판만큼 구별해요.","게다가 연습(학습)으로 솜씨를 키울 수 있어요."]},{"kind":"prof","when":"3주차 화요일 수업","lines":["WL 은 '1 과 5 의 친구인 2' 로 이름을 다시 붙여요. 사전처럼 단사예요.","GNN 은 1, 5 의 표현을 모아 2 의 표현과 합쳐 업데이트하는데, 여기서 문제가 생겨요.","GIN 은 이 과정을 바꿔 최소한 해시 함수만큼의 표현력을 갖게 한대요."]}],"pass3":[{"kind":"check","q":"**튜플(Tuple)** 의 둘째 칸을 멀티셋으로 다루는 이유는?","choices":["친구 번호를 어떤 순서로 매기든 결과가 같아야 해서","계산이 빨라서","내 색을 두 번 넣으려고"],"a":0,"why":"친구는 여러 명이고 순서가 없어요. 그래서 순서는 무시하고 개수는 세는 멀티셋으로 받아요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["그림 이름표 '특징(features)' 과 '색(colors)' 은 같은 종류 정보예요. 부르는 이름만 달라요.","$c^{(k)}$ 의 $(k)$ 는 k 제곱이 아니라 라운드(층) 번호예요.","내 칸과 친구 칸을 섞으면 (2,{2,3}) 과 (3,{2,2}) 가 같아져요."]},{"kind":"english","head":"GIN 한 줄 정의","en":"GIN uses a neural network to model the injective HASH function over the tuple of the root node feature and the multi-set of neighbor colors.","ko":"GIN 은 루트 노드 특징과 이웃 색 멀티셋의 튜플 위에서 단사 HASH 함수를 신경망으로 모델링한다."}],"pass4":[{"kind":"say","lines":["GIN 모델을 만드는 코드는 3주차 노트북에 없어요.","대신 노트북에서 집계된 튜플을 글자로 바꾸는 함수로 두 칸 모양을 확인해요."]},{"kind":"pyterm","name":"언패킹(풀어 담기)","say":["튜플의 칸을 변수 여러 개에 한 번에 나눠 담아요."],"example":"own, nbrs = (2, (2, 3))\nprint(own)\nprint(nbrs)","out":"2\n(2, 3)"},{"kind":"code","head":"튜플 (내 색, 친구 색) 을 '2,{2,3}' 글자로 (1/3)","file":"Sample_Code_3_번역.ipynb 셀 19 (1/3)","code":"def aggregate(G, colors):\n    \"\"\"Step 2: aggregated color of every node = (own color, sorted tuple of neighbor colors).\"\"\"\n    return {v: (colors[v], tuple(sorted(colors[u] for u in G[v]))) for v in G}\n\n\ndef wl_refine(graphs, num_iterations=3):\n    \"\"\"\n    Color refinement run jointly on a list of graphs with one shared HASH table.\n\n    Returns `rounds`, where rounds[l] is a dict:\n        'colors' : [{node: color} per graph]             colors after round l\n        'agg'    : [{node: aggregated color} per graph]  what was hashed in round l\n        'table'  : {aggregated color: new color}         the HASH table of round l\n    rounds[0] is the initial coloring: every node gets color 1.\n    \"\"\"\n    rounds = [{'colors': [{v: 1 for v in G} for G in graphs], 'agg': None, 'table': {}}]\n    next_color = 2\n    for _ in range(num_iterations):\n        agg = [aggregate(G, c) for G, c in zip(graphs, rounds[-1]['colors'])]\n        # Step 3: 단사 해시. 처음 보는 집계된 색마다 아직 안 쓴 다음 번호를 준다.\n        # (매 라운드의 입력은 새 색들이므로 라운드마다 자기 표 하나만 있으면 된다.)\n        table = {}\n        for a in agg:\n            for sig in a.values():\n                if sig not in table:\n                    table[sig] = next_color\n                    next_color += 1\n        colors = [{v: table[sig] for v, sig in a.items()} for a in agg]\n        rounds.append({'colors': colors, 'agg': agg, 'table': table})\n    return rounds\n","lines":[{"from":1,"to":4,"say":"aggregate 함수: 노드마다 (내 색, 이웃 색을 정렬해 묶은 튜플)을 만들어 사전으로 돌려줘요."},{"from":5,"to":15,"say":"wl_refine 함수의 이름과 설명이에요. 여러 그래프가 HASH 표를 같이 쓰며 색 정제를 하고 rounds 목록을 돌려준대요."},{"from":16,"to":17,"say":"0라운드: 모든 노드를 색 1 로 칠해 rounds 에 넣어요. 새 번호는 2 부터 줘요."},{"from":18,"to":19,"say":"라운드 수만큼 반복하며, 지난 라운드 색으로 모든 노드의 집계 색을 만들어요."},{"from":20,"to":27,"say":"주석 두 줄 뒤, 빈 사전 table 에 처음 보는 집계 색마다 다음 번호를 적어요. 같은 조합은 같은 번호예요."},{"from":28,"to":31,"say":"표에서 새 번호를 찾아 노드를 다시 칠하고, 이번 라운드 결과를 rounds 끝에 붙여요. 다 돌면 rounds 를 돌려줘요."}]},{"kind":"code","head":"튜플 (내 색, 친구 색) 을 '2,{2,3}' 글자로 (2/3)","file":"Sample_Code_3_번역.ipynb 셀 19 (2/3)","code":"\ndef color_histogram(colors):\n    \"\"\"How many nodes carry each color: the graph-level fingerprint.\"\"\"\n    return dict(sorted(Counter(colors.values()).items()))\n\n\ndef wl_report(rounds, names):\n    \"\"\"The WL test: compare the two graphs' color histograms round by round.\"\"\"\n    differ = False\n    for l, r in enumerate(rounds):\n        h1, h2 = (color_histogram(c) for c in r['colors'])\n        differ = differ or h1 != h2\n        print(f\"round {l}:  {names[0]} {str(h1):<34s} {'==' if h1 == h2 else '!='}  {names[1]} {h2}\")\n    print('\\n→ NON-ISOMORPHIC (the histograms differ)' if differ else\n          '\\n→ INCONCLUSIVE (the histograms are always equal)')\n\n\n# ---- 그리기 -------------------------------------------------------------------------\ndef fmt_agg(sig):\n    \"\"\"(3, (3, 4)) -> '3,{3,4}'\"\"\"\n    own, nbrs = sig\n    return f\"{own},{{{','.join(map(str, nbrs))}}}\"\n\n\ndef draw_aggregated(G, pos, ax, colors, agg, title=None):\n    \"\"\"Each node is a box showing its aggregated color, filled with its current color.\"\"\"\n    nx.draw_networkx_edges(G, pos, ax=ax, edge_color=C_EDGE, width=2.0)\n    for v in G:\n        f = color_of(colors[v])\n        ax.text(*pos[v], fmt_agg(agg[v]), ha='center', va='center', fontsize=10, color=ink(f),\n                bbox=dict(boxstyle='round,pad=0.35', fc=f, ec=C_DARK, lw=1.2))\n    xs, ys = zip(*pos.values())\n    ax.set_xlim(min(xs) - 0.5, max(xs) + 0.5)\n    ax.set_ylim(min(ys) - 0.4, max(ys) + 0.4)\n    if title:\n        ax.set_title(title)\n    ax.set_axis_off()\n","lines":[{"from":1,"to":5,"say":"color_histogram 함수: Counter 로 색마다 노드가 몇 개인지 세서 번호 순으로 정리해요."},{"from":6,"to":16,"say":"wl_report 함수: 라운드마다 두 그래프의 색 개수표를 비교해 == 또는 != 를 출력하고, 마지막에 판정을 알려 줘요."},{"from":17,"to":18,"say":"그리기 부분 시작이에요. fmt_agg 는 (3, (3, 4)) 같은 집계 색을 '3,{3,4}' 글자로 바꿔요."},{"from":19,"to":20,"say":"함수 fmt_agg 예요. 설명문 예시처럼 (3, (3, 4)) 를 '3,{3,4}' 로 바꿔요."},{"from":21,"to":21,"say":"튜플을 두 변수로 풀어요. own 은 첫째 칸 내 색, nbrs 는 둘째 칸 친구 색 묶음이에요."},{"from":22,"to":22,"say":"친구 색을 쉼표로 이어 중괄호로 감싼 글자를 돌려줘요. f-문자열에서 중괄호 글자는 두 번 겹쳐 써요."},{"from":24,"to":38,"say":"draw_aggregated 함수: 노드마다 집계 색 글자를 지금 색으로 칠한 상자에 적어 그려요."}],"link":"own = 주황 칸 루트 노드 특징, nbrs = 초록 칸 이웃 노드 색"},{"kind":"code","head":"튜플 (내 색, 친구 색) 을 '2,{2,3}' 글자로 (3/3)","file":"Sample_Code_3_번역.ipynb 셀 19 (3/3)","code":"\ndef draw_hash_table(ax, table, title):\n    tab = ax.table(cellText=[[fmt_agg(sig), c] for sig, c in table.items()],\n                   colLabels=['aggregated color', 'new color'], loc='center', cellLoc='center')\n    tab.auto_set_font_size(False); tab.set_fontsize(11); tab.scale(1, 1.7)\n    for j in range(2):                                   # 머리글 행\n        tab[0, j].set_facecolor(C_DARK)\n        tab[0, j].get_text().set(color='white', fontweight='bold')\n    for i, c in enumerate(table.values(), start=1):      # 새 색마다 칸을 그 색으로 칠한다\n        tab[i, 1].set_facecolor(color_of(c))\n        tab[i, 1].get_text().set(color=ink(color_of(c)), fontweight='bold')\n    ax.set_title(title)\n    ax.set_axis_off()\n\n\ndef show_initial(graphs, names, positions, rounds):\n    fig, axes = plt.subplots(1, len(graphs), figsize=(11, 3))\n    for ax, G, name, pos, c in zip(axes, graphs, names, positions, rounds[0]['colors']):\n        draw_graph(G, pos, ax, colors=c, labels='color', title=name)\n    fig.suptitle('Step 1 - Assign initial colors: every node gets color 1',\n                 fontsize=13, fontweight='bold')\n    plt.tight_layout(); plt.show()\n\n\ndef show_round(graphs, names, positions, rounds, l):\n    \"\"\"One round, left to right: aggregated colors -> HASH table -> new colors.\"\"\"\n    r, prev = rounds[l], rounds[l - 1]['colors']\n    fig = plt.figure(figsize=(15, 5.6))\n    gs = fig.add_gridspec(2, 3, width_ratios=[1, 0.75, 1])\n    for i, (G, name, pos) in enumerate(zip(graphs, names, positions)):\n        draw_aggregated(G, pos, fig.add_subplot(gs[i, 0]), prev[i], r['agg'][i],\n                        title=f'{name}: aggregated colors')\n        draw_graph(G, pos, fig.add_subplot(gs[i, 2]), colors=r['colors'][i], labels='color',\n                   title=f'{name}: new colors')\n    draw_hash_table(fig.add_subplot(gs[:, 1]), r['table'], title=f'HASH table (round {l})')\n    fig.suptitle(f'Round {l}:   Step 2 - aggregate neighboring colors   →   '\n                 f'Step 3 - injectively hash   →   new colors', fontsize=13, fontweight='bold')\n    plt.tight_layout(); plt.show()","lines":[{"from":1,"to":14,"say":"draw_hash_table 함수: HASH 표를 '집계 색, 새 색' 두 열짜리 표 그림으로 그리고 새 색 칸을 그 색으로 칠해요."},{"from":15,"to":23,"say":"show_initial 함수: 모든 노드가 색 1 인 시작 그림을 그래프마다 그려요."},{"from":24,"to":38,"say":"show_round 함수: 한 라운드를 왼쪽 집계 색, 가운데 HASH 표, 오른쪽 새 색 순서로 한 장에 그려요."}]}]},{"p":54,"title":"완전한 GIN 모델 (2): Xu 등의 정리","terms":["GIN","Injective","Tuple","MLP","Sum aggregation","Embedding"],"pass1":[{"kind":"say","lines":["두 칸 묶음, 곧 **튜플(Tuple)** 을 받는 **단사(Injective)** 함수라면 무엇이든 정해진 모양의 신경망으로 만들 수 있다는 정리예요.","2019년 논문에서 Xu 등이 증명한 내용으로, **그래프 동형 네트워크(GIN)** 의 핵심이에요."]},{"kind":"points","head":"그 신경망의 네 단계","items":["첫째, 내 색과 이웃 색을 모두 같은 작은 신경망(**다층 퍼셉트론(MLP)**)으로 바꿔 적어요.","둘째, 내 것에만 1 보다 살짝 큰 수를 곱해 '이건 내 것' 이라고 표시해요. 살짝 더한 양은 학습으로 정해요.","셋째, 이웃 것은 전부 더해요. 몇 명이었는지 남기는 **합 집계(Sum aggregation)** 예요.","넷째, 모두 합친 것을 또 다른 MLP 에 넣어 새 색을 만들어요."]},{"kind":"analogy","head":"세 단계 요리법","scene":"모든 재료를 같은 칼로 손질해요. 내가 가져온 재료에만 이름표를 붙이고, 친구들이 가져온 재료는 한 냄비에 모두 넣어요. 마지막으로 전부 섞어 간을 맞춰요. 이름표 덕에 내 재료가 무엇이었는지 잊지 않고, 한 냄비에 다 넣었으니 재료가 몇 개였는지도 남아요.","map":[["같은 칼로 손질","첫째 단계, 같은 MLP 로 바꿔 적기"],["내 재료에 이름표","둘째 단계, 내 것에 무게 더 얹기"],["한 냄비에 모두 넣기","**합 집계(Sum aggregation)**"],["마지막 간 맞추기","넷째 단계, 또 다른 MLP"]]}],"pass2":[{"kind":"look","head":"슬라이드를 차례로 짚어 볼게요","boxes":[{"x":0.03,"y":0.16,"w":0.28,"h":0.06,"say":"정리(Theorem). Xu 등, ICLR 2019 학회 논문이에요."},{"x":0.14,"y":0.24,"w":0.62,"h":0.1,"say":"p.53 과 같은 **튜플(Tuple)**. 왼쪽 루트 노드 특징, 오른쪽 이웃 노드 색."},{"x":0.07,"y":0.36,"w":0.33,"h":0.05,"say":"튜플 위의 모든 단사 함수는 다음으로 모델링할 수 있대요."},{"x":0.24,"y":0.43,"w":0.48,"h":0.14,"say":"긴 식이에요. 안쪽 **다층 퍼셉트론(MLP)** 이 번역, 바깥 MLP_Φ 가 마무리예요."},{"x":0.07,"y":0.59,"w":0.26,"h":0.06,"say":"ε 은 학습으로 정하는 숫자 하나(스칼라)예요."}]},{"kind":"formula","head":"정리의 식, 안쪽부터 읽기","tex":"\\text{MLP}_{\\Phi}\\left((1+\\epsilon)\\cdot \\text{MLP}_f\\left(c^{(k)}(v)\\right) + \\sum_{u \\in N(v)} \\text{MLP}_f\\left(c^{(k)}(u)\\right)\\right)","parts":[{"sym":"\\text{MLP}_f(c^{(k)}(v))","say":"내 색을 벡터로 번역. 친구에게도 같은 MLP_f 를 써요"},{"sym":"\\sum_{u \\in N(v)}","say":"친구 전원의 번역 벡터를 더하기. 이게 집계예요"},{"sym":"(1+\\epsilon)\\cdot","say":"내 벡터에만 곱해서 '내 칸' 을 표시"},{"sym":"\\epsilon","say":"학습으로 조정되는 숫자 하나"},{"sym":"\\text{MLP}_{\\Phi}","say":"합친 벡터로 새 **임베딩(Embedding)** 을 만드는 MLP. 이게 업데이트예요"}],"whole":"내 색과 친구 색을 같은 번역기로 바꾸고, 내 것은 (1+ε)배, 친구 것은 합해 더한 뒤, 또 다른 MLP 에 넣어 새 색을 만들어요."},{"kind":"points","head":"왜 이런 모양일까","items":["합: 평균, 최댓값은 같은 친구가 몇 명인지 잃어요. **합 집계(Sum aggregation)** 는 개수를 기억해요.","(1+ε): 그냥 더하면 내 칸과 친구 칸이 섞여요. 내 것에만 다른 무게를 줘요.","**다층 퍼셉트론(MLP)**: 층이 충분히 넓으면 거의 어떤 함수든 흉내 내요(보편 근사 정리)."]},{"kind":"figure","head":"GIN 한 층의 계산 흐름","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\"><circle cx=\"35\" cy=\"60\" r=\"16\" class=\"n2\"/><text x=\"35\" y=\"65\" font-size=\"15\" text-anchor=\"middle\" class=\"tl\">v<\/text><circle cx=\"35\" cy=\"150\" r=\"16\" class=\"n\"/><text x=\"35\" y=\"155\" font-size=\"14\" text-anchor=\"middle\" class=\"tl\">u1<\/text><circle cx=\"35\" cy=\"190\" r=\"16\" class=\"n\"/><text x=\"35\" y=\"195\" font-size=\"14\" text-anchor=\"middle\" class=\"tl\">u2<\/text><circle cx=\"35\" cy=\"230\" r=\"16\" class=\"n\"/><text x=\"35\" y=\"235\" font-size=\"14\" text-anchor=\"middle\" class=\"tl\">u3<\/text><rect x=\"78\" y=\"45\" width=\"78\" height=\"30\" rx=\"8\" class=\"box b1\"/><text x=\"117\" y=\"66\" font-size=\"14\" text-anchor=\"middle\" class=\"t b1\">MLP_f<\/text><rect x=\"78\" y=\"135\" width=\"78\" height=\"110\" rx=\"8\" class=\"box b1\"/><text x=\"117\" y=\"185\" font-size=\"14\" text-anchor=\"middle\" class=\"t b1\">MLP_f<\/text><text x=\"117\" y=\"205\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b1\">(같은 것)<\/text><line x1=\"52\" y1=\"60\" x2=\"67\" y2=\"60\" class=\"e b1\"/><polygon points=\"76,60 67,65 67,55\" class=\"arrow b1\"/><line x1=\"52\" y1=\"190\" x2=\"67\" y2=\"190\" class=\"e b1\"/><polygon points=\"76,190 67,195 67,185\" class=\"arrow b1\"/><rect x=\"185\" y=\"45\" width=\"90\" height=\"30\" rx=\"8\" class=\"box2 b2\"/><text x=\"230\" y=\"66\" font-size=\"15\" text-anchor=\"middle\" class=\"t b2\">×(1+ε)<\/text><rect x=\"185\" y=\"175\" width=\"90\" height=\"30\" rx=\"8\" class=\"box2 b2\"/><text x=\"230\" y=\"196\" font-size=\"15\" text-anchor=\"middle\" class=\"t b2\">Σ 합<\/text><line x1=\"157\" y1=\"60\" x2=\"174\" y2=\"60\" class=\"e b2\"/><polygon points=\"183,60 174,65 174,55\" class=\"arrow b2\"/><line x1=\"157\" y1=\"190\" x2=\"174\" y2=\"190\" class=\"e b2\"/><polygon points=\"183,190 174,195 174,185\" class=\"arrow b2\"/><circle cx=\"305\" cy=\"125\" r=\"17\" class=\"n b2\"/><text x=\"305\" y=\"130\" font-size=\"18\" text-anchor=\"middle\" class=\"tl b2\">+<\/text><line x1=\"275\" y1=\"68\" x2=\"288.8\" y2=\"103.6\" class=\"e b2\"/><polygon points=\"292,112 284.1,105.4 293.4,101.8\" class=\"arrow b2\"/><line x1=\"275\" y1=\"182\" x2=\"288.8\" y2=\"146.4\" class=\"e b2\"/><polygon points=\"292,138 293.4,148.2 284.1,144.6\" class=\"arrow b2\"/><rect x=\"340\" y=\"110\" width=\"85\" height=\"30\" rx=\"8\" class=\"box2 b3\"/><text x=\"382\" y=\"131\" font-size=\"15\" text-anchor=\"middle\" class=\"t b3\">MLP_Φ<\/text><line x1=\"322\" y1=\"125\" x2=\"329\" y2=\"125\" class=\"e b3\"/><polygon points=\"338,125 329,130 329,120\" class=\"arrow b3\"/><line x1=\"425\" y1=\"125\" x2=\"459\" y2=\"125\" class=\"e b3\"/><polygon points=\"468,125 459,130 459,120\" class=\"arrow b3\"/><text x=\"430\" y=\"165\" font-size=\"14\" text-anchor=\"middle\" class=\"t b3\">새 임베딩<\/text><text x=\"230\" y=\"30\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b2\">내 칸 표시<\/text><text x=\"230\" y=\"230\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b2\">개수까지 기억<\/text><\/svg>","caption":"번역(메시지), 합(집계), 마무리(업데이트). 앞에서 배운 GNN 한 층과 같은 뼈대예요.","builds":3},{"kind":"steps","head":"ε 과 합을 숫자로 확인","steps":["ε = 0: X 는 1×1 + 10 = 11, Y 는 1×10 + 1 = 11","ε = 0 이면 X 와 Y 가 같아져서 구별 실패","ε = 0.5: X 는 1.5×1 + 10 = 11.5, Y 는 1.5×10 + 1 = 16","봉투 {B} 의 합 10, {B, B} 의 합 20. 평균은 둘 다 10"],"answer":"ε 은 내 칸을 표시하고, 합은 개수를 기억해요. 둘 다 **단사(Injective)** 를 지키는 장치예요.","given":"MLP_f 가 색 A 를 1, 색 B 를 10 으로 번역. MLP_Φ 는 그대로 통과. X = (A, {B}), Y = (B, {A})"},{"kind":"prof","when":"3주차 화요일 수업","lines":["$\\epsilon$ 은 학습 가능한 스칼라예요.","초기 특징이 다른데도 못 가른다면 '내 자신을 잊어서'라고 봐야 한대요.","그래서 $\\epsilon$ 으로 내 자신을 얼마나 더 기억할지 정해 줘요."]}],"pass3":[{"kind":"check","q":"ε = 0 일 때 헷갈릴 수 있는 두 노드는?","choices":["(A, {B}) 와 (B, {A})","(A, {B}) 와 (A, {B, B})","(A, {A}) 와 (B, {B})"],"a":0,"why":"ε = 0 이면 나와 친구가 대칭이라 자리를 바꿔도 합이 같아요."},{"kind":"check","q":"**합 집계(Sum aggregation)** 가 평균보다 나은 이유는?","choices":["계산이 더 빨라서","같은 이웃이 몇 개인지까지 기억해서","값이 항상 작아서"],"a":1,"why":"{B} 와 {B, B} 는 합이 10 대 20 으로 갈리지만 평균은 둘 다 10 이에요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["영어 슬라이드는 'can be modeled as' 가 빠져 문장이 끝나지 않아요. 한글 슬라이드에는 넣었어요.","정리는 이런 모양으로 만들 방법이 '존재한다' 는 뜻이에요. 학습이 늘 완벽한 단사를 배운다는 보장은 아니에요.","논문은 ε 을 특별한 값으로 잡고, 코드는 학습하거나 0 으로 두기도 해요. 시험은 0.5 로 고정해 주기도 해요."]},{"kind":"english","head":"합이 단사인 이유","en":"Unlike mean or max pooling, sum aggregation is injective on multi-sets.","ko":"평균이나 최댓값 풀링과 달리 합 집계는 멀티셋에서 단사이다.","tip":"GNN 2024 가을 기말 5번 (b) 해설의 핵심 문장이에요."}],"pass4":[{"kind":"say","lines":["GIN 층을 만드는 코드는 3주차 노트북에 없어요.","대신 아래 예시 코드로 합과 평균의 차이만 파이썬으로 확인해요."]},{"kind":"pyterm","name":"sum 과 len (예시 코드)","say":["sum(리스트) 는 모두 더한 값, len(리스트) 는 원소 개수예요.","평균은 sum 을 len 으로 나눈 값이에요. [10] 과 [10, 10] 을 비교해요."],"example":"print(sum([10]), sum([10, 10]))\nprint(sum([10]) / len([10]), sum([10, 10]) / len([10, 10]))","out":"10 20\n10.0 10.0"}]},{"p":55,"title":"완전한 GIN 모델 (3): 원핫이면 그냥 더해도 된다","terms":["One-hot encoding","Injective","GINConv","MLP","Sum aggregation"],"pass1":[{"kind":"say","lines":["처음 색을 **원-핫 인코딩(One-hot encoding)**, 곧 '자기 색 칸에만 1' 로 적었다면 좋은 일이 생겨요.","그냥 더하기만 해도 칸마다 색별 개수가 세어져서, 정보를 잃지 않거든요.","그래서 앞 쪽 네 단계 중 첫째 단계를 빼고, 한 줄짜리 **GIN 층(GINConv)** 을 써요.","내 것에 무게를 살짝 더 얹고, 이웃 것은 더해서, MLP 하나에 넣는 모양이에요."]},{"kind":"look","head":"원-핫을 더한 결과","boxes":[{"x":0.29,"y":0.23,"w":0.36,"h":0.17,"say":"노랑 1개와 파랑 2개를 더하면 노랑 칸에 1, 파랑 칸에 2 가 남아요. 색마다 몇 개인지 그대로예요."}]},{"kind":"analogy","head":"반장 선거 개표","scene":"반장 선거 투표용지에는 후보 칸이 있고, 한 장에 한 칸만 도장을 찍어요. 개표할 때 용지를 겹쳐 칸별 도장 수를 세면 후보별 득표 수가 나와요. 득표 수만 알면 어떤 표 묶음이었는지 정확히 알 수 있어요. 그래서 따로 번역할 필요 없이 그냥 세기만 하면 돼요.","map":[["한 칸만 도장 찍힌 용지","**원-핫 인코딩(One-hot encoding)** 으로 적은 색"],["칸별 도장 수 세기","원-핫들을 더하기"],["득표 수로 표 묶음을 알 수 있음","**단사(Injective)**"]]}],"pass2":[{"kind":"look","head":"슬라이드를 차례로 짚어 볼게요","boxes":[{"x":0.03,"y":0.16,"w":0.5,"h":0.06,"say":"입력 특징 c(0)(v) 가 원-핫이면 그냥 더해도 단사래요. 0 은 맨 처음 라운드예요."},{"x":0.29,"y":0.23,"w":0.36,"h":0.17,"say":"노랑 (1,0) 하나, 파랑 (0,1) 둘을 더하면 (1,2). 노랑 1개, 파랑 2개라는 뜻이에요."},{"x":0.03,"y":0.43,"w":0.24,"h":0.06,"say":"함수의 정확한 모양은 상관없고 단사만 지키면 돼요."},{"x":0.13,"y":0.56,"w":0.73,"h":0.16,"say":"**GIN 층(GINConv)** 식. 내 벡터 (1+ε)배와 친구 벡터 합을 MLP_Φ 하나에 넣어요."},{"x":0.13,"y":0.73,"w":0.27,"h":0.1,"say":"주황 루트 노드 특징, 초록 이웃 노드 특징. 앞에서 '색' 이던 게 여기선 '특징' 이에요."}]},{"kind":"figure","head":"원-핫 벡터를 더하면 색별 개수","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\"><circle cx=\"40\" cy=\"60\" r=\"16\" class=\"n2\"/><text x=\"40\" y=\"100\" font-size=\"15\" text-anchor=\"middle\" class=\"t\">(1, 0)<\/text><text x=\"78\" y=\"66\" font-size=\"18\" text-anchor=\"middle\" class=\"tb\">+<\/text><circle cx=\"115\" cy=\"60\" r=\"16\" class=\"n3\"/><text x=\"115\" y=\"100\" font-size=\"15\" text-anchor=\"middle\" class=\"t\">(0, 1)<\/text><text x=\"153\" y=\"66\" font-size=\"18\" text-anchor=\"middle\" class=\"tb\">+<\/text><circle cx=\"190\" cy=\"60\" r=\"16\" class=\"n3\"/><text x=\"190\" y=\"100\" font-size=\"15\" text-anchor=\"middle\" class=\"t\">(0, 1)<\/text><text x=\"228\" y=\"66\" font-size=\"18\" text-anchor=\"middle\" class=\"tb b1\">=<\/text><text x=\"275\" y=\"66\" font-size=\"18\" text-anchor=\"middle\" class=\"tb b1\">(1, 2)<\/text><line x1=\"320\" y1=\"200\" x2=\"460\" y2=\"200\" class=\"e b1\"/><rect x=\"345\" y=\"160\" width=\"40\" height=\"40\" rx=\"2\" class=\"box2 b1\"/><text x=\"365\" y=\"150\" font-size=\"15\" text-anchor=\"middle\" class=\"t b1\">1<\/text><text x=\"365\" y=\"222\" font-size=\"14\" text-anchor=\"middle\" class=\"t b1\">노랑 칸<\/text><rect x=\"405\" y=\"120\" width=\"40\" height=\"80\" rx=\"2\" class=\"box b1\"/><text x=\"425\" y=\"110\" font-size=\"15\" text-anchor=\"middle\" class=\"t b1\">2<\/text><text x=\"425\" y=\"222\" font-size=\"14\" text-anchor=\"middle\" class=\"t b1\">파랑 칸<\/text><text x=\"150\" y=\"160\" font-size=\"15\" text-anchor=\"middle\" class=\"t b2\">칸이 색마다 따로라서<\/text><text x=\"150\" y=\"185\" font-size=\"15\" text-anchor=\"middle\" class=\"t b2\">봉투가 다르면 합도 달라요<\/text><text x=\"240\" y=\"258\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b2\">실수 하나라면 0.5 + 0.5 = 1.0 + 0 (충돌)<\/text><\/svg>","caption":"원-핫의 합은 멀티셋 속 색마다 몇 개인지를 그대로 담아요.","builds":2},{"kind":"compare","head":"p.54 정리 식에서 무엇이 빠졌나","cols":["부분","p.54 정리 식","p.55 GINConv"],"rows":[["내 것","$(1+\\epsilon)\\cdot\\text{MLP}_f(c(v))$","$(1+\\epsilon)\\cdot c(v)$"],["친구 것","$\\sum_u \\text{MLP}_f(c(u))$","$\\sum_u c(u)$"],["바깥","$\\text{MLP}_{\\Phi}$","$\\text{MLP}_{\\Phi}$ 그대로"]]},{"kind":"formula","head":"**GIN 층(GINConv)** 식","tex":"\\text{GINConv}\\left(c^{(k)}(v), \\{c^{(k)}(u)\\}_{u\\in N(v)}\\right) = \\text{MLP}_{\\Phi}\\left((1+\\epsilon)\\cdot c^{(k)}(v) + \\sum_{u\\in N(v)} c^{(k)}(u)\\right)","parts":[{"sym":"(1+\\epsilon)\\cdot c^{(k)}(v)","say":"내 벡터에 1+ε 을 곱해 내 칸을 표시"},{"sym":"\\sum_{u\\in N(v)} c^{(k)}(u)","say":"친구 벡터를 번역 없이 그대로 전부 더하기"},{"sym":"\\text{MLP}_{\\Phi}","say":"합친 결과를 넣는 MLP 하나"}],"whole":"내 벡터에 (1+ε) 을 곱하고, 친구 벡터를 전부 더해 합친 뒤, **다층 퍼셉트론(MLP)** 하나에 넣어요."},{"kind":"steps","head":"ε = 0.1 로 두 노드 계산","steps":["X: 1.1×(1,0) + (0,1) + (0,1) = (1.1, 2)","Y: 1.1×(0,1) + (1,0) + (0,1) = (1, 2.1)","ε = 0 이면 X, Y 둘 다 (1, 2) 로 같아져요.","원-핫이 아닌 실수라면 {0.5, 0.5} 합 1.0, {1.0, 0} 합 1.0 으로 충돌해요."],"answer":"원-핫이면 합이 단사이고, ε 이 내 칸을 표시해 줘요.","given":"노랑 (1,0), 파랑 (0,1). X 는 노랑, 친구 파랑 2명. Y 는 파랑, 친구 노랑 1명과 파랑 1명"},{"kind":"points","head":"2층부터는 원-핫이 아닌데?","items":["앞 층 MLP_Φ 의 출력이 곧 다음 층의 입력이에요.","그래서 앞 층 MLP_Φ 가 다음 층 MLP_f 의 일까지 함께 배워요.","코드로 GIN 층을 만들 때는 층마다 MLP 하나와 숫자 ε 하나만 정하면 돼요."]}],"pass3":[{"kind":"warn","head":"헷갈리기 쉬운 점","items":["'그냥 더해도 단사' 는 **원-핫 인코딩(One-hot encoding)** 입력일 때만 맞아요.","MLP_f 를 뺐다고 표현력이 줄지 않아요. 그 일을 앞 층 MLP_Φ 가 맡아요.","그림의 Φ[ ] 는 대괄호 안 합에 Φ 를 씌운다는 뜻이지 곱하기가 아니에요."]},{"kind":"english","head":"원-핫 합이 단사인 이유","en":"Summing one-hot vectors counts each color, so it is injective on multi-sets.","ko":"원-핫 벡터를 더하면 색마다 개수를 세므로 멀티셋에서 단사이다."},{"kind":"check","q":"색이 3 종류일 때 둘째 색의 **원-핫 인코딩(One-hot encoding)** 은?","choices":["(0, 1, 0)","(2)","(1, 1, 0)","(0, 2, 0)"],"a":0,"why":"칸이 색 수만큼 있고 해당 칸만 1, 나머지는 0 이에요."}],"pass4":[{"kind":"pyterm","name":"넘파이 배열 더하기 (예시 코드)","say":["np.array 는 숫자 벡터예요. + 로 더하면 칸끼리 더해져요.","원-핫 벡터의 합이 색별 개수가 되는 걸 확인해요."],"example":"import numpy as np\nprint(np.array([1, 0]) + np.array([0, 1]) + np.array([0, 1]))","out":"[1 2]"},{"kind":"say","lines":["**GIN 층(GINConv)** 을 직접 쓰는 코드는 3주차 노트북에 없어요.","PyTorch Geometric 같은 라이브러리의 GIN 층도 MLP 를 인자로 받아 이 식을 계산해요."]}]},{"p":56,"title":"완전한 GIN 모델 (4): 알고리즘으로 정리","terms":["GIN","GINConv","Differentiable","K-hop neighborhood","Embedding","Color refinement"],"pass1":[{"kind":"say","lines":["GIN 은 **색 정제(Color refinement)** 와 순서가 똑같은 알고리즘이에요.","처음에 노드마다 숫자 목록을 하나씩 주고, **GIN 층(GINConv)** 으로 여러 번 고쳐요.","층을 세 번 지나면 세 걸음 안쪽 모양이 담겨요. 이런 범위를 **K홉 이웃(K-hop neighborhood)** 이라고 해요. K 는 걸음 수예요.","해시와 달리 GIN 층은 조금씩 고치며 배울 수 있어요. 이런 성질을 **미분 가능(Differentiable)** 이라고 해요."]},{"kind":"compare","head":"색 정제와 GIN 나란히","cols":["단계","색 정제","GIN"],"rows":[["시작","모든 노드에 같은 색","노드마다 처음 숫자 목록"],["고치기","정해진 번호표 규칙(해시)","학습하는 GIN 층"],["결과","색별 개수표","노드마다 숫자 목록(임베딩)"]]}],"pass2":[{"kind":"look","head":"슬라이드를 차례로 짚어 볼게요","boxes":[{"x":0.03,"y":0.16,"w":0.4,"h":0.23,"say":"주어진 것: 노드 집합 V 인 그래프 G. 노드마다 초기 벡터 c(0)(v) 를 줘요."},{"x":0.24,"y":0.49,"w":0.49,"h":0.12,"say":"p.53 의 HASH 자리에 빨간 GINConv 가 들어갔을 뿐 입력은 같아요."},{"x":0.37,"y":0.62,"w":0.16,"h":0.05,"say":"**미분 가능(Differentiable)** 한 색 HASH 함수라서 학습할 수 있어요."},{"x":0.1,"y":0.72,"w":0.57,"h":0.06,"say":"서로 다른 입력을 서로 다른 **임베딩(Embedding)** 으로 보낸다. 곧 단사예요."},{"x":0.07,"y":0.8,"w":0.57,"h":0.06,"say":"K 번 반복하면 c(K)(v) 가 **K홉 이웃(K-hop neighborhood)** 구조를 요약해요."}]},{"kind":"compare","head":"색 정제와 GIN 나란히","cols":["단계","색 정제 (1-WL)","GIN"],"rows":[["시작","모든 노드 색 1","초기 벡터 c(0)(v)"],["갱신","HASH(내 색, 친구 색 봉투)","GINConv(내 벡터, 친구 벡터들)"],["반복","안정될 때까지","K 층"],["결과","색 히스토그램","노드 임베딩"]]},{"kind":"points","head":"미분 가능이 왜 중요할까","items":["**미분 가능(Differentiable)**: 파라미터를 조금 바꾸면 출력도 조금만 바뀌어요.","그래야 틀린 만큼 조금씩 고치는 경사 하강법으로 배울 수 있어요.","표를 찾는 HASH 는 번호가 뚝뚝 끊겨서 조금씩 고칠 수가 없어요."]},{"kind":"steps","head":"기출 방식으로 GIN 한 층 계산","steps":["A: 1.5×1 = 1.5, 이웃 B+C = 5, 합 6.5","B: 1.5×2 = 3, 이웃 A+C = 4, 합 7","C: 1.5×3 = 4.5, 이웃 A+B+D = 7, 합 11.5","D: 1.5×4 = 6, 이웃 C = 3, 합 9","2층 A: 1.5×6.5 + (7 + 11.5) = 28.25"],"answer":"1층 A 6.5, B 7, C 11.5, D 9. D 의 값 4 는 2층에서야 A 에 도착해요.","given":"엣지 A-B, A-C, B-C, C-D. 초기값 A=1, B=2, C=3, D=4. ε = 0.5, MLP 는 생략"},{"kind":"figure","head":"층이 늘면 한 걸음씩 퍼져요","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\"><text x=\"115\" y=\"24\" font-size=\"15\" text-anchor=\"middle\" class=\"tb\">1층 후 (ε = 0.5)<\/text><line x1=\"50\" y1=\"75\" x2=\"50\" y2=\"195\" class=\"e\"/><line x1=\"50\" y1=\"75\" x2=\"120\" y2=\"135\" class=\"e\"/><line x1=\"50\" y1=\"195\" x2=\"120\" y2=\"135\" class=\"e\"/><line x1=\"120\" y1=\"135\" x2=\"195\" y2=\"135\" class=\"e\"/><circle cx=\"50\" cy=\"75\" r=\"16\" class=\"n2\"/><text x=\"50\" y=\"80\" font-size=\"15\" text-anchor=\"middle\" class=\"tl\">A<\/text><circle cx=\"50\" cy=\"195\" r=\"16\" class=\"n\"/><text x=\"50\" y=\"200\" font-size=\"15\" text-anchor=\"middle\" class=\"tl\">B<\/text><circle cx=\"120\" cy=\"135\" r=\"16\" class=\"n\"/><text x=\"120\" y=\"140\" font-size=\"15\" text-anchor=\"middle\" class=\"tl\">C<\/text><circle cx=\"195\" cy=\"135\" r=\"16\" class=\"n3\"/><text x=\"195\" y=\"140\" font-size=\"15\" text-anchor=\"middle\" class=\"tl\">D<\/text><text x=\"88\" y=\"70\" font-size=\"15\" text-anchor=\"start\" class=\"t\">6.5<\/text><text x=\"88\" y=\"212\" font-size=\"15\" text-anchor=\"start\" class=\"t\">7<\/text><text x=\"120\" y=\"175\" font-size=\"15\" text-anchor=\"middle\" class=\"t\">11.5<\/text><text x=\"195\" y=\"175\" font-size=\"15\" text-anchor=\"middle\" class=\"t\">9<\/text><text x=\"115\" y=\"250\" font-size=\"14\" text-anchor=\"middle\" class=\"tm\">A 의 6.5 에 D 의 4 는 없음<\/text><line x1=\"240\" y1=\"40\" x2=\"240\" y2=\"255\" class=\"hl\"/><circle cx=\"365\" cy=\"140\" r=\"52\" fill=\"none\" class=\"hl b1\"/><circle cx=\"365\" cy=\"140\" r=\"98\" fill=\"none\" class=\"hl b2\"/><text x=\"365\" y=\"30\" font-size=\"15\" text-anchor=\"middle\" class=\"tb\">A 가 보는 범위<\/text><circle cx=\"365\" cy=\"140\" r=\"15\" class=\"n2\"/><text x=\"365\" y=\"145\" font-size=\"14\" text-anchor=\"middle\" class=\"tl\">A<\/text><circle cx=\"320\" cy=\"150\" r=\"13\" class=\"n b1\"/><text x=\"320\" y=\"155\" font-size=\"14\" text-anchor=\"middle\" class=\"tl b1\">B<\/text><circle cx=\"410\" cy=\"150\" r=\"13\" class=\"n b1\"/><text x=\"410\" y=\"155\" font-size=\"14\" text-anchor=\"middle\" class=\"tl b1\">C<\/text><text x=\"365\" y=\"108\" font-size=\"14\" text-anchor=\"middle\" class=\"t b1\">1층: B, C<\/text><circle cx=\"455\" cy=\"180\" r=\"13\" class=\"n3 b2\"/><text x=\"455\" y=\"185\" font-size=\"14\" text-anchor=\"middle\" class=\"tl b2\">D<\/text><text x=\"365\" y=\"262\" font-size=\"14\" text-anchor=\"middle\" class=\"t b2\">2층: D 까지 도착<\/text><\/svg>","caption":"K 층이면 K 걸음 안까지만 보여요. 층 수가 곧 '몇 걸음까지 보느냐' 예요.","builds":2},{"kind":"prof","when":"3주차 화요일 수업","lines":["GIN 은 'GNN 은 왜 WL 만큼 못 하나' 라는 의문에서 출발했대요.","고친 것은 셋: 풀링 방식, 업데이트 방식, 그리고 타깃 노드 표현을 잘 기억하기."]}],"pass3":[{"kind":"exam","src":"GNN 2024 가을 기말 5번 (a) (10점 문제)","q":"Consider an undirected graph of four nodes A, B, C, D with initial features. According to the GIN model with a fixed scalar ε = 0.5, h_i(k) = (1+ε) h_i(k-1) + sum over j in N(i) of h_j(k-1). Calculate the feature of each node at k = 1.","qko":"노드 A, B, C, D 무방향 그래프와 초기 특징이 주어진다. ε = 0.5 로 고정한 GIN 식으로 k = 1 의 특징을 구하라.","solve":["해설 계산에서 읽은 값: A 0.2, B 0.3, C 0.2, D 0.1. 이웃 A {B,C,D}, B {A,C}, C {A,B,D}, D {A,C}","A: 1.5×0.2 + (0.3+0.2+0.1) = 0.3 + 0.6 = 0.9","B: 1.5×0.3 + (0.2+0.2) = 0.45 + 0.4 = 0.85","C: 1.5×0.2 + (0.2+0.3+0.1) = 0.3 + 0.6 = 0.9","D: 1.5×0.1 + (0.2+0.2) = 0.15 + 0.4 = 0.55"],"answer":"A 0.9, B 0.85, C 0.9, D 0.55"},{"kind":"warn","head":"계산 실수 막기","items":["이웃 합에 자기 자신을 또 넣지 마세요. 자기 몫은 (1+ε) 칸에서 이미 계산했어요.","한 층 안에서는 모든 노드가 동시에 이전 층 값만 써요. 방금 구한 새 값을 섞지 마세요.","슬라이드 상자 식은 입력을 중괄호로 한 번 더 감쌌어요. 소괄호 튜플로 읽어야 해요."]},{"kind":"english","head":"K 층의 뜻","en":"After K GIN layers, each node embedding summarizes the structure of its K-hop neighborhood.","ko":"K 개의 GIN 층을 지나면 각 노드 임베딩은 K홉 이웃의 구조를 요약한다."},{"kind":"check","q":"2층 GIN 에서, 노드 A 로부터 3걸음 떨어진 노드의 정보는?","choices":["A 의 임베딩에 들어 있다","전혀 들어 있지 않다","절반만 들어 있다"],"a":1,"why":"K 층이면 **K홉 이웃(K-hop neighborhood)** 까지만 봐요. 3걸음은 2층 범위 밖이에요."}],"pass4":[{"kind":"code","head":"계산 그래프를 층 수만큼 펼치기 (1/2)","file":"Sample_Code_3_번역.ipynb 셀 12 (1/2)","code":"def unfolding_tree(G, root, depth):\n    \"\"\"\n    Computational graph of `root` for a `depth`-layer GNN.\n    Tree nodes are walks starting at `root`; attribute 'orig' is the graph node a copy stands for.\n    Edges point child -> parent, the direction messages flow.\n    \"\"\"\n    T = nx.DiGraph()\n    T.add_node((root,), orig=root, level=0)\n    frontier = [(root,)]\n    for d in range(1, depth + 1):\n        frontier = [walk + (u,) for walk in frontier for u in sorted(G[walk[-1]])]\n        for walk in frontier:\n            T.add_node(walk, orig=walk[-1], level=d)\n            T.add_edge(walk, walk[:-1])\n    return T\n\n\ndef draw_tree(T, ax, uniform=False, title=None, node_size=460, font_size=9):\n    \"\"\"Draw a tree with the root on top. uniform=True paints every copy gray (only shape matters).\"\"\"\n    pos, next_x = {}, [0.0]\n\n    def place(n):                                   # 각 부모를 자식들의 가운데 위에 놓는다\n        kids = sorted(T.predecessors(n))\n        if kids:\n            x = float(np.mean([place(k) for k in kids]))\n        else:\n            x, next_x[0] = next_x[0], next_x[0] + 1\n        pos[n] = (x, -T.nodes[n]['level'])\n        return x\n\n    place(next(n for n in T if T.nodes[n]['level'] == 0))\n    nodes = list(T.nodes())\n    fill = [color_of(0 if uniform else T.nodes[n]['orig'] + 1) for n in nodes]\n    nx.draw_networkx_edges(T, pos, ax=ax, arrows=False, edge_color=C_EDGE, width=1.4)\n    nx.draw_networkx_nodes(T, pos, nodelist=nodes, ax=ax, node_color=fill,\n                           edgecolors=C_DARK, linewidths=1.1, node_size=node_size)\n    for n, f in zip(nodes, fill):\n        ax.text(*pos[n], str(T.nodes[n]['orig']), ha='center', va='center',\n                fontsize=font_size, color=ink(f))\n    if title:\n        ax.set_title(title)\n    ax.set_axis_off()\n    ax.margins(0.08)\n","lines":[{"from":1,"to":6,"say":"root 노드의 depth 층짜리 **계산 그래프(Computational graph)** 를 만드는 함수예요. 2~6줄은 설명문이에요."},{"from":7,"to":9,"say":"빈 방향 그래프 T 에 뿌리 (root,) 를 넣어요. frontier 는 지금 맨 아래 줄 목록이에요."},{"from":10,"to":11,"say":"층 수만큼 반복해요. 맨 아래 줄 걸음마다 마지막 노드의 친구를 하나씩 붙여 새 줄을 만들어요."},{"from":12,"to":14,"say":"새 줄 노드를 트리에 넣고 부모와 엣지로 이어요. 한 번 돌 때마다 한 걸음 더 멀리 가요."},{"from":15,"to":15,"say":"완성된 트리를 돌려줘요."},{"from":18,"to":31,"say":"draw_tree 함수의 시작 부분이에요. place 가 자식들을 먼저 배치하고, 부모를 그 가운데 위에 놓아 좌표를 정해요."},{"from":32,"to":44,"say":"노드 색을 정하고 선, 동그라미, 번호 글자를 그려요. uniform=True 면 모두 회색이라 모양만 보여요."}],"link":"depth = GIN 층 수 K. 트리 깊이가 K 라서 K홉 밖은 안 보여요."},{"kind":"code","head":"계산 그래프를 층 수만큼 펼치기 (2/2)","file":"Sample_Code_3_번역.ipynb 셀 12 (2/2)","code":"\nG_demo = nx.Graph([(0, 1), (0, 2), (1, 2), (1, 3), (2, 4), (3, 4), (4, 5)])\nPOS_DEMO = nx.spring_layout(G_demo, seed=3)\n\nfig = plt.figure(figsize=(14, 4.4))\ngs = fig.add_gridspec(1, 3, width_ratios=[1, 1.25, 1.6])\ndraw_graph(G_demo, POS_DEMO, fig.add_subplot(gs[0]), colors={v: v + 1 for v in G_demo},\n           highlight=0, title='The graph (target node 0)')\nfor k, depth in enumerate([1, 2]):\n    T = unfolding_tree(G_demo, 0, depth)\n    draw_tree(T, fig.add_subplot(gs[k + 1]),\n              title=f'Computational graph of node 0, {depth} layer(s)\\n'\n                    f'({T.number_of_nodes()} tree nodes)')\nplt.tight_layout(); plt.show()\n\nsizes = [unfolding_tree(G_demo, 0, L).number_of_nodes() for L in range(6)]\nprint(f'Tree size for L = 0..5 layers: {sizes}   (the graph has only {G_demo.number_of_nodes()} nodes)')","lines":[{"from":1,"to":4,"say":"예시 그래프 G_demo 를 (노드, 노드) 쌍 목록으로 만들고 그릴 좌표를 정해요."},{"from":5,"to":14,"say":"그림 세 칸에 원래 그래프와 1층, 2층 계산 그래프를 나란히 그려요."},{"from":15,"to":17,"say":"층 수 0 부터 5 까지 나무 크기를 세서 출력해요. 그래프 노드는 6개뿐인데 나무는 금방 커져요."}]},{"kind":"pyterm","name":"range 와 for","say":["range(1, 4) 는 1, 2, 3 을 차례로 만들어요. 끝 수 4 는 빠져요.","for d in range(1, depth + 1) 은 1층부터 depth 층까지 반복한다는 뜻이에요."],"example":"for d in range(1, 4):\n    print(d)","out":"1\n2\n3"},{"kind":"code","head":"층 수에 따라 트리 크기 재기 (1/2)","file":"Sample_Code_3_번역.ipynb 셀 12 (1/2)","code":"def unfolding_tree(G, root, depth):\n    \"\"\"\n    Computational graph of `root` for a `depth`-layer GNN.\n    Tree nodes are walks starting at `root`; attribute 'orig' is the graph node a copy stands for.\n    Edges point child -> parent, the direction messages flow.\n    \"\"\"\n    T = nx.DiGraph()\n    T.add_node((root,), orig=root, level=0)\n    frontier = [(root,)]\n    for d in range(1, depth + 1):\n        frontier = [walk + (u,) for walk in frontier for u in sorted(G[walk[-1]])]\n        for walk in frontier:\n            T.add_node(walk, orig=walk[-1], level=d)\n            T.add_edge(walk, walk[:-1])\n    return T\n\n\ndef draw_tree(T, ax, uniform=False, title=None, node_size=460, font_size=9):\n    \"\"\"Draw a tree with the root on top. uniform=True paints every copy gray (only shape matters).\"\"\"\n    pos, next_x = {}, [0.0]\n\n    def place(n):                                   # 각 부모를 자식들의 가운데 위에 놓는다\n        kids = sorted(T.predecessors(n))\n        if kids:\n            x = float(np.mean([place(k) for k in kids]))\n        else:\n            x, next_x[0] = next_x[0], next_x[0] + 1\n        pos[n] = (x, -T.nodes[n]['level'])\n        return x\n\n    place(next(n for n in T if T.nodes[n]['level'] == 0))\n    nodes = list(T.nodes())\n    fill = [color_of(0 if uniform else T.nodes[n]['orig'] + 1) for n in nodes]\n    nx.draw_networkx_edges(T, pos, ax=ax, arrows=False, edge_color=C_EDGE, width=1.4)\n    nx.draw_networkx_nodes(T, pos, nodelist=nodes, ax=ax, node_color=fill,\n                           edgecolors=C_DARK, linewidths=1.1, node_size=node_size)\n    for n, f in zip(nodes, fill):\n        ax.text(*pos[n], str(T.nodes[n]['orig']), ha='center', va='center',\n                fontsize=font_size, color=ink(f))\n    if title:\n        ax.set_title(title)\n    ax.set_axis_off()\n    ax.margins(0.08)\n","lines":[{"from":1,"to":6,"say":"unfolding_tree 함수의 이름과 설명(따옴표 세 개 사이 글)이에요. 뿌리에서 depth 층만큼 펼친 계산 그래프를 만들어요."},{"from":7,"to":9,"say":"빈 방향 그래프 T 를 만들고 뿌리 하나를 넣어요. frontier 는 지금 나무 맨 아래 줄 목록이에요."},{"from":10,"to":17,"say":"층마다 맨 아래 줄 노드의 이웃을 하나씩 붙여 새 줄을 만들고, 자식에서 부모로 가는 선을 그어요. 끝나면 나무를 돌려줘요."},{"from":18,"to":31,"say":"draw_tree 함수의 시작 부분이에요. place 가 자식들을 먼저 배치하고, 부모를 그 가운데 위에 놓아 좌표를 정해요."},{"from":32,"to":44,"say":"노드 색을 정하고 선, 동그라미, 번호 글자를 그려요. uniform=True 면 모두 회색이라 모양만 보여요."}]},{"kind":"code","head":"층 수에 따라 트리 크기 재기 (2/2)","file":"Sample_Code_3_번역.ipynb 셀 12 (2/2)","code":"\nG_demo = nx.Graph([(0, 1), (0, 2), (1, 2), (1, 3), (2, 4), (3, 4), (4, 5)])\nPOS_DEMO = nx.spring_layout(G_demo, seed=3)\n\nfig = plt.figure(figsize=(14, 4.4))\ngs = fig.add_gridspec(1, 3, width_ratios=[1, 1.25, 1.6])\ndraw_graph(G_demo, POS_DEMO, fig.add_subplot(gs[0]), colors={v: v + 1 for v in G_demo},\n           highlight=0, title='The graph (target node 0)')\nfor k, depth in enumerate([1, 2]):\n    T = unfolding_tree(G_demo, 0, depth)\n    draw_tree(T, fig.add_subplot(gs[k + 1]),\n              title=f'Computational graph of node 0, {depth} layer(s)\\n'\n                    f'({T.number_of_nodes()} tree nodes)')\nplt.tight_layout(); plt.show()\n\nsizes = [unfolding_tree(G_demo, 0, L).number_of_nodes() for L in range(6)]\nprint(f'Tree size for L = 0..5 layers: {sizes}   (the graph has only {G_demo.number_of_nodes()} nodes)')","lines":[{"from":1,"to":4,"say":"예시 그래프 G_demo 를 (노드, 노드) 쌍 목록으로 만들고 그릴 좌표를 정해요."},{"from":5,"to":14,"say":"그림 세 칸에 원래 그래프와 1층, 2층 계산 그래프를 나란히 그려요."},{"from":16,"to":16,"say":"층 수 L 을 0 부터 5 까지 바꿔 가며 트리 노드 수를 리스트에 모아요. 대괄호 안 for 는 리스트를 한 줄로 만드는 문법이에요."},{"from":17,"to":17,"say":"셀 11 설명에 따르면 그래프 노드는 6개뿐인데 트리는 162개까지 커져요."}],"link":"층이 늘면 보는 범위도, 계산 그래프도 함께 커져요."}]},{"p":57,"title":"GIN 과 WL 그래프 커널","terms":["WL graph kernel","GIN","GINConv","One-hot encoding","Embedding","Downstream task","Differentiable"],"pass1":[{"kind":"say","lines":["GIN 은 **WL 그래프 커널(WL graph kernel)** 을 배울 수 있는 신경망으로 바꾼 버전이에요.","뼈대는 같고, 다른 점은 두 가지예요.","하나, 색 번호 대신 짧은 숫자 목록인 **임베딩(Embedding)** 을 써서 노드끼리 얼마나 닮았는지 나타내요.","둘, 번호표 규칙 대신 학습하는 GIN 층을 써서, 풀고 싶은 문제에 맞게 스스로 고쳐요."]},{"kind":"analogy","head":"반 이름과 지도 좌표","scene":"'5반', '7반' 이라는 이름만으로는 두 교실이 가까운지 알 수 없어요. 그런데 교실마다 지도 좌표가 적혀 있으면 복도 하나 차이인지, 건물 반대편인지 계산할 수 있어요. GIN 의 임베딩은 이 지도 좌표처럼, 노드끼리 얼마나 닮았는지를 거리로 보여 줘요.","map":[["반 이름","WL 의 색 번호"],["교실 지도 좌표","짧은 숫자 목록, **임베딩(Embedding)**"],["두 교실 사이 거리","두 노드가 닮은 정도"]]}],"pass2":[{"kind":"look","head":"슬라이드를 차례로 짚어 볼게요","boxes":[{"x":0.03,"y":0.16,"w":0.59,"h":0.06,"say":"GIN 은 **WL 그래프 커널(WL graph kernel)** 의 미분 가능한 신경망 버전으로 볼 수 있대요."},{"x":0.2,"y":0.29,"w":0.6,"h":0.1,"say":"WL 그래프 커널 행: 노드 색(원핫)을 HASH 로 갱신해요."},{"x":0.2,"y":0.39,"w":0.6,"h":0.1,"say":"GIN 행: 노드 **임베딩(Embedding)**(저차원 벡터)을 GINConv 로 갱신해요."},{"x":0.07,"y":0.6,"w":0.71,"h":0.06,"say":"장점 1: 저차원이라서 노드 사이 세밀한 유사도를 담아요."},{"x":0.07,"y":0.76,"w":0.55,"h":0.06,"say":"장점 2: 갱신 함수 파라미터를 **다운스트림 과제(Downstream task)** 에 맞게 학습해요."}]},{"kind":"points","head":"용어 정리","items":["커널: 여기서는 두 대상의 유사도를 재는 함수예요.","**WL 그래프 커널(WL graph kernel)**: 라운드별 색 히스토그램을 특징 벡터로 삼아 유사도를 매겨요.","저차원: 칸 수를 16, 64 처럼 미리 정해 두고 소수점 숫자로 채운 벡터예요.","**다운스트림 과제(Downstream task)**: 최종적으로 풀 문제예요. 예를 들어 분자 독성 맞히기."]},{"kind":"steps","head":"원핫 거리 대 임베딩 거리","steps":["원핫: 색 5, 7, 8 은 각자 자기 칸만 1","원핫 거리($e_5$ 는 색 5 칸만 1 인 벡터, 겹세로줄은 두 점 사이 거리): $\\lVert e_5 - e_7 \\rVert = \\lVert e_5 - e_8 \\rVert = \\sqrt{2} \\approx 1.414$","예시 임베딩: 색 5 (0.9, 0.1), 색 7 (0.8, 0.2), 색 8 (0.1, 0.9)","5 와 7: $\\sqrt{0.01 + 0.01} = \\sqrt{0.02} \\approx 0.141$","5 와 8: $\\sqrt{0.64 + 0.64} = \\sqrt{1.28} \\approx 1.131$"],"answer":"임베딩은 '5 와 7 은 닮고 8 은 멀다' 를 거리로 보여 줘요. 좌표는 설명용 예시 값이에요.","given":"p.52 의 2라운드 색: 5 는 2,{2,3}, 7 은 2,{2,4} 로 닮았고, 8 은 4,{2} 꼬리 끝"},{"kind":"figure","head":"원핫 색 대 저차원 임베딩","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\"><text x=\"120\" y=\"26\" font-size=\"15\" text-anchor=\"middle\" class=\"tb\">WL: 원핫 색<\/text><line x1=\"120\" y1=\"70\" x2=\"50\" y2=\"190\" class=\"e\"/><line x1=\"120\" y1=\"70\" x2=\"190\" y2=\"190\" class=\"e\"/><line x1=\"50\" y1=\"190\" x2=\"190\" y2=\"190\" class=\"e\"/><circle cx=\"120\" cy=\"70\" r=\"17\" class=\"n\"/><text x=\"120\" y=\"75\" font-size=\"15\" text-anchor=\"middle\" class=\"tl\">5<\/text><circle cx=\"50\" cy=\"190\" r=\"17\" class=\"n2\"/><text x=\"50\" y=\"195\" font-size=\"15\" text-anchor=\"middle\" class=\"tl\">7<\/text><circle cx=\"190\" cy=\"190\" r=\"17\" class=\"n3\"/><text x=\"190\" y=\"195\" font-size=\"15\" text-anchor=\"middle\" class=\"tl\">8<\/text><text x=\"68\" y=\"128\" font-size=\"15\" text-anchor=\"middle\" class=\"t\">√2<\/text><text x=\"172\" y=\"128\" font-size=\"15\" text-anchor=\"middle\" class=\"t\">√2<\/text><text x=\"120\" y=\"215\" font-size=\"15\" text-anchor=\"middle\" class=\"t\">√2<\/text><text x=\"120\" y=\"250\" font-size=\"14\" text-anchor=\"middle\" class=\"tm\">같다, 다르다만 표현<\/text><line x1=\"240\" y1=\"40\" x2=\"240\" y2=\"255\" class=\"hl b1\"/><text x=\"365\" y=\"26\" font-size=\"15\" text-anchor=\"middle\" class=\"tb b1\">GIN: 저차원 임베딩<\/text><line x1=\"275\" y1=\"220\" x2=\"465\" y2=\"220\" class=\"e b1\"/><line x1=\"275\" y1=\"220\" x2=\"275\" y2=\"45\" class=\"e b1\"/><circle cx=\"445\" cy=\"205\" r=\"14\" class=\"n b1\"/><text x=\"445\" y=\"210\" font-size=\"14\" text-anchor=\"middle\" class=\"tl b1\">5<\/text><circle cx=\"420\" cy=\"180\" r=\"14\" class=\"n2 b1\"/><text x=\"420\" y=\"185\" font-size=\"14\" text-anchor=\"middle\" class=\"tl b1\">7<\/text><circle cx=\"300\" cy=\"65\" r=\"14\" class=\"n3 b1\"/><text x=\"300\" y=\"70\" font-size=\"14\" text-anchor=\"middle\" class=\"tl b1\">8<\/text><text x=\"390\" y=\"145\" font-size=\"14\" text-anchor=\"middle\" class=\"t b2\">5 와 7 가까움 0.14<\/text><text x=\"360\" y=\"90\" font-size=\"14\" text-anchor=\"start\" class=\"t b2\">8 은 멂 1.13<\/text><text x=\"365\" y=\"250\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b2\">닮은 정도를 거리로 표현<\/text><\/svg>","caption":"원핫은 모든 쌍의 거리가 같고, 임베딩은 닮은 노드끼리 가깝게 놓을 수 있어요.","builds":2},{"kind":"compare","head":"무엇을, 무엇으로 고치나","cols":["","갱신 대상","갱신 함수"],"rows":[["WL 그래프 커널","노드 색 (원핫)","HASH (고정 규칙)"],["GIN","노드 임베딩 (저차원)","GINConv (학습)"]]},{"kind":"prof","when":"3주차 화요일 수업","lines":["갱신 대상: WL 은 원핫 같은 이름, GIN 은 고차원 노드 표현이에요.","갱신 함수: WL 은 해시, GIN 은 그래프 합성곱이에요.","GIN 은 그 합성곱을 최소한 해시만큼 표현력 있게 바꾼 거래요."]},{"kind":"mining","src":"마이닝 9강 Graph Kernels","lines":["그래프 커널은 두 그래프 유사도를 그래프 특징 벡터의 내적으로 계산하는 함수라고 배웠어요.","그래플릿, 최단 경로, 랜덤 워크, 그리고 WL 커널을 배웠죠.","WL 커널 특징 벡터가 라운드별 색 개수이고, p.52 코사인 유사도가 그 예예요."]}],"pass3":[{"kind":"exam","src":"그래프 마이닝 2024 봄 중간 12번 (10점, 커널 유사도 형식)","q":"Make feature vectors of graphs G1 and G2 using the shortest path kernel and calculate the similarity of the graphs using the cosine similarity.","qko":"최단 경로 커널로 G1, G2 의 특징 벡터를 만들고 코사인 유사도를 구하라. (WL 대신 최단 경로 길이를 세는 같은 틀)","solve":["G1 최단 경로: 0-1 길이 1, 0-2 길이 1, 1-2 길이 2. 길이별 개수 (2, 1)","G2: 0-1, 0-2, 0-3 길이 1. 1-2, 1-3, 2-3 길이 2. 개수 (3, 3)","내적: 2×3 + 1×3 = 9","길이: $\\sqrt{4+1} = \\sqrt{5}$, $\\sqrt{9+9} = \\sqrt{18}$","$\\cos = 9 / (\\sqrt{5}\\sqrt{18}) = 9 / \\sqrt{90}$"],"answer":"약 0.949. 해설에는 0.9847 로 적혀 있지만 직접 계산하면 0.949 예요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["저차원은 정보가 적다는 뜻이 아니라 칸 수가 색 종류만큼 불어나지 않는다는 뜻이에요.","두 장점은 '더 잘 배운다' 는 이야기지 '더 많이 구별한다' 가 아니에요. 구별력은 p.58 에서 봐요.","마이닝 2024 봄 중간 12번 해설의 0.9847 은 숫자 순서가 뒤바뀐 것으로 보여요. 시험에서는 끝까지 직접 계산해요."]},{"kind":"english","head":"GIN 과 WL 커널 비교 문장","en":"GIN is a differentiable neural version of the WL graph kernel: it updates low-dimensional node embeddings with GINConv instead of one-hot colors with HASH.","ko":"GIN 은 WL 그래프 커널의 미분 가능한 신경망 버전이다. 원핫 색을 HASH 로 고치는 대신 저차원 노드 임베딩을 GINConv 로 고친다."},{"kind":"check","q":"**다운스트림 과제(Downstream task)** 의 뜻은?","choices":["최종적으로 풀고 싶은 문제","데이터를 내려받는 작업","층을 아래로 쌓는 일"],"a":0,"why":"예를 들어 분자 독성 맞히기처럼 모델을 써서 결국 풀려는 과제예요."}],"pass4":[{"kind":"say","lines":["1주차 실습 노트북 PracticeCode_1_번역.ipynb 에 WL 을 직접 구현한 코드가 있어요.","HASH 자리에 진짜 해시 함수(sha224)가 들어간 버전이에요."]},{"kind":"code","head":"WL 뼈대 함수: 해시로 색 갱신, 개수로 정규형","file":"PracticeCode_1_번역.ipynb 셀 157","code":"import hashlib\nimport copy\nimport itertools\n\n# WL을 계산하는 기본 함수\ndef compute_base_WL(graph, k, verbose, n_set, initial_colors_func, find_neighbors_func):    \n    G, n = n_set(graph)\n    colors = initial_colors_func(n)\n    old_colors = copy.deepcopy(colors)\n    \n    for i in range(len(n)):\n        for node in n:\n            neigh_colors = \"\".join([colors[i][0] for i in find_neighbors_func(G, n, node)])\n            colors[node].extend([neigh_colors])\n            colors[node].sort()\n            \n        # 해시로 갱신\n        colors = {i: [hashlib.sha224(\"\".join(colors[i]).encode('utf-8')).hexdigest()] for i in colors}\n        \n        if list(Counter([item for sublist in colors.values() for item in sublist]).values()) == list(Counter([item for sublist in old_colors.values() for item in sublist]).values()) and i != 0:\n            if verbose:\n                print(f'Converged at iteration {i}!')\n            break\n        \n        old_colors = copy.deepcopy(colors)\n    canonical_form = sorted(Counter([item for sublist in colors.values() for item in sublist]).items())\n    \n    if verbose:\n        print(f'Canonical Form Found: \\n {canonical_form} \\n')\n        \n    return canonical_form\n","lines":[{"from":1,"to":3,"say":"import 는 도구 상자를 불러오는 말이에요. hashlib 은 해시 함수, copy 는 복사 도구예요."},{"from":5,"to":5,"say":"# 뒤는 실행되지 않는 메모(주석)예요. 아래가 WL 을 계산하는 기본 함수라는 뜻이에요."},{"from":6,"to":9,"say":"n_set 으로 노드 목록 n 을, initial_colors_func 로 첫 색을 만들어요. 함수를 재료로 넘길 수 있어요."},{"from":11,"to":15,"say":"노드마다 친구 색을 이어 붙여 내 색 목록에 넣고 정렬해요. (내 색, 친구 색 봉투) 집계예요."},{"from":17,"to":18,"say":"sha224 해시로 새 색 문자열을 만들어요. 슬라이드 WL 행의 HASH 가 이 줄이에요."},{"from":20,"to":23,"say":"색 개수 분포가 지난번과 같으면 안정됐다고 보고 break 로 반복을 멈춰요."},{"from":25,"to":31,"say":"마지막 (색, 개수) 목록을 정렬해 돌려줘요. 이게 색 히스토그램, 곧 WL 커널의 특징이에요."}],"link":"WL 행: 갱신 대상 = 색 문자열, 갱신 함수 = 해시. GIN 은 이 자리에 벡터와 GINConv 를 넣어요."},{"kind":"warn","head":"코드 읽을 때 주의","items":["13번 줄 안쪽에서 변수 이름 i 를 다시 써서 바깥 i 와 겹쳐 보여요. 대괄호 안 for 변수는 밖에 영향을 주지 않아 동작은 해요.","Counter 는 이 셀보다 앞 셀에서 불러온 것을 그대로 써요."]}]},{"p":58,"title":"GIN 의 표현력: 1-WL 과 정확히 같다","terms":["Expressive power","GIN","1-WL","Message passing","Computational graph","Sum aggregation"],"pass1":[{"kind":"say","lines":["GIN 과 WL 그래프 커널이 구별하는 힘, 곧 **표현력(Expressive power)** 은 정확히 같아요.","WL 이 구별하는 그래프는 GIN 도 구별하고, GIN 이 구별하는 그래프는 WL 도 구별해요.","WL 은 실제 그래프 대부분을 구별한다고 밝혀졌어요. 그러니 GIN 도 대부분 구별해요.","이 색칠 방법을 **1-WL 테스트(1-WL)** 라고도 불러요."]},{"kind":"analogy","head":"받아쓰기 실력이 똑같은 두 친구","scene":"받아쓰기 시험에서 민호가 맞힌 문제는 지아도 다 맞히고, 지아가 맞힌 문제는 민호도 다 맞혀요. 그러면 두 사람의 받아쓰기 실력은 딱 같다고 할 수 있어요. 게다가 민호가 대부분의 문제를 맞힌다면 지아도 대부분 맞히겠죠.","map":[["민호","WL, 곧 **1-WL 테스트(1-WL)**"],["지아","GIN"],["맞힌 문제","구별해 낸 그래프 쌍"]]}],"pass2":[{"kind":"look","head":"슬라이드를 차례로 짚어 볼게요","boxes":[{"x":0.03,"y":0.16,"w":0.59,"h":0.06,"say":"GIN 과 WL 그래프 커널의 **표현력(Expressive power)** 은 정확히 같대요."},{"x":0.07,"y":0.31,"w":0.73,"h":0.06,"say":"GIN 이 구별하면 WL 도 구별하고, 그 반대도 성립해요. 방향이 두 개예요."},{"x":0.03,"y":0.47,"w":0.2,"h":0.06,"say":"얼마나 강력한가?"},{"x":0.07,"y":0.56,"w":0.84,"h":0.1,"say":"WL 커널은 실제 그래프 대부분을 구별한다고 밝혀졌대요. 인용 [Cai et al. 1992] 는 뒤에서 고쳐요."},{"x":0.07,"y":0.71,"w":0.52,"h":0.06,"say":"따라서 GIN 도 실제 그래프 대부분을 구별할 만큼 강력해요."}]},{"kind":"points","head":"'같다' 는 두 방향","items":["GIN ≤ WL: **메시지 패싱(Message passing)** GNN 은 **계산 그래프(Computational graph)** 만 봐요.","WL 이 같은 색을 준 두 노드는 계산 그래프 모양도 같아서, 어떤 메시지 패싱 GNN 도 둘을 다르게 못 봐요.","GIN ≥ WL: 합과 단사 MLP 라서 WL 이 다르다고 한 노드를 GIN 도 다르게 봐요.","평균(GCN 계열), 최댓값(GraphSAGE max-pool) 집계는 이 방향이 안 돼서 WL 보다 약해요."]},{"kind":"figure","head":"표현력 사다리","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\"><rect x=\"20\" y=\"205\" width=\"150\" height=\"38\" rx=\"8\" class=\"box b1\"/><text x=\"95\" y=\"230\" font-size=\"15\" text-anchor=\"middle\" class=\"t b1\">최댓값 집계<\/text><rect x=\"120\" y=\"155\" width=\"160\" height=\"38\" rx=\"8\" class=\"box b1\"/><text x=\"200\" y=\"180\" font-size=\"15\" text-anchor=\"middle\" class=\"t b1\">평균 집계 (GCN)<\/text><rect x=\"230\" y=\"105\" width=\"170\" height=\"38\" rx=\"8\" class=\"box2 b2\"/><text x=\"315\" y=\"130\" font-size=\"16\" text-anchor=\"middle\" class=\"tb b2\">GIN = 1-WL<\/text><line x1=\"150\" y1=\"205\" x2=\"171.6\" y2=\"197.1\" class=\"e b1\"/><polygon points=\"180,194 173.3,201.8 169.8,192.4\" class=\"arrow b1\"/><line x1=\"260\" y1=\"155\" x2=\"281.6\" y2=\"147.1\" class=\"e b2\"/><polygon points=\"290,144 283.3,151.8 279.8,142.4\" class=\"arrow b2\"/><line x1=\"10\" y1=\"92\" x2=\"470\" y2=\"92\" class=\"hl b2\"/><text x=\"460\" y=\"84\" font-size=\"14\" text-anchor=\"end\" class=\"tb b2\">메시지 패싱의 천장<\/text><rect x=\"300\" y=\"25\" width=\"170\" height=\"38\" rx=\"8\" class=\"box b3\"/><text x=\"385\" y=\"50\" font-size=\"15\" text-anchor=\"middle\" class=\"t b3\">천장 위 (p.63, p.64)<\/text><text x=\"20\" y=\"40\" font-size=\"14\" text-anchor=\"start\" class=\"tm b1\">위로 갈수록 강함<\/text><\/svg>","caption":"메시지 패싱 GNN 의 천장은 **1-WL 테스트(1-WL)** 이고, GIN 이 그 천장에 닿아요.","builds":3},{"kind":"steps","head":"평균이 약한 이유를 숫자로","steps":["봉투 {2, 3}: 합 (1, 1), 평균 (0.5, 0.5)","봉투 {2, 2}: 합 (2, 0), 평균 (1, 0)","봉투 {2}: 합 (1, 0), 평균 (1, 0)","{2} 와 {2, 2} 는 합으로는 갈리지만 평균으로는 같아요."],"answer":"평균은 '몇 명인지' 를 놓쳐요. 그래서 **합 집계(Sum aggregation)** 를 쓰는 GIN 만 WL 에 닿아요.","given":"1라운드 색을 원핫으로: 색 2 는 (1, 0), 색 3 은 (0, 1)"},{"kind":"prof","when":"3주차 화요일 수업","lines":["GNN 은 WL 과 작동 원리가 같아서 표현력 상한이 **1-WL** 이래요.","하지만 모든 과제에서 GIN 이 GCN, GraphSAGE 보다 월등하진 않대요.","GIN 은 구조 분별에 특화된 모델이니까요."]},{"kind":"mining","src":"마이닝 9강 Graph Kernels","lines":["완전 그래프 커널은 동형이 아닌 그래프에 반드시 다른 특징을 주는 커널이에요.","그걸 계산하는 건 동형 판정만큼 어렵고, 동형 문제는 다항 시간 알고리즘이 알려져 있지 않다고 배웠어요.","그러니 빠른 WL 이 전부를 구별하긴 어려워요. '대부분' 이 자연스러운 결론이에요."]}],"pass3":[{"kind":"exam","src":"GNN 2024 가을 기말 5번 (b)","q":"What are the reasons why the GIN model achieves 1-d Weisfeiler-Lehman?","qko":"GIN 모델이 1차원 WL 테스트 수준에 도달하는 이유는 무엇인가?","solve":["GIN 은 이웃 특징을 합(sum)으로 모아요.","평균, 최댓값 풀링과 달리 합은 멀티셋에서 단사예요.","합 뒤에 단사 MLP 를 붙여 서로 다른 입력을 서로 다른 임베딩으로 보내요.","WL 의 단사 HASH 와 같은 일을 하므로 1-WL 만큼 구별해요."],"answer":"GIN uses sum aggregation, which is injective on multi-sets, combined with an injective MLP, so GIN is as powerful as the 1-WL test."},{"kind":"english","head":"천장 문장","en":"No message passing GNN can exceed 1-WL, so GIN is the most expressive message passing GNN.","ko":"어떤 메시지 패싱 GNN 도 1-WL 을 넘을 수 없으므로, GIN 이 가장 표현력이 높은 메시지 패싱 GNN 이다."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["인용 [Cai et al. 1992] 는 어긋나요. 그 논문은 WL 계열이 구별 못 하는 쌍을 만든 것으로 유명해요. '거의 모든 그래프 구별' 은 Babai, Erdős, Selkow(1980) 쪽이 정확해요.","'구별할 수 있다' 와 '과제를 잘 푼다' 는 달라요. 데이터가 적으면 성능은 낮을 수 있어요.","GIN = WL 은 MLP 가 단사 함수를 제대로 배운 이상적인 경우의 이야기예요."]},{"kind":"check","q":"메시지 패싱 GNN 의 **표현력(Expressive power)** 천장은?","choices":["평균 집계","1-WL","모든 k-WL","완전 그래프 커널"],"a":1,"why":"메시지 패싱은 계산 그래프만 봐서 1-WL 을 넘지 못하고, GIN 이 그 천장에 닿아요."}],"pass4":[{"kind":"pyterm","name":"재귀(recursion)","say":["함수가 자기 자신을 다시 부르는 방식이에요.","트리처럼 안에 같은 모양이 반복될 때 써요."],"example":"def depth(n):\n    return 0 if n == 0 else 1 + depth(n - 1)\nprint(depth(3))","out":"3"},{"kind":"code","head":"계산 그래프 모양이 정말 같은지 확인","file":"Sample_Code_3_번역.ipynb 셀 15","code":"fig, axes = plt.subplots(2, 2, figsize=(14, 7), gridspec_kw={'width_ratios': [1, 2.4]})\nfor row, (name, G, pos) in enumerate([('$C_6$', C6, POS_C6), ('$2 \\\\times C_3$', TwoC3, POS_2C3)]):\n    draw_graph(G, pos, axes[row, 0], highlight=0, title=f'{name}  (node 0 outlined)')\n    draw_tree(unfolding_tree(G, 0, 3), axes[row, 1], uniform=True, node_size=330, font_size=7,\n              title=f'Computational graph of node 0 in {name}, 3 layers')\nfig.suptitle('Identical computational graphs → identical embeddings', fontsize=13, fontweight='bold')\nplt.tight_layout(); plt.show()\n\n\ndef tree_shape(T, n):\n    \"\"\"Canonical form of the subtree at n, ignoring which graph node each copy is.\"\"\"\n    return tuple(sorted(tree_shape(T, k) for k in T.predecessors(n)))\n\nsame = all(tree_shape(unfolding_tree(C6, u, L), (u,)) == tree_shape(unfolding_tree(TwoC3, v, L), (v,))\n           for L in range(1, 5) for u in C6 for v in TwoC3)\nprint(f'All 6 x 6 node pairs (C6 node, 2xC3 node) have identical trees for L = 1..4: {same}')","lines":[{"from":1,"to":7,"say":"C6 와 TwoC3 에서 노드 0 을 표시하고, 각각의 3층 계산 그래프를 모양만(회색) 그려 나란히 보여 줘요."},{"from":10,"to":12,"say":"트리 모양만 남기는 재귀 함수예요. 자식 모양들을 정렬해 튜플로 묶어서, 노드 번호와 상관없이 모양이 같으면 같은 값이 돼요."},{"from":14,"to":15,"say":"all(...) 은 안의 비교가 전부 참인지 봐요. 층 1~4, C6 노드 6개, 2xC3 노드 6개의 모든 조합이에요."},{"from":16,"to":16,"say":"출력은 True. 모든 쌍의 **계산 그래프(Computational graph)** 가 똑같아요."}],"link":"셀 13 핵심 보조정리: 계산 그래프가 같으면 모든 GNN 이 같은 임베딩을 줘요. 이게 GIN ≤ WL 방향이에요."}]},{"p":59,"title":"1-WL 이 실패하는 곳","terms":["1-WL","Cycle","Clique","Stable coloring","Computational graph"],"pass1":[{"kind":"say","lines":["사람 눈에는 분명히 다른데, **1-WL 테스트(1-WL)** 가 끝까지 구별하지 못하는 두 그래프가 있어요.","왼쪽은 오각형 두 개를 선 하나로 이은 그래프, 오른쪽은 육각형 두 개가 변 하나를 함께 쓰는 그래프예요.","1-WL 은 한 바퀴 돌아오는 고리인 **사이클(Cycle)** 이 몇 개인지 세지 못해요.","모두가 서로 이어진 무리인 **클리크(Clique)** 가 몇 개인지도 세지 못해요."]},{"kind":"look","head":"두 그래프","boxes":[{"x":0.1,"y":0.25,"w":0.35,"h":0.29,"say":"왼쪽: 오각형 두 개가 가운데 선 하나로 이어져 있어요."},{"x":0.56,"y":0.25,"w":0.3,"h":0.29,"say":"오른쪽: 육각형 두 개가 가운데 변 하나를 함께 써요."}]},{"kind":"analogy","head":"눈 감고 옆 사람만 세기","scene":"안대를 한 친구가 둥글게 앉은 모둠에 가서 '지금 네 옆에 몇 명 있어?' 만 물어볼 수 있어요. 다섯 명이 둘러앉은 모둠이든 여섯 명이 둘러앉은 모둠이든, 누구에게 물어도 '양옆에 2명' 이라는 대답만 돌아와요. 그래서 이 친구는 둘레에 몇 명이 앉았는지 알아낼 수 없어요.","map":[["옆에 몇 명인지만 묻기","1-WL 이 모으는 정보"],["둘레에 앉은 사람 수","**사이클(Cycle)** 의 길이"]]}],"pass2":[{"kind":"look","head":"슬라이드를 차례로 짚어 볼게요","boxes":[{"x":0.03,"y":0.16,"w":0.5,"h":0.06,"say":"WL 커널은 몇몇 기본 그래프 구조를 구별하지 못한대요. 예를 봐요."},{"x":0.1,"y":0.25,"w":0.35,"h":0.29,"say":"왼쪽: 오각형 두 개가 E-F 엣지 하나로 이어져요. 엣지 5+5+1 = 11 개."},{"x":0.56,"y":0.25,"w":0.3,"h":0.29,"say":"오른쪽: 육각형 두 개가 E-F 변을 함께 써요. 엣지 6+6-1 = 11 개."},{"x":0.03,"y":0.6,"w":0.61,"h":0.06,"say":"WL 커널은 **사이클(Cycle)**, **클리크(Clique)** 같은 부분 구조의 개수를 세지 못해요."}]},{"kind":"points","head":"용어와 기본 정보","items":["**사이클(Cycle)**: 같은 엣지를 두 번 쓰지 않고 한 바퀴 돌아오는 길. 왼쪽은 길이 5 가 2개, 오른쪽은 길이 6 이 2개.","**클리크(Clique)**: 무리 안 모든 두 노드가 연결된 무리. 3개짜리가 삼각형이에요.","두 그래프 모두 E, F 만 친구 3명이고 나머지 8명은 친구 2명이에요."]},{"kind":"steps","head":"두 그래프에 1-WL 을 돌려요","steps":["0라운드: 모두 색 1. 둘 다 {1: 10}","1라운드: E, F 는 1,{1,1,1} 이라 3, 나머지는 2. 둘 다 {2: 8, 3: 2}","2라운드: 갈림길 E, F 는 3,{2,2,3} 이라 4","갈림길 옆 C, D, G, H 는 2,{2,3} 이라 5. 먼 쪽 A, B, I, J 는 2,{2,2} 라 6","3라운드: 조합이 여전히 세 가지뿐이라 무리가 더 쪼개지지 않아요."],"answer":"둘 다 {4: 2, 5: 4, 6: 4} 에서 **안정된 색칠(Stable coloring)**. 1-WL 은 끝내 구별 못 해요."},{"kind":"figure","head":"안정된 색이 완전히 같아요","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\"><text x=\"122\" y=\"24\" font-size=\"15\" text-anchor=\"middle\" class=\"tb\">오각형 두 개<\/text><text x=\"342\" y=\"24\" font-size=\"15\" text-anchor=\"middle\" class=\"tb\">육각형 두 개<\/text><line x1=\"25\" y1=\"90\" x2=\"70\" y2=\"55\" class=\"e\"/><line x1=\"70\" y1=\"55\" x2=\"105\" y2=\"120\" class=\"e\"/><line x1=\"105\" y1=\"120\" x2=\"70\" y2=\"185\" class=\"e\"/><line x1=\"70\" y1=\"185\" x2=\"25\" y2=\"150\" class=\"e\"/><line x1=\"25\" y1=\"150\" x2=\"25\" y2=\"90\" class=\"e\"/><line x1=\"105\" y1=\"120\" x2=\"140\" y2=\"120\" class=\"e\"/><line x1=\"140\" y1=\"120\" x2=\"175\" y2=\"55\" class=\"e\"/><line x1=\"175\" y1=\"55\" x2=\"220\" y2=\"90\" class=\"e\"/><line x1=\"220\" y1=\"90\" x2=\"220\" y2=\"150\" class=\"e\"/><line x1=\"220\" y1=\"150\" x2=\"175\" y2=\"185\" class=\"e\"/><line x1=\"175\" y1=\"185\" x2=\"140\" y2=\"120\" class=\"e\"/><circle cx=\"25\" cy=\"90\" r=\"14\" class=\"n3\"/><text x=\"25\" y=\"95\" font-size=\"14\" text-anchor=\"middle\" class=\"tl\">A<\/text><circle cx=\"70\" cy=\"55\" r=\"14\" class=\"n\"/><text x=\"70\" y=\"60\" font-size=\"14\" text-anchor=\"middle\" class=\"tl\">C<\/text><circle cx=\"105\" cy=\"120\" r=\"14\" class=\"n2\"/><text x=\"105\" y=\"125\" font-size=\"14\" text-anchor=\"middle\" class=\"tl\">E<\/text><circle cx=\"70\" cy=\"185\" r=\"14\" class=\"n\"/><text x=\"70\" y=\"190\" font-size=\"14\" text-anchor=\"middle\" class=\"tl\">D<\/text><circle cx=\"25\" cy=\"150\" r=\"14\" class=\"n3\"/><text x=\"25\" y=\"155\" font-size=\"14\" text-anchor=\"middle\" class=\"tl\">B<\/text><circle cx=\"140\" cy=\"120\" r=\"14\" class=\"n2\"/><text x=\"140\" y=\"125\" font-size=\"14\" text-anchor=\"middle\" class=\"tl\">F<\/text><circle cx=\"175\" cy=\"55\" r=\"14\" class=\"n\"/><text x=\"175\" y=\"60\" font-size=\"14\" text-anchor=\"middle\" class=\"tl\">G<\/text><circle cx=\"220\" cy=\"90\" r=\"14\" class=\"n3\"/><text x=\"220\" y=\"95\" font-size=\"14\" text-anchor=\"middle\" class=\"tl\">I<\/text><circle cx=\"220\" cy=\"150\" r=\"14\" class=\"n3\"/><text x=\"220\" y=\"155\" font-size=\"14\" text-anchor=\"middle\" class=\"tl\">J<\/text><circle cx=\"175\" cy=\"185\" r=\"14\" class=\"n\"/><text x=\"175\" y=\"190\" font-size=\"14\" text-anchor=\"middle\" class=\"tl\">H<\/text><line x1=\"262\" y1=\"90\" x2=\"302\" y2=\"58\" class=\"e\"/><line x1=\"302\" y1=\"58\" x2=\"342\" y2=\"90\" class=\"e\"/><line x1=\"342\" y1=\"90\" x2=\"342\" y2=\"150\" class=\"e\"/><line x1=\"342\" y1=\"150\" x2=\"302\" y2=\"182\" class=\"e\"/><line x1=\"302\" y1=\"182\" x2=\"262\" y2=\"150\" class=\"e\"/><line x1=\"262\" y1=\"150\" x2=\"262\" y2=\"90\" class=\"e\"/><line x1=\"342\" y1=\"90\" x2=\"382\" y2=\"58\" class=\"e\"/><line x1=\"382\" y1=\"58\" x2=\"422\" y2=\"90\" class=\"e\"/><line x1=\"422\" y1=\"90\" x2=\"422\" y2=\"150\" class=\"e\"/><line x1=\"422\" y1=\"150\" x2=\"382\" y2=\"182\" class=\"e\"/><line x1=\"382\" y1=\"182\" x2=\"342\" y2=\"150\" class=\"e\"/><circle cx=\"262\" cy=\"90\" r=\"14\" class=\"n3\"/><text x=\"262\" y=\"95\" font-size=\"14\" text-anchor=\"middle\" class=\"tl\">A<\/text><circle cx=\"302\" cy=\"58\" r=\"14\" class=\"n\"/><text x=\"302\" y=\"63\" font-size=\"14\" text-anchor=\"middle\" class=\"tl\">C<\/text><circle cx=\"342\" cy=\"90\" r=\"14\" class=\"n2\"/><text x=\"342\" y=\"95\" font-size=\"14\" text-anchor=\"middle\" class=\"tl\">E<\/text><circle cx=\"342\" cy=\"150\" r=\"14\" class=\"n2\"/><text x=\"342\" y=\"155\" font-size=\"14\" text-anchor=\"middle\" class=\"tl\">F<\/text><circle cx=\"302\" cy=\"182\" r=\"14\" class=\"n\"/><text x=\"302\" y=\"187\" font-size=\"14\" text-anchor=\"middle\" class=\"tl\">D<\/text><circle cx=\"262\" cy=\"150\" r=\"14\" class=\"n3\"/><text x=\"262\" y=\"155\" font-size=\"14\" text-anchor=\"middle\" class=\"tl\">B<\/text><circle cx=\"382\" cy=\"58\" r=\"14\" class=\"n\"/><text x=\"382\" y=\"63\" font-size=\"14\" text-anchor=\"middle\" class=\"tl\">G<\/text><circle cx=\"422\" cy=\"90\" r=\"14\" class=\"n3\"/><text x=\"422\" y=\"95\" font-size=\"14\" text-anchor=\"middle\" class=\"tl\">I<\/text><circle cx=\"422\" cy=\"150\" r=\"14\" class=\"n3\"/><text x=\"422\" y=\"155\" font-size=\"14\" text-anchor=\"middle\" class=\"tl\">J<\/text><circle cx=\"382\" cy=\"182\" r=\"14\" class=\"n\"/><text x=\"382\" y=\"187\" font-size=\"14\" text-anchor=\"middle\" class=\"tl\">H<\/text><text x=\"240\" y=\"228\" font-size=\"15\" text-anchor=\"middle\" class=\"t b1\">색 4 갈림길 2개, 색 5 옆 4개, 색 6 먼 쪽 4개<\/text><text x=\"240\" y=\"256\" font-size=\"15\" text-anchor=\"middle\" class=\"tb b2\">두 그래프 모두 {4:2, 5:4, 6:4} 에서 멈춤<\/text><\/svg>","caption":"고리 크기 5 와 6 은 색에 드러나지 않아요.","builds":2},{"kind":"points","head":"사람 눈으로는 쉽게 달라요","items":["왼쪽은 E-F 엣지를 끊으면 두 조각으로 나뉘지만, 오른쪽은 안 나뉘어요.","1-WL 쪽지에는 '몇 걸음 만에 제자리로 오는지' 가 적히지 않아요.","대응하는 노드의 **계산 그래프(Computational graph)** 가 모든 깊이에서 같아서 GIN 도 같은 답을 내요."]},{"kind":"prof","when":"3주차 화요일 수업","lines":["GNN 이 못 가르는 대표 구조는 **사이클(Cycle)** 이 있는 구조래요.","사이클이나 **클리크(Clique)** 가 있으면 두 그래프가 다르다는 것조차 못 가려요.","이게 큰 문제가 되는 분야가 있다고 했어요."]},{"kind":"mining","src":"마이닝 7강 Subgraph Mining","lines":["부분그래프를 '네트워크의 레고 블록' 이라고 불렀어요.","부분그래프는 네트워크를 특징짓고 서로 구별하는 힘을 가진다고 배웠죠.","이 쌍은 오각형 블록 2개와 육각형 블록 2개로 블록이 다른데도 같은 색을 받았어요."]}],"pass3":[{"kind":"english","head":"WL 벡터가 같을 때 안전한 문장","en":"The WL feature vectors are identical, so the WL kernel cannot distinguish the two graphs; this does not guarantee that they are isomorphic.","ko":"WL 특징 벡터가 같으므로 WL 커널은 두 그래프를 구별하지 못한다. 이것이 동형임을 보장하지는 않는다.","tip":"마이닝 2024 봄 중간 11번처럼 유사도 1 이 나와도 '동형이다' 라고 쓰면 안 돼요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["영어 슬라이드 제목은 'regular graphs' 인데 이 그림은 정규 그래프가 아니에요. E, F 만 차수 3 이에요.","이 두 그림은 p.60 '분자 쌍둥이' 카드의 탄소 뼈대예요. 왼쪽 바이사이클로펜틸, 오른쪽 데칼린.","1-WL 이 못 가른다는 건 '같다' 가 아니라 '판정을 못 한다' 예요."]},{"kind":"check","q":"**클리크(Clique)** 의 뜻은?","choices":["무리 안 모든 두 노드가 서로 연결된 무리","한 바퀴 돌아오는 길","친구가 가장 많은 노드"],"a":0,"why":"3개짜리 클리크가 삼각형이에요. 한 바퀴 돌아오는 길은 사이클이에요."}],"pass4":[{"kind":"say","lines":["셀 39 설명: 색 정제는 색 무리를 쪼개기만 하고 합치지 않아요.","그래서 많아야 n-1 라운드면 안정되고, 그 뒤로 GNN 층을 더 쌓아도 새로 구별되는 게 없어요."]},{"kind":"code","head":"가라테 클럽에서 구별 안 되는 노드 찾기 (1)","file":"Sample_Code_3_번역.ipynb 셀 41","code":"KC = nx.karate_club_graph()\nexamples = {'Path $P_7$': nx.path_graph(7), 'Ternary tree': nx.balanced_tree(3, 2),\n            '$C_6$': C6, 'Karate club': KC}\n\nfig, (ax1, ax2) = plt.subplots(1, 2, figsize=(15, 5), gridspec_kw={'width_ratios': [1, 1.3]})\nfor name, G in examples.items():\n    counts = [len(set(r['colors'][0].values())) for r in wl_refine([G], 8)]\n    ax1.plot(counts, marker='o', lw=2, label=f'{name} (n={G.number_of_nodes()})')\nax1.set(xlabel='round $\\\\ell$', ylabel='number of distinct colors',\n        title='Number of colors per round')\nax1.grid(alpha=0.3); ax1.legend(fontsize=9)\n\n# 표시용 재색칠: 노드가 2개 이상인 클래스에는 색 1, 2, ... 를 주고, 유일한 노드는 0(회색)\nfinal = wl_refine([KC], 3)[-1]['colors'][0]\nsizes = Counter(final.values())\nshared = {c: i for i, c in enumerate(sorted(c for c in sizes if sizes[c] > 1), start=1)}\ndraw_graph(KC, nx.spring_layout(KC, seed=42, k=0.5), ax2,\n           colors={v: shared.get(c, 0) for v, c in final.items()}, node_size=260, font_size=7,\n           title=f'Karate club after 3 rounds: {len(sizes)} classes for {KC.number_of_nodes()} nodes')\nplt.tight_layout(); plt.show()\n\nfor c in shared:\n    vs = [v for v in KC if final[v] == c]\n    print(f'indistinguishable: nodes {vs}  (degrees {[KC.degree(v) for v in vs]})')","lines":[{"from":1,"to":4,"say":"가라테 동아리 친구 관계 그래프 KC 와 예시 그래프 네 개를 사전 examples 에 담아요."},{"from":5,"to":12,"say":"그래프마다 색 정제를 8 라운드 돌려 라운드별 서로 다른 색 수를 세고, 꺾은선 그래프로 그려요."},{"from":13,"to":13,"say":"KC 에 3 라운드를 돌린 최종 색에서 노드가 2개 이상인 색만 골라 다시 칠해 그려요."},{"from":14,"to":14,"say":"가라테 클럽 그래프 KC 에 3라운드 색 정제를 해요. [-1] 은 마지막 라운드, ['colors'][0] 은 첫 그래프의 색 사전이에요."},{"from":15,"to":15,"say":"색마다 노드가 몇 개인지 세요."},{"from":16,"to":16,"say":"노드가 2개 이상인 색에만 표시 번호 1, 2, ... 를 새로 붙여요."},{"from":17,"to":20,"say":"KC 에 3 라운드를 돌린 최종 색에서 노드가 2개 이상인 색만 골라 다시 칠해 그려요."},{"from":21,"to":24,"say":"끝까지 같은 색이라 구별되지 않은 노드 무리와 그 차수를 출력해요."}],"link":"같은 색 = 1-WL 에게, 곧 모든 메시지 패싱 GNN 에게 구조적으로 구별 불가"},{"kind":"code","head":"가라테 클럽에서 구별 안 되는 노드 찾기 (2)","file":"Sample_Code_3_번역.ipynb 셀 41","code":"KC = nx.karate_club_graph()\nexamples = {'Path $P_7$': nx.path_graph(7), 'Ternary tree': nx.balanced_tree(3, 2),\n            '$C_6$': C6, 'Karate club': KC}\n\nfig, (ax1, ax2) = plt.subplots(1, 2, figsize=(15, 5), gridspec_kw={'width_ratios': [1, 1.3]})\nfor name, G in examples.items():\n    counts = [len(set(r['colors'][0].values())) for r in wl_refine([G], 8)]\n    ax1.plot(counts, marker='o', lw=2, label=f'{name} (n={G.number_of_nodes()})')\nax1.set(xlabel='round $\\\\ell$', ylabel='number of distinct colors',\n        title='Number of colors per round')\nax1.grid(alpha=0.3); ax1.legend(fontsize=9)\n\n# 표시용 재색칠: 노드가 2개 이상인 클래스에는 색 1, 2, ... 를 주고, 유일한 노드는 0(회색)\nfinal = wl_refine([KC], 3)[-1]['colors'][0]\nsizes = Counter(final.values())\nshared = {c: i for i, c in enumerate(sorted(c for c in sizes if sizes[c] > 1), start=1)}\ndraw_graph(KC, nx.spring_layout(KC, seed=42, k=0.5), ax2,\n           colors={v: shared.get(c, 0) for v, c in final.items()}, node_size=260, font_size=7,\n           title=f'Karate club after 3 rounds: {len(sizes)} classes for {KC.number_of_nodes()} nodes')\nplt.tight_layout(); plt.show()\n\nfor c in shared:\n    vs = [v for v in KC if final[v] == c]\n    print(f'indistinguishable: nodes {vs}  (degrees {[KC.degree(v) for v in vs]})')","lines":[{"from":1,"to":4,"say":"가라테 동아리 친구 관계 그래프 KC 와 예시 그래프 네 개를 사전 examples 에 담아요."},{"from":5,"to":12,"say":"그래프마다 색 정제를 8 라운드 돌려 라운드별 서로 다른 색 수를 세고, 꺾은선 그래프로 그려요."},{"from":13,"to":20,"say":"KC 에 3 라운드를 돌린 최종 색에서 노드가 2개 이상인 색만 골라 다시 칠해 그려요."},{"from":22,"to":23,"say":"표시 번호가 붙은 색마다 그 색을 가진 노드 목록 vs 를 모아요."},{"from":24,"to":24,"say":"노드와 차수를 출력해요. 셀 40 설명 예: 노드 14, 15, 18, 20, 22 는 모두 차수 2 이고 서로 구별 불가."}]}]},{"p":60,"title":"1-WL 이 실패하는 곳: 정규 그래프","terms":["Regular graph","1-WL","Clustering coefficient","Cycle","GIN","Message passing"],"pass1":[{"kind":"say","lines":["모든 노드의 친구 수가 똑같은 그래프를 **정규 그래프(Regular graph)** 라고 해요.","이런 그래프에서 **1-WL 테스트(1-WL)** 는 아무것도 알아내지 못해요. 모든 노드가 처음부터 끝까지 같은 색이거든요.","예를 들어 떨어진 삼각형 두 개와 육각형 하나는 모양이 분명 다른데, 1-WL 에게는 똑같아 보여요."]},{"kind":"figure","head":"삼각형 두 개 대 육각형 하나","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\"><text x=\"110\" y=\"24\" font-size=\"16\" text-anchor=\"middle\" class=\"tb\">삼각형 두 개<\/text><text x=\"370\" y=\"24\" font-size=\"16\" text-anchor=\"middle\" class=\"tb\">육각형 하나<\/text><line x1=\"40\" y1=\"55\" x2=\"100\" y2=\"55\" class=\"e\"/><line x1=\"100\" y1=\"55\" x2=\"70\" y2=\"105\" class=\"e\"/><line x1=\"70\" y1=\"105\" x2=\"40\" y2=\"55\" class=\"e\"/><line x1=\"125\" y1=\"55\" x2=\"185\" y2=\"55\" class=\"e\"/><line x1=\"185\" y1=\"55\" x2=\"155\" y2=\"105\" class=\"e\"/><line x1=\"155\" y1=\"105\" x2=\"125\" y2=\"55\" class=\"e\"/><line x1=\"370\" y1=\"30\" x2=\"322.4\" y2=\"55\" class=\"e\"/><line x1=\"322.4\" y1=\"55\" x2=\"322.4\" y2=\"105\" class=\"e\"/><line x1=\"322.4\" y1=\"105\" x2=\"370\" y2=\"130\" class=\"e\"/><line x1=\"370\" y1=\"130\" x2=\"417.6\" y2=\"105\" class=\"e\"/><line x1=\"417.6\" y1=\"105\" x2=\"417.6\" y2=\"55\" class=\"e\"/><line x1=\"417.6\" y1=\"55\" x2=\"370\" y2=\"30\" class=\"e\"/><circle cx=\"40\" cy=\"55\" r=\"13\" class=\"n\"/><circle cx=\"100\" cy=\"55\" r=\"13\" class=\"n\"/><circle cx=\"70\" cy=\"105\" r=\"13\" class=\"n\"/><circle cx=\"125\" cy=\"55\" r=\"13\" class=\"n\"/><circle cx=\"185\" cy=\"55\" r=\"13\" class=\"n\"/><circle cx=\"155\" cy=\"105\" r=\"13\" class=\"n\"/><circle cx=\"370\" cy=\"30\" r=\"13\" class=\"n\"/><circle cx=\"322.4\" cy=\"55\" r=\"13\" class=\"n\"/><circle cx=\"322.4\" cy=\"105\" r=\"13\" class=\"n\"/><circle cx=\"370\" cy=\"130\" r=\"13\" class=\"n\"/><circle cx=\"417.6\" cy=\"105\" r=\"13\" class=\"n\"/><circle cx=\"417.6\" cy=\"55\" r=\"13\" class=\"n\"/><text x=\"110\" y=\"145\" font-size=\"15\" text-anchor=\"middle\" class=\"t\">친구끼리도 친구<\/text><text x=\"370\" y=\"160\" font-size=\"15\" text-anchor=\"middle\" class=\"t\">친구끼리는 모르는 사이<\/text><rect x=\"30\" y=\"175\" width=\"420\" height=\"85\" rx=\"10\" class=\"box b1\"/><text x=\"240\" y=\"200\" font-size=\"15\" text-anchor=\"middle\" class=\"t b1\">모든 점이 친구 2명, 친구의 친구도 2명씩<\/text><text x=\"240\" y=\"225\" font-size=\"15\" text-anchor=\"middle\" class=\"t b2\">그래서 몇 번을 다시 칠해도 모두 같은 색이에요<\/text><text x=\"240\" y=\"250\" font-size=\"15\" text-anchor=\"middle\" class=\"tb b2\">1-WL 테스트는 두 그래프를 구별하지 못해요<\/text><\/svg>","caption":"모든 라운드에서 모든 노드가 한 가지 색이에요. 친구끼리 서로 아는지는 색에 드러나지 않아요.","builds":2}],"pass2":[{"kind":"look","head":"슬라이드를 차례로 짚어 볼게요","boxes":[{"x":0.05,"y":0.17,"w":0.44,"h":0.45,"say":"G = 2×C3 는 떨어진 삼각형 두 개, H = C6 는 육각형 하나예요."},{"x":0.05,"y":0.63,"w":0.44,"h":0.22,"say":"둘 다 노드 6개의 2-정규. 모든 노드, 모든 라운드 색이 하나라서 1-WL 은 판정 불가."},{"x":0.51,"y":0.17,"w":0.44,"h":0.16,"say":"카드 1: 어떤 d-정규 그래프도 구별 불가. 가장 작은 비동형 쌍이 노드 6개에서 나와요."},{"x":0.51,"y":0.35,"w":0.44,"h":0.16,"say":"카드 2: 삼각형을 세지 못함. G 의 **클러스터링 계수(Clustering coefficient)** 는 1, H 는 0."},{"x":0.51,"y":0.52,"w":0.44,"h":0.16,"say":"카드 3: 분자 쌍둥이. 데칼린과 바이사이클로펜틸은 둘 다 C10H18 인데 1-WL 색칠이 같아요."},{"x":0.51,"y":0.7,"w":0.44,"h":0.16,"say":"카드 4: CSL 그래프. 4-정규 벤치마크라 1-WL 모델은 찍기 수준 점수예요."}]},{"kind":"formula","head":"왼쪽 아래 상자의 식","tex":"c_v^{(t)} = \\gamma_t \\quad \\forall v,\\ \\forall t","parts":[{"sym":"\\mathrm{C}_n","say":"노드 n 개짜리 **사이클(Cycle)**. C3 는 삼각형, C6 는 육각형"},{"sym":"c_v^{(t)}","say":"라운드 t 에서 노드 v 의 색. p.53 의 c(k)(v) 와 같은 것"},{"sym":"\\gamma_t","say":"라운드 t 에 모두가 똑같이 받는 단 하나의 색"},{"sym":"\\forall t","say":"모든 라운드 t 에 대해"}],"whole":"두 그래프 어느 노드든, 어느 라운드든 색은 그 라운드의 공통 색 하나뿐이에요."},{"kind":"steps","head":"1-WL 과 GIN 으로 직접 확인","steps":["0라운드: 모두 1. {1: 6} = {1: 6}","1라운드: 모든 노드 1,{1,1} 이라 2. {2: 6} = {2: 6}","2라운드: 모든 노드 2,{2,2} 라 3. HASH 표에 조합이 한 줄뿐","GIN (초기값 1, ε = 0, MLP 통과): 1층 1+1+1 = 3, 2층 3+3+3 = 9","그래프 전체를 합으로 요약해도 6×9 = 54 로 같아요."],"answer":"1-WL 도 GIN 도 두 그래프를 영원히 같게 봐요."},{"kind":"steps","head":"**클러스터링 계수(Clustering coefficient)** 로 차이 보기","steps":["계수 = 내 친구 쌍 중 서로도 친구인 쌍의 비율","2×C3 노드: 친구 둘이 서로 친구. 1/1 = 1","C6 노드: 양옆 친구끼리는 안 이어짐. 0/1 = 0"],"answer":"사람에게는 1 대 0 으로 확연히 다른데, 1-WL 은 같은 색만 봐요."},{"kind":"points","head":"왜 노드 6개가 가장 작은 쌍일까","items":["2-정규는 노드 3, 4, 5 개면 삼각형, 사각형, 오각형 하나뿐이라 헷갈릴 쌍이 없어요.","노드 6개가 되면 C6 와 2×C3 두 가지가 생겨요.","3-정규도 노드 6개에서 삼각기둥 모양과 K3,3(노드를 세 개씩 두 편으로 나눠 편 사이만 모두 이은 그래프)이 1-WL 로 안 갈려요. 앞은 삼각형이 있고 뒤는 없어요."]},{"kind":"prof","when":"3주차 화요일 수업","lines":["초기 특징이 같으면 사이클 위 어느 노드 입장에서도 이웃 구성이 같아요.","그래서 구별이 안 된다고 했어요. 모두 이웃이 둘인 2-정규 그래프가 그 경우예요."]}],"pass3":[{"kind":"exam","src":"그래프 마이닝 2026 봄 기말 3번 (b) (5점)","q":"Provide an example of a simple graph structure that the 1-WL test is provably incapable of detecting or counting.","qko":"1-WL 테스트가 탐지하거나 셀 수 없음이 증명된 간단한 그래프 구조의 예를 들라.","solve":["대표 예: 삼각형(길이 3 사이클)","구체적 쌍: 육각형 하나 C6 대 떨어진 삼각형 두 개 2×C3","둘 다 2-정규라서 매 라운드 모든 노드가 같은 색을 받아요.","히스토그램이 늘 같아 구별 못 해요. 한쪽은 삼각형 2개, 다른 쪽은 0개인데도요."],"answer":"A triangle. 1-WL cannot distinguish a single hexagon C6 from two disconnected triangles 2 × C3."},{"kind":"english","head":"정규 그래프 실패 문장","en":"1-WL cannot distinguish a 6-cycle from two disjoint triangles. Both graphs are 2-regular, so every node receives the same color in every round.","ko":"1-WL 은 육각형과 떨어진 삼각형 두 개를 구별하지 못한다. 둘 다 2-정규라서 매 라운드 모든 노드가 같은 색을 받는다."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["구별 불가는 **같은 노드 수**의 d-정규 그래프끼리 이야기예요. 노드 수가 다르면 합이 달라 바로 갈려요.","슬라이드 둘째 카드는 앞 글자 G 가 빠져 '의 클러스터링 계수는 1' 로 시작해요.","CSL 카드의 '찍기 수준' 은 우연히 맞히는 정도(종류 수에 반비례)의 정확도라는 뜻이에요."]},{"kind":"check","q":"C6 와 2×C3 에 1라운드를 돌리면 색은 몇 종류일까요?","choices":["1 종류","2 종류","6 종류"],"a":0,"why":"모든 노드가 1,{1,1} 로 같은 조합이라 새 색도 하나뿐이에요."},{"kind":"check","q":"**정규 그래프(Regular graph)** 란?","choices":["모든 노드의 차수가 같은 그래프","사이클이 없는 그래프","엣지가 규칙적으로 늘어나는 그래프"],"a":0,"why":"모두 차수 d 면 d-정규예요. 삼각형과 육각형 노드는 모두 친구 2명이라 2-정규예요."}],"pass4":[{"kind":"code","head":"두 실패 그래프 만들고 기본 통계 비교","file":"Sample_Code_3_번역.ipynb 셀 9","code":"C6    = nx.cycle_graph(6)\nTwoC3 = nx.disjoint_union(nx.cycle_graph(3), nx.cycle_graph(3))\n\nfor name, G in [('C6', C6), ('2 x C3', TwoC3)]:\n    print(f'{name:7s} | nodes {G.number_of_nodes()} | edges {G.number_of_edges()} '\n          f'| components {nx.number_connected_components(G)} '\n          f'| degrees {sorted(d for _, d in G.degree())} '\n          f'| triangles {sum(nx.triangles(G).values()) // 3}')\nprint(f'Isomorphic? {nx.is_isomorphic(C6, TwoC3)}')\n\n# 뒤의 그림들에서 재사용할 고정 좌표: 육각형 하나, 그리고 나란히 놓인 삼각형 두 개\nPOS_C6  = nx.circular_layout(C6)\nPOS_2C3 = {}\nfor nodes, cx, start in [([0, 1, 2], -1.0, np.pi), ([3, 4, 5], 1.0, 0.0)]:\n    for i, n in enumerate(nodes):\n        a = start + 2 * np.pi * i / 3\n        POS_2C3[n] = np.array([cx + 0.55 * np.cos(a), 0.55 * np.sin(a)])\n\nfig, axes = plt.subplots(1, 2, figsize=(10, 3.8))\ndraw_graph(C6, POS_C6, axes[0], title='$C_6$  (one 6-cycle)')\ndraw_graph(TwoC3, POS_2C3, axes[1], title='$2 \\\\times C_3$  (two triangles)')\nfig.suptitle('Two non-isomorphic graphs - every node has degree 2', fontsize=13, fontweight='bold')\nplt.tight_layout(); plt.show()","lines":[{"from":1,"to":1,"say":"cycle_graph(6) 은 노드 6개가 고리로 이어진 그래프, 곧 육각형이에요."},{"from":2,"to":2,"say":"삼각형 두 개를 노드 번호가 안 겹치게 이어 붙여 한 그래프로 만들어요."},{"from":4,"to":4,"say":"(이름, 그래프) 쌍 두 개짜리 리스트를 차례로 돌아요."},{"from":5,"to":8,"say":"노드 수, 엣지 수, 연결 성분 수, 차수 목록, 삼각형 수를 출력해요. 삼각형 수는 합을 3 으로 나눠요(// 는 정수 나눗셈)."},{"from":9,"to":9,"say":"is_isomorphic 는 정확한 동형 판정이에요. 결과는 False."},{"from":10,"to":17,"say":"뒤 그림에서 계속 쓸 좌표를 정해요. 육각형은 원 모양으로, 삼각형 두 개는 왼쪽과 오른쪽에 나란히 놓아요."},{"from":18,"to":23,"say":"그림판 두 칸을 만들어 두 그래프를 나란히 그리고 화면에 보여 줘요."}],"link":"차수 목록은 둘 다 2 여섯 개인데 삼각형 수는 다르죠. 슬라이드 '삼각형을 세지 못함' 카드와 짝이에요."},{"kind":"code","head":"C6 대 2×C3 에 색 정제 4라운드","file":"Sample_Code_3_번역.ipynb 셀 35","code":"CYCLES = dict(graphs=[C6, TwoC3], names=['$C_6$', '$2 \\\\times C_3$'], positions=[POS_C6, POS_2C3])\nrounds_cyc = wl_refine(CYCLES['graphs'], num_iterations=4)\n\nfor l in [1, 2]:\n    show_round(**CYCLES, rounds=rounds_cyc, l=l)\n\nwl_report(rounds_cyc, ['C6  ', '2xC3'])","lines":[{"from":1,"to":1,"say":"p.51 의 PAIR 와 같은 모양으로 두 그래프 정보를 묶어요."},{"from":2,"to":2,"say":"4라운드 **색 정제(Color refinement)** 를 계산해요."},{"from":4,"to":5,"say":"라운드 1 과 2 의 과정을 그림으로 그려요."},{"from":7,"to":7,"say":"보고서 출력. 셀 34 설명대로 HASH 표 행이 매번 하나, 히스토그램이 {1: 6}, {2: 6}, {3: 6} 처럼 늘 같아 INCONCLUSIVE 예요."}],"link":"슬라이드 '매 라운드 히스토그램이 같음, 1-WL 은 판정 불가' 가 이 출력이에요."},{"kind":"code","head":"1주차 노트북: 3-정규 그래프 두 개","file":"PracticeCode_1_번역.ipynb 셀 167","code":"# 그래프 L 만들기\nL = nx.Graph(\n    [\n        (\"a\", \"g\"),\n        (\"a\", \"h\"),\n        (\"a\", \"i\"),\n        (\"g\", \"b\"),\n        (\"g\", \"c\"),\n        (\"b\", \"h\"),\n        (\"b\", \"j\"),\n        (\"h\", \"d\"),\n        (\"c\", \"i\"),\n        (\"c\", \"j\"),\n        (\"i\", \"d\"),\n        (\"d\", \"j\"),\n    ]\n)\n\n# 그래프 R 만들기\nR = nx.Graph(\n    [\n        (1, 2),\n        (1, 5),\n        (1, 4),\n        (2, 6),\n        (2, 3),\n        (3, 7),\n        (3, 4),\n        (4, 8),\n        (5, 6),\n        (5, 8),\n        (6, 7),\n        (7, 8),\n    ]\n)\n\ncheck_graph_isomorphic(R, L, k=1, verbose=True, method='WL')","lines":[{"from":1,"to":18,"say":"그래프 L 을 문자 이름 노드 쌍 12개로 만들어요. nx.Graph 에 (노드, 노드) 쌍 리스트를 넣으면 선이 생겨요."},{"from":19,"to":36,"say":"그래프 R 을 숫자 이름 노드 쌍 12개로 만들어요."},{"from":37,"to":37,"say":"셀 166 설명: L 과 R 은 노드 8개, 모두 차수 3 인 3-정규 그래프예요. 1-WL 은 True(같다고 봄)를 출력하지만 실제로는 동형이 아니에요."}],"link":"슬라이드 카드 1 '어떤 d-정규 그래프도 구별 불가' 의 3-정규 예예요."}]},{"p":61,"title":"사이클이 왜 중요한가","terms":["Cycle","1-WL","Message passing"],"pass1":[{"kind":"say","lines":["분자를 그래프로 그리면 원자는 점, 원자 사이 결합은 선이 돼요.","분자에는 원자들이 한 바퀴 이어진 고리, 곧 **사이클(Cycle)** 이 아주 많아요.","고리가 몇 개인지, 몇 각형인지에 따라 물질의 성질이 크게 달라져요.","그래서 고리를 세지 못하는 1-WL 의 한계는 화학에서 실제로 문제가 돼요."]},{"kind":"look","head":"분자 그림 속 고리","boxes":[{"x":0.15,"y":0.42,"w":0.21,"h":0.37,"say":"왼쪽 분자예요. 육각형 고리 여러 개가 옆으로 붙어 있어요."},{"x":0.41,"y":0.54,"w":0.22,"h":0.25,"say":"가운데 분자에는 육각형 사이에 오각형 고리도 섞여 있어요."}]}],"pass2":[{"kind":"look","head":"슬라이드를 차례로 짚어 볼게요","boxes":[{"x":0.03,"y":0.16,"w":0.5,"h":0.06,"say":"화합물 속 원자 사이 결합은 사이클을 이뤄요. 원자가 노드, 결합이 엣지예요."},{"x":0.03,"y":0.25,"w":0.6,"h":0.06,"say":"육각형은 유기 화합물에서 가장 흔한 다각형이고, 그래서 안정된 물질을 만들어요."},{"x":0.15,"y":0.42,"w":0.21,"h":0.37,"say":"독소루비신: 위쪽에 고리 네 개가 옆으로 붙고, 아래에 O 가 든 육각형 고리(당)가 있어요."},{"x":0.41,"y":0.54,"w":0.22,"h":0.25,"say":"캄토테신: 고리 크기가 6-6-5-6-6 이에요. 오각형이 섞여 있어요."},{"x":0.67,"y":0.35,"w":0.18,"h":0.45,"say":"에토포사이드: 대부분 육각형이고 가운데 줄 양 끝에 오각형이 있어요."}]},{"kind":"points","head":"구조식 읽는 법","items":["선이 꺾이는 꼭짓점마다 탄소가 있고, 글자는 생략해요.","선 하나는 결합, 두 줄 선은 이중 결합이에요.","O 는 산소, N 은 질소, CH3 는 탄소 하나에 수소 셋이에요.","굵은 쐐기와 점선 쐐기는 결합이 종이 앞쪽, 뒤쪽을 향한다는 입체 표시예요."]},{"kind":"figure","head":"같은 탄소 6개라도","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\"><text x=\"80\" y=\"30\" font-size=\"15\" text-anchor=\"middle\" class=\"tb\">사슬 (C 6개)<\/text><line x1=\"20\" y1=\"100\" x2=\"44\" y2=\"75\" class=\"e b1\"/><line x1=\"44\" y1=\"75\" x2=\"68\" y2=\"100\" class=\"e b1\"/><line x1=\"68\" y1=\"100\" x2=\"92\" y2=\"75\" class=\"e b1\"/><line x1=\"92\" y1=\"75\" x2=\"116\" y2=\"100\" class=\"e b1\"/><line x1=\"116\" y1=\"100\" x2=\"140\" y2=\"75\" class=\"e b1\"/><circle cx=\"20\" cy=\"100\" r=\"10\" class=\"n3 b1\"/><circle cx=\"44\" cy=\"75\" r=\"10\" class=\"n b1\"/><circle cx=\"68\" cy=\"100\" r=\"10\" class=\"n b1\"/><circle cx=\"92\" cy=\"75\" r=\"10\" class=\"n b1\"/><circle cx=\"116\" cy=\"100\" r=\"10\" class=\"n b1\"/><circle cx=\"140\" cy=\"75\" r=\"10\" class=\"n3 b1\"/><text x=\"80\" y=\"150\" font-size=\"15\" text-anchor=\"middle\" class=\"t b1\">끝은 차수 1<\/text><text x=\"245\" y=\"30\" font-size=\"15\" text-anchor=\"middle\" class=\"tb b2\">육각형 고리<\/text><line x1=\"245\" y1=\"50\" x2=\"206\" y2=\"72.5\" class=\"e b2\"/><line x1=\"206\" y1=\"72.5\" x2=\"206\" y2=\"117.5\" class=\"e b2\"/><line x1=\"206\" y1=\"117.5\" x2=\"245\" y2=\"140\" class=\"e b2\"/><line x1=\"245\" y1=\"140\" x2=\"284\" y2=\"117.5\" class=\"e b2\"/><line x1=\"284\" y1=\"117.5\" x2=\"284\" y2=\"72.5\" class=\"e b2\"/><line x1=\"284\" y1=\"72.5\" x2=\"245\" y2=\"50\" class=\"e b2\"/><circle cx=\"245\" cy=\"50\" r=\"10\" class=\"n b2\"/><circle cx=\"206\" cy=\"72.5\" r=\"10\" class=\"n b2\"/><circle cx=\"206\" cy=\"117.5\" r=\"10\" class=\"n b2\"/><circle cx=\"245\" cy=\"140\" r=\"10\" class=\"n b2\"/><circle cx=\"284\" cy=\"117.5\" r=\"10\" class=\"n b2\"/><circle cx=\"284\" cy=\"72.5\" r=\"10\" class=\"n b2\"/><text x=\"395\" y=\"30\" font-size=\"15\" text-anchor=\"middle\" class=\"tb b2\">오각형 고리<\/text><line x1=\"395\" y1=\"56\" x2=\"355.1\" y2=\"85\" class=\"e b2\"/><line x1=\"355.1\" y1=\"85\" x2=\"370.3\" y2=\"132\" class=\"e b2\"/><line x1=\"370.3\" y1=\"132\" x2=\"419.7\" y2=\"132\" class=\"e b2\"/><line x1=\"419.7\" y1=\"132\" x2=\"434.9\" y2=\"85\" class=\"e b2\"/><line x1=\"434.9\" y1=\"85\" x2=\"395\" y2=\"56\" class=\"e b2\"/><circle cx=\"395\" cy=\"56\" r=\"10\" class=\"n b2\"/><circle cx=\"355.1\" cy=\"85\" r=\"10\" class=\"n b2\"/><circle cx=\"370.3\" cy=\"132\" r=\"10\" class=\"n b2\"/><circle cx=\"419.7\" cy=\"132\" r=\"10\" class=\"n b2\"/><circle cx=\"434.9\" cy=\"85\" r=\"10\" class=\"n b2\"/><text x=\"320\" y=\"175\" font-size=\"15\" text-anchor=\"middle\" class=\"t b2\">모든 노드가 친구 2명<\/text><text x=\"240\" y=\"230\" font-size=\"15\" text-anchor=\"middle\" class=\"t b3\">1-WL 은 사슬 끝은 알아채지만<\/text><text x=\"240\" y=\"255\" font-size=\"15\" text-anchor=\"middle\" class=\"tb b3\">고리가 5개짜리인지 6개짜리인지는 몰라요<\/text><\/svg>","caption":"한 분자 안에 오각형과 육각형이 섞여 있으면 1-WL 수준 GNN 이 헷갈릴 수 있어요.","builds":3},{"kind":"compare","head":"1-WL 이 알아채는 것과 모르는 것","cols":["모양","차수","1-WL"],"rows":[["사슬","끝 1, 나머지 2","1라운드에 끝을 알아챔"],["육각형 고리","모두 2","크기를 모름"],["오각형 고리","모두 2","크기를 모름"]]},{"kind":"prof","when":"3주차 화요일 수업","lines":["큰 문제가 되는 분야는 분자 구조 분석, 특히 신약 설계래요.","벤젠 같은 탄소 고리는 초기 특징이 '탄소' 뿐이라 서로 잘 구별이 안 돼요.","전자 회로, 화학 공정 시뮬레이션도 구조 식별이 중요한 과제래요."]},{"kind":"mining","src":"마이닝 7강, 9강","lines":["7강은 반복되는 구조 부품이 기능을 결정한다며 카복실기를 예로 들었어요.","9강은 깊이 d 까지의 라벨 경로를 세는 화학정보학용 커널을 소개했어요.","둘 다 '분자 성질은 작은 부분 구조가 좌우한다' 는 같은 생각이에요."]}],"pass3":[{"kind":"english","head":"사이클이 중요한 이유","en":"Molecules consist of rings, and the number and size of rings determine chemical properties. Since 1-WL-bounded GNNs cannot count cycles, they may confuse molecules with different ring structures.","ko":"분자는 고리로 이루어져 있고 고리의 수와 크기가 화학적 성질을 정한다. 1-WL 에 묶인 GNN 은 사이클을 세지 못해서 고리 구조가 다른 분자를 헷갈릴 수 있다.","tip":"GNN 2024 가을 기말 6번 (b) 해설에도 cycles, cliques 가 핵심 단어로 나와요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["구조식에는 수소 대부분과 탄소 글자가 생략돼요. 분자 그래프도 보통 수소를 뺀 뼈대 원자만 노드로 써요.","1-WL 이 **사이클(Cycle)** 에 대해 아무것도 모르는 건 아니에요. 사슬 끝처럼 차수가 달라지는 곳은 알아채요."]},{"kind":"check","q":"사슬과 고리 중 1-WL 이 바로 알아채는 것은?","choices":["사슬의 끝 노드","고리의 크기","고리의 개수"],"a":0,"why":"사슬 끝은 차수 1 이라 1라운드에 다른 색을 받아요. 고리 크기와 개수는 몰라요."}],"pass4":[]},{"p":62,"title":"왜 클리크와 준클리크인가?","terms":["Clique","Quasi-clique","1-WL","Cycle"],"pass1":[{"kind":"say","lines":["무리 안의 모두가 서로 연결된 무리를 **클리크(Clique)**, 거의 모두가 연결된 무리를 **준클리크(Quasi-clique)** 라고 해요.","이렇게 빽빽한 무리는 여러 분야에서 중요한 신호예요.","사기꾼 무리 찾기, 함께 일하는 단백질 무리 찾기, 그래프를 짧게 줄여 저장하기가 그 예예요.","그런데 1-WL 은 가장 작은 클리크인 삼각형조차 세지 못해요."]},{"kind":"analogy","head":"친구 수만 묻는 선생님","scene":"모둠이 두 개 있어요. 한 모둠은 네 명 모두가 서로서로 친구이고, 다른 모둠은 딱 한 쌍만 빼고 모두 친구예요. 1-WL 선생님은 학생마다 '친구가 몇 명이니?' 만 묻고, '네 친구들끼리도 서로 친구니?' 는 묻지 않아요. 그래서 이 선생님은 빽빽한 무리가 어디 있는지 알아채기 어려워요.","map":[["모두가 서로 친구인 모둠","**클리크(Clique)**"],["한 쌍만 빼고 친구인 모둠","**준클리크(Quasi-clique)**"],["친구 수만 묻는 선생님","**1-WL 테스트(1-WL)**"]]}],"pass2":[{"kind":"look","head":"그림 세 장을 차례로 읽어요","boxes":[{"x":0.15,"y":0.25,"w":0.23,"h":0.49,"say":"사기꾼 탐지 [Hooi et al. 2016]. 행은 사용자, 열은 대상, 검은 점은 리뷰나 팔로우 같은 행동이에요."},{"x":0.3,"y":0.57,"w":0.08,"h":0.13,"say":"오른쪽 아래 Fraudsters 칸이 새까매요. 사기꾼 대부분이 고객 대부분에게 점을 찍은 빽빽한 블록이에요."},{"x":0.4,"y":0.25,"w":0.21,"h":0.53,"say":"PPI 네트워크의 단백질 복합체 검출 [Vlaic et al. 2017]. 촘촘한 덩어리가 복합체 후보예요."},{"x":0.68,"y":0.25,"w":0.15,"h":0.53,"say":"그래프 압축. 인접행렬의 진한 네모 블록은 '전부 연결' 한 줄로 적어 공간을 줄여요."}]},{"kind":"points","head":"용어 정리","items":["**클리크(Clique)**: 무리 안 모든 두 노드가 서로 연결된 무리예요.","**준클리크(Quasi-clique)**: 거의 모든 쌍이 연결된 무리. 기준(예: 90%)은 연구마다 정해요.","Camouflage(위장): 사기꾼이 들키지 않으려고 정직한 대상에도 점을 찍은 부분이에요.","PPI: 단백질-단백질 상호작용(Protein-Protein Interaction). 복합체는 한 팀처럼 뭉쳐 일하는 단백질 무리예요."]},{"kind":"figure","head":"클리크와 준클리크","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\"><text x=\"100\" y=\"28\" font-size=\"15\" text-anchor=\"middle\" class=\"tb b1\">4-클리크<\/text><line x1=\"50\" y1=\"60\" x2=\"150\" y2=\"60\" class=\"e2 b1\"/><line x1=\"50\" y1=\"60\" x2=\"50\" y2=\"160\" class=\"e2 b1\"/><line x1=\"50\" y1=\"60\" x2=\"150\" y2=\"160\" class=\"e2 b1\"/><line x1=\"150\" y1=\"60\" x2=\"50\" y2=\"160\" class=\"e2 b1\"/><line x1=\"150\" y1=\"60\" x2=\"150\" y2=\"160\" class=\"e2 b1\"/><line x1=\"50\" y1=\"160\" x2=\"150\" y2=\"160\" class=\"e2 b1\"/><circle cx=\"50\" cy=\"60\" r=\"15\" class=\"n2 b1\"/><circle cx=\"150\" cy=\"60\" r=\"15\" class=\"n2 b1\"/><circle cx=\"50\" cy=\"160\" r=\"15\" class=\"n2 b1\"/><circle cx=\"150\" cy=\"160\" r=\"15\" class=\"n2 b1\"/><text x=\"100\" y=\"205\" font-size=\"15\" text-anchor=\"middle\" class=\"t b1\">6쌍 중 6 연결<\/text><text x=\"100\" y=\"230\" font-size=\"15\" text-anchor=\"middle\" class=\"tb b1\">밀도 1.00<\/text><text x=\"330\" y=\"28\" font-size=\"15\" text-anchor=\"middle\" class=\"tb b2\">준클리크<\/text><line x1=\"280\" y1=\"60\" x2=\"380\" y2=\"60\" class=\"e b2\"/><line x1=\"280\" y1=\"60\" x2=\"280\" y2=\"160\" class=\"e b2\"/><line x1=\"280\" y1=\"60\" x2=\"380\" y2=\"160\" class=\"e b2\"/><line x1=\"380\" y1=\"60\" x2=\"280\" y2=\"160\" class=\"hl b2\"/><line x1=\"380\" y1=\"60\" x2=\"380\" y2=\"160\" class=\"e b2\"/><line x1=\"280\" y1=\"160\" x2=\"380\" y2=\"160\" class=\"e b2\"/><circle cx=\"280\" cy=\"60\" r=\"15\" class=\"n b2\"/><circle cx=\"380\" cy=\"60\" r=\"15\" class=\"n b2\"/><circle cx=\"280\" cy=\"160\" r=\"15\" class=\"n b2\"/><circle cx=\"380\" cy=\"160\" r=\"15\" class=\"n b2\"/><text x=\"330\" y=\"205\" font-size=\"15\" text-anchor=\"middle\" class=\"t b2\">6쌍 중 5 연결 (1쌍 빠짐)<\/text><text x=\"330\" y=\"230\" font-size=\"15\" text-anchor=\"middle\" class=\"tb b2\">밀도 약 0.83<\/text><text x=\"240\" y=\"262\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b2\">1-WL 은 '네 친구끼리도 친구야?' 를 묻지 않아요<\/text><\/svg>","caption":"밀도 = 연결된 쌍 수 / 가능한 쌍 수. 1 이면 클리크, 1 에 가까우면 준클리크예요.","builds":2},{"kind":"steps","head":"밀도 계산","steps":["노드 4개의 가능한 쌍: 4×3/2 = 6","6쌍 모두 연결: 밀도 1.00, 4-클리크","5쌍 연결: 약 0.83. 기준을 0.8 로 잡으면 준클리크","3쌍 연결: 0.50. 빽빽하지 않음","사기꾼 3명이 고객 대상 2개에 모두 행동: 6칸 중 6칸, 밀도 1.00"],"answer":"사기꾼 블록처럼 밀도가 1 에 가까운 곳이 수상한 무리예요."},{"kind":"steps","head":"삼각형(3-클리크) 세기","steps":["세 노드 묶음마다 세 쌍이 모두 이어졌는지 봐요.","{A, B, C}: A-B, A-C, B-C 모두 있음. 삼각형","C, E, D 가 들어간 다른 묶음은 한 쌍 이상 빠져요."],"answer":"삼각형 1개. 1-WL 은 이런 개수를 직접 알려 주지 못해요.","given":"엣지 A-B, A-C, B-C, C-E, E-D"},{"kind":"mining","src":"마이닝 9강 Graph Kernels","lines":["그래플릿 커널은 크기 3, 4, 5 인 작은 부분그래프가 몇 번 나오는지 세어 특징 벡터로 만들어요.","크기 3 그래플릿에 삼각형이 있으니 1-WL 이 못 세는 삼각형 수를 직접 세요.","대신 크기 k 그래플릿 수가 O(n^k) 로 늘어 계산이 비싸요."]}],"pass3":[{"kind":"exam","src":"그래프 마이닝 2026 봄 기말 1번 (10점)","q":"Consider an undirected graph with nodes A, B, C, D, E and edges (A,B), (A,C), (B,C), (C,E), (E,D). Compute the graphlet count vector f_G for graphlets of size k = 3 (g1: path of length 2, g2: triangle). How does k dictate the trade-off between expressive power and computational complexity?","qko":"노드 5개 그래프에서 크기 3 그래플릿(g1 길이 2 경로, g2 삼각형) 개수 벡터를 구하고, k 에 따른 표현력과 계산량의 맞교환을 서술하라.","solve":["삼각형: {A, B, C} 1개","길이 2 경로(삼각형 제외): {A, C, E}, {B, C, E}, {C, E, D} 3개","f_G = (g1 개수, g2 개수) = (3, 1)","(b) k 가 크면 큰 클리크 같은 풍부한 구조를 잡아 더 잘 구별하지만, 세는 비용이 O(n^k) 로 커져요."],"answer":"f_G = (3, 1)"},{"kind":"exam","src":"그래프 마이닝 2024 봄 중간 10번 (10점)","q":"Consider an undirected graph G of eight nodes and four graphlets g1, g2, g3, g4. Count the number of the kernel subgraphs of limited size 3, and make a feature vector for graph G.","qko":"노드 8개 그래프에서 크기 3 그래플릿 네 종류가 각각 몇 번 나오는지 세고 특징 벡터를 만들어라.","solve":["해설 개수: g1 1개, g2 14개, g3 23개, g4 17개","특징 벡터 f_G = (1, 14, 23, 17)","검산: 노드 8개에서 세 노드 묶음은 8×7×6/6 = 56 개","네 그래플릿이 크기 3 의 네 가지 모양(엣지 0~3개)이라면 합이 56 이어야 하는데 해설 합은 55 예요."],"answer":"해설 답 (1, 14, 23, 17). 직접 풀 때는 개수 합이 56 인지 꼭 검산해요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["준클리크의 '거의' 가 몇 퍼센트인지는 정해진 값이 없어요.","사기꾼 블록은 사용자와 대상, 두 종류 노드 사이 블록이에요. 같은 종류끼리의 클리크와 조금 다르지만 같은 신호 역할을 해요.","Dhulipala et al. 압축 논문은 KDD 2016 으로 알려져 있어요. 슬라이드의 2017 은 연도가 어긋난 것으로 보여요."]},{"kind":"check","q":"**준클리크(Quasi-clique)** 의 뜻은?","choices":["거의 모든 쌍이 연결된 빽빽한 무리","노드가 하나뿐인 무리","사이클이 없는 무리"],"a":0,"why":"모든 쌍이 연결되면 클리크, 거의 모든 쌍이면 준클리크예요."}],"pass4":[{"kind":"pyterm","name":"nx.triangles 로 삼각형 세기 (예시 코드)","say":["nx.triangles(G) 는 노드마다 속한 삼각형 수를 사전으로 줘요. 노트북 셀 9 에서도 써요.","삼각형 하나를 세 노드가 각각 세니까 합을 3 으로 나눠요. 기출 그래프로 확인해요."],"example":"import networkx as nx\nG = nx.Graph([('A','B'), ('A','C'), ('B','C'), ('C','E'), ('E','D')])\nprint(sum(nx.triangles(G).values()) // 3)","out":"1"}]},{"p":63,"title":"GNN 의 표현력 높이기","terms":["Expressive power","Computational graph","Cycle","Message passing","Embedding"],"pass1":[{"kind":"say","lines":["삼각형과 사각형처럼 고리의 길이만 다르면, 지금까지의 GNN 은 구별하지 못해요.","고리 위 모든 노드가 친구 2명씩이라, 노드마다 펼친 나무인 **계산 그래프(Computational graph)** 가 똑같거든요.","하지만 새로운 방법을 더하면 GNN 의 구별하는 힘, 곧 **표현력(Expressive power)** 을 높일 수 있어요."]},{"kind":"look","head":"고리와 나무","boxes":[{"x":0.11,"y":0.41,"w":0.35,"h":0.28,"say":"왼쪽 A 는 삼각형, B 는 사각형이에요. 테두리가 굵은 두 노드가 주인공이에요."},{"x":0.58,"y":0.33,"w":0.28,"h":0.36,"say":"오른쪽은 두 주인공의 계산 그래프예요. 나무 모양이 똑같아요."}]},{"kind":"analogy","head":"손잡고 선 원과 방울","scene":"세 명이 손잡고 둥글게 선 원과 네 명이 손잡고 선 원이 있어요. 눈을 감고 옆 사람 손만 더듬으면, 어느 원에서든 '양손에 한 명씩' 이에요. 옆 사람의 옆 사람을 계속 더듬어 가도 느낌은 똑같아요. 이때 내 손에 방울을 달고 돌려 보면, 몇 번 만에 방울이 돌아오는지로 원의 크기를 알 수 있어요.","map":[["손잡고 선 원","**사이클(Cycle)**"],["옆 사람 손만 더듬기","메시지 패싱, 똑같은 계산 그래프"],["내 손에 단 방울","주인공에게만 붙이는 특별 표시"]]}],"pass2":[{"kind":"look","head":"슬라이드를 차례로 짚어 볼게요","boxes":[{"x":0.03,"y":0.16,"w":0.33,"h":0.06,"say":"GNN 의 **표현력(Expressive power)** 을 높일 수 있을까?"},{"x":0.03,"y":0.25,"w":0.67,"h":0.06,"say":"기존 GNN 틀이 구별하지 못하는 기본 구조가 있어요. 예: 사이클의 차이."},{"x":0.11,"y":0.41,"w":0.35,"h":0.28,"say":"A 는 삼각형, B 는 사각형. 테두리 굵은 v1, v2 가 주인공이고, 모든 노드 특징이 같은 노란색이에요."},{"x":0.58,"y":0.33,"w":0.28,"h":0.36,"say":"v1 과 v2 의 **계산 그래프(Computational graph)**. 1, 2, 4, 8 로 모두 15개인 3층 트리가 똑같아요."},{"x":0.03,"y":0.75,"w":0.86,"h":0.1,"say":"표현력을 높일 수 있대요. 대괄호 속 세 논문이 방법이에요."}]},{"kind":"points","head":"계산 그래프가 같은 이유","items":["뿌리(주인공) 아래에 이웃을 붙이고, 그 이웃 아래에 또 이웃을 붙여요.","모든 노드의 이웃이 2명이라 줄마다 2배: 1, 2, 4, 8.","15개 동그라미는 15명이 아니라 같은 노드가 여러 번 등장한 거예요.","모양과 특징이 같으면 어떤 **메시지 패싱(Message passing)** GNN 도 같은 **임베딩(Embedding)** 을 줘요."]},{"kind":"points","head":"대괄호 속 세 논문","items":["You et al. AAAI 2021: 주인공에 특별 표시를 붙여 메시지를 돌리는 ID-GNN","Li et al. NeurIPS 2020: 노드 사이 거리 정보를 특징으로 넣는 거리 인코딩","Kanatsoulis et al. ICLR 2024: GNN 이 사이클 같은 부분 구조 개수를 셀 수 있게 하는 연구"]},{"kind":"figure","head":"같은 트리, 다른 고리","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\"><text x=\"70\" y=\"26\" font-size=\"15\" text-anchor=\"middle\" class=\"tb\">A 삼각형<\/text><text x=\"185\" y=\"26\" font-size=\"15\" text-anchor=\"middle\" class=\"tb\">B 사각형<\/text><line x1=\"40\" y1=\"70\" x2=\"110\" y2=\"115\" class=\"e\"/><line x1=\"110\" y1=\"115\" x2=\"40\" y2=\"160\" class=\"e\"/><line x1=\"40\" y1=\"160\" x2=\"40\" y2=\"70\" class=\"e\"/><line x1=\"150\" y1=\"70\" x2=\"220\" y2=\"70\" class=\"e\"/><line x1=\"220\" y1=\"70\" x2=\"220\" y2=\"160\" class=\"e\"/><line x1=\"220\" y1=\"160\" x2=\"150\" y2=\"160\" class=\"e\"/><line x1=\"150\" y1=\"160\" x2=\"150\" y2=\"70\" class=\"e\"/><circle cx=\"40\" cy=\"70\" r=\"16\" class=\"n2\"/><text x=\"40\" y=\"75\" font-size=\"14\" text-anchor=\"middle\" class=\"tl\">v1<\/text><circle cx=\"110\" cy=\"115\" r=\"16\" class=\"n\"/><circle cx=\"40\" cy=\"160\" r=\"16\" class=\"n\"/><circle cx=\"150\" cy=\"70\" r=\"16\" class=\"n2\"/><text x=\"150\" y=\"75\" font-size=\"14\" text-anchor=\"middle\" class=\"tl\">v2<\/text><circle cx=\"220\" cy=\"70\" r=\"16\" class=\"n\"/><circle cx=\"220\" cy=\"160\" r=\"16\" class=\"n\"/><circle cx=\"150\" cy=\"160\" r=\"16\" class=\"n\"/><line x1=\"250\" y1=\"30\" x2=\"250\" y2=\"230\" class=\"hl\"/><text x=\"365\" y=\"26\" font-size=\"15\" text-anchor=\"middle\" class=\"tb b1\">v1, v2 의 계산 그래프<\/text><line x1=\"325\" y1=\"100\" x2=\"365\" y2=\"55\" class=\"e b1\"/><line x1=\"405\" y1=\"100\" x2=\"365\" y2=\"55\" class=\"e b1\"/><line x1=\"305\" y1=\"145\" x2=\"325\" y2=\"100\" class=\"e b1\"/><line x1=\"345\" y1=\"145\" x2=\"325\" y2=\"100\" class=\"e b1\"/><line x1=\"385\" y1=\"145\" x2=\"405\" y2=\"100\" class=\"e b1\"/><line x1=\"425\" y1=\"145\" x2=\"405\" y2=\"100\" class=\"e b1\"/><line x1=\"295\" y1=\"190\" x2=\"305\" y2=\"145\" class=\"e b1\"/><line x1=\"315\" y1=\"190\" x2=\"305\" y2=\"145\" class=\"e b1\"/><line x1=\"335\" y1=\"190\" x2=\"345\" y2=\"145\" class=\"e b1\"/><line x1=\"355\" y1=\"190\" x2=\"345\" y2=\"145\" class=\"e b1\"/><line x1=\"375\" y1=\"190\" x2=\"385\" y2=\"145\" class=\"e b1\"/><line x1=\"395\" y1=\"190\" x2=\"385\" y2=\"145\" class=\"e b1\"/><line x1=\"415\" y1=\"190\" x2=\"425\" y2=\"145\" class=\"e b1\"/><line x1=\"435\" y1=\"190\" x2=\"425\" y2=\"145\" class=\"e b1\"/><circle cx=\"365\" cy=\"55\" r=\"12\" class=\"n2 b1\"/><circle cx=\"325\" cy=\"100\" r=\"12\" class=\"n b1\"/><circle cx=\"405\" cy=\"100\" r=\"12\" class=\"n b1\"/><circle cx=\"305\" cy=\"145\" r=\"12\" class=\"n b1\"/><circle cx=\"345\" cy=\"145\" r=\"12\" class=\"n b1\"/><circle cx=\"385\" cy=\"145\" r=\"12\" class=\"n b1\"/><circle cx=\"425\" cy=\"145\" r=\"12\" class=\"n b1\"/><circle cx=\"295\" cy=\"190\" r=\"8\" class=\"n b1\"/><circle cx=\"315\" cy=\"190\" r=\"8\" class=\"n b1\"/><circle cx=\"335\" cy=\"190\" r=\"8\" class=\"n b1\"/><circle cx=\"355\" cy=\"190\" r=\"8\" class=\"n b1\"/><circle cx=\"375\" cy=\"190\" r=\"8\" class=\"n b1\"/><circle cx=\"395\" cy=\"190\" r=\"8\" class=\"n b1\"/><circle cx=\"415\" cy=\"190\" r=\"8\" class=\"n b1\"/><circle cx=\"435\" cy=\"190\" r=\"8\" class=\"n b1\"/><text x=\"365\" y=\"222\" font-size=\"15\" text-anchor=\"middle\" class=\"t b2\">1 + 2 + 4 + 8 = 15, 모양이 같아요<\/text><text x=\"125\" y=\"215\" font-size=\"15\" text-anchor=\"middle\" class=\"tb b3\">3걸음 귀환: 삼각형 2, 사각형 0<\/text><text x=\"240\" y=\"258\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b3\">주인공 표시(ID)를 붙이면 2 대 0 으로 갈라져요<\/text><\/svg>","caption":"층을 더 쌓아도 트리 모양은 계속 같아요. 새 정보를 더해야 갈라져요.","builds":3},{"kind":"steps","head":"주인공 표시 아이디어를 손으로","steps":["삼각형: $A^2$ 1행 = (2, 1, 1), $A$ 1열 = (0, 1, 1)","$(A^3)_{11} = 2\\times0 + 1\\times1 + 1\\times1 = 2$","사각형: $A^2$ 1행 = (2, 0, 2, 0), $A$ 1열 = (0, 1, 0, 1)","$(A^3)_{11} = 0 + 0 + 0 + 0 = 0$","사각형은 두 색으로 번갈아 칠할 수 있어서 홀수 걸음 뒤엔 반드시 반대 색에 있어요."],"answer":"3걸음 귀환 수: 삼각형 2, 사각형 0. 이 수를 특징으로 넣으면 갈라져요.","given":"주인공에게만 표시를 붙이고 '3걸음 만에 주인공에게 돌아오는 길' 수를 세요. $A$ 는 인접행렬(이어진 두 노드의 칸에 1 을 적은 표)이고, 이 수는 $A$ 를 세 번 곱한 표의 대각 칸이에요."},{"kind":"prof","when":"3주차 화요일 수업","lines":["GNN 은 1-WL 이 한계이고 답이 없나? 당연히 아니래요. 더 개선할 수 있어요.","1-WL 은 노드에, 2-WL 은 엣지에, 3-WL 은 삼각형에 이름을 줘요.","이렇게 차원을 키운 게 **k-WL** 이고, 표현력이 기하급수적으로 커진대요."]}],"pass3":[{"kind":"exam","src":"GNN 2024 가을 기말 6번 (GNN-AK, 10점)","q":"According to the GNN-AK model (from star to subgraph) with SUM as AGG over the k-hop subgraph rooted at v (including v) and MEAN aggregation, calculate the feature of each node at k = 1 and l = 0. Why does considering a set of k-hop subgraphs make the model more expressive than only neighbor aggregation?","qko":"노드마다 v 를 뿌리로 하는 k홉 부분그래프 안에서 SUM 으로 모으고 MEAN 으로 합치는 GNN-AK 로 k = 1 특징을 구하라. k홉 부분그래프 묶음이 왜 이웃 집계보다 표현력이 높은가?","solve":["노드 v 마다 v 를 포함한 1홉 부분그래프를 오려 내요.","부분그래프 안 특징을 SUM. 해설 예: A 의 부분그래프 {A, B, C, D} 라서 1+2+3+4 = 10","해설은 B, C 의 부분그래프 {A, B, C} 를 6 으로 계산하고, A 는 MEAN(10, 6, 6, 7) = 7.25","(b) k홉 부분그래프는 엣지 배치, 사이클, 클리크 같은 k홉 안 구조 전체를 간직해요. 이웃 집계는 이웃 특징 멀티셋만 봐요."],"answer":"A 의 SUM 값 10, MEAN 으로 합친 A 는 7.25. 부분그래프는 이웃 집계가 놓치는 고차 구조를 담아요."},{"kind":"english","head":"부분그래프가 더 강한 이유","en":"A k-hop subgraph retains the whole structure within k hops, such as edge arrangements, cycles and cliques, while neighbor aggregation only sees a multi-set of neighbor features.","ko":"k홉 부분그래프는 엣지 배치, 사이클, 클리크 같은 k홉 안의 구조 전체를 간직하지만, 이웃 집계는 이웃 특징의 멀티셋만 본다."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["트리 셋째 줄 4개 중 2개는 사실 주인공 자신이에요. 메시지가 왔다 갔다 하거든요.","층을 더 쌓기만 해서는 계산 그래프가 계속 같아요. ID, 거리, 부분 구조 수 같은 새 정보를 더해야 해요.","GNN-AK 해설은 D 의 부분그래프를 G[A, D] 로 쓰고 SUM(3, 4) = 7 로 계산해 초기값과 어긋나요. 방법만 익히고 숫자는 문제 그림으로 다시 확인해요."]},{"kind":"check","q":"삼각형 노드와 사각형 노드의 3층 **계산 그래프(Computational graph)** 는?","choices":["완전히 같다","삼각형 쪽이 더 크다","사각형 쪽이 더 크다"],"a":0,"why":"두 경우 모두 모든 노드 이웃이 2명이라 1, 2, 4, 8 로 같은 모양의 트리가 돼요."}],"pass4":[{"kind":"code","head":"계산 그래프를 나란히 그리기","file":"Sample_Code_3_번역.ipynb 셀 15","code":"fig, axes = plt.subplots(2, 2, figsize=(14, 7), gridspec_kw={'width_ratios': [1, 2.4]})\nfor row, (name, G, pos) in enumerate([('$C_6$', C6, POS_C6), ('$2 \\\\times C_3$', TwoC3, POS_2C3)]):\n    draw_graph(G, pos, axes[row, 0], highlight=0, title=f'{name}  (node 0 outlined)')\n    draw_tree(unfolding_tree(G, 0, 3), axes[row, 1], uniform=True, node_size=330, font_size=7,\n              title=f'Computational graph of node 0 in {name}, 3 layers')\nfig.suptitle('Identical computational graphs → identical embeddings', fontsize=13, fontweight='bold')\nplt.tight_layout(); plt.show()\n\n\ndef tree_shape(T, n):\n    \"\"\"Canonical form of the subtree at n, ignoring which graph node each copy is.\"\"\"\n    return tuple(sorted(tree_shape(T, k) for k in T.predecessors(n)))\n\nsame = all(tree_shape(unfolding_tree(C6, u, L), (u,)) == tree_shape(unfolding_tree(TwoC3, v, L), (v,))\n           for L in range(1, 5) for u in C6 for v in TwoC3)\nprint(f'All 6 x 6 node pairs (C6 node, 2xC3 node) have identical trees for L = 1..4: {same}')","lines":[{"from":1,"to":1,"say":"plt.subplots(2, 2) 는 2행 2열 그림 칸 axes 를 만들어요."},{"from":2,"to":2,"say":"C6 와 2×C3 를 한 줄씩 돌아요. enumerate 가 줄 번호 row 를 줘요."},{"from":3,"to":3,"say":"왼쪽 칸에 그래프를 그리고 노드 0 을 빨간 테두리로 강조해요."},{"from":4,"to":5,"say":"오른쪽 칸에 노드 0 의 3층 계산 그래프를 그려요. uniform=True 라서 모두 회색, 모양만 보여요."},{"from":6,"to":7,"say":"전체 제목 '같은 계산 그래프는 같은 임베딩' 을 달고 화면에 보여 줘요."},{"from":8,"to":12,"say":"tree_shape 함수는 번호를 무시하고 나무 모양만 튜플로 적어요. 자식 모양들을 정렬해 묶으니 모양이 같으면 결과도 같아요."},{"from":13,"to":16,"say":"층 1 부터 4 까지, C6 의 모든 노드와 TwoC3 의 모든 노드의 나무 모양이 같은지 all 로 확인하고 출력해요."}],"link":"셀 14 설명: 두 트리 모두 1+2+4+8 = 15 노드 완전 이진 트리예요. 슬라이드 트리와 같은 모양이고, 노트북 쌍은 C6 대 2×C3 예요."}]},{"p":64,"title":"1-WL 천장 깨기","terms":["Invariance","k-WL","Ego-network","1-WL","Message passing","Expressive power"],"pass1":[{"kind":"say","lines":["1-WL 이라는 천장을 넘는 방법은 크게 다섯 가족이 있어요.","모두 세 가지 재료 중 하나를 바꿔요. 노드에 주는 정보, 메시지를 주고받는 범위, 그리고 **불변성(Invariance)** 이에요.","불변성은 노드 번호를 바꿔 붙여도 결과가 같아야 한다는 약속이에요.","다만 공짜는 없어요. 더 잘 구별하는 대신 계산이 늘거나 약속이 조금 느슨해져요."]},{"kind":"points","head":"다섯 가족 한 줄씩","items":["A 특징 더하기: 노드에 위치나 작은 구조의 개수 같은 정보를 더 줘요.","B 부분그래프: 나와 내 주변만 오려 낸 작은 그래프, 곧 **에고 네트워크(Ego-network)** 여러 개 위에서 GNN 을 돌려요.","C 고차 GNN: 노드 하나 대신 노드 여러 개 묶음에 색을 칠해요. **k-WL 테스트(k-WL)** 와 같은 힘이에요.","D 대칭 깨기: 번호를 바꿔도 같아야 한다는 약속을 조금 풀어요.","E 전역: 멀리 떨어진 노드끼리도 직접 주고받게 해요."]}],"pass2":[{"kind":"look","head":"위 세 줄: 재료와 A, B, C 가족","boxes":[{"x":0.04,"y":0.15,"w":0.58,"h":0.04,"say":"모든 방법은 세 재료 중 하나를 완화해 구별력을 얻어요. 특징, 메시지 패싱 범위, 불변성."},{"x":0.05,"y":0.24,"w":0.9,"h":0.12,"say":"A 특징 풍부하게 하기: 위치, 구조 인코딩, 무작위 초기화, 부분 구조 개수. 가장 싸요. 약 3-WL 이상(확률적)."},{"x":0.05,"y":0.37,"w":0.9,"h":0.12,"say":"B 부분그래프와 **에고 네트워크(Ego-network)**: 부분그래프 묶음 위에서 GNN. 1-WL 초과, 노드 기반은 3-WL 이하."},{"x":0.05,"y":0.5,"w":0.9,"h":0.12,"say":"C 고차 GNN: k-GNN, PPGN 등. 노드 튜플 텐서 위 등변 사상 학습. **k-WL 테스트(k-WL)** 와 같음."}]},{"kind":"look","head":"아래 세 줄: D, E 가족과 결론","boxes":[{"x":0.05,"y":0.63,"w":0.9,"h":0.12,"say":"D 대칭 깨기: DropGNN, 무작위 특징. 여러 번 돌려 평균. **불변성(Invariance)** 은 분포 수준만. 높은 확률로 보편적."},{"x":0.05,"y":0.76,"w":0.9,"h":0.12,"say":"E 전역으로 가기: 구조 편향 그래프 트랜스포머. 모든 쌍 어텐션. 힘은 전부 인코딩이 결정."},{"x":0.04,"y":0.89,"w":0.42,"h":0.04,"say":"공짜 점심은 없다: 계산량, 불변성 보장, 표본 복잡도 중 하나로 대가를 치러요."}]},{"kind":"points","head":"새 용어","items":["**불변성(Invariance)**: 노드 번호를 바꿔 붙여도 결과가 같아야 한다는 성질이에요.","**k-WL 테스트(k-WL)**: 노드 k 개 묶음에 색을 칠해요. k 가 크면 더 강하지만 묶음 수가 폭발해요.","**에고 네트워크(Ego-network)**: 나와 내 주변 몇 홉만 오려 낸 작은 그래프예요.","등변: 번호를 섞으면 출력도 똑같이 섞이는 성질. 표본 복잡도: 잘 배우려면 필요한 데이터 양."]},{"kind":"figure","head":"세 재료와 다섯 가족","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\"><rect x=\"185\" y=\"110\" width=\"150\" height=\"44\" rx=\"10\" class=\"box2\"/><text x=\"260\" y=\"130\" font-size=\"15\" text-anchor=\"middle\" class=\"tb\">1-WL 메시지 패싱<\/text><text x=\"260\" y=\"148\" font-size=\"14\" text-anchor=\"middle\" class=\"t\">천장<\/text><rect x=\"10\" y=\"25\" width=\"140\" height=\"40\" rx=\"8\" class=\"box b1\"/><text x=\"80\" y=\"50\" font-size=\"15\" text-anchor=\"middle\" class=\"t b1\">재료 1: 특징<\/text><rect x=\"170\" y=\"25\" width=\"140\" height=\"40\" rx=\"8\" class=\"box b1\"/><text x=\"240\" y=\"50\" font-size=\"15\" text-anchor=\"middle\" class=\"t b1\">재료 2: 범위<\/text><rect x=\"330\" y=\"25\" width=\"140\" height=\"40\" rx=\"8\" class=\"box b1\"/><text x=\"400\" y=\"50\" font-size=\"15\" text-anchor=\"middle\" class=\"t b1\">재료 3: 불변성<\/text><line x1=\"80\" y1=\"65\" x2=\"205\" y2=\"110\" class=\"e b1\"/><line x1=\"240\" y1=\"65\" x2=\"255\" y2=\"110\" class=\"e b1\"/><line x1=\"400\" y1=\"65\" x2=\"315\" y2=\"110\" class=\"e b1\"/><line x1=\"50\" y1=\"192\" x2=\"260\" y2=\"154\" class=\"e2 b2\"/><circle cx=\"50\" cy=\"210\" r=\"17\" class=\"n3 b2\"/><text x=\"50\" y=\"215\" font-size=\"15\" text-anchor=\"middle\" class=\"tl b2\">A<\/text><text x=\"50\" y=\"250\" font-size=\"14\" text-anchor=\"middle\" class=\"t b2\">특징 추가<\/text><line x1=\"155\" y1=\"192\" x2=\"260\" y2=\"154\" class=\"e2 b2\"/><circle cx=\"155\" cy=\"210\" r=\"17\" class=\"n b2\"/><text x=\"155\" y=\"215\" font-size=\"15\" text-anchor=\"middle\" class=\"tl b2\">B<\/text><text x=\"155\" y=\"250\" font-size=\"14\" text-anchor=\"middle\" class=\"t b2\">부분그래프<\/text><line x1=\"260\" y1=\"192\" x2=\"260\" y2=\"154\" class=\"e2 b2\"/><circle cx=\"260\" cy=\"210\" r=\"17\" class=\"n b2\"/><text x=\"260\" y=\"215\" font-size=\"15\" text-anchor=\"middle\" class=\"tl b2\">C<\/text><text x=\"260\" y=\"250\" font-size=\"14\" text-anchor=\"middle\" class=\"t b2\">고차 k-WL<\/text><line x1=\"365\" y1=\"192\" x2=\"260\" y2=\"154\" class=\"e2 b2\"/><circle cx=\"365\" cy=\"210\" r=\"17\" class=\"n b2\"/><text x=\"365\" y=\"215\" font-size=\"15\" text-anchor=\"middle\" class=\"tl b2\">E<\/text><text x=\"365\" y=\"250\" font-size=\"14\" text-anchor=\"middle\" class=\"t b2\">전역 어텐션<\/text><line x1=\"445\" y1=\"192\" x2=\"260\" y2=\"154\" class=\"e2 b2\"/><circle cx=\"445\" cy=\"210\" r=\"17\" class=\"n2 b2\"/><text x=\"445\" y=\"215\" font-size=\"15\" text-anchor=\"middle\" class=\"tl b2\">D<\/text><text x=\"445\" y=\"250\" font-size=\"14\" text-anchor=\"middle\" class=\"t b2\">대칭 깨기<\/text><\/svg>","caption":"무엇을 바꾸느냐에 따라 얻는 힘과 치르는 대가가 달라요.","builds":2},{"kind":"compare","head":"다섯 가족 한눈에","cols":["가족","바꾸는 재료","구별력","주 대가"],"rows":[["A 특징","특징","약 3-WL 이상(확률적)","인코딩 계산"],["B 부분그래프","범위","1-WL 초과, 3-WL 이하","부분그래프 수만큼 계산"],["C 고차","범위(튜플)","k-WL","튜플 수 폭발"],["D 대칭 깨기","불변성","높은 확률로 보편","불변성 보장 약화"],["E 전역","범위(전체)","인코딩에 따라","모든 쌍 계산"]]},{"kind":"steps","head":"C6 와 2×C3 에 가족별로 적용","steps":["1-WL, GIN: 모든 노드가 같은 값. 구별 안 됨","A 삼각형 수를 초기 특징으로: 2×C3 노드 1, C6 노드 0. 바로 구별","B 1홉 에고 네트워크 엣지 수: 2×C3 노드 3(삼각형), C6 노드 2(경로). 구별","E 차수 인코딩만(차수 2 는 0.2): 12개 노드 모두 0.2. 여전히 구별 안 됨","E 최단 경로 거리: C6 에는 거리 2, 3 인 쌍이 있고 2×C3 는 거리 1 뿐. 구별"],"answer":"어떤 재료를 넣느냐가 전부예요. 차수만 넣으면 **정규 그래프(Regular graph)** 에서 여전히 실패해요."},{"kind":"prof","when":"3주차 화요일 수업","lines":["가장 쉬운 법: 구조 특징(차수, 라플라시안 고유벡터 등)을 초기 특징에 넣기. 계산 부담이 있어요.","부분그래프 묶음: 1-WL 보다 강하고 3-WL 이하예요. '3-WL 이하' 가 중요하대요.","노드, 엣지 무작위 드롭은 비슷한 효과지만 더 약해요.","GNN 을 k-WL 로 확장하면 강하지만 너무 복잡해서 잘 안 쓴대요."]},{"kind":"mining","src":"마이닝 7강 Subgraph Mining","lines":["마지막 쪽 'GNN 시대의 부분그래프 마이닝' 에서 모티프와 부분그래프를 특징 공학에 쓸 수 있다고 했어요.","A 가족의 '부분 구조 개수를 특징으로 넣기' 가 바로 그 특징 공학이에요.","지난 학기 그래플릿 세기가 GNN 천장을 깨는 재료로 다시 쓰여요."]}],"pass3":[{"kind":"exam","src":"GNN 2024 가을 기말 7번 (Graphormer, 10점)","q":"Given a directed graph of six nodes A to F, according to the Graphormer model, calculate the initial node features with Centrality Encoding. The degree lookup table is T = {0: 0.0, 1: 0.1, 2: 0.2, 3: 0.3, 4: 0.4}. Why does encoding structural information make the model more powerful, and what structural information should be considered?","qko":"방향 그래프에서 차수 룩업 표 T 로 중심성 인코딩을 적용해 초기 특징을 구하고, 구조 정보를 넣으면 왜 더 강해지는지, 어떤 구조 정보를 넣어야 하는지 서술하라. (E 가족)","solve":["중심성 인코딩: 원래 특징 + T[한쪽 방향 차수] + T[다른 방향 차수]","해설: A = 1 + T[1] + T[2] = 1 + 0.1 + 0.2 = 1.3","B = 3 + 0.0 + 0.2 = 3.2, C = 5 + 0.2 + 0.2 = 5.4","D = 2 + 0.3 + 0.1 = 2.4, E = 4 + 0.1 + 0.2 = 4.3, F = 6 + 0.1 + 0.1 = 6.2","(b) 구조 인코딩은 이웃 집계가 못 가르는 비동형 그래프를 구별하게 해 WL 을 넘게 도와요. 예: 라플라시안 고유벡터, 최단 경로 거리, 랜덤 워크, 구조적 정체성"],"answer":"A 1.3, B 3.2, C 5.4, D 2.4, E 4.3, F 6.2"},{"kind":"english","head":"구조 인코딩이 강한 이유","en":"Structural encodings such as degree, subgraph structures or motifs help the model distinguish non-isomorphic graphs that simple neighbor aggregation cannot, going beyond the WL test.","ko":"차수, 부분 구조, 모티프 같은 구조 인코딩은 단순 이웃 집계가 못 가르는 비동형 그래프를 구별하게 도와 WL 테스트를 넘게 한다."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["C 의 'k-WL 과 정확히 같음' 은 느슨한 요약이에요. 예를 들어 PPGN 은 3-WL 수준으로 알려져 있어요.","D 의 '높은 확률로 보편적' 은 주로 무작위 특징 쪽 결과예요. DropGNN 에도 같다고 읽으면 과해요.","천장을 넘는다고 늘 좋은 게 아니에요. 실제 그래프 대부분은 1-WL 로도 구별되니(p.58) 비용을 따져 골라요."]},{"kind":"check","q":"1-WL 천장을 넘는 가장 싼 방법은?","choices":["A 특징 풍부하게 하기","C 고차 GNN","E 전역 어텐션"],"a":0,"why":"메시지 패싱은 그대로 두고 처음 입력에 삼각형 수 같은 정보만 붙이면 돼요."},{"kind":"check","q":"**불변성(Invariance)** 의 뜻은?","choices":["노드 번호를 바꿔 붙여도 결과가 같아야 한다","학습 중 가중치가 안 바뀐다","그래프 크기가 고정이다"],"a":0,"why":"D 가족은 이 성질을 분포 수준으로 완화해서 구별력을 얻어요."}],"pass4":[{"kind":"say","lines":["C 가족의 뿌리인 **k-WL 테스트(k-WL)** 를 1주차 노트북에서 코드로 볼 수 있어요."]},{"kind":"code","head":"노드 대신 노드 k 개 묶음에 색칠하기","file":"PracticeCode_1_번역.ipynb 셀 162","code":"def kWL(G, k, verbose=False):\n    def n_set(G):\n        G = nx.convert_node_labels_to_integers(G)\n        V = list(G.nodes())\n        \n        # 노드 k개짜리 튜플을 하나의 원소로 본다\n        V_k = [comb for comb in itertools.combinations(V, k)]\n        return G, V_k\n\n    def set_initial_colors(n):\n        return {i: [hashlib.sha224(str(i).encode('utf-8')).hexdigest()] for i in n}\n\n    # 이웃 튜플 찾기\n    def find_neighbors(G, V_k, node):\n        return [n for n in V_k if len(set(n) - set(V_k[V_k.index(node)])) == 1]\n\n    return compute_base_WL(G, k, verbose, n_set, set_initial_colors, find_neighbors)","lines":[{"from":1,"to":1,"say":"k 를 받는 kWL 함수예요. 안에 작은 함수 세 개를 만들어 p.57 의 뼈대 함수에 넘겨요."},{"from":2,"to":8,"say":"combinations(V, k) 로 노드 k 개 묶음(튜플)을 전부 만들어요. 이 묶음 하나하나가 색칠 대상이에요."},{"from":10,"to":11,"say":"초기 색은 튜플 자체를 해시해서 묶음마다 달라요."},{"from":13,"to":15,"say":"이웃은 나와 노드 하나만 다른 튜플이에요. set 차집합 크기가 1 이면 이웃이에요."},{"from":17,"to":17,"say":"1-WL 과 같은 뼈대 compute_base_WL 로 계산해요."}],"link":"노드 대신 튜플에 색을 칠하는 것이 C 고차 GNN 가족이 흉내 내는 k-WL 이에요."},{"kind":"code","head":"1-WL 이 못 가른 3-정규 쌍을 2-WL 로","file":"PracticeCode_1_번역.ipynb 셀 170","code":"check_graph_isomorphic(R, L, k=2, verbose=True, method='kWL')","lines":[{"from":1,"to":1,"say":"셀 169 설명: p.60 에서 1-WL 이 True 로 못 가른 L, R 을 k=2 로 비교하면 False, 곧 구별해요."}],"link":"천장 위(k-WL)에서는 정규 그래프 쌍도 갈라질 수 있어요."},{"kind":"warn","head":"코드 읽을 때 주의","items":["셀 169 설명대로 소제목은 'k = 3' 이지만 코드는 k=2 를 써요.","노드가 많거나 k 가 크면 묶음 수가 폭발해 매우 느려져요. C 가족의 대가 '계산량' 이 이거예요."]}]},{"p":84,"title":"Q&A","terms":["Color refinement","GIN","1-WL","Regular graph","Invariance"],"pass1":[{"kind":"say","lines":["3주차 강의는 여기까지예요. 질문 시간이에요.","오늘은 색칠 시험을 배우고, 그걸 신경망으로 만든 GIN 을 보고, 그 한계와 넘는 방법까지 봤어요."]},{"kind":"recap","items":["**색 정제(Color refinement)**: 이웃 색을 모아 내 색과 묶고, 다른 묶음엔 다른 번호를 주는 규칙(해시)으로 새 색을 붙여요.","**그래프 동형 네트워크(GIN)**: 내 것에 무게를 살짝 더 얹고 이웃 것은 더해 신경망에 넣어요. 구별하는 힘은 **1-WL 테스트(1-WL)** 와 같아요.","모든 노드의 친구 수가 같은 **정규 그래프(Regular graph)**, 고리, 빽빽한 무리 앞에서 1-WL 이 실패해요.","천장 넘기: 노드 정보, 주고받는 범위, **불변성(Invariance)** 중 하나를 바꿔요.","오늘의 용어: Color refinement(색 정제), Injective(단사), GIN(그래프 동형 네트워크), Regular graph(정규 그래프), Invariance(불변성)"]}],"pass2":[{"kind":"prof","when":"3주차 화요일 수업","lines":["표현력은 다른 걸 다르다고, 같은 걸 같다고 말할 수 있느냐예요.","GNN 은 k층 뿌리 있는 부분 트리로 노드를 가르고, 상한은 1-WL 이에요.","합 집계, MLP 업데이트, 나를 기억하는 항으로 그 상한에 다가가요.","사이클은 여전히 못 가르니 구조 특징, 부분그래프 묶음 등으로 넘어요."]}],"pass3":[{"kind":"check","q":"혼자 점검 1: p.52 표의 2라운드 줄이 틀린 이유는?","choices":["개수 합이 노드 수 6 과 달라서","색 번호가 너무 커서","2라운드는 원래 계산하지 않아서"],"a":0,"why":"G1 은 합 8, G2 는 합 9 였어요. 히스토그램 개수 합은 늘 노드 수예요."},{"kind":"check","q":"혼자 점검 2: GINConv 에서 합 대신 평균을 쓰면?","choices":["1-WL 보다 약해질 수 있다","1-WL 보다 강해진다","아무 차이 없다"],"a":0,"why":"평균은 {B} 와 {B, B} 를 같게 봐요. 개수를 잃어서 단사가 깨져요(p.54, p.58)."},{"kind":"check","q":"혼자 점검 3: **안정된 색칠(Stable coloring)** 의 뜻은?","choices":["라운드를 더 돌려도 같은 색 무리가 더 쪼개지지 않는 상태","모든 노드가 같은 색인 상태","색 번호가 더 이상 커지지 않는 상태"],"a":0,"why":"번호 이름은 바뀌어도 무리 나누기가 그대로면 안정이에요. p.59 의 {4:2, 5:4, 6:4} 가 예예요."}],"pass4":[]}]};
